func (*Table) isBlock()          {}
func (*Figure) isBlock()         {}
func (*Div) isBlock()            {}

// ---- Meta ----

type MetaValue interface{ isMeta() }

type MetaMap struct {
	Keys   []string
	Values map[string]MetaValue
}
type MetaList struct{ Items []MetaValue }
type MetaBool struct{ Value bool }
type MetaString struct{ Text string }
type MetaInlines struct{ Inlines []Inline }
type MetaBlocks struct{ Blocks []Block }

func (*MetaMap) isMeta()     {}
func (*MetaList) isMeta()    {}
func (*MetaBool) isMeta()    {}
func (*MetaString) isMeta()  {}
func (*MetaInlines) isMeta() {}
func (*MetaBlocks) isMeta()  {}

func newMetaMap() *MetaMap {
	return &MetaMap{Values: map[string]MetaValue{}}
}

func (m *MetaMap) Set(k string, v MetaValue) {
	if _, ok := m.Values[k]; !ok {
		// keep keys sorted (Haskell Map ordering by code point)
		i := 0
		for i < len(m.Keys) && m.Keys[i] < k {
			i++
		}
		m.Keys = append(m.Keys, "")
		copy(m.Keys[i+1:], m.Keys[i:])
		m.Keys[i] = k
	}
	m.Values[k] = v
}

func (m *MetaMap) Get(k string) (MetaValue, bool) {
	v, ok := m.Values[k]
	return v, ok
}

func (m *MetaMap) Delete(k string) {
	if _, ok := m.Values[k]; !ok {
		return
	}
	delete(m.Values, k)
	for i, kk := range m.Keys {
		if kk == k {
			m.Keys = append(m.Keys[:i], m.Keys[i+1:]...)
			break
		}
	}
}

func (m *MetaMap) Len() int { return len(m.Keys) }

type Pandoc struct {
	Meta   *MetaMap
	Blocks []Block
}

// ---- Helpers ----

func strInl(s string) Inline { return &Str{Text: s} }

var spaceInl Inline = &Space{}
var softBreakInl Inline = &SoftBreak{}
var lineBreakInl Inline = &LineBreak{}

// stringify converts inlines to plain text (like Text.Pandoc.Shared.stringify).
func stringify(ils []Inline) string {
	var sb []byte
	var go_ func([]Inline)
	go_ = func(ils []Inline) {
		for _, il := range ils {
			switch x := il.(type) {
			case *Str:
				sb = append(sb, x.Text...)
			case *Space, *SoftBreak:
				sb = append(sb, ' ')
			case *LineBreak:
				sb = append(sb, ' ')
			case *Code:
				sb = append(sb, x.Text...)
			case *Math:
				sb = append(sb, x.Text...)
			case *RawInline:
				// raw inlines are dropped by stringify
			case *Quoted:
				if x.Type == SingleQuote {
					sb = append(sb, "\u2018"...)
					go_(x.Inlines)
					sb = append(sb, "\u2019"...)
				} else {
					sb = append(sb, "\u201c"...)
					go_(x.Inlines)
					sb = append(sb, "\u201d"...)
				}
			case *Note:
				// notes are dropped
			default:
				go_(inlineChildren(il))
			}
		}
	}
	go_(ils)
	return string(sb)
}

func stringifyBlocks(bs []Block) string {
	var out string
	for i, b := range bs {
		if i > 0 {
			out += " "
		}
		out += stringify(blockInlines(b))
	}
	return out
}

// blockInlines returns all inlines in a block (recursively) for stringification.
func blockInlines(b Block) []Inline {
	switch x := b.(type) {
	case *Plain:
		return x.Inlines
	case *Para:
		return x.Inlines
	case *Header:
		return x.Inlines
	case *LineBlock:
		var out []Inline
		for i, l := range x.Lines {
			if i > 0 {
				out = append(out, &LineBreak{})
			}
			out = append(out, l...)
		}
		return out
	case *CodeBlock:
		return []Inline{&Str{Text: x.Text}}
	case *RawBlock:
		return nil
	case *BlockQuote:
		return blocksInlines(x.Blocks)
	case *Div:
		return blocksInlines(x.Blocks)
	case *Figure:
		return blocksInlines(x.Blocks)
	case *OrderedList:
		var out []Inline
		for _, it := range x.Items {
			out = append(out, blocksInlines(it)...)
		}
		return out
	case *BulletList:
		var out []Inline
		for _, it := range x.Items {
			out = append(out, blocksInlines(it)...)
		}
		return out
	case *DefinitionList:
		var out []Inline
		for _, it := range x.Items {
			out = append(out, it.Term...)
			for _, d := range it.Defs {
				out = append(out, blocksInlines(d)...)
			}
		}
		return out
	case *Table:
		var out []Inline
		out = append(out, blocksInlines(x.Caption.Blocks)...)
		rows := append([]Row{}, x.Head.Rows...)
		for _, b := range x.Bodies {
			rows = append(rows, b.Head...)
			rows = append(rows, b.Body...)
		}
		rows = append(rows, x.Foot.Rows...)
		for _, r := range rows {
			for _, c := range r.Cells {
				out = append(out, blocksInlines(c.Blocks)...)
			}
		}
		return out
	}
	return nil
}

func blocksInlines(bs []Block) []Inline {
	var out []Inline
	for _, b := range bs {
		out = append(out, blockInlines(b)...)
	}
	return out
}

// inlineChildren returns direct inline children of an inline container.
func inlineChildren(il Inline) []Inline {
	switch x := il.(type) {
	case *Emph:
		return x.Inlines
	case *Underline:
		return x.Inlines
	case *Strong:
		return x.Inlines
	case *Strikeout:
		return x.Inlines
	case *Superscript:
		return x.Inlines
	case *Subscript:
		return x.Inlines
	case *SmallCaps:
		return x.Inlines
	case *Quoted:
		return x.Inlines
	case *Cite:
		return x.Inlines
	case *Link:
		return x.Inlines
	case *Image:
		return x.Inlines
	case *Span:
		return x.Inlines
	}
	return nil
}

// walkInlines applies f to every inline in the document (bottom-up transform).
func walkInlinesInBlocks(bs []Block, f func([]Inline) []Inline) []Block {
	out := make([]Block, 0, len(bs))
	for _, b := range bs {
		out = append(out, walkInlinesInBlock(b, f))
	}
	return out
}

func walkInlinesInBlock(b Block, f func([]Inline) []Inline) Block {
	switch x := b.(type) {
	case *Plain:
		return &Plain{Inlines: walkInlines(x.Inlines, f)}
	case *Para:
		return &Para{Inlines: walkInlines(x.Inlines, f)}
	case *Header:
		return &Header{Level: x.Level, Attr: x.Attr, Inlines: walkInlines(x.Inlines, f)}
	case *LineBlock:
		ls := make([][]Inline, len(x.Lines))
		for i, l := range x.Lines {
			ls[i] = walkInlines(l, f)
		}
		return &LineBlock{Lines: ls}
	case *BlockQuote:
		return &BlockQuote{Blocks: walkInlinesInBlocks(x.Blocks, f)}
	case *Div:
		return &Div{Attr: x.Attr, Blocks: walkInlinesInBlocks(x.Blocks, f)}
	case *Figure:
		return &Figure{Attr: x.Attr, Caption: walkCaption(x.Caption, f), Blocks: walkInlinesInBlocks(x.Blocks, f)}
	case *OrderedList:
		items := make([][]Block, len(x.Items))
		for i, it := range x.Items {
			items[i] = walkInlinesInBlocks(it, f)
		}
		return &OrderedList{Attrs: x.Attrs, Items: items}
	case *BulletList:
		items := make([][]Block, len(x.Items))
		for i, it := range x.Items {
			items[i] = walkInlinesInBlocks(it, f)
		}
		return &BulletList{Items: items}
	case *DefinitionList:
		items := make([]DefItem, len(x.Items))
		for i, it := range x.Items {
			defs := make([][]Block, len(it.Defs))
			for j, d := range it.Defs {
				defs[j] = walkInlinesInBlocks(d, f)
			}
			items[i] = DefItem{Term: walkInlines(it.Term, f), Defs: defs}
		}
		return &DefinitionList{Items: items}
	case *Table:
		t := *x
		t.Caption = walkCaption(x.Caption, f)
		t.Head = TableHead{Attr: x.Head.Attr, Rows: walkRows(x.Head.Rows, f)}
		t.Foot = TableFoot{Attr: x.Foot.Attr, Rows: walkRows(x.Foot.Rows, f)}
		bodies := make([]TableBody, len(x.Bodies))
		for i, tb := range x.Bodies {
			bodies[i] = TableBody{Attr: tb.Attr, RowHeadColumns: tb.RowHeadColumns, Head: walkRows(tb.Head, f), Body: walkRows(tb.Body, f)}
		}
		t.Bodies = bodies
		return &t
	}
	return b
}

func walkCaption(c Caption, f func([]Inline) []Inline) Caption {
	nc := Caption{HasShort: c.HasShort, Blocks: walkInlinesInBlocks(c.Blocks, f)}
	if c.HasShort {
		nc.Short = walkInlines(c.Short, f)
	}
	return nc
}

func walkRows(rows []Row, f func([]Inline) []Inline) []Row {
	out := make([]Row, len(rows))
	for i, r := range rows {
		cells := make([]Cell, len(r.Cells))
		for j, c := range r.Cells {
			cells[j] = Cell{Attr: c.Attr, Align: c.Align, RowSpan: c.RowSpan, ColSpan: c.ColSpan, Blocks: walkInlinesInBlocks(c.Blocks, f)}
		}
		out[i] = Row{Attr: r.Attr, Cells: cells}
	}
	return out
}

// walkInlines applies f bottom-up: first to children, then to the list itself.
func walkInlines(ils []Inline, f func([]Inline) []Inline) []Inline {
	out := make([]Inline, 0, len(ils))
	for _, il := range ils {
		out = append(out, walkInline(il, f))
	}
	return f(out)
}

func walkInline(il Inline, f func([]Inline) []Inline) Inline {
	switch x := il.(type) {
	case *Emph:
		return &Emph{Inlines: walkInlines(x.Inlines, f)}
	case *Underline:
		return &Underline{Inlines: walkInlines(x.Inlines, f)}
	case *Strong:
		return &Strong{Inlines: walkInlines(x.Inlines, f)}
	case *Strikeout:
		return &Strikeout{Inlines: walkInlines(x.Inlines, f)}
	case *Superscript:
		return &Superscript{Inlines: walkInlines(x.Inlines, f)}
	case *Subscript:
		return &Subscript{Inlines: walkInlines(x.Inlines, f)}
	case *SmallCaps:
		return &SmallCaps{Inlines: walkInlines(x.Inlines, f)}
	case *Quoted:
		return &Quoted{Type: x.Type, Inlines: walkInlines(x.Inlines, f)}
	case *Cite:
		cs := make([]Citation, len(x.Citations))
		for i, c := range x.Citations {
			cs[i] = c
			cs[i].Prefix = walkInlines(c.Prefix, f)
			cs[i].Suffix = walkInlines(c.Suffix, f)
		}
		return &Cite{Citations: cs, Inlines: walkInlines(x.Inlines, f)}
	case *Link:
		return &Link{Attr: x.Attr, Inlines: walkInlines(x.Inlines, f), Target: x.Target}
	case *Image:
		return &Image{Attr: x.Attr, Inlines: walkInlines(x.Inlines, f), Target: x.Target}
	case *Span:
		return &Span{Attr: x.Attr, Inlines: walkInlines(x.Inlines, f)}
	case *Note:
		return &Note{Blocks: walkInlinesInBlocks(x.Blocks, f)}
	}
	return il
}

// walkBlocks applies f to every block list, bottom-up.
func walkBlocks(bs []Block, f func([]Block) []Block) []Block {
	out := make([]Block, 0, len(bs))
	for _, b := range bs {
		out = append(out, walkBlock(b, f))
	}
	return f(out)
}

func walkBlock(b Block, f func([]Block) []Block) Block {
	switch x := b.(type) {
	case *BlockQuote:
		return &BlockQuote{Blocks: walkBlocks(x.Blocks, f)}
	case *Div:
		return &Div{Attr: x.Attr, Blocks: walkBlocks(x.Blocks, f)}
	case *Figure:
		c := x.Caption
		c.Blocks = walkBlocks(c.Blocks, f)
		return &Figure{Attr: x.Attr, Caption: c, Blocks: walkBlocks(x.Blocks, f)}
	case *OrderedList:
		items := make([][]Block, len(x.Items))
		for i, it := range x.Items {
			items[i] = walkBlocks(it, f)
		}
		return &OrderedList{Attrs: x.Attrs, Items: items}
	case *BulletList:
		items := make([][]Block, len(x.Items))
		for i, it := range x.Items {
			items[i] = walkBlocks(it, f)
		}
		return &BulletList{Items: items}
	case *DefinitionList:
		items := make([]DefItem, len(x.Items))
		for i, it := range x.Items {
			defs := make([][]Block, len(it.Defs))
			for j, d := range it.Defs {
				defs[j] = walkBlocks(d, f)
			}
			items[i] = DefItem{Term: it.Term, Defs: defs}
		}
		return &DefinitionList{Items: items}
	case *Table:
		t := *x
		t.Caption.Blocks = walkBlocks(x.Caption.Blocks, f)
		t.Head = TableHead{Attr: x.Head.Attr, Rows: walkRowsB(x.Head.Rows, f)}
		t.Foot = TableFoot{Attr: x.Foot.Attr, Rows: walkRowsB(x.Foot.Rows, f)}
		bodies := make([]TableBody, len(x.Bodies))
		for i, tb := range x.Bodies {
			bodies[i] = TableBody{Attr: tb.Attr, RowHeadColumns: tb.RowHeadColumns, Head: walkRowsB(tb.Head, f), Body: walkRowsB(tb.Body, f)}
		}
		t.Bodies = bodies
		return &t
	}
	return b
}

func walkRowsB(rows []Row, f func([]Block) []Block) []Row {
	out := make([]Row, len(rows))
	for i, r := range rows {
		cells := make([]Cell, len(r.Cells))
		for j, c := range r.Cells {
			cells[j] = Cell{Attr: c.Attr, Align: c.Align, RowSpan: c.RowSpan, ColSpan: c.ColSpan, Blocks: walkBlocks(c.Blocks, f)}
		}
		out[i] = Row{Attr: r.Attr, Cells: cells}
	}
	return out
}

// queryInlines walks all inlines (including in notes and metadata-free blocks) calling f.
func queryInlinesInBlocks(bs []Block, f func(Inline)) {
	for _, b := range bs {
		queryInlinesInBlock(b, f)
	}
}

func queryInlinesInBlock(b Block, f func(Inline)) {
	walkInlinesInBlock(b, func(ils []Inline) []Inline {
		for _, il := range ils {
			f(il)
		}
		return ils
	})
}

func queryInlines(ils []Inline, f func(Inline)) {
	walkInlines(ils, func(xs []Inline) []Inline {
		for _, il := range xs {
			f(il)
		}
		return xs
	})
}
EOF
echo done"}

