package main

import "strings"

// A faithful (lazy) port of the Hughes/Peyton Jones pretty printer
// (the Haskell "pretty" package) as needed for native output.

type pjKind int

const (
	pjEmpty pjKind = iota
	pjNilAbove
	pjTextBeside
	pjNest
	pjUnion
	pjNoDoc
	pjBeside
	pjAbove
	pjLazy
)

type PJDoc struct {
	kind pjKind
	text string
	size int
	k    int
	g    bool
	p, q *PJDoc
	f    func() *PJDoc
}

func pjForce(d *PJDoc) *PJDoc {
	for d.kind == pjLazy {
		if d.f != nil {
			r := d.f()
			d.f = nil
			r = pjForce(r)
			*d = *r
		} else {
			break
		}
	}
	return d
}

func pjLazyDoc(f func() *PJDoc) *PJDoc { return &PJDoc{kind: pjLazy, f: f} }

var pjEmptyDoc = &PJDoc{kind: pjEmpty}
var pjNoDocDoc = &PJDoc{kind: pjNoDoc}

func pjText(s string) *PJDoc {
	return &PJDoc{kind: pjTextBeside, text: s, size: strDisplayLen(s), p: pjEmptyDoc}
}

func strDisplayLen(s string) int {
	// Haskell's length counts code points.
	n := 0
	for range s {
		n++
	}
	return n
}

func pjTextBesideN(s string, size int, p *PJDoc) *PJDoc {
	return &PJDoc{kind: pjTextBeside, text: s, size: size, p: p}
}

func pjNilAbove(p *PJDoc) *PJDoc { return &PJDoc{kind: pjNilAbove, p: p} }
func pjNest_(k int, p *PJDoc) *PJDoc {
	return &PJDoc{kind: pjNest, k: k, p: p}
}
func pjUnion_(p, q *PJDoc) *PJDoc { return &PJDoc{kind: pjUnion, p: p, q: q} }

func pjMkNest(k int, p *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNest:
		return pjMkNest(k+p.k, p.p)
	case pjNoDoc:
		return pjNoDocDoc
	case pjEmpty:
		return pjEmptyDoc
	}
	if k == 0 {
		return p
	}
	return pjNest_(k, p)
}

func pjMkUnion(p, q *PJDoc) *PJDoc {
	p = pjForce(p)
	if p.kind == pjEmpty {
		return pjEmptyDoc
	}
	return pjUnion_(p, q)
}

// Public combinators -------------------------------------------------

func pjNest(k int, p *PJDoc) *PJDoc {
	return pjLazyDoc(func() *PJDoc { return pjMkNest(k, pjReduce(p)) })
}

// p <> q
func pjCat(p, q *PJDoc) *PJDoc { return pjBeside_(p, false, q) }

// p <+> q
func pjSpaceCat(p, q *PJDoc) *PJDoc { return pjBeside_(p, true, q) }

// p $$ q
func pjAboveOp(p, q *PJDoc) *PJDoc { return pjAbove_(p, false, q) }

func pjBeside_(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	pq := pjForce(q)
	if pq.kind == pjEmpty {
		return p
	}
	pp := pjForce(p)
	if pp.kind == pjEmpty {
		return q
	}
	return &PJDoc{kind: pjBeside, g: g, p: p, q: q}
}

func pjAbove_(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	pq := pjForce(q)
	if pq.kind == pjEmpty {
		return p
	}
	pp := pjForce(p)
	if pp.kind == pjEmpty {
		return q
	}
	return &PJDoc{kind: pjAbove, g: g, p: p, q: q}
}

func pjHsep(ds []*PJDoc) *PJDoc {
	r := pjEmptyDoc
	for i := len(ds) - 1; i >= 0; i-- {
		r = pjBeside_(ds[i], true, r)
	}
	return r
}

func pjHcat(ds []*PJDoc) *PJDoc {
	r := pjEmptyDoc
	for i := len(ds) - 1; i >= 0; i-- {
		r = pjBeside_(ds[i], false, r)
	}
	return r
}

func pjVcat(ds []*PJDoc) *PJDoc {
	r := pjEmptyDoc
	for i := len(ds) - 1; i >= 0; i-- {
		r = pjAbove_(ds[i], false, r)
	}
	return r
}

func pjSep(ds []*PJDoc) *PJDoc  { return pjSepX(true, ds) }
func pjCatS(ds []*PJDoc) *PJDoc { return pjSepX(false, ds) }

func pjHang(d1 *PJDoc, n int, d2 *PJDoc) *PJDoc {
	return pjSep([]*PJDoc{d1, pjNest(n, d2)})
}

func pjParens(d *PJDoc) *PJDoc {
	return pjCat(pjText("("), pjCat(d, pjText(")")))
}

// Reduction ----------------------------------------------------------

func pjReduce(d *PJDoc) *PJDoc {
	d = pjForce(d)
	switch d.kind {
	case pjBeside:
		return pjBeside(d.p, d.g, pjReduce(d.q))
	case pjAbove:
		return pjAbove(d.p, d.g, pjReduce(d.q))
	}
	return d
}

func pjAbove(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjAbove:
		return pjAbove(p.p, p.g, pjAbove(p.q, g, q))
	case pjBeside:
		return pjAboveNest(pjReduce(p), g, 0, pjReduce(q))
	}
	return pjAboveNest(p, g, 0, pjReduce(q))
}

func pjAboveNest(p *PJDoc, g bool, k int, q *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjUnion:
		p1, p2 := p.p, p.q
		return pjUnion_(pjLazyDoc(func() *PJDoc { return pjAboveNest(p1, g, k, q) }),
			pjLazyDoc(func() *PJDoc { return pjAboveNest(p2, g, k, q) }))
	case pjEmpty:
		return pjMkNest(k, q)
	case pjNest:
		pp := p.p
		k1 := p.k
		return pjNest_(k1, pjLazyDoc(func() *PJDoc { return pjAboveNest(pp, g, k-k1, q) }))
	case pjNilAbove:
		pp := p.p
		return pjNilAbove(pjLazyDoc(func() *PJDoc { return pjAboveNest(pp, g, k, q) }))
	case pjTextBeside:
		k1 := k - p.size
		pp := p.p
		rest := pjLazyDoc(func() *PJDoc {
			ppf := pjForce(pp)
			if ppf.kind == pjEmpty {
				return pjNilAboveNest(g, k1, q)
			}
			return pjAboveNest(ppf, g, k1, q)
		})
		return pjTextBesideN(p.text, p.size, rest)
	}
	panic("aboveNest: unexpected")
}

func pjNilAboveNest(g bool, k int, q *PJDoc) *PJDoc {
	q = pjForce(q)
	switch q.kind {
	case pjEmpty:
		return pjEmptyDoc
	case pjNest:
		return pjNilAboveNest(g, k+q.k, q.p)
	}
	if !g && k > 0 {
		return pjTextBesideN(strings.Repeat(" ", k), k, q)
	}
	return pjNilAbove(pjMkNest(k, q))
}

func pjBeside(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjUnion:
		p1, p2 := p.p, p.q
		return pjUnion_(pjLazyDoc(func() *PJDoc { return pjBeside(p1, g, q) }),
			pjLazyDoc(func() *PJDoc { return pjBeside(p2, g, q) }))
	case pjEmpty:
		return q
	case pjNest:
		pp := p.p
		return pjNest_(p.k, pjLazyDoc(func() *PJDoc { return pjBeside(pp, g, q) }))
	case pjBeside:
		if p.g == g {
			p1, q1 := p.p, p.q
			return pjBeside(p1, g, pjLazyDoc(func() *PJDoc { return pjBeside(q1, g, q) }))
		}
		return pjBeside(pjReduce(p), g, q)
	case pjAbove:
		return pjBeside(pjReduce(p), g, q)
	case pjNilAbove:
		pp := p.p
		return pjNilAbove(pjLazyDoc(func() *PJDoc { return pjBeside(pp, g, q) }))
	case pjTextBeside:
		pp := p.p
		rest := pjLazyDoc(func() *PJDoc {
			ppf := pjForce(pp)
			if ppf.kind == pjEmpty {
				return pjNilBeside(g, q)
			}
			return pjBeside(ppf, g, q)
		})
		return pjTextBesideN(p.text, p.size, rest)
	}
	panic("beside: unexpected")
}

func pjNilBeside(g bool, p *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjEmpty:
		return pjEmptyDoc
	case pjNest:
		return pjNilBeside(g, p.p)
	}
	if g {
		return pjTextBesideN(" ", 1, p)
	}
	return p
}

func pjSepX(x bool, ds []*PJDoc) *PJDoc {
	if len(ds) == 0 {
		return pjEmptyDoc
	}
	return pjLazyDoc(func() *PJDoc { return pjSep1(x, pjReduce(ds[0]), 0, ds[1:]) })
}

func pjSep1(g bool, p *PJDoc, k int, ys []*PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjUnion:
		p1, q1 := p.p, p.q
		return pjUnion_(pjLazyDoc(func() *PJDoc { return pjSep1(g, p1, k, ys) }),
			pjLazyDoc(func() *PJDoc { return pjAboveNest(q1, false, k, pjReduce(pjVcat(ys))) }))
	case pjEmpty:
		return pjMkNest(k, pjSepX(g, ys))
	case pjNest:
		pp := p.p
		n := p.k
		return pjNest_(n, pjLazyDoc(func() *PJDoc { return pjSep1(g, pp, k-n, ys) }))
	case pjNilAbove:
		pp := p.p
		return pjNilAbove(pjLazyDoc(func() *PJDoc { return pjAboveNest(pp, false, k, pjReduce(pjVcat(ys))) }))
	case pjTextBeside:
		pp := p.p
		sz := p.size
		return pjTextBesideN(p.text, p.size, pjLazyDoc(func() *PJDoc { return pjSepNB(g, pp, k-sz, ys) }))
	}
	panic("sep1: unexpected")
}

func pjSepNB(g bool, p *PJDoc, k int, ys []*PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNest:
		return pjSepNB(g, p.p, k, ys)
	case pjEmpty:
		var rest *PJDoc
		if g {
			rest = pjHsep(ys)
		} else {
			rest = pjHcat(ys)
		}
		return pjMkUnion(pjOneLiner(pjNilBeside(g, pjReduce(rest))),
			pjLazyDoc(func() *PJDoc { return pjNilAboveNest(false, k, pjReduce(pjVcat(ys))) }))
	}
	return pjSep1(g, p, k, ys)
}

func pjOneLiner(p *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjEmpty:
		return pjEmptyDoc
	case pjNilAbove:
		return pjNoDocDoc
	case pjTextBeside:
		pp := p.p
		return pjTextBesideN(p.text, p.size, pjLazyDoc(func() *PJDoc { return pjOneLiner(pp) }))
	case pjNest:
		pp := p.p
		return pjNest_(p.k, pjLazyDoc(func() *PJDoc { return pjOneLiner(pp) }))
	case pjUnion:
		return pjOneLiner(p.p)
	}
	panic("oneLiner: unexpected")
}

// Rendering ----------------------------------------------------------

func pjBest(w0, r int, d *PJDoc) *PJDoc {
	var get func(w int, d *PJDoc) *PJDoc
	var get1 func(w, sl int, d *PJDoc) *PJDoc
	get = func(w int, d *PJDoc) *PJDoc {
		d = pjForce(d)
		switch d.kind {
		case pjEmpty:
			return pjEmptyDoc
		case pjNoDoc:
			return pjNoDocDoc
		case pjNilAbove:
			pp := d.p
			return pjNilAbove(pjLazyDoc(func() *PJDoc { return get(w, pp) }))
		case pjTextBeside:
			pp := d.p
			sz := d.size
			return pjTextBesideN(d.text, d.size, pjLazyDoc(func() *PJDoc { return get1(w, sz, pp) }))
		case pjNest:
			pp := d.p
			k := d.k
			return pjNest_(k, pjLazyDoc(func() *PJDoc { return get(w-k, pp) }))
		case pjUnion:
			p, q := d.p, d.q
			gp := pjLazyDoc(func() *PJDoc { return get(w, p) })
			if pjFits(minInt(w, r), gp) {
				return gp
			}
			return get(w, q)
		}
		panic("best get: unexpected")
	}
	get1 = func(w, sl int, d *PJDoc) *PJDoc {
		d = pjForce(d)
		switch d.kind {
		case pjEmpty:
			return pjEmptyDoc
		case pjNoDoc:
			return pjNoDocDoc
		case pjNilAbove:
			pp := d.p
			return pjNilAbove(pjLazyDoc(func() *PJDoc { return get(w-sl, pp) }))
		case pjTextBeside:
			pp := d.p
			sz := d.size
			return pjTextBesideN(d.text, d.size, pjLazyDoc(func() *PJDoc { return get1(w, sl+sz, pp) }))
		case pjNest:
			return get1(w, sl, d.p)
		case pjUnion:
			p, q := d.p, d.q
			gp := pjLazyDoc(func() *PJDoc { return get1(w, sl, p) })
			if pjFits(minInt(w, r)-sl, gp) {
				return gp
			}
			return get1(w, sl, q)
		}
		panic("best get1: unexpected")
	}
	return get(w0, d)
}

func pjFits(n int, d *PJDoc) bool {
	for {
		if n < 0 {
			return false
		}
		d = pjForce(d)
		switch d.kind {
		case pjNoDoc:
			return false
		case pjEmpty:
			return true
		case pjNilAbove:
			return true
		case pjTextBeside:
			n -= d.size
			d = d.p
		default:
			panic("fits: unexpected")
		}
	}
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func pjDisplay(d *PJDoc, sb *strings.Builder) {
	var lay func(k int, d *PJDoc)
	var lay2 func(k int, d *PJDoc)
	lay = func(k int, d *PJDoc) {
		for {
			d = pjForce(d)
			switch d.kind {
			case pjNest:
				k += d.k
				d = d.p
				continue
			case pjEmpty:
				return
			case pjNilAbove:
				sb.WriteByte('\n')
				d = d.p
				continue
			case pjTextBeside:
				if k > 0 {
					sb.WriteString(strings.Repeat(" ", k))
				}
				sb.WriteString(d.text)
				lay2(k+d.size, d.p)
				return
			default:
				panic("display lay: unexpected")
			}
		}
	}
	lay2 = func(k int, d *PJDoc) {
		for {
			d = pjForce(d)
			switch d.kind {
			case pjNilAbove:
				sb.WriteByte('\n')
				lay(k, d.p)
				return
			case pjTextBeside:
				sb.WriteString(d.text)
				k += d.size
				d = d.p
				continue
			case pjNest:
				d = d.p
				continue
			case pjEmpty:
				return
			default:
				panic("display lay2: unexpected")
			}
		}
	}
	lay(0, d)
}

// pjRender renders with the given line length and ribbons-per-line.
func pjRender(lineLength int, ribbonsPerLine float64, d *PJDoc) string {
	ribbonLen := haskellRound(float64(lineLength) / ribbonsPerLine)
	best := pjBest(lineLength, ribbonLen, pjReduce(d))
	var sb strings.Builder
	pjDisplay(best, &sb)
	return sb.String()
}

// haskellRound implements Haskell's round (banker's rounding).
func haskellRound(x float64) int {
	n := int(x)
	if x < 0 {
		n = -int(-x)
	}
	frac := x - float64(n)
	if frac > 0.5 || (frac == 0.5 && n%2 != 0) {
		return n + 1
	}
	if frac < -0.5 || (frac == -0.5 && n%2 != 0) {
		return n - 1
	}
	return n
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/hughespj.go <<'EOF'
package main

import "strings"

// A faithful (lazy) port of the Hughes/Peyton Jones pretty printer
// (the Haskell "pretty" package) as needed for native output.

type pjKind int

const (
	pjEmpty pjKind = iota
	pjNilAbove
	pjTextBeside
	pjNest
	pjUnion
	pjNoDoc
	pjBeside
	pjAbove
	pjLazy
)

type PJDoc struct {
	kind pjKind
	text string
	size int
	k    int
	g    bool
	p, q *PJDoc
	f    func() *PJDoc
}

func pjForce(d *PJDoc) *PJDoc {
	for d.kind == pjLazy {
		if d.f != nil {
			r := d.f()
			d.f = nil
			r = pjForce(r)
			*d = *r
		} else {
			break
		}
	}
	return d
}

func pjLazyDoc(f func() *PJDoc) *PJDoc { return &PJDoc{kind: pjLazy, f: f} }

var pjEmptyDoc = &PJDoc{kind: pjEmpty}
var pjNoDocDoc = &PJDoc{kind: pjNoDoc}

func pjText(s string) *PJDoc {
	return &PJDoc{kind: pjTextBeside, text: s, size: strDisplayLen(s), p: pjEmptyDoc}
}

func strDisplayLen(s string) int {
	// Haskell's length counts code points.
	n := 0
	for range s {
		n++
	}
	return n
}

func pjTextBesideN(s string, size int, p *PJDoc) *PJDoc {
	return &PJDoc{kind: pjTextBeside, text: s, size: size, p: p}
}

func pjNilAbove(p *PJDoc) *PJDoc { return &PJDoc{kind: pjNilAbove, p: p} }
func pjNest_(k int, p *PJDoc) *PJDoc {
	return &PJDoc{kind: pjNest, k: k, p: p}
}
func pjUnion_(p, q *PJDoc) *PJDoc { return &PJDoc{kind: pjUnion, p: p, q: q} }

func pjMkNest(k int, p *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNest:
		return pjMkNest(k+p.k, p.p)
	case pjNoDoc:
		return pjNoDocDoc
	case pjEmpty:
		return pjEmptyDoc
	}
	if k == 0 {
		return p
	}
	return pjNest_(k, p)
}

func pjMkUnion(p, q *PJDoc) *PJDoc {
	p = pjForce(p)
	if p.kind == pjEmpty {
		return pjEmptyDoc
	}
	return pjUnion_(p, q)
}

// Public combinators -------------------------------------------------

func pjNest(k int, p *PJDoc) *PJDoc {
	return pjLazyDoc(func() *PJDoc { return pjMkNest(k, pjReduce(p)) })
}

// p <> q
func pjCat(p, q *PJDoc) *PJDoc { return pjBeside_(p, false, q) }

// p <+> q
func pjSpaceCat(p, q *PJDoc) *PJDoc { return pjBeside_(p, true, q) }

// p $$ q
func pjAboveOp(p, q *PJDoc) *PJDoc { return pjAbove_(p, false, q) }

func pjBeside_(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	pq := pjForce(q)
	if pq.kind == pjEmpty {
		return p
	}
	pp := pjForce(p)
	if pp.kind == pjEmpty {
		return q
	}
	return &PJDoc{kind: pjBeside, g: g, p: p, q: q}
}

func pjAbove_(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	pq := pjForce(q)
	if pq.kind == pjEmpty {
		return p
	}
	pp := pjForce(p)
	if pp.kind == pjEmpty {
		return q
	}
	return &PJDoc{kind: pjAbove, g: g, p: p, q: q}
}

func pjHsep(ds []*PJDoc) *PJDoc {
	r := pjEmptyDoc
	for i := len(ds) - 1; i >= 0; i-- {
		r = pjBeside_(ds[i], true, r)
	}
	return r
}

func pjHcat(ds []*PJDoc) *PJDoc {
	r := pjEmptyDoc
	for i := len(ds) - 1; i >= 0; i-- {
		r = pjBeside_(ds[i], false, r)
	}
	return r
}

func pjVcat(ds []*PJDoc) *PJDoc {
	r := pjEmptyDoc
	for i := len(ds) - 1; i >= 0; i-- {
		r = pjAbove_(ds[i], false, r)
	}
	return r
}

func pjSep(ds []*PJDoc) *PJDoc  { return pjSepX(true, ds) }
func pjCatS(ds []*PJDoc) *PJDoc { return pjSepX(false, ds) }

func pjHang(d1 *PJDoc, n int, d2 *PJDoc) *PJDoc {
	return pjSep([]*PJDoc{d1, pjNest(n, d2)})
}

func pjParens(d *PJDoc) *PJDoc {
	return pjCat(pjText("("), pjCat(d, pjText(")")))
}

// Reduction ----------------------------------------------------------

func pjReduce(d *PJDoc) *PJDoc {
	d = pjForce(d)
	switch d.kind {
	case pjBeside:
		return pjBeside(d.p, d.g, pjReduce(d.q))
	case pjAbove:
		return pjAbove(d.p, d.g, pjReduce(d.q))
	}
	return d
}

func pjAbove(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjAbove:
		return pjAbove(p.p, p.g, pjAbove(p.q, g, q))
	case pjBeside:
		return pjAboveNest(pjReduce(p), g, 0, pjReduce(q))
	}
	return pjAboveNest(p, g, 0, pjReduce(q))
}

func pjAboveNest(p *PJDoc, g bool, k int, q *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjUnion:
		p1, p2 := p.p, p.q
		return pjUnion_(pjLazyDoc(func() *PJDoc { return pjAboveNest(p1, g, k, q) }),
			pjLazyDoc(func() *PJDoc { return pjAboveNest(p2, g, k, q) }))
	case pjEmpty:
		return pjMkNest(k, q)
	case pjNest:
		pp := p.p
		k1 := p.k
		return pjNest_(k1, pjLazyDoc(func() *PJDoc { return pjAboveNest(pp, g, k-k1, q) }))
	case pjNilAbove:
		pp := p.p
		return pjNilAbove(pjLazyDoc(func() *PJDoc { return pjAboveNest(pp, g, k, q) }))
	case pjTextBeside:
		k1 := k - p.size
		pp := p.p
		rest := pjLazyDoc(func() *PJDoc {
			ppf := pjForce(pp)
			if ppf.kind == pjEmpty {
				return pjNilAboveNest(g, k1, q)
			}
			return pjAboveNest(ppf, g, k1, q)
		})
		return pjTextBesideN(p.text, p.size, rest)
	}
	panic("aboveNest: unexpected")
}

func pjNilAboveNest(g bool, k int, q *PJDoc) *PJDoc {
	q = pjForce(q)
	switch q.kind {
	case pjEmpty:
		return pjEmptyDoc
	case pjNest:
		return pjNilAboveNest(g, k+q.k, q.p)
	}
	if !g && k > 0 {
		return pjTextBesideN(strings.Repeat(" ", k), k, q)
	}
	return pjNilAbove(pjMkNest(k, q))
}

func pjBeside(p *PJDoc, g bool, q *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjUnion:
		p1, p2 := p.p, p.q
		return pjUnion_(pjLazyDoc(func() *PJDoc { return pjBeside(p1, g, q) }),
			pjLazyDoc(func() *PJDoc { return pjBeside(p2, g, q) }))
	case pjEmpty:
		return q
	case pjNest:
		pp := p.p
		return pjNest_(p.k, pjLazyDoc(func() *PJDoc { return pjBeside(pp, g, q) }))
	case pjBeside:
		if p.g == g {
			p1, q1 := p.p, p.q
			return pjBeside(p1, g, pjLazyDoc(func() *PJDoc { return pjBeside(q1, g, q) }))
		}
		return pjBeside(pjReduce(p), g, q)
	case pjAbove:
		return pjBeside(pjReduce(p), g, q)
	case pjNilAbove:
		pp := p.p
		return pjNilAbove(pjLazyDoc(func() *PJDoc { return pjBeside(pp, g, q) }))
	case pjTextBeside:
		pp := p.p
		rest := pjLazyDoc(func() *PJDoc {
			ppf := pjForce(pp)
			if ppf.kind == pjEmpty {
				return pjNilBeside(g, q)
			}
			return pjBeside(ppf, g, q)
		})
		return pjTextBesideN(p.text, p.size, rest)
	}
	panic("beside: unexpected")
}

func pjNilBeside(g bool, p *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjEmpty:
		return pjEmptyDoc
	case pjNest:
		return pjNilBeside(g, p.p)
	}
	if g {
		return pjTextBesideN(" ", 1, p)
	}
	return p
}

func pjSepX(x bool, ds []*PJDoc) *PJDoc {
	if len(ds) == 0 {
		return pjEmptyDoc
	}
	return pjLazyDoc(func() *PJDoc { return pjSep1(x, pjReduce(ds[0]), 0, ds[1:]) })
}

func pjSep1(g bool, p *PJDoc, k int, ys []*PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjUnion:
		p1, q1 := p.p, p.q
		return pjUnion_(pjLazyDoc(func() *PJDoc { return pjSep1(g, p1, k, ys) }),
			pjLazyDoc(func() *PJDoc { return pjAboveNest(q1, false, k, pjReduce(pjVcat(ys))) }))
	case pjEmpty:
		return pjMkNest(k, pjSepX(g, ys))
	case pjNest:
		pp := p.p
		n := p.k
		return pjNest_(n, pjLazyDoc(func() *PJDoc { return pjSep1(g, pp, k-n, ys) }))
	case pjNilAbove:
		pp := p.p
		return pjNilAbove(pjLazyDoc(func() *PJDoc { return pjAboveNest(pp, false, k, pjReduce(pjVcat(ys))) }))
	case pjTextBeside:
		pp := p.p
		sz := p.size
		return pjTextBesideN(p.text, p.size, pjLazyDoc(func() *PJDoc { return pjSepNB(g, pp, k-sz, ys) }))
	}
	panic("sep1: unexpected")
}

func pjSepNB(g bool, p *PJDoc, k int, ys []*PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNest:
		return pjSepNB(g, p.p, k, ys)
	case pjEmpty:
		var rest *PJDoc
		if g {
			rest = pjHsep(ys)
		} else {
			rest = pjHcat(ys)
		}
		return pjMkUnion(pjOneLiner(pjNilBeside(g, pjReduce(rest))),
			pjLazyDoc(func() *PJDoc { return pjNilAboveNest(false, k, pjReduce(pjVcat(ys))) }))
	}
	return pjSep1(g, p, k, ys)
}

func pjOneLiner(p *PJDoc) *PJDoc {
	p = pjForce(p)
	switch p.kind {
	case pjNoDoc:
		return pjNoDocDoc
	case pjEmpty:
		return pjEmptyDoc
	case pjNilAbove:
		return pjNoDocDoc
	case pjTextBeside:
		pp := p.p
		return pjTextBesideN(p.text, p.size, pjLazyDoc(func() *PJDoc { return pjOneLiner(pp) }))
	case pjNest:
		pp := p.p
		return pjNest_(p.k, pjLazyDoc(func() *PJDoc { return pjOneLiner(pp) }))
	case pjUnion:
		return pjOneLiner(p.p)
	}
	panic("oneLiner: unexpected")
}

// Rendering ----------------------------------------------------------

func pjBest(w0, r int, d *PJDoc) *PJDoc {
	var get func(w int, d *PJDoc) *PJDoc
	var get1 func(w, sl int, d *PJDoc) *PJDoc
	get = func(w int, d *PJDoc) *PJDoc {
		d = pjForce(d)
		switch d.kind {
		case pjEmpty:
			return pjEmptyDoc
		case pjNoDoc:
			return pjNoDocDoc
		case pjNilAbove:
			pp := d.p
			return pjNilAbove(pjLazyDoc(func() *PJDoc { return get(w, pp) }))
		case pjTextBeside:
			pp := d.p
			sz := d.size
			return pjTextBesideN(d.text, d.size, pjLazyDoc(func() *PJDoc { return get1(w, sz, pp) }))
		case pjNest:
			pp := d.p
			k := d.k
			return pjNest_(k, pjLazyDoc(func() *PJDoc { return get(w-k, pp) }))
		case pjUnion:
			p, q := d.p, d.q
			gp := pjLazyDoc(func() *PJDoc { return get(w, p) })
			if pjFits(minInt(w, r), gp) {
				return gp
			}
			return get(w, q)
		}
		panic("best get: unexpected")
	}
	get1 = func(w, sl int, d *PJDoc) *PJDoc {
		d = pjForce(d)
		switch d.kind {
		case pjEmpty:
			return pjEmptyDoc
		case pjNoDoc:
			return pjNoDocDoc
		case pjNilAbove:
			pp := d.p
			return pjNilAbove(pjLazyDoc(func() *PJDoc { return get(w-sl, pp) }))
		case pjTextBeside:
			pp := d.p
			sz := d.size
			return pjTextBesideN(d.text, d.size, pjLazyDoc(func() *PJDoc { return get1(w, sl+sz, pp) }))
		case pjNest:
			return get1(w, sl, d.p)
		case pjUnion:
			p, q := d.p, d.q
			gp := pjLazyDoc(func() *PJDoc { return get1(w, sl, p) })
			if pjFits(minInt(w, r)-sl, gp) {
				return gp
			}
			return get1(w, sl, q)
		}
		panic("best get1: unexpected")
	}
	return get(w0, d)
}

func pjFits(n int, d *PJDoc) bool {
	for {
		if n < 0 {
			return false
		}
		d = pjForce(d)
		switch d.kind {
		case pjNoDoc:
			return false
		case pjEmpty:
			return true
		case pjNilAbove:
			return true
		case pjTextBeside:
			n -= d.size
			d = d.p
		default:
			panic("fits: unexpected")
		}
	}
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func pjDisplay(d *PJDoc, sb *strings.Builder) {
	var lay func(k int, d *PJDoc)
	var lay2 func(k int, d *PJDoc)
	lay = func(k int, d *PJDoc) {
		for {
			d = pjForce(d)
			switch d.kind {
			case pjNest:
				k += d.k
				d = d.p
				continue
			case pjEmpty:
				return
			case pjNilAbove:
				sb.WriteByte('\n')
				d = d.p
				continue
			case pjTextBeside:
				if k > 0 {
					sb.WriteString(strings.Repeat(" ", k))
				}
				sb.WriteString(d.text)
				lay2(k+d.size, d.p)
				return
			default:
				panic("display lay: unexpected")
			}
		}
	}
	lay2 = func(k int, d *PJDoc) {
		for {
			d = pjForce(d)
			switch d.kind {
			case pjNilAbove:
				sb.WriteByte('\n')
				lay(k, d.p)
				return
			case pjTextBeside:
				sb.WriteString(d.text)
				k += d.size
				d = d.p
				continue
			case pjNest:
				d = d.p
				continue
			case pjEmpty:
				return
			default:
				panic("display lay2: unexpected")
			}
		}
	}
	lay(0, d)
}

// pjRender renders with the given line length and ribbons-per-line.
func pjRender(lineLength int, ribbonsPerLine float64, d *PJDoc) string {
	ribbonLen := haskellRound(float64(lineLength) / ribbonsPerLine)
	best := pjBest(lineLength, ribbonLen, pjReduce(d))
	var sb strings.Builder
	pjDisplay(best, &sb)
	return sb.String()
}

// haskellRound implements Haskell's round (banker's rounding).
func haskellRound(x float64) int {
	n := int(x)
	if x < 0 {
		n = -int(-x)
	}
	frac := x - float64(n)
	if frac > 0.5 || (frac == 0.5 && n%2 != 0) {
		return n + 1
	}
	if frac < -0.5 || (frac == -0.5 && n%2 != 0) {
		return n - 1
	}
	return n
}
