// ---- Haskell-style show for strings ----

var asciiTab = []string{"NUL", "SOH", "STX", "ETX", "EOT", "ENQ", "ACK", "BEL",
	"BS", "HT", "LF", "VT", "FF", "SO", "SI",
	"DLE", "DC1", "DC2", "DC3", "DC4", "NAK", "SYN", "ETB",
	"CAN", "EM", "SUB", "ESC", "FS", "GS", "RS", "US", "SP"}

func haskellShowString(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	rs := []rune(s)
	for i, c := range rs {
		var next rune = -1
		if i+1 < len(rs) {
			next = rs[i+1]
		}
		switch {
		case c == '"':
			sb.WriteString("\\\"")
		case c == '\\':
			sb.WriteString("\\\\")
		case c > 0x7e:
			sb.WriteString("\\")
			sb.WriteString(strconv.Itoa(int(c)))
			if next >= '0' && next <= '9' {
				sb.WriteString("\\&")
			}
		case c == 0x7f:
			sb.WriteString("\\DEL")
		case c >= ' ':
			sb.WriteRune(c)
		case c == '\a':
			sb.WriteString("\\a")
		case c == '\b':
			sb.WriteString("\\b")
		case c == '\f':
			sb.WriteString("\\f")
		case c == '\n':
			sb.WriteString("\\n")
		case c == '\r':
			sb.WriteString("\\r")
		case c == '\t':
			sb.WriteString("\\t")
		case c == '\v':
			sb.WriteString("\\v")
		case c == 0x0e:
			sb.WriteString("\\SO")
			if next == 'H' {
				sb.WriteString("\\&")
			}
		default:
			sb.WriteString("\\")
			sb.WriteString(asciiTab[c])
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// ---- Value tree (like pretty-show) ----

type nvKind int

const (
	nvCon nvKind = iota
	nvRec
	nvList
	nvTuple
	nvAtom // string/integer/float literal
)

type NVal struct {
	kind   nvKind
	name   string
	args   []*NVal
