	case nvList:
		ds := make([]*PJDoc, len(v.args))
		for i, a := range v.args {
			ds[i] = ppValue(a)
		}
		return ppBlock("[", "]", ds)
	case nvTuple:
		ds := make([]*PJDoc, len(v.args))
		for i, a := range v.args {
			ds[i] = ppValue(a)
		}
		return ppBlock("(", ")", ds)
	}
	panic("ppValue")
}

func ppAtom(v *NVal) *PJDoc {
	if nvIsAtom(v) {
		return ppValue(v)
	}
	return pjParens(ppValue(v))
