cd /workspace && cat > src/native.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// ---- Haskell-style show for strings ----

var asciiTab = []string{"NUL", "SOH", "STX", "ETX", "EOT", "ENQ", "ACK", "BEL",
	"BS", "HT", "LF", "VT", "FF", "SO", "SI",
	"DLE", "DC1", "DC2", "DC3", "DC4", "NAK", "SYN", "ETB",
	"CAN", "EM", "SUB", "ESC", "FS", "GS", "RS", "US", "SP"}

func haskellShowString(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	rs := []rune(s)
	for i, c := range rs {
		var next rune = -1
		if i+1 < len(rs) {
			next = rs[i+1]
		}
		switch {
		case c == '"':
			sb.WriteString("\\\"")
		case c == '\\':
			sb.WriteString("\\\\")
		case c > 0x7e:
			sb.WriteString("\\")
			sb.WriteString(strconv.Itoa(int(c)))
			if next >= '0' && next <= '9' {
				sb.WriteString("\\&")
			}
		case c == 0x7f:
			sb.WriteString("\\DEL")
		case c >= ' ':
			sb.WriteRune(c)
		case c == '\a':
			sb.WriteString("\\a")
		case c == '\b':
			sb.WriteString("\\b")
		case c == '\f':
			sb.WriteString("\\f")
		case c == '\n':
			sb.WriteString("\\n")
		case c == '\r':
			sb.WriteString("\\r")
		case c == '\t':
			sb.WriteString("\\t")
		case c == '\v':
			sb.WriteString("\\v")
		case c == 0x0e:
			sb.WriteString("\\SO")
			if next == 'H' {
				sb.WriteString("\\&")
			}
		default:
			sb.WriteString("\\")
			sb.WriteString(asciiTab[c])
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// ---- Value tree (like pretty-show) ----

type nvKind int

const (
	nvCon nvKind = iota
	nvRec
	nvList
	nvTuple
	nvAtom // string/integer/float literal
)

type NVal struct {
	kind   nvKind
	name   string
	args   []*NVal
	fields []string // for Rec
}

func nvAtomS(s string) *NVal           { return &NVal{kind: nvAtom, name: s} }
func nvStr(s string) *NVal             { return nvAtomS(haskellShowString(s)) }
func nvInt(i int) *NVal                { return nvAtomS(strconv.Itoa(i)) }
func nvConV(name string, args ...*NVal) *NVal {
	return &NVal{kind: nvCon, name: name, args: args}
}
func nvListV(xs []*NVal) *NVal  { return &NVal{kind: nvList, args: xs} }
func nvTupleV(xs ...*NVal) *NVal { return &NVal{kind: nvTuple, args: xs} }

func nvIsAtom(v *NVal) bool {
	switch v.kind {
	case nvCon:
		return len(v.args) == 0
	}
	return true
}

func nvDouble(f float64) *NVal {
	return nvAtomS(haskellShowDouble(f))
}

// haskellShowDouble approximates Haskell's show for Double.
func haskellShowDouble(f float64) string {
	if f == 0 {
		return "0.0"
	}
	neg := f < 0
	if neg {
		f = -f
	}
	// shortest representation digits
	s := strconv.FormatFloat(f, 'e', -1, 64)
	// s like "d.ddddde+XX"
	mant, expS, _ := strings.Cut(s, "e")
	exp, _ := strconv.Atoi(expS)
	digits := strings.Replace(mant, ".", "", 1)
	e := exp + 1 // number of digits before the decimal point
	var out string
	if 0 < e && e <= 7 {
		if e >= len(digits) {
			out = digits + strings.Repeat("0", e-len(digits)) + ".0"
		} else {
			out = digits[:e] + "." + digits[e:]
		}
	} else if e <= 0 && e > -1 { // 0.1 <= f < 1
		out = "0." + digits
	} else {
		d := digits[:1]
		rest := digits[1:]
		if rest == "" {
			rest = "0"
		}
		out = d + "." + rest + "e" + strconv.Itoa(e-1)
	}
	if neg {
		out = "-" + out
	}
	return out
}

func ppValue(v *NVal) *PJDoc {
	switch v.kind {
	case nvAtom:
		return pjText(v.name)
	case nvCon:
		if len(v.args) == 0 {
			return pjText(v.name)
		}
		ds := make([]*PJDoc, len(v.args))
		for i, a := range v.args {
			ds[i] = ppAtom(a)
		}
		return pjHang(pjText(v.name), 2, pjSep(ds))
	case nvRec:
		ds := make([]*PJDoc, len(v.args))
		for i, a := range v.args {
			ds[i] = pjHang(pjSpaceCat(pjText(v.fields[i]), pjText("=")), 2, ppValue(a))
		}
		return pjHang(pjText(v.name), 2, ppBlock("{", "}", ds))
	case nvList:
		ds := make([]*PJDoc, len(v.args))
		for i, a := range v.args {
			ds[i] = ppValue(a)
		}
		return ppBlock("[", "]", ds)
	case nvTuple:
		ds := make([]*PJDoc, len(v.args))
		for i, a := range v.args {
			ds[i] = ppValue(a)
		}
		return ppBlock("(", ")", ds)
	}
	panic("ppValue")
}

func ppAtom(v *NVal) *PJDoc {
	if nvIsAtom(v) {
		return ppValue(v)
	}
	return pjParens(ppValue(v))
}

func ppBlock(open, close string, ds []*PJDoc) *PJDoc {
	if len(ds) == 0 {
		return pjText(open + close)
	}
	items := make([]*PJDoc, 0, len(ds)+1)
	items = append(items, pjSpaceCat(pjText(open), ds[0]))
	for _, d := range ds[1:] {
		items = append(items, pjSpaceCat(pjText(","), d))
	}
	items = append(items, pjText(close))
	return pjSep(items)
}

// ---- AST -> NVal ----

func nvAttr(a Attr) *NVal {
	cls := make([]*NVal, len(a.Classes))
	for i, c := range a.Classes {
		cls[i] = nvStr(c)
	}
	kvs := make([]*NVal, len(a.KVs))
	for i, kv := range a.KVs {
		kvs[i] = nvTupleV(nvStr(kv[0]), nvStr(kv[1]))
	}
	return nvTupleV(nvStr(a.ID), nvListV(cls), nvListV(kvs))
}

func nvInlines(ils []Inline) *NVal {
	xs := make([]*NVal, len(ils))
	for i, il := range ils {
		xs[i] = nvInline(il)
	}
	return nvListV(xs)
}

func nvBlocks(bs []Block) *NVal {
	xs := make([]*NVal, len(bs))
	for i, b := range bs {
		xs[i] = nvBlock(b)
	}
	return nvListV(xs)
}

func nvTarget(t Target) *NVal { return nvTupleV(nvStr(t.URL), nvStr(t.Title)) }

func nvInline(il Inline) *NVal {
	switch x := il.(type) {
	case *Str:
		return nvConV("Str", nvStr(x.Text))
	case *Emph:
		return nvConV("Emph", nvInlines(x.Inlines))
	case *Underline:
		return nvConV("Underline", nvInlines(x.Inlines))
	case *Strong:
		return nvConV("Strong", nvInlines(x.Inlines))
	case *Strikeout:
		return nvConV("Strikeout", nvInlines(x.Inlines))
	case *Superscript:
		return nvConV("Superscript", nvInlines(x.Inlines))
	case *Subscript:
		return nvConV("Subscript", nvInlines(x.Inlines))
	case *SmallCaps:
		return nvConV("SmallCaps", nvInlines(x.Inlines))
	case *Quoted:
		q := "SingleQuote"
		if x.Type == DoubleQuote {
			q = "DoubleQuote"
		}
		return nvConV("Quoted", nvConV(q), nvInlines(x.Inlines))
	case *Cite:
		cs := make([]*NVal, len(x.Citations))
		for i, c := range x.Citations {
			mode := "NormalCitation"
			switch c.Mode {
			case AuthorInText:
				mode = "AuthorInText"
			case SuppressAuthor:
				mode = "SuppressAuthor"
			}
			cs[i] = &NVal{kind: nvRec, name: "Citation",
				fields: []string{"citationId", "citationPrefix", "citationSuffix", "citationMode", "citationNoteNum", "citationHash"},
				args:   []*NVal{nvStr(c.ID), nvInlines(c.Prefix), nvInlines(c.Suffix), nvConV(mode), nvInt(c.NoteNum), nvInt(c.Hash)}}
		}
		return nvConV("Cite", nvListV(cs), nvInlines(x.Inlines))
	case *Code:
		return nvConV("Code", nvAttr(x.Attr), nvStr(x.Text))
	case *Space:
		return nvConV("Space")
	case *SoftBreak:
		return nvConV("SoftBreak")
	case *LineBreak:
		return nvConV("LineBreak")
	case *Math:
		m := "InlineMath"
		if x.Type == DisplayMath {
			m = "DisplayMath"
		}
		return nvConV("Math", nvConV(m), nvStr(x.Text))
	case *RawInline:
		return nvConV("RawInline", nvConV("Format", nvStr(x.Format)), nvStr(x.Text))
	case *Link:
		return nvConV("Link", nvAttr(x.Attr), nvInlines(x.Inlines), nvTarget(x.Target))
	case *Image:
		return nvConV("Image", nvAttr(x.Attr), nvInlines(x.Inlines), nvTarget(x.Target))
	case *Note:
		return nvConV("Note", nvBlocks(x.Blocks))
	case *Span:
		return nvConV("Span", nvAttr(x.Attr), nvInlines(x.Inlines))
	}
	panic(fmt.Sprintf("nvInline: unknown %T", il))
}

func nvAlign(a Alignment) *NVal {
	switch a {
	case AlignLeft:
		return nvConV("AlignLeft")
	case AlignRight:
		return nvConV("AlignRight")
	case AlignCenter:
		return nvConV("AlignCenter")
	}
	return nvConV("AlignDefault")
}

func nvColWidth(w ColWidth) *NVal {
	if w.Default {
		return nvConV("ColWidthDefault")
	}
	return nvConV("ColWidth", nvDouble(w.Width))
}

func nvCaption(c Caption) *NVal {
	var short *NVal
	if c.HasShort {
		short = nvConV("Just", nvInlines(c.Short))
	} else {
		short = nvConV("Nothing")
	}
	return nvConV("Caption", short, nvBlocks(c.Blocks))
}

func nvRow(r Row) *NVal {
	cells := make([]*NVal, len(r.Cells))
	for i, c := range r.Cells {
		cells[i] = nvConV("Cell", nvAttr(c.Attr), nvAlign(c.Align), nvConV("RowSpan", nvInt(c.RowSpan)),
			nvConV("ColSpan", nvInt(c.ColSpan)), nvBlocks(c.Blocks))
	}
	return nvConV("Row", nvAttr(r.Attr), nvListV(cells))
}

func nvRows(rows []Row) *NVal {
	xs := make([]*NVal, len(rows))
	for i, r := range rows {
		xs[i] = nvRow(r)
	}
	return nvListV(xs)
}

func nvListAttrs(la ListAttributes) *NVal {
	styles := []string{"DefaultStyle", "Example", "Decimal", "LowerRoman", "UpperRoman", "LowerAlpha", "UpperAlpha"}
	delims := []string{"DefaultDelim", "Period", "OneParen", "TwoParens"}
	return nvTupleV(nvInt(la.Start), nvConV(styles[la.Style]), nvConV(delims[la.Delim]))
}

func nvBlock(b Block) *NVal {
	switch x := b.(type) {
	case *Plain:
		return nvConV("Plain", nvInlines(x.Inlines))
	case *Para:
		return nvConV("Para", nvInlines(x.Inlines))
	case *LineBlock:
		ls := make([]*NVal, len(x.Lines))
		for i, l := range x.Lines {
			ls[i] = nvInlines(l)
		}
		return nvConV("LineBlock", nvListV(ls))
	case *CodeBlock:
		return nvConV("CodeBlock", nvAttr(x.Attr), nvStr(x.Text))
	case *RawBlock:
		return nvConV("RawBlock", nvConV("Format", nvStr(x.Format)), nvStr(x.Text))
	case *BlockQuote:
		return nvConV("BlockQuote", nvBlocks(x.Blocks))
	case *OrderedList:
		items := make([]*NVal, len(x.Items))
		for i, it := range x.Items {
			items[i] = nvBlocks(it)
		}
		return nvConV("OrderedList", nvListAttrs(x.Attrs), nvListV(items))
	case *BulletList:
		items := make([]*NVal, len(x.Items))
		for i, it := range x.Items {
			items[i] = nvBlocks(it)
		}
		return nvConV("BulletList", nvListV(items))
	case *DefinitionList:
		items := make([]*NVal, len(x.Items))
		for i, it := range x.Items {
			defs := make([]*NVal, len(it.Defs))
			for j, d := range it.Defs {
				defs[j] = nvBlocks(d)
			}
			items[i] = nvTupleV(nvInlines(it.Term), nvListV(defs))
		}
		return nvConV("DefinitionList", nvListV(items))
	case *Header:
		return nvConV("Header", nvInt(x.Level), nvAttr(x.Attr), nvInlines(x.Inlines))
	case *HorizontalRule:
		return nvConV("HorizontalRule")
	case *Table:
		specs := make([]*NVal, len(x.ColSpecs))
		for i, s := range x.ColSpecs {
			specs[i] = nvTupleV(nvAlign(s.Align), nvColWidth(s.Width))
		}
		bodies := make([]*NVal, len(x.Bodies))
		for i, tb := range x.Bodies {
			bodies[i] = nvConV("TableBody", nvAttr(tb.Attr), nvConV("RowHeadColumns", nvInt(tb.RowHeadColumns)),
				nvRows(tb.Head), nvRows(tb.Body))
		}
		return nvConV("Table", nvAttr(x.Attr), nvCaption(x.Caption), nvListV(specs),
			nvConV("TableHead", nvAttr(x.Head.Attr), nvRows(x.Head.Rows)),
			nvListV(bodies),
			nvConV("TableFoot", nvAttr(x.Foot.Attr), nvRows(x.Foot.Rows)))
	case *Figure:
		return nvConV("Figure", nvAttr(x.Attr), nvCaption(x.Caption), nvBlocks(x.Blocks))
	case *Div:
		return nvConV("Div", nvAttr(x.Attr), nvBlocks(x.Blocks))
	}
	panic(fmt.Sprintf("nvBlock: unknown %T", b))
}

func nvMetaValue(m MetaValue) *NVal {
	switch x := m.(type) {
	case *MetaMap:
		return nvConV("MetaMap", nvMetaMapInner(x))
	case *MetaList:
		xs := make([]*NVal, len(x.Items))
		for i, it := range x.Items {
			xs[i] = nvMetaValue(it)
		}
		return nvConV("MetaList", nvListV(xs))
	case *MetaBool:
		if x.Value {
			return nvConV("MetaBool", nvConV("True"))
		}
		return nvConV("MetaBool", nvConV("False"))
	case *MetaString:
		return nvConV("MetaString", nvStr(x.Text))
	case *MetaInlines:
		return nvConV("MetaInlines", nvInlines(x.Inlines))
	case *MetaBlocks:
		return nvConV("MetaBlocks", nvBlocks(x.Blocks))
	}
	panic("nvMetaValue")
}

func nvMetaMapInner(m *MetaMap) *NVal {
	xs := make([]*NVal, len(m.Keys))
	for i, k := range m.Keys {
		xs[i] = nvTupleV(nvStr(k), nvMetaValue(m.Values[k]))
	}
	return nvConV("fromList", nvListV(xs))
}

func writeNative(doc *Pandoc, opts *WriterOptions) string {
	var v *NVal
	if opts.Standalone {
		meta := &NVal{kind: nvRec, name: "Meta", fields: []string{"unMeta"}, args: []*NVal{nvMetaMapInner(doc.Meta)}}
		v = nvConV("Pandoc", meta, nvBlocks(doc.Blocks))
	} else {
		v = nvBlocks(doc.Blocks)
	}
	cols := opts.Columns
	if opts.WrapText == WrapNone {
		cols = 1000000 // effectively no wrapping? pandoc uses writerColumns anyway
	}
	return pjRender(cols, 1.2, ppValue(v)) + "\n"
}
EOF
echo ok

