package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// ---- JSON writer ----

type jw struct {
	buf bytes.Buffer
}

func (w *jw) raw(s string) { w.buf.WriteString(s) }

func (w *jw) str(s string) {
	// aeson-style escaping: escapes ", \, control chars; non-ASCII preserved.
	w.buf.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			w.buf.WriteString(`\"`)
		case '\\':
			w.buf.WriteString(`\\`)
		case '\n':
			w.buf.WriteString(`\n`)
		case '\r':
			w.buf.WriteString(`\r`)
		case '\t':
			w.buf.WriteString(`\t`)
		case '\b':
			w.buf.WriteString(`\b`)
		case '\f':
			w.buf.WriteString(`\f`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&w.buf, `\u%04x`, r)
			} else {
				w.buf.WriteRune(r)
			}
		}
	}
	w.buf.WriteByte('"')
}

func (w *jw) tagged(t string, body func()) {
	w.raw(`{"t":`)
	w.str(t)
	if body != nil {
		w.raw(`,"c":`)
		body()
	}
	w.raw("}")
}

func (w *jw) list(n int, f func(i int)) {
	w.raw("[")
	for i := 0; i < n; i++ {
		if i > 0 {
			w.raw(",")
		}
		f(i)
	}
	w.raw("]")
}

func (w *jw) strList(xs []string) {
	w.list(len(xs), func(i int) { w.str(xs[i]) })
}

func (w *jw) attr(a Attr) {
	w.raw("[")
	w.str(a.ID)
	w.raw(",")
	w.strList(a.Classes)
	w.raw(",")
	w.list(len(a.KVs), func(i int) {
		w.raw("[")
		w.str(a.KVs[i][0])
		w.raw(",")
		w.str(a.KVs[i][1])
		w.raw("]")
	})
	w.raw("]")
}

func (w *jw) inlines(ils []Inline) {
	w.list(len(ils), func(i int) { w.inline(ils[i]) })
}

func (w *jw) blocks(bs []Block) {
	w.list(len(bs), func(i int) { w.block(bs[i]) })
}

func (w *jw) target(t Target) {
	w.raw("[")
	w.str(t.URL)
	w.raw(",")
	w.str(t.Title)
	w.raw("]")
}

func (w *jw) inline(il Inline) {
	switch x := il.(type) {
	case *Str:
		w.tagged("Str", func() { w.str(x.Text) })
	case *Emph:
		w.tagged("Emph", func() { w.inlines(x.Inlines) })
	case *Underline:
		w.tagged("Underline", func() { w.inlines(x.Inlines) })
	case *Strong:
