	default:
		panic(fmt.Sprintf("json inline: %T", il))
	}
}

func (w *jw) align(a Alignment) {
	switch a {
	case AlignLeft:
		w.tagged("AlignLeft", nil)
	case AlignRight:
		w.tagged("AlignRight", nil)
	case AlignCenter:
		w.tagged("AlignCenter", nil)
	default:
		w.tagged("AlignDefault", nil)
	}
}

func (w *jw) caption(c Caption) {
	w.raw("[")
	if c.HasShort {
		w.inlines(c.Short)
	} else {
		w.raw("null")
	}
	w.raw(",")
	w.blocks(c.Blocks)
	w.raw("]")
}

func (w *jw) rows(rows []Row) {
	w.list(len(rows), func(i int) {
		r := rows[i]
		w.raw("[")
		w.attr(r.Attr)
		w.raw(",")
		w.list(len(r.Cells), func(j int) {
			c := r.Cells[j]
			w.raw("[")
			w.attr(c.Attr)
			w.raw(",")
			w.align(c.Align)
			w.raw(",")
			w.raw(strconv.Itoa(c.RowSpan))
			w.raw(",")
			w.raw(strconv.Itoa(c.ColSpan))
			w.raw(",")
			w.blocks(c.Blocks)
			w.raw("]")
		})
		w.raw("]")
	})
}

func (w *jw) block(b Block) {
	switch x := b.(type) {
	case *Plain:
		w.tagged("Plain", func() { w.inlines(x.Inlines) })
	case *Para:
		w.tagged("Para", func() { w.inlines(x.Inlines) })
	case *LineBlock:
		w.tagged("LineBlock", func() {
			w.list(len(x.Lines), func(i int) { w.inlines(x.Lines[i]) })
		})
	case *CodeBlock:
		w.tagged("CodeBlock", func() {
			w.raw("[")
			w.attr(x.Attr)
			w.raw(",")
			w.str(x.Text)
			w.raw("]")
		})
	case *RawBlock:
		w.tagged("RawBlock", func() {
			w.raw("[")
			w.str(x.Format)
			w.raw(",")
			w.str(x.Text)
			w.raw("]")
		})
	case *BlockQuote:
		w.tagged("BlockQuote", func() { w.blocks(x.Blocks) })
	case *OrderedList:
		w.tagged("OrderedList", func() {
			w.raw("[[")
			w.raw(strconv.Itoa(x.Attrs.Start))
			w.raw(",")
			styles := []string{"DefaultStyle", "Example", "Decimal", "LowerRoman", "UpperRoman", "LowerAlpha", "UpperAlpha"}
			delims := []string{"DefaultDelim", "Period", "OneParen", "TwoParens"}
			w.tagged(styles[x.Attrs.Style], nil)
			w.raw(",")
			w.tagged(delims[x.Attrs.Delim], nil)
			w.raw("],")
			w.list(len(x.Items), func(i int) { w.blocks(x.Items[i]) })
			w.raw("]")
		})
	case *BulletList:
		w.tagged("BulletList", func() {
			w.list(len(x.Items), func(i int) { w.blocks(x.Items[i]) })
		})
	case *DefinitionList:
		w.tagged("DefinitionList", func() {
			w.list(len(x.Items), func(i int) {
				it := x.Items[i]
				w.raw("[")
				w.inlines(it.Term)
				w.raw(",")
				w.list(len(it.Defs), func(j int) { w.blocks(it.Defs[j]) })
				w.raw("]")
			})
		})
	case *Header:
		w.tagged("Header", func() {
			w.raw("[")
			w.raw(strconv.Itoa(x.Level))
			w.raw(",")
			w.attr(x.Attr)
			w.raw(",")
			w.inlines(x.Inlines)
			w.raw("]")
		})
	case *HorizontalRule:
		w.tagged("HorizontalRule", nil)
	case *Table:
		w.tagged("Table", func() {
			w.raw("[")
			w.attr(x.Attr)
			w.raw(",")
			w.caption(x.Caption)
			w.raw(",")
			w.list(len(x.ColSpecs), func(i int) {
				s := x.ColSpecs[i]
				w.raw("[")
				w.align(s.Align)
				w.raw(",")
				if s.Width.Default {
					w.tagged("ColWidthDefault", nil)
				} else {
					w.tagged("ColWidth", func() { w.raw(jsonFloat(s.Width.Width)) })
				}
				w.raw("]")
			})
			w.raw(",[")
			w.attr(x.Head.Attr)
			w.raw(",")
			w.rows(x.Head.Rows)
			w.raw("],")
			w.list(len(x.Bodies), func(i int) {
				tb := x.Bodies[i]
				w.raw("[")
				w.attr(tb.Attr)
				w.raw(",")
				w.raw(strconv.Itoa(tb.RowHeadColumns))
				w.raw(",")
				w.rows(tb.Head)
				w.raw(",")
				w.rows(tb.Body)
				w.raw("]")
			})
			w.raw(",[")
			w.attr(x.Foot.Attr)
			w.raw(",")
			w.rows(x.Foot.Rows)
			w.raw("]]")
		})
	case *Figure:
		w.tagged("Figure", func() {
			w.raw("[")
			w.attr(x.Attr)
			w.raw(",")
			w.caption(x.Caption)
			w.raw(",")
			w.blocks(x.Blocks)
			w.raw("]")
		})
	case *Div:
		w.tagged("Div", func() {
			w.raw("[")
			w.attr(x.Attr)
			w.raw(",")
			w.blocks(x.Blocks)
			w.raw("]")
		})
	default:
		panic(fmt.Sprintf("json block: %T", b))
	}
}

func jsonFloat(f float64) string {
	// aeson encodes doubles in shortest form; integers as e.g. 1.0? aeson uses
	// scientific notation rules: 0.5 -> 0.5, 1 -> 1.0? pandoc outputs e.g. 0.5
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.ContainsAny(s, ".e") {
		s += ".0"
	}
	return s
}

func (w *jw) metaValue(m MetaValue) {
	switch x := m.(type) {
	case *MetaMap:
		w.tagged("MetaMap", func() { w.metaMapInner(x) })
	case *MetaList:
		w.tagged("MetaList", func() {
			w.list(len(x.Items), func(i int) { w.metaValue(x.Items[i]) })
		})
	case *MetaBool:
		w.tagged("MetaBool", func() {
			if x.Value {
				w.raw("true")
			} else {
				w.raw("false")
			}
		})
	case *MetaString:
		w.tagged("MetaString", func() { w.str(x.Text) })
	case *MetaInlines:
		w.tagged("MetaInlines", func() { w.inlines(x.Inlines) })
	case *MetaBlocks:
		w.tagged("MetaBlocks", func() { w.blocks(x.Blocks) })
	}
}

func (w *jw) metaMapInner(m *MetaMap) {
	w.raw("{")
	for i, k := range m.Keys {
		if i > 0 {
			w.raw(",")
		}
		w.str(k)
		w.raw(":")
		w.metaValue(m.Values[k])
	}
	w.raw("}")
}

func writeJSON(doc *Pandoc) string {
	w := &jw{}
	w.raw(`{"pandoc-api-version":[1,23,1,2],"meta":`)
	w.metaMapInner(doc.Meta)
	w.raw(`,"blocks":`)
	w.blocks(doc.Blocks)
	w.raw("}")
	return w.buf.String() + "\n"
}

// ---- JSON reader ----

type jsonErr struct{ msg string }

func (e *jsonErr) Error() string { return e.msg }

func readJSON(input string) (*Pandoc, error) {
	var v interface{}
	dec := json.NewDecoder(strings.NewReader(input))
	dec.UseNumber()
	if err := dec.Decode(&v); err != nil {
		return nil, &jsonErr{"JSON parse error: " + err.Error()}
	}
	obj, ok := v.(map[string]interface{})
	if !ok {
		return nil, &jsonErr{"JSON parse error: expected object"}
	}
	doc := &Pandoc{Meta: newMetaMap()}
	if m, ok := obj["meta"].(map[string]interface{}); ok {
		doc.Meta = jrMetaMap(m)
	}
	if bs, ok := obj["blocks"].([]interface{}); ok {
		doc.Blocks = jrBlocks(bs)
	}
	return doc, nil
}

func jrMetaMap(m map[string]interface{}) *MetaMap {
	mm := newMetaMap()
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		mm.Set(k, jrMetaValue(m[k]))
	}
	return mm
}

func jrMetaValue(v interface{}) MetaValue {
	obj, ok := v.(map[string]interface{})
	if !ok {
		return &MetaString{}
	}
	t, _ := obj["t"].(string)
	c := obj["c"]
	switch t {
	case "MetaMap":
		m, _ := c.(map[string]interface{})
		return jrMetaMap(m)
	case "MetaList":
		xs, _ := c.([]interface{})
		ml := &MetaList{}
		for _, x := range xs {
			ml.Items = append(ml.Items, jrMetaValue(x))
		}
		return ml
	case "MetaBool":
		b, _ := c.(bool)
		return &MetaBool{Value: b}
	case "MetaString":
		s, _ := c.(string)
		return &MetaString{Text: s}
	case "MetaInlines":
		xs, _ := c.([]interface{})
		return &MetaInlines{Inlines: jrInlines(xs)}
	case "MetaBlocks":
		xs, _ := c.([]interface{})
		return &MetaBlocks{Blocks: jrBlocks(xs)}
	}
	return &MetaString{}
}

func jrStr(v interface{}) string {
	s, _ := v.(string)
	return s
}

func jrInt(v interface{}) int {
	switch n := v.(type) {
	case json.Number:
		i, _ := n.Int64()
		return int(i)
	case float64:
		return int(n)
	}
	return 0
}

func jrFloat(v interface{}) float64 {
	switch n := v.(type) {
	case json.Number:
		f, _ := n.Float64()
		return f
	case float64:
		return n
	}
	return 0
}

func jrList(v interface{}) []interface{} {
	xs, _ := v.([]interface{})
	return xs
}

func jrAttr(v interface{}) Attr {
	xs := jrList(v)
	if len(xs) < 3 {
		return Attr{}
	}
	a := Attr{ID: jrStr(xs[0])}
	for _, c := range jrList(xs[1]) {
		a.Classes = append(a.Classes, jrStr(c))
	}
	for _, kv := range jrList(xs[2]) {
		p := jrList(kv)
		if len(p) == 2 {
			a.KVs = append(a.KVs, [2]string{jrStr(p[0]), jrStr(p[1])})
		}
	}
	return a
}

func jrTarget(v interface{}) Target {
	xs := jrList(v)
	if len(xs) < 2 {
		return Target{}
	}
	return Target{URL: jrStr(xs[0]), Title: jrStr(xs[1])}
}

func jrTag(v interface{}) (string, interface{}) {
	obj, ok := v.(map[string]interface{})
	if !ok {
		return "", nil
	}
	t, _ := obj["t"].(string)
	return t, obj["c"]
}

func jrInlines(xs []interface{}) []Inline {
	out := make([]Inline, 0, len(xs))
	for _, x := range xs {
		if il := jrInline(x); il != nil {
			out = append(out, il)
		}
	}
	return out
}

func jrInline(v interface{}) Inline {
	t, c := jrTag(v)
	switch t {
	case "Str":
		return &Str{Text: jrStr(c)}
	case "Emph":
		return &Emph{Inlines: jrInlines(jrList(c))}
	case "Underline":
		return &Underline{Inlines: jrInlines(jrList(c))}
	case "Strong":
		return &Strong{Inlines: jrInlines(jrList(c))}
	case "Strikeout":
		return &Strikeout{Inlines: jrInlines(jrList(c))}
	case "Superscript":
		return &Superscript{Inlines: jrInlines(jrList(c))}
	case "Subscript":
		return &Subscript{Inlines: jrInlines(jrList(c))}
	case "SmallCaps":
		return &SmallCaps{Inlines: jrInlines(jrList(c))}
	case "Quoted":
		xs := jrList(c)
		qt, _ := jrTag(xs[0])
		q := &Quoted{Type: DoubleQuote, Inlines: jrInlines(jrList(xs[1]))}
		if qt == "SingleQuote" {
			q.Type = SingleQuote
		}
		return q
	case "Cite":
		xs := jrList(c)
		ci := &Cite{Inlines: jrInlines(jrList(xs[1]))}
		for _, cv := range jrList(xs[0]) {
			obj, _ := cv.(map[string]interface{})
			cit := Citation{ID: jrStr(obj["citationId"]), Prefix: jrInlines(jrList(obj["citationPrefix"])),
				Suffix: jrInlines(jrList(obj["citationSuffix"])), NoteNum: jrInt(obj["citationNoteNum"]), Hash: jrInt(obj["citationHash"])}
			mt, _ := jrTag(obj["citationMode"])
			switch mt {
			case "AuthorInText":
				cit.Mode = AuthorInText
			case "SuppressAuthor":
				cit.Mode = SuppressAuthor
			default:
				cit.Mode = NormalCitation
			}
			ci.Citations = append(ci.Citations, cit)
		}
		return ci
	case "Code":
		xs := jrList(c)
		return &Code{Attr: jrAttr(xs[0]), Text: jrStr(xs[1])}
	case "Space":
		return &Space{}
	case "SoftBreak":
		return &SoftBreak{}
	case "LineBreak":
		return &LineBreak{}
	case "Math":
		xs := jrList(c)
		mt, _ := jrTag(xs[0])
		m := &Math{Type: InlineMath, Text: jrStr(xs[1])}
		if mt == "DisplayMath" {
			m.Type = DisplayMath
		}
		return m
	case "RawInline":
		xs := jrList(c)
		return &RawInline{Format: jrStr(xs[0]), Text: jrStr(xs[1])}
	case "Link":
		xs := jrList(c)
		return &Link{Attr: jrAttr(xs[0]), Inlines: jrInlines(jrList(xs[1])), Target: jrTarget(xs[2])}
	case "Image":
		xs := jrList(c)
		return &Image{Attr: jrAttr(xs[0]), Inlines: jrInlines(jrList(xs[1])), Target: jrTarget(xs[2])}
	case "Note":
		return &Note{Blocks: jrBlocks(jrList(c))}
	case "Span":
		xs := jrList(c)
		return &Span{Attr: jrAttr(xs[0]), Inlines: jrInlines(jrList(xs[1]))}
	}
	return nil
}

func jrAlign(v interface{}) Alignment {
	t, _ := jrTag(v)
	switch t {
	case "AlignLeft":
		return AlignLeft
	case "AlignRight":
		return AlignRight
	case "AlignCenter":
		return AlignCenter
	}
	return AlignDefault
}

func jrCaption(v interface{}) Caption {
	xs := jrList(v)
	cap := Caption{}
	if len(xs) == 2 {
		if xs[0] != nil {
			cap.HasShort = true
			cap.Short = jrInlines(jrList(xs[0]))
		}
		cap.Blocks = jrBlocks(jrList(xs[1]))
	}
	return cap
}

func jrRows(v interface{}) []Row {
	var rows []Row
	for _, rv := range jrList(v) {
		rx := jrList(rv)
		r := Row{Attr: jrAttr(rx[0])}
		for _, cv := range jrList(rx[1]) {
			cx := jrList(cv)
			r.Cells = append(r.Cells, Cell{Attr: jrAttr(cx[0]), Align: jrAlign(cx[1]), RowSpan: jrInt(cx[2]), ColSpan: jrInt(cx[3]), Blocks: jrBlocks(jrList(cx[4]))})
		}
		rows = append(rows, r)
	}
	return rows
}

func jrBlocks(xs []interface{}) []Block {
	out := make([]Block, 0, len(xs))
	for _, x := range xs {
		if b := jrBlock(x); b != nil {
			out = append(out, b)
		}
	}
	return out
}

func jrBlocksList(v interface{}) [][]Block {
	var out [][]Block
	for _, x := range jrList(v) {
		out = append(out, jrBlocks(jrList(x)))
	}
	return out
}

func jrBlock(v interface{}) Block {
	t, c := jrTag(v)
	switch t {
	case "Plain":
		return &Plain{Inlines: jrInlines(jrList(c))}
	case "Para":
		return &Para{Inlines: jrInlines(jrList(c))}
	case "LineBlock":
		lb := &LineBlock{}
		for _, l := range jrList(c) {
			lb.Lines = append(lb.Lines, jrInlines(jrList(l)))
		}
		return lb
	case "CodeBlock":
		xs := jrList(c)
		return &CodeBlock{Attr: jrAttr(xs[0]), Text: jrStr(xs[1])}
	case "RawBlock":
		xs := jrList(c)
		return &RawBlock{Format: jrStr(xs[0]), Text: jrStr(xs[1])}
	case "BlockQuote":
		return &BlockQuote{Blocks: jrBlocks(jrList(c))}
	case "OrderedList":
		xs := jrList(c)
		la := jrList(xs[0])
		attrs := ListAttributes{Start: jrInt(la[0])}
		st, _ := jrTag(la[1])
		styles := map[string]ListNumberStyle{"DefaultStyle": DefaultStyle, "Example": Example, "Decimal": Decimal, "LowerRoman": LowerRoman, "UpperRoman": UpperRoman, "LowerAlpha": LowerAlpha, "UpperAlpha": UpperAlpha}
		delims := map[string]ListNumberDelim{"DefaultDelim": DefaultDelim, "Period": Period, "OneParen": OneParen, "TwoParens": TwoParens}
		attrs.Style = styles[st]
		dt, _ := jrTag(la[2])
		attrs.Delim = delims[dt]
		return &OrderedList{Attrs: attrs, Items: jrBlocksList(xs[1])}
	case "BulletList":
		return &BulletList{Items: jrBlocksList(c)}
	case "DefinitionList":
		dl := &DefinitionList{}
		for _, it := range jrList(c) {
			xs := jrList(it)
			dl.Items = append(dl.Items, DefItem{Term: jrInlines(jrList(xs[0])), Defs: jrBlocksList(xs[1])})
		}
		return dl
	case "Header":
		xs := jrList(c)
		return &Header{Level: jrInt(xs[0]), Attr: jrAttr(xs[1]), Inlines: jrInlines(jrList(xs[2]))}
	case "HorizontalRule":
		return &HorizontalRule{}
	case "Table":
		xs := jrList(c)
		t := &Table{Attr: jrAttr(xs[0]), Caption: jrCaption(xs[1])}
		for _, sv := range jrList(xs[2]) {
			sx := jrList(sv)
			cs := ColSpec{Align: jrAlign(sx[0])}
			wt, wc := jrTag(sx[1])
			if wt == "ColWidth" {
				cs.Width = ColWidth{Width: jrFloat(wc)}
			} else {
				cs.Width = ColWidth{Default: true}
			}
			t.ColSpecs = append(t.ColSpecs, cs)
		}
		hx := jrList(xs[3])
		t.Head = TableHead{Attr: jrAttr(hx[0]), Rows: jrRows(hx[1])}
		for _, bv := range jrList(xs[4]) {
			bx := jrList(bv)
			t.Bodies = append(t.Bodies, TableBody{Attr: jrAttr(bx[0]), RowHeadColumns: jrInt(bx[1]), Head: jrRows(bx[2]), Body: jrRows(bx[3])})
		}
		fx := jrList(xs[5])
		t.Foot = TableFoot{Attr: jrAttr(fx[0]), Rows: jrRows(fx[1])}
		return t
	case "Figure":
		xs := jrList(c)
		return &Figure{Attr: jrAttr(xs[0]), Caption: jrCaption(xs[1]), Blocks: jrBlocks(jrList(xs[2]))}
	case "Div":
		xs := jrList(c)
		return &Div{Attr: jrAttr(xs[0]), Blocks: jrBlocks(jrList(xs[1]))}
	}
	return nil
}
EOF
echo ok"}

