actions.command:
cd /workspace && cat > src/doclayout.go <<'EOF'
package main

import (
	"strings"
	"unicode"
)

// A port of the doclayout library (Text.DocLayout).

type dlKind int

const (
	dText dlKind = iota
	dBlock
	dVFill
	dPrefixed
	dBeforeNonBlank
	dFlush
	dBreakingSpace
	dAfterBreak
	dCarriageReturn
	dNewLine
	dBlankLines
	dConcat
	dEmpty
)

type Doc struct {
	kind  dlKind
	n     int      // width (Text/Block/VFill) or count (BlankLines)
	s     string   // text / prefix
	lines []string // Block
	a, b  *Doc
}

var (
	Empty         = &Doc{kind: dEmpty}
	BreakingSpace = &Doc{kind: dBreakingSpace}
	CR            = &Doc{kind: dCarriageReturn}
	NewLineDoc    = &Doc{kind: dNewLine}
	Blankline     = &Doc{kind: dBlankLines, n: 1}
)

func Blanklines(n int) *Doc { return &Doc{kind: dBlankLines, n: n} }

func (d *Doc) IsEmpty() bool {
	return d == nil || d.kind == dEmpty
}

// realLength computes display width (wide chars count 2, combining 0).
func realLength(s string) int {
	n := 0
	for _, r := range s {
		n += charWidth(r)
	}
	return n
}

func charWidth(r rune) int {
	if r < 0x20 {
		return 0
	}
	if r < 0x300 {
		return 1
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Cf, r) {
		return 0
	}
	if r == 0x200B {
		return 0
	}
	if isWideRune(r) {
		return 2
	}
	return 1
}

func isWideRune(r rune) bool {
	switch {
	case r >= 0x1100 && r <= 0x115F,
		r >= 0x2E80 && r <= 0x303E,
		r >= 0x3041 && r <= 0x33FF,
		r >= 0x3400 && r <= 0x4DBF,
		r >= 0x4E00 && r <= 0x9FFF,
		r >= 0xA000 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3,
		r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE4F,
		r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6,
		r >= 0x1F300 && r <= 0x1F64F,
		r >= 0x1F900 && r <= 0x1F9FF,
		r >= 0x20000 && r <= 0x2FFFD,
		r >= 0x30000 && r <= 0x3FFFD:
		return true
	}
	return false
}

// Text creates a text doc (no newlines expected).
func TextD(s string) *Doc {
	if s == "" {
		return Empty
	}
	return &Doc{kind: dText, n: realLength(s), s: s}
}

// Literal splits on newlines.
func Literal(s string) *Doc {
	if s == "" {
		return Empty
	}
	parts := strings.Split(s, "\n")
	var docs []*Doc
	for i, p := range parts {
		if i > 0 {
			docs = append(docs, NewLineDoc)
		}
		if p != "" {
			docs = append(docs, &Doc{kind: dText, n: realLength(p), s: p})
		}
	}
	return Cat(docs...)
}

func Cat(ds ...*Doc) *Doc {
	var r *Doc = Empty
	for _, d := range ds {
		r = Concat(r, d)
	}
	return r
}

func Concat(a, b *Doc) *Doc {
	if a == nil || a.kind == dEmpty {
		if b == nil {
			return Empty
		}
		return b
	}
	if b == nil || b.kind == dEmpty {
		return a
	}
	return &Doc{kind: dConcat, a: a, b: b}
}

// a <+> b
func SpaceCat(a, b *Doc) *Doc {
	if a.IsEmpty() {
		return b
	}
	if b.IsEmpty() {
		return a
	}
	return Cat(a, BreakingSpace, b)
}

// a $$ b
func Above(a, b *Doc) *Doc {
	if a.IsEmpty() {
		return b
	}
	if b.IsEmpty() {
		return a
	}
	return Cat(a, CR, b)
}

// a $+$ b
func AboveBlank(a, b *Doc) *Doc {
	if a.IsEmpty() {
		return b
	}
	if b.IsEmpty() {
		return a
	}
	return Cat(a, Blankline, b)
}

func Hsep(ds []*Doc) *Doc {
	r := Empty
	for i := len(ds) - 1; i >= 0; i-- {
		r = SpaceCat(ds[i], r)
	}
	return r
}

func Hcat(ds []*Doc) *Doc { return Cat(ds...) }

func Vcat(ds []*Doc) *Doc {
	r := Empty
	for i := len(ds) - 1; i >= 0; i-- {
		r = Above(ds[i], r)
	}
	return r
}

func Vsep(ds []*Doc) *Doc {
	r := Empty
	for i := len(ds) - 1; i >= 0; i-- {
		r = AboveBlank(ds[i], r)
	}
	return r
}

func Nest(ind int, d *Doc) *Doc {
	return &Doc{kind: dPrefixed, s: strings.Repeat(" ", ind), a: d}
}

func Hang(ind int, start, d *Doc) *Doc {
	return Concat(start, Nest(ind, d))
}

func Prefixed(pref string, d *Doc) *Doc {
	return &Doc{kind: dPrefixed, s: pref, a: d}
}

func Flush(d *Doc) *Doc          { return &Doc{kind: dFlush, a: d} }
func BeforeNonBlank(d *Doc) *Doc { return &Doc{kind: dBeforeNonBlank, a: d} }
func AfterBreak(s string) *Doc   { return &Doc{kind: dAfterBreak, s: s} }
func VFill(w int, s string) *Doc { return &Doc{kind: dVFill, n: w, s: s} }

// Nowrap replaces breaking spaces with literal spaces (top level only).
func Nowrap(d *Doc) *Doc {
	parts := unfoldD(d)
	out := make([]*Doc, len(parts))
	for i, p := range parts {
		if p.kind == dBreakingSpace {
			out[i] = &Doc{kind: dText, n: 1, s: " "}
		} else {
			out[i] = p
		}
	}
	return Cat(out...)
}

func unfoldD(d *Doc) []*Doc {
	var out []*Doc
	var go_ func(d *Doc)
	go_ = func(d *Doc) {
		switch d.kind {
		case dEmpty:
		case dConcat:
			go_(d.a)
			go_(d.b)
		default:
			out = append(out, d)
		}
	}
	go_(d)
	return out
}

// Chomp removes trailing blank lines / spaces.
func Chomp(d *Doc) *Doc {
	switch d.kind {
	case dBlankLines, dCarriageReturn, dNewLine, dBreakingSpace:
		return Empty
	case dPrefixed:
		return &Doc{kind: dPrefixed, s: d.s, a: Chomp(d.a)}
	case dConcat:
		b := Chomp(d.b)
		if b.IsEmpty() {
			return Chomp(d.a)
		}
		return Concat(d.a, b)
	}
	return d
}

// Nestle removes leading blank lines.
func Nestle(d *Doc) *Doc {
	switch d.kind {
	case dBlankLines, dCarriageReturn, dNewLine:
		return Empty
	case dConcat:
		a := Nestle(d.a)
		if a.IsEmpty() {
			return Nestle(d.b)
		}
		return Concat(a, d.b)
	}
	return d
}

func Block(filler func(string) string, width int, d *Doc) *Doc {
	if width < 1 && !d.IsEmpty() {
		width = 1
	}
	rendered := Render(width, d)
	lines := chopLines(width, rendered)
	for i, l := range lines {
		lines[i] = filler(l)
	}
	return &Doc{kind: dBlock, n: width, lines: lines}
}

func LBlock(w int, d *Doc) *Doc {
	return Block(func(s string) string { return s }, w, d)
}

func RBlock(w int, d *Doc) *Doc {
	return Block(func(s string) string {
		return strings.Repeat(" ", maxInt(0, w-realLength(s))) + s
	}, w, d)
}

func CBlock(w int, d *Doc) *Doc {
	return Block(func(s string) string {
		return strings.Repeat(" ", maxInt(0, (w-realLength(s))/2)) + s
	}, w, d)
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func chopLines(n int, s string) []string {
	lines := strings.Split(s, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	var out []string
	for _, l := range lines {
		if realLength(l) <= n {
			out = append(out, l)
			continue
		}
		// chop into pieces of at most n columns
		cur := ""
		w := 0
		for _, r := range l {
			cw := charWidth(r)
			if w+cw > n && cur != "" {
				out = append(out, cur)
				cur = ""
				w = 0
			}
			cur += string(r)
			w += cw
		}
		if cur != "" {
			out = append(out, cur)
		}
	}
	return out
}

// Offset: maximum line width when rendered without wrapping.
func Offset(d *Doc) int {
	return maxLineLen(Render(0, d))
}

// MinOffset: maximum line width when rendered at width 0.
func MinOffset(d *Doc) int {
	return maxLineLen(renderWith(0, true, d))
}

func maxLineLen(s string) int {
	m := 0
	for _, l := range strings.Split(s, "\n") {
		if n := realLength(l); n > m {
			m = n
		}
	}
	return m
}

func Height(d *Doc) int {
	return len(strings.Split(Render(0, d), "\n"))
}

// ---- Rendering ----

type renderState struct {
	out        strings.Builder
	prefix     string
	usePrefix  bool
	lineLength int
	hasLimit   bool
	column     int
	newlines   int
}

// Render renders a doc; lineLength <= 0 means no wrapping.
func Render(lineLength int, d *Doc) string {
	return renderWith(lineLength, lineLength > 0, d)
}

func renderWith(lineLength int, hasLimit bool, d *Doc) string {
	st := &renderState{usePrefix: true, lineLength: lineLength, hasLimit: hasLimit, newlines: 2}
	st.renderDoc(d)
	return st.out.String()
}

func (st *renderState) renderDoc(d *Doc) {
	st.renderList(normalizeDocs(unfoldD(d)))
}

func normalizeDocs(xs []*Doc) []*Doc {
	// implement the rewrite rules iteratively
	var out []*Doc
	i := 0
	for i < len(xs) {
		x := xs[i]
		var next *Doc
		if i+1 < len(xs) {
			next = xs[i+1]
		}
		isLast := next == nil
		switch x.kind {
		case dConcat, dEmpty:
			i++
			continue
		case dNewLine:
			if isLast {
				xs[i] = CR
				continue
			}
			if next.kind == dBlankLines {
				xs[i+1] = next
				i++
				continue
			}
			if next.kind == dBreakingSpace || next.kind == dCarriageReturn {
				// drop next
				xs = append(xs[:i+1], xs[i+2:]...)
				continue
			}
		case dBlankLines:
			if isLast {
				xs[i] = CR
				continue
			}
			switch next.kind {
			case dBlankLines:
				m := x.n
				if next.n > m {
					m = next.n
				}
				xs[i+1] = Blanklines(m)
				i++
				continue
			case dBreakingSpace, dCarriageReturn, dNewLine:
				xs = append(xs[:i+1], xs[i+2:]...)
				continue
			}
		case dBreakingSpace:
			if isLast {
				i++
				continue
			}
			switch next.kind {
			case dCarriageReturn, dNewLine, dBlankLines, dBreakingSpace:
				// drop this
				xs = append(xs[:i], xs[i+1:]...)
				continue
			}
		case dCarriageReturn:
			if !isLast {
				switch next.kind {
				case dCarriageReturn, dBreakingSpace:
					xs = append(xs[:i+1], xs[i+2:]...)
					continue
				case dBlankLines:
					xs = append(xs[:i], xs[i+1:]...)
					continue
				}
			}
		}
		out = append(out, x)
		i++
	}
	return out
}

func offsetOf(d *Doc) int {
	switch d.kind {
	case dText, dBlock, dVFill:
		return d.n
	case dBreakingSpace:
		return 1
	}
	return 0
}

func isBreakable(d *Doc) bool {
	switch d.kind {
	case dBreakingSpace, dCarriageReturn, dNewLine, dBlankLines:
		return true
	case dConcat:
		if d.a.kind == dEmpty {
			return isBreakable(d.b)
		}
		return isBreakable(d.a)
	}
	return false
}

func startsBlankStr(s string) bool {
	for _, r := range s {
		return unicode.IsSpace(r)
	}
	return true
}

func startsBlank(d *Doc) bool {
	switch d.kind {
	case dText:
		return startsBlankStr(d.s)
	case dBlock:
		if d.n <= 0 {
			return false
		}
		for _, l := range d.lines {
			if !startsBlankStr(l) {
				return false
			}
		}
		return true
	case dVFill:
		return d.n > 0 && startsBlankStr(d.s)
	case dPrefixed, dBeforeNonBlank, dFlush:
		return startsBlank(d.a)
	case dBreakingSpace, dCarriageReturn, dNewLine, dBlankLines, dEmpty:
		return true
	case dAfterBreak:
		return startsBlankStr(d.s)
	case dConcat:
		if d.a.kind == dEmpty {
			return startsBlank(d.b)
		}
		return startsBlank(d.a)
	}
	return false
}

func (st *renderState) outp(off int, s string) {
	if st.column == 0 && st.usePrefix && st.prefix != "" {
		st.out.WriteString(st.prefix)
		st.column += realLength(st.prefix)
	}
	st.out.WriteString(s)
	st.column += off
	st.newlines = 0
}

func (st *renderState) newline() {
	if st.column == 0 && st.usePrefix && st.prefix != "" {
		pref := strings.TrimRightFunc(st.prefix, unicode.IsSpace)
		st.out.WriteString(pref)
		st.column += realLength(pref)
	}
	st.out.WriteByte('\n')
	st.column = 0
	st.newlines++
}

type isBlock struct {
	w     int
	lines []string
	vfill bool
	fill  string
}

func toIsBlock(d *Doc) (isBlock, bool) {
	switch d.kind {
	case dBlock:
		return isBlock{w: d.n, lines: d.lines}, true
	case dVFill:
		return isBlock{w: d.n, vfill: true, fill: d.s}, true
	}
	return isBlock{}, false
}

func mergeBlocks(addSpace bool, b1, b2 isBlock) *Doc {
	if b1.vfill && b2.vfill {
		return &Doc{kind: dVFill, n: b1.w + b2.w, s: b1.fill + b2.fill}
	}
	n1, n2 := len(b1.lines), len(b2.lines)
	if b1.vfill {
		n1 = n2
	}
	if b2.vfill {
		n2 = n1
	}
	n := n1
	if n2 > n {
		n = n2
	}
	get := func(b isBlock, i int) string {
		if b.vfill {
			return b.fill
		}
		if i < len(b.lines) {
			return b.lines[i]
		}
		return ""
	}
	w := b1.w + b2.w
	if addSpace {
		w++
	}
	lines := make([]string, n)
	for i := 0; i < n; i++ {
		l1 := get(b1, i)
		l2 := get(b2, i)
		pad := b1.w - realLength(l1)
		if pad < 0 {
			pad = 0
		}
		s := l1 + strings.Repeat(" ", pad)
		if addSpace && l2 != "" {
			s += " "
		} else if addSpace {
			s += " "
		}
		lines[i] = s + l2
	}
	return &Doc{kind: dBlock, n: w, lines: lines}
}

func (st *renderState) renderList(xs []*Doc) {
	for i := 0; i < len(xs); i++ {
		x := xs[i]
		switch x.kind {
		case dEmpty, dConcat:
			continue
		case dText:
			st.outp(x.n, x.s)
		case dPrefixed:
			oldPref := st.prefix
			st.prefix = st.prefix + x.s
			st.renderDoc(x.a)
			st.prefix = oldPref
		case dFlush:
			old := st.usePrefix
			st.usePrefix = false
			st.renderDoc(x.a)
			st.usePrefix = old
		case dBeforeNonBlank:
			if i+1 < len(xs) {
				if !startsBlank(xs[i+1]) {
					st.renderDoc(x.a)
				}
			}
		case dBlankLines:
			if st.newlines <= x.n {
				for k := 0; k < 1+x.n-st.newlines; k++ {
					st.newline()
				}
			}
		case dCarriageReturn:
			if st.newlines == 0 {
				st.newline()
			}
		case dNewLine:
			st.newline()
		case dBreakingSpace:
			j := i + 1
			for j < len(xs) && xs[j].kind == dBreakingSpace {
				j++
			}
			off := 0
			for k := j; k < len(xs) && !isBreakable(xs[k]); k++ {
				off += offsetOf(xs[k])
			}
			if st.hasLimit && st.column+1+off > st.lineLength {
				st.newline()
			} else if st.column > 0 {
				st.outp(1, " ")
			}
			i = j - 1
		case dAfterBreak:
			if st.newlines > 0 {
				st.outp(realLength(x.s), x.s)
			}
		case dBlock, dVFill:
			b1, _ := toIsBlock(x)
			// merge with following blocks
			if i+1 < len(xs) {
				if b2, ok := toIsBlock(xs[i+1]); ok {
					xs[i+1] = mergeBlocks(false, b1, b2)
					continue
				}
				if i+2 < len(xs) && xs[i+1].kind == dBreakingSpace {
					if b2, ok := toIsBlock(xs[i+2]); ok {
						xs[i+2] = mergeBlocks(true, b1, b2)
						i++
						continue
					}
				}
			}
			if x.kind == dVFill {
				// render as a single line
				st.outp(x.n, x.s)
				continue
			}
			oldPref := st.prefix
			if n := st.column - realLength(oldPref); n > 0 {
				st.prefix = oldPref + strings.Repeat(" ", n)
			}
			for k, l := range x.lines {
				if k > 0 {
					if st.newlines == 0 {
						st.newline()
					}
				}
				st.outp(0, l)
				st.column += realLength(l)
			}
			st.prefix = oldPref
		}
	}
}
