package main

import (
	"strings"
	"unicode"
)

type htmlTagKind int

const (
	tagOpen htmlTagKind = iota
	tagClose
	tagComment
	tagDecl // <!DOCTYPE ...>, <?...?>, <![CDATA[...]]>
)

type HTMLTag struct {
	Kind        htmlTagKind
	Name        string // lowercased
	Attrs       [][2]string
	SelfClosing bool
	Raw         string
	Comment     string
}

func (t *HTMLTag) Attr(k string) (string, bool) {
	for _, a := range t.Attrs {
		if a[0] == k {
			return a[1], true
		}
	}
	return "", false
}

func isTagNameStart(r rune) bool { return unicode.IsLetter(r) }
func isTagNameChar(r rune) bool {
	return isAlphaNum(r) || r == '-' || r == '_' || r == ':' || r == '.'
}

// parseHTMLTag tries to parse an HTML tag starting at rs[pos] (which must be '<').
// Returns the tag and the number of runes consumed, or ok=false.
func parseHTMLTag(rs []rune, pos int) (tag HTMLTag, n int, ok bool) {
	if pos >= len(rs) || rs[pos] != '<' {
		return
	}
	i := pos + 1
	if i >= len(rs) {
		return
	}
	// comment
	if hasPrefixRunes(rs, i, "!--") {
		j := i + 3
		end := indexRunes(rs, j, "-->")
		if end < 0 {
			return
		}
		tag = HTMLTag{Kind: tagComment, Comment: string(rs[j:end]), Raw: string(rs[pos : end+3])}
		return tag, end + 3 - pos, true
	}
	if hasPrefixRunes(rs, i, "![CDATA[") {
		end := indexRunes(rs, i, "]]>")
		if end < 0 {
			return
		}
		tag = HTMLTag{Kind: tagDecl, Name: "![CDATA[", Raw: string(rs[pos : end+3])}
		return tag, end + 3 - pos, true
	}
