	q := newMdP(s, p.st)
	q.inList = p.inList
	q.inHtmlBlock = p.inHtmlBlock
	q.divLevel = p.divLevel
	q.allowLineBreaks = p.allowLineBreaks
	q.allowLinks = p.allowLinks
	q.quoteCtx = p.quoteCtx
	q.inNote = p.inNote
	q.inTable = p.inTable
	return q
}

func (p *mdP) ext(name string) bool { return p.st.exts.Has(name) }

// ---- primitive helpers ----

func (p *mdP) eof() bool { return p.pos >= len(p.s) }

func (p *mdP) peek() rune {
	if p.pos < len(p.s) {
		return p.s[p.pos]
	}
	return 0
}

func (p *mdP) peekAt(off int) rune {
	if p.pos+off < len(p.s) && p.pos+off >= 0 {
		return p.s[p.pos+off]
	}
	return 0
}

func (p *mdP) char(c rune) bool {
	if p.pos < len(p.s) && p.s[p.pos] == c {
		p.pos++
		return true
	}
	return false
}

func (p *mdP) str(s string) bool {
	save := p.pos
	for _, r := range s {
		if !p.char(r) {
			p.pos = save
			return false
		}
	}
	return true
}

func (p *mdP) lookingAt(s string) bool {
	return hasPrefixRunes(p.s, p.pos, s)
}

func (p *mdP) satisfy(f func(rune) bool) (rune, bool) {
	if p.pos < len(p.s) && f(p.s[p.pos]) {
		r := p.s[p.pos]
		p.pos++
		return r, true
	}
	return 0, false
}

func (p *mdP) many(f func(rune) bool) string {
	start := p.pos
	for p.pos < len(p.s) && f(p.s[p.pos]) {
		p.pos++
	}
	return string(p.s[start:p.pos])
}

func (p *mdP) many1(f func(rune) bool) (string, bool) {
	s := p.many(f)
	return s, len(s) > 0
}

func (p *mdP) skipSpaces() {
	for p.pos < len(p.s) && isSpaceChar(p.s[p.pos]) {
		p.pos++
	}
}

func (p *mdP) skipSpaces1() bool {
	if !isSpaceChar(p.peek()) {
		return false
	}
	p.skipSpaces()
	return true
}

func (p *mdP) newline() bool {
	return p.char('\n')
}

// blankline: skipSpaces then newline
func (p *mdP) blankline() bool {
	save := p.pos
	p.skipSpaces()
	if p.newline() {
		return true
	}
	p.pos = save
	return false
}

func (p *mdP) blanklines() (string, bool) {
	start := p.pos
	n := 0
	for p.blankline() {
		n++
	}
	return string(p.s[start:p.pos]), n > 0
}

func (p *mdP) isBlankLineAhead() bool {
	save := p.pos
	ok := p.blankline()
	p.pos = save
	return ok
}

// anyLine: consume up to and including newline; returns the line without newline.
func (p *mdP) anyLine() (string, bool) {
	if p.eof() {
		return "", false
	}
	start := p.pos
	for p.pos < len(p.s) && p.s[p.pos] != '\n' {
		p.pos++
	}
	line := string(p.s[start:p.pos])
	if p.pos < len(p.s) {
		p.pos++ // newline
		return line, true
	}
	// no newline at eof: pandoc's anyLine requires newline... but input always ends with \n
	return line, true
}

func (p *mdP) anyLineNewline() (string, bool) {
	l, ok := p.anyLine()
	if !ok {
		return "", false
	}
	return l + "\n", true
}

// nonindentSpaces: up to tabStop-1 spaces
func (p *mdP) nonindentSpaces() string {
	start := p.pos
	n := 0
	for n < p.st.tabStop-1 && p.char(' ') {
		n++
	}
	return string(p.s[start:p.pos])
}

func (p *mdP) skipNonindentSpaces() int {
	return len(p.nonindentSpaces())
}

// indentSpaces: exactly tabStop spaces (or a tab)
func (p *mdP) indentSpaces() bool {
	save := p.pos
	for i := 0; i < p.st.tabStop; i++ {
		if !p.char(' ') {
			p.pos = save
			return p.char('\t')
		}
	}
	return true
}

func (p *mdP) gobbleSpaces(n int) bool {
	save := p.pos
	for i := 0; i < n; i++ {
		if !p.char(' ') {
			p.pos = save
			return false
		}
	}
	return true
}

func (p *mdP) gobbleAtMostSpaces(n int) int {
	c := 0
	for c < n && p.char(' ') {
		c++
	}
	return c
}

// spnl: skip spaces, optional newline, skip spaces
func (p *mdP) spnl() {
	p.skipSpaces()
	if p.newline() {
		p.skipSpaces()
	}
}

func (p *mdP) restOfLine() string {
	i := p.pos
	for i < len(p.s) && p.s[i] != '\n' {
		i++
	}
	return string(p.s[p.pos:i])
}

// ---- Reader entry ----

func readMarkdown(input string, exts *ExtSet, opts *ReaderOptions) (*Pandoc, []string) {
	st := &mdState{
		refs:        map[string]refDef{},
		notes:       map[string][]Block{},
		headerKeys:  map[string]refDef{},
		identifiers: map[string]bool{},
		meta:        newMetaMap(),
		exts:        exts,
		tabStop:     opts.TabStop,
		columns:     opts.Columns,
		abbrevs:     defaultAbbrevs(),
		indentedCodeClasses: opts.IndentedCodeClasses,
		defaultImageExt: opts.DefaultImageExtension,
	}
	text := input
	if !opts.PreserveTabs {
		text = tabFilter(opts.TabStop, text)
	} else {
		text = strings.ReplaceAll(text, "\r\n", "\n")
	}
	// strip BOM
	text = strings.TrimPrefix(text, "\uFEFF")
	text += "\n\n"
	p := newMdP(text, st)
	// pandoc title block
	if st.exts.Has("pandoc_title_block") {
		p.titleBlock()
	}
	blocks := p.parseBlocks()
	// resolve placeholders
	blocks = p.resolveBlocks(blocks)
	meta := st.meta
	// resolve meta inlines too
	for _, k := range meta.Keys {
		meta.Values[k] = p.resolveMeta(meta.Values[k])
	}
	return &Pandoc{Meta: meta, Blocks: blocks}, st.warnings
}

type ReaderOptions struct {
	TabStop               int
	Columns               int
	PreserveTabs          bool
	IndentedCodeClasses   []string
	DefaultImageExtension string
	StripComments         bool
}

func defaultAbbrevs() map[string]bool {
	m := map[string]bool{}
	for _, a := range strings.Fields("Mr. Mrs. Ms. Capt. Dr. Prof. Gen. Gov. e.g. i.e. Sgt. St. vol. vs. Sen. Reps. Rep. Pres. Hon. Rev. Ph.D. M.D. M.A. p. pp. ch. sec. cf. cp.") {
		m[a] = true
	}
	return m
}

// ---- Block parsing ----

func (p *mdP) parseBlocks() []Block {
	var out []Block
	for !p.eof() {
		bs, ok := p.block()
		if !ok {
			// should not happen; skip a char to avoid infinite loop
			p.pos++
			continue
		}
		out = append(out, bs...)
	}
	return out
}

func (p *mdP) block() ([]Block, bool) {
	if _, ok := p.blanklines(); ok {
		return nil, true
	}
	type bp func() ([]Block, bool)
	parsers := []bp{
		p.codeBlockFenced,
		p.yamlMetaBlock,
		p.bulletList,
		p.divHtml,
		p.divFenced,
		p.header,
		p.htmlBlock,
		p.table,
		p.codeBlockIndented,
		p.rawTeXBlock,
		p.lineBlock,
		p.blockQuote,
		p.hrule,
		p.orderedList,
		p.definitionList,
		p.noteBlock,
		p.referenceKey,
		p.para,
		p.plain,
	}
	for _, f := range parsers {
		save := p.pos
		if bs, ok := f(); ok {
			return bs, true
		}
		p.pos = save
	}
	return nil, false
}

// ---- title block ----

func (p *mdP) titleBlock() {
	save := p.pos
	if !p.char('%') {
		p.pos = save
		return
	}
	p.pos = save
	// title line(s)
	title, ok := p.titleLine()
	if !ok {
		p.pos = save
		return
	}
	var authors []string
	var date string
	if p.char('%') {
		p.skipSpaces()
		// authors: rest of line, plus continuation lines indented
		first := p.restOfLine()
		p.anyLine()
		var lines []string
		if trimSpace(first) != "" {
			lines = append(lines, first)
		}
		for {
			s2 := p.pos
			if p.peek() == ' ' && !p.isBlankLineAhead() {
				l, _ := p.anyLine()
				lines = append(lines, l)
				continue
			}
			p.pos = s2
			break
		}
		for _, l := range lines {
			for _, a := range strings.Split(l, ";") {
				if t := trimSpace(a); t != "" {
					authors = append(authors, t)
				}
			}
		}
		if p.char('%') {
			p.skipSpaces()
			date = trimSpace(p.restOfLine())
			p.anyLine()
		}
	}
	p.blanklines()
	if trimSpace(title) != "" {
		ils := p.parseInlinesStr(trimSpace(title))
		p.st.meta.Set("title", &MetaInlines{Inlines: ils})
	}
	if len(authors) > 0 {
		ml := &MetaList{}
		for _, a := range authors {
			ml.Items = append(ml.Items, &MetaInlines{Inlines: p.parseInlinesStr(a)})
		}
		p.st.meta.Set("author", ml)
	}
	if date != "" {
		p.st.meta.Set("date", &MetaInlines{Inlines: p.parseInlinesStr(date)})
	}
}

func (p *mdP) titleLine() (string, bool) {
	if !p.char('%') {
		return "", false
	}
	p.skipSpaces()
	first := p.restOfLine()
	p.anyLine()
	lines := []string{first}
	for {
		s := p.pos
		if p.peek() == ' ' && !p.isBlankLineAhead() {
			l, _ := p.anyLine()
			lines = append(lines, trimSpace(l))
			continue
		}
		p.pos = s
		break
	}
	return strings.Join(lines, " "), true
}

// parseInlinesStr parses a string as inlines (trimmed).
func (p *mdP) parseInlinesStr(s string) []Inline {
	q := p.sub(s)
	return trimInlines(q.inlines())
}

func (p *mdP) parseBlocksStr(s string) []Block {
	q := p.sub(s)
	return q.parseBlocks()
}

// ---- Headers ----

func (p *mdP) header() ([]Block, bool) {
	if bs, ok := p.atxHeader(); ok {
		return bs, true
	}
	return p.setextHeader()
}

func (p *mdP) atxHeader() ([]Block, bool) {
	save := p.pos
	hashes := p.many(func(r rune) bool { return r == '#' })
	level := len(hashes)
	if level == 0 || level > 6 {
		p.pos = save
		return nil, false
	}
	// not a fancy list marker "#."
	if p.ext("fancy_lists") && (p.peek() == '.' || p.peek() == ')') {
		p.pos = save
		return nil, false
	}
	if p.ext("space_in_atx_header") {
		if !(isSpaceChar(p.peek()) || p.peek() == '\n') {
			p.pos = save
			return nil, false
		}
	}
	p.skipSpaces()
	oldALB := p.allowLineBreaks
	p.allowLineBreaks = false
	rawStart := p.pos
	var ils []Inline
	for {
		if p.atxClosingAhead() {
			break
		}
		x, ok := p.inline()
		if !ok {
			break
		}
		ils = meldInlines(ils, x)
	}
	raw := string(p.s[rawStart:p.pos])
	p.allowLineBreaks = oldALB
	attr, ok := p.atxClosing()
	if !ok {
		p.pos = save
		return nil, false
	}
	ils = trimInlines(ils)
	attr = p.registerHeader(ils, raw, attr)
	return []Block{&Header{Level: level, Attr: attr, Inlines: ils}}, true
}

func (p *mdP) atxClosingAhead() bool {
	save := p.pos
	_, ok := p.atxClosing()
	p.pos = save
	return ok
}

func (p *mdP) atxClosing() (Attr, bool) {
	save := p.pos
	for p.char('#') {
	}
	p.skipSpaces()
	attr := Attr{}
	if p.ext("header_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	if _, ok := p.blanklines(); !ok {
		p.pos = save
		return Attr{}, false
	}
	return attr, true
}

func (p *mdP) setextHeader() ([]Block, bool) {
	save := p.pos
	// lookahead: a line followed by a line of = or -
	line := p.restOfLine()
	if trimSpace(line) == "" {
		return nil, false
	}
	nlPos := p.pos + len([]rune(line))
	if nlPos >= len(p.s) {
		return nil, false
	}
	// check underline
	i := nlPos + 1
	if i >= len(p.s) || (p.s[i] != '=' && p.s[i] != '-') {
		return nil, false
	}
	uc := p.s[i]
	j := i
	for j < len(p.s) && p.s[j] == uc {
		j++
	}
	k := j
	for k < len(p.s) && isSpaceChar(p.s[k]) {
		k++
	}
	if k >= len(p.s) || p.s[k] != '\n' {
		return nil, false
	}
	p.skipSpaces()
	oldALB := p.allowLineBreaks
	p.allowLineBreaks = false
	rawStart := p.pos
	var ils []Inline
	for p.pos < nlPos {
		if p.setextHeaderEndAhead(nlPos) {
			break
		}
		x, ok := p.inline()
		if !ok {
			break
		}
		ils = meldInlines(ils, x)
	}
	raw := string(p.s[rawStart:p.pos])
	p.allowLineBreaks = oldALB
	attr := Attr{}
	p.skipSpaces()
	if p.ext("header_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	p.skipSpaces()
	if !p.newline() {
		p.pos = save
		return nil, false
	}
	// underline
	for p.char(uc) {
	}
	if _, ok := p.blanklines(); !ok {
		p.pos = save
		return nil, false
	}
	level := 1
	if uc == '-' {
		level = 2
	}
	ils = trimInlines(ils)
	attr = p.registerHeader(ils, raw, attr)
	return []Block{&Header{Level: level, Attr: attr, Inlines: ils}}, true
}

func (p *mdP) setextHeaderEndAhead(nlPos int) bool {
	save := p.pos
	defer func() { p.pos = save }()
	p.skipSpaces()
	if p.ext("header_attributes") {
		if _, ok := p.attributes(); ok {
			p.skipSpaces()
			return p.pos == nlPos
		}
	}
	return p.pos == nlPos
}

func (p *mdP) registerHeader(ils []Inline, raw string, attr Attr) Attr {
	raw = trimSpace(raw)
	if attr.ID == "" && p.ext("auto_identifiers") {
		gfm := p.ext("gfm_auto_identifiers")
		ascii := p.ext("ascii_identifiers")
		attr.ID = uniqueIdent(ils, p.st.identifiers, gfm, ascii)
	}
	if attr.ID != "" {
		p.st.identifiers[attr.ID] = true
	}
	if raw != "" && p.ext("implicit_header_references") {
		key := toKey(raw)
		if _, exists := p.st.headerKeys[key]; !exists {
			p.st.headerKeys[key] = refDef{URL: "#" + attr.ID, Title: "", Attr: attr}
		}
	}
	return attr
}

// ---- attributes {#id .class key=val} ----

func (p *mdP) attributes() (Attr, bool) {
	save := p.pos
	if !p.char('{') {
		return Attr{}, false
	}
	p.spnl()
	attr := Attr{}
	for {
		s := p.pos
		if ok := p.attribute(&attr); !ok {
			p.pos = s
			break
		}
		p.spnl()
	}
	if !p.char('}') {
		p.pos = save
		return Attr{}, false
	}
	return attr, true
}

func isIdentChar(r rune) bool {
	return isAlphaNum(r) || r == '-' || r == '_' || r == ':' || r == '.'
}

func (p *mdP) attribute(attr *Attr) bool {
	save := p.pos
	switch {
	case p.char('#'):
		id, ok := p.many1(isIdentChar)
		if !ok {
			p.pos = save
			return false
		}
		attr.ID = id
		return true
	case p.char('.'):
		cls, ok := p.many1(func(r rune) bool { return isAlphaNum(r) || r == '-' || r == '_' })
		if !ok {
			p.pos = save
			return false
		}
		attr.Classes = append(attr.Classes, cls)
		return true
	case p.char('-'):
		attr.Classes = append(attr.Classes, "unnumbered")
		return true
	}
	// key=val
	if !unicode.IsLetter(p.peek()) {
		return false
	}
	key := p.many(isIdentChar)
	if !p.char('=') {
		p.pos = save
		return false
	}
	var val string
	if p.char('"') {
		v, ok := p.manyTillLitChar('"')
		if !ok {
			p.pos = save
			return false
		}
		val = v
	} else if p.char('\'') {
		v, ok := p.manyTillLitChar('\'')
		if !ok {
			p.pos = save
			return false
		}
		val = v
	} else {
		var sb strings.Builder
		for !p.eof() {
			r := p.peek()
			if r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '}' {
				break
			}
			if r == '\\' {
				if c, ok := p.escapedCharRaw(); ok {
					sb.WriteRune(c)
					continue
				}
			}
			sb.WriteRune(r)
			p.pos++
		}
		val = sb.String()
	}
	switch key {
	case "id":
		attr.ID = val
	case "class":
		attr.Classes = append(attr.Classes, strings.Fields(val)...)
	default:
		attr.KVs = append(attr.KVs, [2]string{key, val})
	}
	return true
}

// manyTillLitChar reads litChars until the closing delimiter (consumed).
func (p *mdP) manyTillLitChar(end rune) (string, bool) {
	var sb strings.Builder
	for {
		if p.eof() {
			return "", false
		}
		if p.char(end) {
			return sb.String(), true
		}
		s, ok := p.litChar()
		if !ok {
			return "", false
		}
		sb.WriteString(s)
	}
}

// litChar: escaped char, character reference, or any char except newline (newline -> space).
func (p *mdP) litChar() (string, bool) {
	if p.peek() == '\\' {
		if c, ok := p.escapedCharRaw(); ok {
			return string(c), true
		}
	}
	if p.peek() == '&' {
		if s, n, ok := parseEntityAt(p.s, p.pos); ok {
			p.pos += n
			return s, true
		}
	}
	if p.eof() {
		return "", false
	}
	r := p.peek()
	if r == '\n' {
		// newline followed by non-blank -> space
		save := p.pos
		p.pos++
		if p.isBlankLineAhead() || p.eof() {
			p.pos = save
			return "", false
		}
		return " ", true
	}
	p.pos++
	return string(r), true
}

// escapedCharRaw: backslash followed by escapable char
func (p *mdP) escapedCharRaw() (rune, bool) {
	save := p.pos
	if !p.char('\\') {
		return 0, false
	}
	r := p.peek()
	if p.eof() {
		p.pos = save
		return 0, false
	}
	if p.ext("all_symbols_escapable") {
		if !isAlphaNum(r) && r != '\n' && r != '\r' {
			p.pos++
			return r, true
		}
	} else if strings.ContainsRune("\\`*_{}[]()>#+-.!~\"", r) {
		p.pos++
		return r, true
	}
	p.pos = save
	return 0, false
}

func (p *mdP) rawAttribute() (string, bool) {
	save := p.pos
	if !p.char('{') {
		return "", false
	}
	p.skipSpaces()
	if !p.char('=') {
		p.pos = save
		return "", false
	}
	format, ok := p.many1(func(r rune) bool { return isAlphaNum(r) || r == '-' || r == '_' })
	if !ok {
		p.pos = save
		return "", false
	}
	p.skipSpaces()
	if !p.char('}') {
		p.pos = save
		return "", false
	}
	return format, true
}

// ---- Fenced code ----

func (p *mdP) codeBlockFenced() ([]Block, bool) {
	save := p.pos
	indent := p.skipNonindentSpaces()
	c := p.peek()
	if !((c == '~' && p.ext("fenced_code_blocks")) || (c == '`' && p.ext("backtick_code_blocks"))) {
		p.pos = save
		return nil, false
	}
	fence := p.many(func(r rune) bool { return r == c })
	size := len(fence)
	if size < 3 {
		p.pos = save
		return nil, false
	}
	p.skipSpaces()
	var attr Attr
	var rawFormat string
	isRaw := false
	if p.ext("raw_attribute") {
		if f, ok := p.rawAttribute(); ok {
			isRaw = true
			rawFormat = f
		}
	}
	if !isRaw {
		if p.ext("fenced_code_attributes") {
			if a, ok := p.attributes(); ok {
				attr = a
			} else if lang, ok := p.many1(func(r rune) bool { return !unicode.IsSpace(r) }); ok {
				if c == '`' && strings.ContainsRune(lang, '`') {
					p.pos = save
					return nil, false
				}
				attr.Classes = []string{toLanguageId(lang)}
			}
		} else if lang, ok := p.many1(func(r rune) bool { return !unicode.IsSpace(r) }); ok {
			attr.Classes = []string{toLanguageId(lang)}
		}
	}
	if !p.blankline() {
		p.pos = save
		return nil, false
	}
	var lines []string
	for {
		if p.eof() {
			p.pos = save
			return nil, false
		}
		// closing fence?
		s := p.pos
		p.skipNonindentSpaces()
		closing := p.many(func(r rune) bool { return r == c })
		if len(closing) >= size {
			if _, ok := p.blanklines(); ok {
				break
			}
		}
		p.pos = s
		p.gobbleAtMostSpaces(indent)
		l, ok := p.anyLine()
		if !ok {
			p.pos = save
			return nil, false
		}
		lines = append(lines, l)
	}
	contents := strings.Join(lines, "\n")
	if isRaw {
		return []Block{&RawBlock{Format: rawFormat, Text: contents}}, true
	}
	return []Block{&CodeBlock{Attr: attr, Text: contents}}, true
}

func toLanguageId(s string) string {
	s = strings.ToLower(s)
	switch s {
	case "c++":
		return "cpp"
	case "objective-c":
		return "objectivec"
	}
	return s
}

// ---- Indented code ----

func (p *mdP) codeBlockIndented() ([]Block, bool) {
	save := p.pos
	var sb strings.Builder
	n := 0
	for {
		s := p.pos
		if p.indentSpaces() {
			l, ok := p.anyLineNewline()
			if !ok {
				p.pos = s
				break
			}
			sb.WriteString(l)
			n++
			continue
		}
		// blanklines followed by indented line
		b, ok := p.blanklines()
		if ok && p.indentSpaces() {
			l, ok2 := p.anyLineNewline()
			if ok2 {
				sb.WriteString(b)
				sb.WriteString(l)
				n++
				continue
			}
		}
		p.pos = s
		break
	}
	if n == 0 {
		p.pos = save
		return nil, false
	}
	p.blanklines()
	text := strings.TrimRight(sb.String(), "\n")
	attr := Attr{Classes: append([]string{}, p.st.indentedCodeClasses...)}
	return []Block{&CodeBlock{Attr: attr, Text: text}}, true
}

// ---- Block quote ----

func (p *mdP) emailBlockQuoteStart() bool {
	save := p.pos
	p.skipNonindentSpaces()
	if p.char('>') {
		p.char(' ')
		return true
	}
	p.pos = save
	return false
}

func (p *mdP) blockQuote() ([]Block, bool) {
	save := p.pos
	if !p.emailBlockQuoteStart() {
		return nil, false
	}
	var lines []string
	readLine := func() string {
		var sb strings.Builder
		for !p.eof() {
			r := p.peek()
			if r == '\n' {
				// lazy continuation: newline not followed by quote start or blank line
				s := p.pos
				p.pos++
				if p.emailBlockQuoteStart() {
					p.pos = s
					break
				}
				if p.isBlankLineAhead() || p.eof() {
					p.pos = s
					break
				}
				sb.WriteByte('\n')
				continue
			}
			sb.WriteRune(r)
			p.pos++
		}
		return sb.String()
	}
	lines = append(lines, readLine())
	for {
		s := p.pos
		if p.newline() && p.emailBlockQuoteStart() {
			lines = append(lines, readLine())
			continue
		}
		p.pos = s
		break
	}
	if !p.newline() && !p.eof() {
		p.pos = save
		return nil, false
	}
	p.blanklines()
	raw := strings.Join(lines, "\n") + "\n\n"
	q := p.sub(raw)
	contents := q.parseBlocks()
	return []Block{&BlockQuote{Blocks: contents}}, true
}

// ---- Horizontal rule ----

func (p *mdP) hrule() ([]Block, bool) {
	save := p.pos
	p.skipSpaces()
	c := p.peek()
	if c != '*' && c != '-' && c != '_' {
		p.pos = save
		return nil, false
	}
	p.pos++
	for i := 0; i < 2; i++ {
		s := p.pos
		p.skipSpaces()
		if !p.char(c) {
			p.pos = save
			_ = s
			return nil, false
		}
	}
	for !p.eof() && (isSpaceChar(p.peek()) || p.peek() == c) {
		p.pos++
	}
	if !p.newline() {
		p.pos = save
		return nil, false
	}
	p.blanklines()
	return []Block{&HorizontalRule{}}, true
}

// ---- Line block ----

func (p *mdP) lineBlock() ([]Block, bool) {
	if !p.ext("line_blocks") {
		return nil, false
	}
	save := p.pos
	var lines []string
	for {
		s := p.pos
		l, ok := p.lineBlockLine()
		if !ok {
			p.pos = s
			break
		}
		lines = append(lines, l)
	}
	if len(lines) == 0 {
		p.pos = save
		return nil, false
	}
	for {
		s := p.pos
		if p.char('|') && p.blankline() {
			continue
		}
		p.pos = s
		break
	}
	lb := &LineBlock{}
	for _, l := range lines {
		lb.Lines = append(lb.Lines, p.parseInlinesStr(l))
	}
	return []Block{lb}, true
}

func (p *mdP) lineBlockLine() (string, bool) {
	if !p.char('|') {
		return "", false
	}
	if !p.char(' ') {
		return "", false
	}
	white := p.many(isSpaceChar)
	if p.peek() == '\n' {
		return "", false
	}
	line, _ := p.anyLine()
	parts := []string{line}
	for {
		s := p.pos
		if p.char(' ') {
			l, ok := p.anyLine()
			if ok {
				parts = append(parts, l)
				continue
			}
		}
		p.pos = s
		break
	}
	return strings.Repeat("\u00a0", len(white)) + strings.Join(parts, " "), true
}

// ---- Paragraph / plain ----

func (p *mdP) inlines() []Inline {
	var out []Inline
	for {
		x, ok := p.inline()
		if !ok {
			break
		}
		out = meldInlines(out, x)
	}
	return out
}

func (p *mdP) inlines1() ([]Inline, bool) {
	ils := p.inlines()
	return ils, len(ils) > 0
}

func (p *mdP) para() ([]Block, bool) {
	save := p.pos
	ils, ok := p.inlines1()
	if !ok {
		p.pos = save
		return nil, false
	}
	ils = trimInlines(ils)
	afterInlines := p.pos
	isPara := false
	if p.newline() {
		if _, ok := p.blanklines(); ok {
			isPara = true
		} else if !p.ext("blank_before_blockquote") && p.lookingAtBlockQuote() {
			isPara = true
		} else if p.ext("backtick_code_blocks") && p.lookingAtFencedCode() {
			isPara = true
		} else if !p.ext("blank_before_header") && p.lookingAtHeader() {
			isPara = true
		} else if p.ext("lists_without_preceding_blankline") && !p.inList && p.lookingAtListStart() {
			isPara = true
		} else if p.ext("native_divs") && p.inHtmlBlock == "div" && p.lookingAtCloseTag("div") {
			isPara = true
		} else if p.ext("fenced_divs") && p.divLevel > 0 && p.lookingAtDivFenceEnd() {
			isPara = true
		}
	}
	if !isPara {
		p.pos = afterInlines
		return []Block{&Plain{Inlines: ils}}, true
	}
	// implicit figure
	if len(ils) == 1 && p.ext("implicit_figures") {
		if img, ok := ils[0].(*Image); ok && len(img.Inlines) > 0 {
			return []Block{&Figure{Attr: Attr{}, Caption: Caption{Blocks: []Block{&Plain{Inlines: img.Inlines}}},
				Blocks: []Block{&Plain{Inlines: []Inline{img}}}}}, true
		}
	}
	return []Block{&Para{Inlines: ils}}, true
}

func (p *mdP) plain() ([]Block, bool) {
	save := p.pos
	ils, ok := p.inlines1()
	if !ok {
		p.pos = save
		return nil, false
	}
	return []Block{&Plain{Inlines: trimInlines(ils)}}, true
}

func (p *mdP) lookingAtBlockQuote() bool {
	save := p.pos
	defer func() { p.pos = save }()
	return p.emailBlockQuoteStart()
}

func (p *mdP) lookingAtFencedCode() bool {
	save := p.pos
	defer func() { p.pos = save }()
	_, ok := p.codeBlockFenced()
	return ok
}

func (p *mdP) lookingAtHeader() bool {
	save := p.pos
	defer func() { p.pos = save }()
	_, ok := p.header()
	return ok
}

func (p *mdP) lookingAtListStart() bool {
	save := p.pos
	defer func() { p.pos = save }()
	return p.listStart()
}

func (p *mdP) lookingAtCloseTag(name string) bool {
	save := p.pos
	defer func() { p.pos = save }()
	tag, _, ok := p.htmlTagAt()
	return ok && tag.Kind == tagClose && tag.Name == name
}

func (p *mdP) lookingAtDivFenceEnd() bool {
	save := p.pos
	defer func() { p.pos = save }()
	return p.divFenceEnd()
}

// ---- Fenced divs ----

func (p *mdP) divFenced() ([]Block, bool) {
	if !p.ext("fenced_divs") {
		return nil, false
	}
	save := p.pos
	p.skipNonindentSpaces()
	colons := p.many(func(r rune) bool { return r == ':' })
	if len(colons) < 3 {
		p.pos = save
		return nil, false
	}
	p.skipSpaces()
	var attr Attr
	if a, ok := p.attributes(); ok {
		attr = a
	} else if cls, ok := p.many1(func(r rune) bool { return !unicode.IsSpace(r) && r != '{' && r != '}' && r != ':' }); ok {
		attr.Classes = []string{cls}
	} else {
		p.pos = save
		return nil, false
	}
	p.skipSpaces()
	for p.char(':') {
	}
	if !p.blankline() {
		p.pos = save
		return nil, false
	}
	p.divLevel++
	var contents []Block
	for {
		if p.eof() {
			break
		}
		if p.lookingAtDivFenceEnd() {
			break
		}
		bs, ok := p.block()
		if !ok {
			break
		}
		contents = append(contents, bs...)
	}
	p.divLevel--
	if !p.divFenceEnd() {
		p.pos = save
		return nil, false
	}
	return []Block{&Div{Attr: attr, Blocks: contents}}, true
}

func (p *mdP) divFenceEnd() bool {
	save := p.pos
	p.skipNonindentSpaces()
	colons := p.many(func(r rune) bool { return r == ':' })
	if len(colons) < 3 {
		p.pos = save
		return false
	}
	if !p.blankline() {
		p.pos = save
		return false
	}
	p.blanklines()
	return true
}

// ---- HTML blocks ----

func (p *mdP) htmlTagAt() (HTMLTag, int, bool) {
	if p.peek() != '<' {
		return HTMLTag{}, 0, false
	}
	return parseHTMLTag(p.s, p.pos)
}

func (p *mdP) divHtml() ([]Block, bool) {
	if !p.ext("native_divs") {
		return nil, false
	}
	save := p.pos
	tag, n, ok := p.htmlTagAt()
	if !ok || tag.Kind != tagOpen || tag.Name != "div" || tag.SelfClosing {
		return nil, false
	}
	p.pos += n
	oldIn := p.inHtmlBlock
	p.inHtmlBlock = "div"
	blsStart := p.pos
	if p.blankline() {
		p.blanklines()
	}
	bls := string(p.s[blsStart:p.pos])
	var contents []Block
	for !p.eof() {
		if p.lookingAtCloseTag("div") {
			break
		}
		bs, ok := p.block()
		if !ok {
			break
		}
		contents = append(contents, bs...)
	}
	closed := false
	if t, n2, ok := p.htmlTagAt(); ok && t.Kind == tagClose && t.Name == "div" {
		p.pos += n2
		closed = true
	}
	p.inHtmlBlock = oldIn
	if closed {
		attr := attrFromHTML(tag.Attrs)
		return []Block{&Div{Attr: attr, Blocks: contents}}, true
	}
	_ = save
	return append([]Block{&RawBlock{Format: "html", Text: tag.Raw + bls}}, contents...), true
}

func attrFromHTML(attrs [][2]string) Attr {
	a := Attr{}
	for _, kv := range attrs {
		switch kv[0] {
		case "id":
			a.ID = kv[1]
		case "class":
			a.Classes = append(a.Classes, strings.Fields(kv[1])...)
		default:
			a.KVs = append(a.KVs, kv)
		}
	}
	return a
}

func (p *mdP) htmlBlock() ([]Block, bool) {
	if !p.ext("raw_html") {
		return nil, false
	}
	save := p.pos
	tag, n, ok := p.htmlTagAt()
	if !ok {
		return nil, false
	}
	if tag.Kind == tagOpen && tag.IsBlockTag() && p.ext("markdown_in_html_blocks") {
		if bs, ok := p.rawHtmlBlocks(tag, n); ok {
			return bs, true
		}
		p.pos = save
	}
	// htmlBlock'
	first, ok := p.htmlElement()
	if !ok {
		p.pos = save
		return nil, false
	}
	p.skipSpaces()
	p.blanklines()
	if first == "" {
		return nil, true
	}
	return []Block{&RawBlock{Format: "html", Text: first}}, true
}

// htmlElement: rawVerbatimBlock | strictHtmlBlock | block tag
func (p *mdP) htmlElement() (string, bool) {
	save := p.pos
	tag, n, ok := p.htmlTagAt()
	if !ok {
		return "", false
	}
	switch tag.Kind {
	case tagComment:
		p.pos += n
		return tag.Raw, true
	case tagDecl:
		p.pos += n
		return tag.Raw, true
	}
	if tag.Kind == tagOpen && (tag.Name == "pre" || tag.Name == "style" || tag.Name == "script" || tag.Name == "textarea") {
		if s, ok := p.htmlInBalanced(tag, n); ok {
			return s, true
		}
		p.pos = save
	}
	if !tag.IsInlineTag() || tag.IsBlockTag() {
		if tag.Kind == tagOpen && !tag.SelfClosing {
			if s, ok := p.htmlInBalanced(tag, n); ok {
				return s, true
			}
			p.pos = save
		}
		if tag.IsBlockTag() {
			p.pos += n
			return tag.Raw, true
		}
	}
	return "", false
}

// htmlInBalanced: consume from the open tag to the matching close tag.
func (p *mdP) htmlInBalanced(open HTMLTag, n int) (string, bool) {
	start := p.pos
	i := p.pos + n
	depth := 1
	for i < len(p.s) {
		if p.s[i] == '<' {
			t, m, ok := parseHTMLTag(p.s, i)
			if ok {
				if t.Kind == tagOpen && t.Name == open.Name && !t.SelfClosing {
					depth++
				} else if t.Kind == tagClose && t.Name == open.Name {
					depth--
					if depth == 0 {
						i += m
						p.pos = i
						// must be followed by blank line (block context)
						return string(p.s[start:i]), true
					}
				}
				i += m
				continue
			}
		}
		i++
	}
	return "", false
}

func (p *mdP) rawHtmlBlocks(tag HTMLTag, n int) ([]Block, bool) {
	p.pos += n
	selfClosing := tag.SelfClosing
	p.skipSpaces()
	indentLevel := 0
	s := p.pos
	if p.blankline() {
		indentLevel = len(p.many(func(r rune) bool { return r == ' ' }))
		p.pos = s
		p.blankline()
	} else {
		p.pos = s
	}
	oldIn := p.inHtmlBlock
	p.inHtmlBlock = tag.Name
	var contents []Block
	if !selfClosing {
		for !p.eof() {
			if p.lookingAtCloseTag(tag.Name) {
				break
			}
			s2 := p.pos
			p.gobbleAtMostSpaces(indentLevel)
			if p.lookingAtCloseTag(tag.Name) {
				break
			}
			bs, ok := p.block()
			if !ok {
				p.pos = s2
				break
			}
			contents = append(contents, bs...)
		}
	}
	s3 := p.pos
	p.gobbleAtMostSpaces(indentLevel)
	if t, m, ok := p.htmlTagAt(); ok && t.Kind == tagClose && t.Name == tag.Name {
		p.pos += m
		p.inHtmlBlock = oldIn
		out := []Block{&RawBlock{Format: "html", Text: tag.Raw}}
		out = append(out, contents...)
		out = append(out, &RawBlock{Format: "html", Text: t.Raw})
		return out, true
	}
	p.pos = s3
	p.inHtmlBlock = oldIn
	out := []Block{&RawBlock{Format: "html", Text: tag.Raw}}
	out = append(out, contents...)
	return out, true
}

// ---- Raw TeX blocks ----

var inlineTeXEnvs = map[string]bool{}

func init() {
	for _, e := range strings.Fields("equation equation* align align* alignat alignat* gather gather* multline multline* eqnarray eqnarray* flalign flalign* displaymath math split") {
		inlineTeXEnvs[e] = true
	}
}

func (p *mdP) rawTeXBlock() ([]Block, bool) {
	if !p.ext("raw_tex") {
		return nil, false
	}
	save := p.pos
	var parts []string
	for {
		s := p.pos
		raw, ok := p.rawLaTeXBlockPiece()
		if !ok {
			p.pos = s
			break
		}
		parts = append(parts, raw)
		if _, ok := p.blanklines(); !ok {
			break
		}
	}
	if len(parts) == 0 {
		p.pos = save
		return nil, false
	}
	return []Block{&RawBlock{Format: "tex", Text: trimSpace(strings.Join(parts, ""))}}, true
}

// rawLaTeXBlockPiece parses a \begin{env}...\end{env} (non-inline env) or a block-level command.
func (p *mdP) rawLaTeXBlockPiece() (string, bool) {
	save := p.pos
	if !p.char('\\') {
		return "", false
	}
	if p.lookingAt("begin{") {
		p.pos = save
		s, env, ok := p.texEnvironment()
		if !ok || inlineTeXEnvs[env] {
			p.pos = save
			return "", false
		}
		return s, true
	}
	// block-level commands (e.g. \section, \newcommand, ...)
	name := p.many(unicode.IsLetter)
	if name == "" {
		p.pos = save
		return "", false
	}
	p.pos = save
	s, ok := p.texCommand()
	if !ok {
		p.pos = save
		return "", false
	}
	// must be followed by blankline to be a block
	s2 := p.pos
	if !p.isBlankLineAhead() {
		p.pos = save
		return "", false
	}
	p.pos = s2
	return s, true
}

// texEnvironment parses \begin{name} ... \end{name}, returns raw text and env name.
func (p *mdP) texEnvironment() (string, string, bool) {
	save := p.pos
	if !p.str("\\begin{") {
		return "", "", false
	}
	name := p.many(func(r rune) bool { return r != '}' && r != '\n' })
	if !p.char('}') || name == "" {
		p.pos = save
		return "", "", false
	}
	depth := 1
	beginS := "\\begin{" + name + "}"
	endS := "\\end{" + name + "}"
	for !p.eof() {
		if p.lookingAt(beginS) {
			depth++
			p.pos += len([]rune(beginS))
			continue
		}
		if p.lookingAt(endS) {
			depth--
			p.pos += len([]rune(endS))
			if depth == 0 {
				return string(p.s[save:p.pos]), name, true
			}
			continue
		}
		p.pos++
	}
	p.pos = save
	return "", "", false
}

// texCommand parses \name[opt]{arg}... returning raw text.
func (p *mdP) texCommand() (string, bool) {
	save := p.pos
	if !p.char('\\') {
		return "", false
	}
	name := p.many(unicode.IsLetter)
	if name == "" {
		// control symbol
		if p.eof() || p.peek() == '\n' {
			p.pos = save
			return "", false
		}
		p.pos++
		return string(p.s[save:p.pos]), true
	}
	p.char('*')
	for {
		s := p.pos
		p.skipSpaces()
		if p.peek() == '[' {
			if !p.texBalanced('[', ']') {
				p.pos = s
				break
			}
			continue
		}
		if p.peek() == '{' {
			if !p.texBalanced('{', '}') {
				p.pos = s
				break
			}
			continue
		}
		p.pos = s
		break
	}
	return string(p.s[save:p.pos]), true
}

func (p *mdP) texBalanced(open, close rune) bool {
	save := p.pos
	if !p.char(open) {
		return false
	}
	depth := 1
	for !p.eof() {
		r := p.peek()
		if r == '\\' {
			p.pos += 2
			continue
		}
		if r == open {
			depth++
		} else if r == close {
			depth--
			if depth == 0 {
				p.pos++
				return true
			}
		} else if r == '\n' {
			// allow newlines but not blank lines
			if p.pos+1 < len(p.s) && p.s[p.pos+1] == '\n' {
				p.pos = save
				return false
			}
		}
		p.pos++
	}
	p.pos = save
	return false
}

// ---- Footnote definitions ----

func (p *mdP) noteMarker() (string, bool) {
	save := p.pos
	if !p.str("[^") {
		return "", false
	}
	label := p.many(func(r rune) bool { return !unicode.IsSpace(r) && r != ']' && r != '^' && r != '[' })
	if label == "" || !p.char(']') {
		p.pos = save
		return "", false
	}
	return label, true
}

func (p *mdP) noteBlock() ([]Block, bool) {
	if !p.ext("footnotes") {
		return nil, false
	}
	save := p.pos
	p.skipNonindentSpaces()
	label, ok := p.noteMarker()
	if !ok || !p.char(':') {
		p.pos = save
		return nil, false
	}
	p.blankline()
	p.indentSpaces()
	oldInNote := p.inNote
	p.inNote = true
	rawLines := func() string {
		first, _ := p.anyLine()
		lines := []string{first}
		for {
			s := p.pos
			if p.isBlankLineAhead() || p.eof() {
				break
			}
			// a new note marker ends it
			s2 := p.pos
			p.skipNonindentSpaces()
			if _, ok := p.noteMarker(); ok {
				p.pos = s
				break
			}
			p.pos = s2
			l, ok := p.anyLine()
			if !ok {
				p.pos = s
				break
			}
			lines = append(lines, l)
		}
		return strings.Join(lines, "\n") + "\n"
	}
	raw := rawLines()
	for {
		s := p.pos
		b, ok := p.blanklines()
		if ok && p.indentSpaces() {
			raw += b + rawLines()
			continue
		}
		p.pos = s
		break
	}
	p.blanklines()
	raw += "\n"
	q := p.sub(raw)
	parsed := q.parseBlocks()
	p.inNote = oldInNote
	if _, exists := p.st.notes[label]; !exists {
		p.st.notes[label] = parsed
		p.st.noteOrder = append(p.st.noteOrder, label)
	} else {
		p.st.warnings = append(p.st.warnings, "[WARNING] Duplicate note reference '"+label+"'")
	}
	return nil, true
}

// ---- Reference keys ----

func (p *mdP) referenceKey() ([]Block, bool) {
	save := p.pos
	p.skipNonindentSpaces()
	// not a citation
	if p.lookingAt("[@") || p.lookingAt("[^") {
		p.pos = save
		return nil, false
	}
	_, raw, ok := p.reference()
	if !ok {
		p.pos = save
		return nil, false
	}
	if !p.char(':') {
		p.pos = save
		return nil, false
	}
	p.skipSpaces()
	p.newline()
	p.skipSpaces()
	if p.peek() == '[' {
		p.pos = save
		return nil, false
	}
	var src string
	if p.char('<') {
		s, ok := p.manyTillLitChar('>')
		if !ok {
			p.pos = save
			return nil, false
		}
		src = s
	} else {
		var parts []string
		for {
			s := p.pos
			p.skipSpaces()
			if p.referenceTitleAhead() || (p.ext("link_attributes") && p.attributesAhead()) || p.referenceAhead() {
				p.pos = s
				break
			}
			var sb strings.Builder
			for !p.eof() && !unicode.IsSpace(p.peek()) {
				c, ok := p.litChar()
				if !ok {
					break
				}
				sb.WriteString(c)
			}
			if sb.Len() == 0 {
				p.pos = s
				break
			}
			parts = append(parts, sb.String())
		}
		src = strings.Join(parts, " ")
	}
	tit := ""
	if t, ok := p.referenceTitle(); ok {
		tit = t
	}
	attr := Attr{}
	if p.ext("link_attributes") {
		s := p.pos
		p.skipSpaces()
		p.newline()
		p.skipSpaces()
		if a, ok := p.attributes(); ok {
			attr = a
		} else {
			p.pos = s
		}
	}
	if _, ok := p.blanklines(); !ok {
		p.pos = save
		return nil, false
	}
	key := toKey(raw)
	def := refDef{URL: escapeURI(trimRight(src)), Title: tit, Attr: attr}
	if old, exists := p.st.refs[key]; exists {
		if old.URL != def.URL || old.Title != def.Title {
			p.st.warnings = append(p.st.warnings, "[WARNING] Duplicate link reference '"+raw+"'")
		}
	}
	p.st.refs[key] = def
	return nil, true
}

func (p *mdP) referenceTitleAhead() bool {
	save := p.pos
	defer func() { p.pos = save }()
	_, ok := p.referenceTitle()
	return ok
}

func (p *mdP) attributesAhead() bool {
	save := p.pos
	defer func() { p.pos = save }()
	_, ok := p.attributes()
	return ok
}

func (p *mdP) referenceAhead() bool {
	save := p.pos
	defer func() { p.pos = save }()
	_, _, ok := p.reference()
	return ok
}

func (p *mdP) referenceTitle() (string, bool) {
	save := p.pos
	p.skipSpaces()
	p.newline()
	p.skipSpaces()
	if t, ok := p.quotedTitle('"'); ok {
		return t, true
	}
	if t, ok := p.quotedTitle('\''); ok {
		return t, true
	}
	if p.peek() == '(' {
		if t, ok := p.charsInBalanced('(', ')'); ok {
			return t, true
		}
	}
	p.pos = save
	return "", false
}

func (p *mdP) charsInBalanced(open, close rune) (string, bool) {
	save := p.pos
	if !p.char(open) {
		return "", false
	}
	var sb strings.Builder
	depth := 1
	for !p.eof() {
		r := p.peek()
		if r == open {
			depth++
			sb.WriteRune(r)
			p.pos++
			continue
		}
		if r == close {
			depth--
			p.pos++
			if depth == 0 {
				return sb.String(), true
			}
			sb.WriteRune(r)
			continue
		}
		c, ok := p.litChar()
		if !ok {
			break
		}
		sb.WriteString(c)
	}
	p.pos = save
	return "", false
}

// quotedTitle parses a title in quotes.
func (p *mdP) quotedTitle(q rune) (string, bool) {
	save := p.pos
	if !p.char(q) {
		return "", false
	}
	if unicode.IsSpace(p.peek()) && false {
		p.pos = save
		return "", false
	}
	var sb strings.Builder
	for {
		if p.eof() {
			p.pos = save
			return "", false
		}
		// ender: quote not followed by alphanumeric
		if p.peek() == q {
			s := p.pos
			p.pos++
			if !isAlphaNum(p.peek()) {
				return strings.Join(strings.Fields(sb.String()), " "), true
			}
			p.pos = s
			// nested quote: include literally
			sb.WriteRune(q)
			p.pos++
			continue
		}
		if p.peek() == '\n' {
			s := p.pos
			p.pos++
			if p.isBlankLineAhead() || p.eof() {
				p.pos = save
				return "", false
			}
			_ = s
			sb.WriteByte(' ')
			continue
		}
		c, ok := p.litChar()
		if !ok {
			p.pos = save
			return "", false
		}
		sb.WriteString(c)
	}
}

// ---- YAML metadata block ----

func (p *mdP) yamlMetaBlock() ([]Block, bool) {
	if !p.ext("yaml_metadata_block") {
		return nil, false
	}
	save := p.pos
	if !p.str("---") {
		return nil, false
	}
	if !p.blankline() {
		p.pos = save
		return nil, false
	}
	// collect lines until --- or ...
	var lines []string
	for {
		if p.eof() {
			p.pos = save
			return nil, false
		}
		s := p.pos
		if (p.str("---") || p.str("...")) && p.blankline() {
			break
		}
		p.pos = s
		l, _ := p.anyLine()
		lines = append(lines, l)
	}
	p.blanklines()
	raw := strings.Join(lines, "\n")
	m, err := parseYAMLMeta(raw, p)
	if err != nil {
		p.st.warnings = append(p.st.warnings, "[WARNING] Could not parse YAML metadata: "+err.Error())
		return nil, true
	}
	for _, k := range m.Keys {
		if _, exists := p.st.meta.Values[k]; !exists || true {
			// later values override earlier? pandoc: first wins for repeated keys? Actually later blocks override.
			p.st.meta.Set(k, m.Values[k])
		}
	}
	return nil, true
}
