func (p *mdP) note() ([]Inline, bool) {
	if !p.ext("footnotes") {
		return nil, false
	}
	save := p.pos
	label, ok := p.noteMarker()
	if !ok {
		p.pos = save
		return nil, false
	}
	if p.inNote {
		// pandoc disallows notes within notes? It allows but let's keep.
	}
	return []Inline{&notePH{label: label}}, true
}

func (p *mdP) inlineNote() ([]Inline, bool) {
	if !p.ext("inline_notes") {
		return nil, false
	}
	save := p.pos
	if !p.char('^') {
		return nil, false
	}
	if p.peek() != '[' {
		p.pos = save
		return nil, false
	}
	oldInNote := p.inNote
	p.inNote = true
	ils, _, ok := p.reference()
	p.inNote = oldInNote
	if !ok {
		p.pos = save
		return nil, false
	}
	return []Inline{&Note{Blocks: []Block{&Para{Inlines: ils}}}}, true
}

// ---- citations ----

func (p *mdP) cite() ([]Inline, bool) {
	if !p.ext("citations") {
		return nil, false
	}
	save := p.pos
	if cits, ok := p.textualCite(); ok {
		return cits, true
	}
	p.pos = save
	cits, ok := p.normalCite()
	if !ok {
		p.pos = save
		return nil, false
	}
	raw := string(p.s[save:p.pos])
	return []Inline{&Cite{Citations: cits, Inlines: []Inline{&Str{Text: raw}}}}, true
}

func (p *mdP) citeKey() (bool, string, bool) {
	save := p.pos
	if !p.notAfterString() {
		return false, "", false
	}
	suppress := p.char('-')
	if !p.char('@') {
		p.pos = save
		return false, "", false
	}
	// key: {...} form or regular
	if p.char('{') {
		key := p.many(func(r rune) bool { return r != '}' && r != '\n' })
		if !p.char('}') || key == "" {
			p.pos = save
			return false, "", false
		}
		return suppress, key, true
	}
	first, ok := p.satisfy(func(r rune) bool { return isAlphaNum(r) || r == '_' })
	if !ok {
		p.pos = save
		return false, "", false
	}
	var sb strings.Builder
	sb.WriteRune(first)
	for !p.eof() {
		r := p.peek()
		if isAlphaNum(r) || r == '_' {
			sb.WriteRune(r)
			p.pos++
			continue
		}
		if strings.ContainsRune(":.#$%&-+?<>~/", r) {
			// internal punctuation must be followed by alnum
			n := p.peekAt(1)
			if isAlphaNum(n) || n == '_' {
				sb.WriteRune(r)
				p.pos++
				continue
			}
		}
		break
	}
	return suppress, sb.String(), true
}

func (p *mdP) textualCite() ([]Inline, bool) {
	save := p.pos
	suppress, key, ok := p.citeKey()
	if !ok {
		return nil, false
	}
	mode := AuthorInText
	if suppress {
		mode = SuppressAuthor
	}
	first := Citation{ID: key, Mode: mode}
	// optional following bracketed suffix/citations
	s := p.pos
	p.spnl()
	if p.peek() == '[' {
		s2 := p.pos
		if rest, ok := p.normalCite(); ok {
			cits := append([]Citation{first}, rest...)
			raw := string(p.s[save:p.pos])
			if suppress {
				// -@key [...] → all normal? pandoc: if suppress, first becomes SuppressAuthor and rest...
			}
			return []Inline{&Cite{Citations: cits, Inlines: []Inline{&Str{Text: raw}}}}, true
		}
		p.pos = s2
		// bare locator [p. 33]
		if p.char('[') {
			start := p.pos
			depth := 1
			for !p.eof() && depth > 0 {
				if p.peek() == '[' {
					depth++
				} else if p.peek() == ']' {
					depth--
				}
				if depth > 0 {
					p.pos++
				}
			}
			if depth == 0 {
				inner := string(p.s[start:p.pos])
				p.pos++
				// must not look like a citation key inside
				if !strings.Contains(inner, "@") {
					suffix := p.parseInlinesStr(inner)
					first.Suffix = suffix
					raw := string(p.s[save:p.pos])
					return []Inline{&Cite{Citations: []Citation{first}, Inlines: []Inline{&Str{Text: raw}}}}, true
				}
			}
		}
	}
	p.pos = s
	raw := string(p.s[save:p.pos])
	return []Inline{&Cite{Citations: []Citation{first}, Inlines: []Inline{&Str{Text: raw}}}}, true
}

func (p *mdP) normalCite() ([]Citation, bool) {
	save := p.pos
	if !p.char('[') {
		return nil, false
	}
	p.spnl()
	var cits []Citation
	for {
		c, ok := p.citation()
		if !ok {
			p.pos = save
			return nil, false
		}
		cits = append(cits, c)
		p.spnl()
		if p.char(';') {
			p.spnl()
			continue
		}
		break
	}
	if !p.char(']') {
		p.pos = save
		return nil, false
	}
	return cits, true
}

func (p *mdP) citation() (Citation, bool) {
	save := p.pos
	// prefix: inlines until @ or -@
	var prefix []Inline
	for !p.eof() {
		if p.peek() == '@' || (p.peek() == '-' && p.peekAt(1) == '@') || p.peek() == ';' || p.peek() == ']' {
			break
		}
		s := p.pos
		if _, ok := p.citeKeyAhead(); ok {
			break
		}
		p.pos = s
		x, ok := p.inline()
		if !ok {
			break
		}
		prefix = meldInlines(prefix, x)
	}
	suppress, key, ok := p.citeKey()
	if !ok {
		p.pos = save
		return Citation{}, false
	}
	// suffix: until ; or ]
	var suffix []Inline
	start := p.pos
	depth := 0
	for !p.eof() {
		r := p.peek()
		if r == '[' {
			depth++
		} else if r == ']' {
			if depth == 0 {
				break
			}
			depth--
		} else if r == ';' && depth == 0 {
			break
		}
		p.pos++
	}
	if p.pos > start {
		suffix = p.parseInlinesStr(string(p.s[start:p.pos]))
		// pandoc keeps leading comma/space in suffix: e.g. ", p. 33"
		raw := string(p.s[start:p.pos])
		q := p.sub(raw)
		suffix = trimInlines(q.inlines())
	}
	mode := NormalCitation
	if suppress {
		mode = SuppressAuthor
	}
	return Citation{ID: key, Prefix: trimInlines(prefix), Suffix: suffix, Mode: mode}, true
}

func (p *mdP) citeKeyAhead() (string, bool) {
	save := p.pos
	defer func() { p.pos = save }()
	_, k, ok := p.citeKey()
	return k, ok
}

func (p *mdP) exampleRef() ([]Inline, bool) {
	if !p.ext("example_lists") {
		return nil, false
	}
	save := p.pos
	if !p.char('@') {
		return nil, false
	}
	label, ok := p.many1(func(r rune) bool { return isAlphaNum(r) || r == '_' || r == '-' })
	if !ok {
		p.pos = save
		return nil, false
	}
	return []Inline{&exampleRefPH{label: label}}, true
}

type exampleRefPH struct{ label string }

func (*exampleRefPH) isInline() {}
