type notePH struct{ label string }

func (*notePH) isInline() {}

// ---- Inline dispatcher ----

func (p *mdP) inline() ([]Inline, bool) {
	if p.eof() {
		return nil, false
	}
	c := p.peek()
	save := p.pos
	try := func(f func() ([]Inline, bool)) ([]Inline, bool) {
		if r, ok := f(); ok {
			return r, true
		}
		p.pos = save
		return nil, false
	}
	switch c {
	case ' ', '\t':
		if r, ok := try(p.whitespace); ok {
			return r, true
		}
	case '\n':
		if r, ok := try(p.endline); ok {
			return r, true
		}
	case '`':
		if r, ok := try(p.code); ok {
			return r, true
		}
	case '_', '*':
		if r, ok := try(p.strongOrEmph); ok {
			return r, true
		}
	case '^':
		if r, ok := try(p.superscript); ok {
			return r, true
		}
		if r, ok := try(p.inlineNote); ok {
			return r, true
		}
	case '[':
		if r, ok := try(p.note); ok {
			return r, true
		}
		if r, ok := try(p.cite); ok {
			return r, true
		}
		if r, ok := try(p.bracketedSpan); ok {
			return r, true
		}
		if r, ok := try(p.link); ok {
			return r, true
		}
	case '!':
		if r, ok := try(p.image); ok {
			return r, true
		}
	case '$':
		if r, ok := try(p.math); ok {
			return r, true
		}
	case '~':
		if r, ok := try(p.strikeout); ok {
			return r, true
		}
		if r, ok := try(p.subscript); ok {
			return r, true
		}
	case '<':
		if r, ok := try(p.autoLink); ok {
			return r, true
		}
		if r, ok := try(p.spanHtml); ok {
			return r, true
		}
		if r, ok := try(p.rawHtmlInline); ok {
			return r, true
		}
		if r, ok := try(p.ltSign); ok {
			return r, true
		}
	case '\\':
		if r, ok := try(p.math); ok {
			return r, true
		}
		if r, ok := try(p.escapedNewline); ok {
			return r, true
		}
		if r, ok := try(p.escapedChar); ok {
			return r, true
		}
		if r, ok := try(p.rawLaTeXInline); ok {
			return r, true
		}
	case '@':
		if r, ok := try(p.cite); ok {
			return r, true
		}
		if r, ok := try(p.exampleRef); ok {
			return r, true
		}
	case '"', '\'', '\u2018', '\u0091', '\u201c', '\u0093', '-', '.':
		if r, ok := try(p.smart); ok {
			return r, true
		}
	case '&':
		if r, ok := try(p.charRef); ok {
			return r, true
		}
	}
	// fallbacks
	if p.ext("autolink_bare_uris") {
		if r, ok := try(p.bareURL); ok {
			return r, true
		}
	}
	if r, ok := try(p.strP); ok {
		return r, true
	}
	if r, ok := try(p.endline); ok {
		return r, true
	}
	if r, ok := try(p.smart); ok {
		return r, true
	}
	if r, ok := try(p.symbol); ok {
		return r, true
	}
	if r, ok := try(p.ltSign); ok {
		return r, true
	}
	return nil, false
}

// ---- whitespace / endline ----

func (p *mdP) whitespace() ([]Inline, bool) {
	if !isSpaceChar(p.peek()) {
		return nil, false
	}
	p.pos++
	if isSpaceChar(p.peek()) {
		p.skipSpaces()
		save := p.pos
		if _, ok := p.endline(); ok {
			if p.allowLineBreaks {
				return []Inline{&LineBreak{}}, true
			}
			p.pos = save
			return []Inline{&Space{}}, true
		}
		p.pos = save
		return []Inline{&Space{}}, true
	}
	p.skipSpaces()
	return []Inline{&Space{}}, true
}

func (p *mdP) endline() ([]Inline, bool) {
	save := p.pos
	if !p.newline() {
		return nil, false
	}
	if p.isBlankLineAhead() {
		p.pos = save
		return nil, false
	}
	if p.inList && p.lookingAtListStart() {
		p.pos = save
		return nil, false
	}
	if p.ext("lists_without_preceding_blankline") && p.lookingAtListStart() {
		p.pos = save
		return nil, false
	}
	if !p.ext("blank_before_blockquote") && p.lookingAtBlockQuote() {
		p.pos = save
		return nil, false
	}
	if !p.ext("blank_before_header") && p.peek() == '#' {
		p.pos = save
		return nil, false
	}
	if p.ext("backtick_code_blocks") && p.peek() == '`' && p.lookingAtFencedCode() {
		p.pos = save
		return nil, false
	}
	if p.inHtmlBlock != "" && p.lookingAtCloseTag(p.inHtmlBlock) {
		p.pos = save
		return nil, false
	}
	if p.divLevel > 0 && p.lookingAtDivFenceEnd() {
		p.pos = save
		return nil, false
	}
	if p.inTable {
		// in table cells, newlines are not allowed (handled by caller)
	}
	if p.eof() {
		return []Inline{}, true
	}
	if p.ext("hard_line_breaks") {
		return []Inline{&LineBreak{}}, true
	}
	if p.ext("ignore_line_breaks") {
		return []Inline{}, true
	}
	p.skipSpaces()
	return []Inline{&SoftBreak{}}, true
}

// ---- str / symbol ----

func (p *mdP) strP() ([]Inline, bool) {
	start := p.pos
	for {
		if s, ok := p.many1(isAlphaNum); ok {
			_ = s
			continue
		}
		// a period followed by alnum (for abbreviations like e.g.)
		if p.peek() == '.' && p.pos+1 < len(p.s) && isAlphaNum(p.s[p.pos+1]) && false {
			p.pos++
			continue
		}
		break
	}
	if p.pos == start {
		return nil, false
	}
	result := string(p.s[start:p.pos])
	p.lastStrPos = p.pos
	if p.ext("smart") {
		// abbreviation: result followed by '.' then space
		if p.peek() == '.' {
			cand := result + "."
			if p.st.abbrevs[cand] {
				save := p.pos
				p.pos++
				s2 := p.pos
				if ws, ok := p.whitespace(); ok {
					// not followed by note/cite
					if p.peek() == '[' || p.peek() == '@' {
						// pandoc checks notFollowedBy cite/note
						s3 := p.pos
						if _, ok := p.note(); ok {
							p.pos = save
							return []Inline{&Str{Text: result}}, true
						}
						p.pos = s3
						if _, ok := p.cite(); ok {
							p.pos = save
							return []Inline{&Str{Text: result}}, true
						}
						p.pos = s3
					}
					if len(ws) == 1 {
						if _, isSp := ws[0].(*Space); isSp {
							return []Inline{&Str{Text: cand + "\u00a0"}}, true
						}
						return append([]Inline{&Str{Text: cand}}, ws...), true
					}
				}
				p.pos = s2
				p.pos = save
			}
		}
	}
	return []Inline{&Str{Text: result}}, true
}

func (p *mdP) symbol() ([]Inline, bool) {
	r := p.peek()
	if p.eof() {
		return nil, false
	}
	if r == '<' || r == '\n' || r == '\t' || r == ' ' {
		return nil, false
	}
	if r == '\\' {
		// only if not a raw TeX block
		save := p.pos
		if _, ok := p.rawTeXBlock(); ok {
			p.pos = save
			return nil, false
		}
		p.pos = save
	}
	p.pos++
	return []Inline{&Str{Text: string(r)}}, true
}

func (p *mdP) ltSign() ([]Inline, bool) {
	if p.peek() != '<' {
		return nil, false
	}
	if p.ext("raw_html") {
		if p.inHtmlBlock != "" && p.lookingAtCloseTag(p.inHtmlBlock) {
			return nil, false
		}
		if t, _, ok := p.htmlTagAt(); ok && t.IsBlockTag() {
			return nil, false
		}
	}
	p.pos++
	return []Inline{&Str{Text: "<"}}, true
}

func (p *mdP) charRef() ([]Inline, bool) {
	if s, n, ok := parseEntityAt(p.s, p.pos); ok {
		p.pos += n
		return []Inline{&Str{Text: s}}, true
	}
	return nil, false
}

// ---- escapes ----

func (p *mdP) escapedChar() ([]Inline, bool) {
	c, ok := p.escapedCharRaw()
	if !ok {
		return nil, false
	}
	if c == ' ' {
		return []Inline{&Str{Text: "\u00a0"}}, true
	}
	return []Inline{&Str{Text: string(c)}}, true
}

func (p *mdP) escapedNewline() ([]Inline, bool) {
	if !p.ext("escaped_line_breaks") {
		return nil, false
	}
	if p.peek() == '\\' && p.peekAt(1) == '\n' {
		p.pos++
		return []Inline{&LineBreak{}}, true
	}
	return nil, false
}

// ---- code ----

func (p *mdP) code() ([]Inline, bool) {
	save := p.pos
	starts := p.many(func(r rune) bool { return r == '`' })
	if starts == "" {
		return nil, false
	}
	n := len(starts)
	p.skipSpaces()
	var sb strings.Builder
	for {
		if p.eof() {
			p.pos = save
			return nil, false
		}
		// closing?
		s := p.pos
		p.skipSpaces()
		closing := p.many(func(r rune) bool { return r == '`' })
		if len(closing) == n {
			break
		}
		p.pos = s
		r := p.peek()
		if r == '`' {
			sb.WriteString(p.many(func(r rune) bool { return r == '`' }))
			continue
		}
		if r == '\n' {
			p.pos++
			if p.isBlankLineAhead() || p.eof() {
				p.pos = save
				return nil, false
			}
			sb.WriteByte(' ')
			continue
		}
		sb.WriteString(p.many(func(r rune) bool { return r != '`' && r != '\n' }))
	}
	result := trimSpace(sb.String())
	if p.ext("raw_attribute") {
		if f, ok := p.rawAttribute(); ok {
			return []Inline{&RawInline{Format: f, Text: result}}, true
		}
	}
	attr := Attr{}
	if p.ext("inline_code_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	return []Inline{&Code{Attr: attr, Text: result}}, true
}

// ---- emphasis ----

func (p *mdP) notAfterString() bool {
	return p.lastStrPos != p.pos
}

func (p *mdP) strongOrEmph() ([]Inline, bool) {
	c := p.peek()
	if c != '*' && c != '_' {
		return nil, false
	}
	if c == '_' && p.ext("intraword_underscores") && !p.notAfterString() {
		return nil, false
	}
	cs := p.many(func(r rune) bool { return r == c })
	// followed by whitespace -> literal
	save := p.pos
	if ws, ok := p.whitespace(); ok {
		return append([]Inline{&Str{Text: cs}}, ws...), true
	}
	p.pos = save
	switch len(cs) {
	case 3:
		return p.three(c), true
	case 2:
		return p.two(c, nil), true
	case 1:
		return p.one(c, nil), true
	}
	return []Inline{&Str{Text: cs}}, true
}

func (p *mdP) ender(c rune, n int) bool {
	save := p.pos
	for i := 0; i < n; i++ {
		if !p.char(c) {
			p.pos = save
			return false
		}
	}
	if c == '*' || !p.ext("intraword_underscores") {
		return true
	}
	if isAlphaNum(p.peek()) {
		p.pos = save
		return false
	}
	return true
}

func (p *mdP) enderAhead(c rune, n int) bool {
	save := p.pos
	ok := p.ender(c, n)
	p.pos = save
	return ok
}

func (p *mdP) three(c rune) []Inline {
	var contents []Inline
	for {
		if p.enderAhead(c, 1) {
			break
		}
		x, ok := p.inline()
		if !ok {
			break
		}
		contents = meldInlines(contents, x)
	}
	if p.ender(c, 3) {
		p.lastStrPos = p.pos
		return []Inline{&Strong{Inlines: []Inline{&Emph{Inlines: contents}}}}
	}
	if p.ender(c, 2) {
		p.lastStrPos = p.pos
		return p.one(c, []Inline{&Strong{Inlines: contents}})
	}
	if p.ender(c, 1) {
		p.lastStrPos = p.pos
		return p.two(c, []Inline{&Emph{Inlines: contents}})
	}
	return meldInlines([]Inline{&Str{Text: string([]rune{c, c, c})}}, contents)
}

func (p *mdP) two(c rune, prefix []Inline) []Inline {
	var contents []Inline
	for {
		if p.enderAhead(c, 2) {
			break
		}
		save := p.pos
		x, ok := p.inline()
		if !ok {
			p.pos = save
			break
		}
		contents = meldInlines(contents, x)
	}
	if p.ender(c, 2) {
		p.lastStrPos = p.pos
		return []Inline{&Strong{Inlines: meldInlines(prefix, contents)}}
	}
	return meldInlines([]Inline{&Str{Text: string([]rune{c, c})}}, meldInlines(prefix, contents))
}

func (p *mdP) one(c rune, prefix []Inline) []Inline {
	var contents []Inline
	for {
		if !p.enderAhead(c, 1) {
			x, ok := p.inline()
			if !ok {
				break
			}
			contents = meldInlines(contents, x)
			continue
		}
		// try: string [c,c] >> notFollowedBy (ender c 1) >> two c mempty
		save := p.pos
		if p.char(c) && p.char(c) && !p.enderAhead(c, 1) {
			contents = meldInlines(contents, p.two(c, nil))
			continue
		}
		p.pos = save
		break
	}
	if p.ender(c, 1) {
		p.lastStrPos = p.pos
		return []Inline{&Emph{Inlines: meldInlines(prefix, contents)}}
	}
	return meldInlines([]Inline{&Str{Text: string(c)}}, meldInlines(prefix, contents))
}

// ---- strikeout / sub / superscript ----

func (p *mdP) strikeout() ([]Inline, bool) {
	if !p.ext("strikeout") {
		return nil, false
	}
	save := p.pos
	if !p.str("~~") {
		return nil, false
	}
	if isSpaceChar(p.peek()) || p.peek() == '\n' {
		p.pos = save
		return nil, false
	}
	var contents []Inline
	for {
		if p.lookingAt("~~") {
			break
		}
		x, ok := p.inline()
		if !ok {
			p.pos = save
			return nil, false
		}
		contents = meldInlines(contents, x)
	}
	if !p.str("~~") || len(contents) == 0 {
		p.pos = save
		return nil, false
	}
	return []Inline{&Strikeout{Inlines: contents}}, true
}

func (p *mdP) superscript() ([]Inline, bool) {
	if !p.ext("superscript") {
		return nil, false
	}
	return p.subOrSuper('^', func(ils []Inline) Inline { return &Superscript{Inlines: ils} })
}

func (p *mdP) subscript() ([]Inline, bool) {
	if !p.ext("subscript") {
		return nil, false
	}
	return p.subOrSuper('~', func(ils []Inline) Inline { return &Subscript{Inlines: ils} })
}

func (p *mdP) subOrSuper(c rune, mk func([]Inline) Inline) ([]Inline, bool) {
	save := p.pos
	if !p.char(c) {
		return nil, false
	}
	if p.ext("short_subsuperscripts") {
		// ^word form
		s := p.pos
		if w, ok := p.many1(isAlphaNum); ok {
			if p.peek() == c {
				p.pos = s
			} else {
				return []Inline{mk([]Inline{&Str{Text: w}})}, true
			}
		}
		p.pos = s
	}
	var contents []Inline
	for {
		if p.peek() == c {
			break
		}
		if p.eof() {
			p.pos = save
			return nil, false
		}
		// no spaces allowed (unless escaped)
		if isSpaceChar(p.peek()) || p.peek() == '\n' {
			p.pos = save
			return nil, false
		}
		x, ok := p.inline()
		if !ok {
			p.pos = save
			return nil, false
		}
		contents = meldInlines(contents, x)
	}
	if !p.char(c) || len(contents) == 0 {
		p.pos = save
		return nil, false
	}
	return []Inline{mk(contents)}, true
}

// ---- math ----

func (p *mdP) math() ([]Inline, bool) {
	save := p.pos
	if p.ext("tex_math_dollars") {
		if s, ok := p.mathDisplayWith("$$", "$$"); ok {
			return []Inline{&Math{Type: DisplayMath, Text: s}}, true
		}
		p.pos = save
		if s, ok := p.mathInlineWith("$", "$"); ok {
			return []Inline{&Math{Type: InlineMath, Text: s}}, true
		}
		p.pos = save
	}
	if p.ext("tex_math_single_backslash") {
		if s, ok := p.mathDisplayWith("\\[", "\\]"); ok {
			return []Inline{&Math{Type: DisplayMath, Text: s}}, true
		}
		p.pos = save
		if s, ok := p.mathInlineWith("\\(", "\\)"); ok {
			return []Inline{&Math{Type: InlineMath, Text: s}}, true
		}
		p.pos = save
	}
	if p.ext("tex_math_double_backslash") {
		if s, ok := p.mathDisplayWith("\\\\[", "\\\\]"); ok {
			return []Inline{&Math{Type: DisplayMath, Text: s}}, true
		}
		p.pos = save
		if s, ok := p.mathInlineWith("\\\\(", "\\\\)"); ok {
			return []Inline{&Math{Type: InlineMath, Text: s}}, true
		}
		p.pos = save
	}
	if p.ext("tex_math_gfm") || p.ext("tex_math_double_backslash") {
		// not supported
	}
	return nil, false
}

func (p *mdP) mathDisplayWith(op, cl string) (string, bool) {
	save := p.pos
	if !p.str(op) {
		return "", false
	}
	var sb strings.Builder
	for {
		if p.eof() {
			p.pos = save
			return "", false
		}
		if p.str(cl) {
			if sb.Len() == 0 {
				p.pos = save
				return "", false
			}
			return sb.String(), true
		}
		r := p.peek()
		if r == '\n' {
			p.pos++
			if p.isBlankLineAhead() || p.eof() {
				p.pos = save
				return "", false
			}
			sb.WriteByte('\n')
			continue
		}
		sb.WriteRune(r)
		p.pos++
	}
}

func (p *mdP) mathInlineWith(op, cl string) (string, bool) {
	save := p.pos
	if !p.str(op) {
		return "", false
	}
	if op == "$" && (isSpaceChar(p.peek()) || p.peek() == '\n') {
		p.pos = save
		return "", false
	}
	var sb strings.Builder
	n := 0
	for {
		if p.eof() {
			p.pos = save
			return "", false
		}
		if n > 0 && p.str(cl) {
			if isDigitR(p.peek()) && cl == "$" {
				p.pos = save
				return "", false
			}
			return trimSpace(sb.String()), true
		}
		r := p.peek()
		switch {
		case r == '\\':
			p.pos++
			if p.lookingAt("text") {
				// \text{...} may contain $
				s := p.pos
				p.str("text")
				if p.peek() == '{' {
					if body, ok := p.balancedBraces(); ok {
						sb.WriteString("\\text" + body)
						n++
						continue
					}
				}
				p.pos = s
			}
			if p.eof() {
				p.pos = save
				return "", false
			}
			sb.WriteRune('\\')
			sb.WriteRune(p.peek())
			p.pos++
			n++
		case r == '\n':
			p.pos++
			if p.isBlankLineAhead() || p.eof() {
				p.pos = save
				return "", false
			}
			if p.peek() == '$' && cl == "$" {
				p.pos = save
				return "", false
			}
			sb.WriteByte(' ')
			n++
		case r == ' ' || r == '\t':
			p.skipSpaces()
			if cl == "$" && p.peek() == '$' {
				p.pos = save
				return "", false
			}
			sb.WriteByte(' ')
			n++
		default:
			sb.WriteRune(r)
			p.pos++
			n++
		}
	}
}

func (p *mdP) balancedBraces() (string, bool) {
	save := p.pos
	if !p.char('{') {
		return "", false
	}
	depth := 1
	for !p.eof() {
		r := p.peek()
		if r == '\\' {
			p.pos += 2
			continue
		}
		if r == '{' {
			depth++
		} else if r == '}' {
			depth--
			if depth == 0 {
				p.pos++
				return string(p.s[save:p.pos]), true
			}
		} else if r == '\n' && p.pos+1 < len(p.s) && p.s[p.pos+1] == '\n' {
			break
		}
		p.pos++
	}
	p.pos = save
	return "", false
}

// ---- smart punctuation ----

func (p *mdP) smart() ([]Inline, bool) {
	if !p.ext("smart") {
		return nil, false
	}
	save := p.pos
	if r, ok := p.doubleQuoted(); ok {
		return r, true
	}
	p.pos = save
	if r, ok := p.singleQuoted(); ok {
		return r, true
	}
	p.pos = save
	// apostrophe
	if p.peek() == '\'' || p.peek() == '\u2019' {
		p.pos++
		return []Inline{&Str{Text: "\u2019"}}, true
	}
	if p.lookingAt("...") {
		p.pos += 3
		return []Inline{&Str{Text: "\u2026"}}, true
	}
	if p.peek() == '-' {
		if p.ext("old_dashes") {
			p.pos++
			if p.char('-') {
				return []Inline{&Str{Text: "\u2014"}}, true
			}
			if isDigitR(p.peek()) {
				return []Inline{&Str{Text: "\u2013"}}, true
			}
			p.pos = save
			return nil, false
		}
		if p.str("--") {
			if p.char('-') {
				return []Inline{&Str{Text: "\u2014"}}, true
			}
			return []Inline{&Str{Text: "\u2013"}}, true
		}
	}
	p.pos = save
	return nil, false
}

func (p *mdP) charOrRef(chars string) bool {
	if strings.ContainsRune(chars, p.peek()) && !p.eof() {
		p.pos++
		return true
	}
	if p.peek() == '&' {
		if s, n, ok := parseEntityAt(p.s, p.pos); ok && len([]rune(s)) == 1 && strings.ContainsRune(chars, []rune(s)[0]) {
			p.pos += n
			return true
		}
	}
	return false
}

func (p *mdP) doubleQuoted() ([]Inline, bool) {
	save := p.pos
	if p.quoteCtx == '"' {
		return nil, false
	}
	if !p.charOrRef("\"\u201c\u0093") {
		return nil, false
	}
	r := p.peek()
	if r == ' ' || r == '\t' || r == '\n' || p.eof() {
		p.pos = save
		return nil, false
	}
	oldCtx := p.quoteCtx
	p.quoteCtx = '"'
	var contents []Inline
	found := false
	for {
		if p.charOrRef("\"\u201d\u0094") {
			found = true
			break
		}
		x, ok := p.inline()
		if !ok {
			break
		}
		contents = meldInlines(contents, x)
	}
	p.quoteCtx = oldCtx
	if !found || len(contents) == 0 {
		p.pos = save
		return nil, false
	}
	return []Inline{&Quoted{Type: DoubleQuote, Inlines: trimInlines(contents)}}, true
}

func (p *mdP) singleQuoted() ([]Inline, bool) {
	save := p.pos
	if p.quoteCtx == '\'' {
		return nil, false
	}
	if !p.notAfterString() {
		return nil, false
	}
	if !p.charOrRef("'\u2018\u0091") {
		return nil, false
	}
	r := p.peek()
	if r == ' ' || r == '\t' || r == '\n' || p.eof() {
		p.pos = save
		return nil, false
	}
	oldCtx := p.quoteCtx
	p.quoteCtx = '\''
	var contents []Inline
	found := false
	for {
		s := p.pos
		if p.charOrRef("'\u2019\u0092") {
			if !isAlphaNum(p.peek()) {
				found = true
				break
			}
			p.pos = s
		}
		x, ok := p.inline()
		if !ok {
			break
		}
		contents = meldInlines(contents, x)
	}
	p.quoteCtx = oldCtx
	if !found || len(contents) == 0 {
		p.pos = save
		return nil, false
	}
	return []Inline{&Quoted{Type: SingleQuote, Inlines: trimInlines(contents)}}, true
}

// ---- links / images ----

// reference parses [label] returning parsed inlines and raw text (incl. brackets).
func (p *mdP) reference() ([]Inline, string, bool) {
	if p.ext("footnotes") && p.lookingAt("[^") {
		return nil, "", false
	}
	if p.ext("citations") && p.lookingAt("[@") {
		return nil, "", false
	}
	save := p.pos
	if !p.char('[') {
		return nil, "", false
	}
	// find balanced close bracket
	depth := 1
	start := p.pos
	for {
		if p.eof() {
			p.pos = save
			return nil, "", false
		}
		r := p.peek()
		switch {
		case r == '\\':
			if _, ok := p.escapedCharRaw(); ok {
				continue
			}
			p.pos++
		case r == '`':
			s := p.pos
			if _, ok := p.code(); ok {
				continue
			}
			p.pos = s + 1
		case r == '$':
			s := p.pos
			if _, ok := p.math(); ok {
				continue
			}
			p.pos = s + 1
		case r == '<':
			s := p.pos
			if _, ok := p.rawHtmlInline(); ok {
				continue
			}
			p.pos = s + 1
		case r == ']':
			depth--
			p.pos++
			if depth == 0 {
				inner := string(p.s[start : p.pos-1])
				raw := string(p.s[save:p.pos])
				q := p.sub(inner)
				ils := trimInlines(q.inlines())
				return ils, raw, true
			}
		case r == '[':
			depth++
			p.pos++
		default:
			p.pos++
		}
	}
}

func (p *mdP) link() ([]Inline, bool) {
	if !p.allowLinks {
		return nil, false
	}
	save := p.pos
	p.allowLinks = false
	lab, raw, ok := p.reference()
	p.allowLinks = true
	if !ok {
		p.pos = save
		return nil, false
	}
	if r, ok := p.regLink(false, lab); ok {
		return r, true
	}
	return p.referenceLink(false, lab, raw)
}

func (p *mdP) image() ([]Inline, bool) {
	save := p.pos
	if !p.char('!') {
		return nil, false
	}
	if p.peek() != '[' {
		p.pos = save
		return nil, false
	}
	oldAllow := p.allowLinks
	p.allowLinks = false
	lab, raw, ok := p.reference()
	p.allowLinks = oldAllow
	if !ok {
		p.pos = save
		return nil, false
	}
	if r, ok := p.regLink(true, lab); ok {
		return r, true
	}
	r, ok := p.referenceLink(true, lab, raw)
	if !ok {
		p.pos = save
		return nil, false
	}
	// pandoc: image fallback includes the '!'
	return r, true
}

func (p *mdP) regLink(isImage bool, lab []Inline) ([]Inline, bool) {
	save := p.pos
	src, tit, ok := p.source()
	if !ok {
		p.pos = save
		return nil, false
	}
	attr := Attr{}
	if p.ext("link_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	if isImage {
		src = p.addImageExt(src)
		return []Inline{&Image{Attr: attr, Inlines: lab, Target: Target{URL: src, Title: tit}}}, true
	}
	return []Inline{&Link{Attr: attr, Inlines: lab, Target: Target{URL: src, Title: tit}}}, true
}

func (p *mdP) addImageExt(src string) string {
	if p.st.defaultImageExt == "" {
		return src
	}
	// add extension if none and not a URL with scheme
	if strings.Contains(src, "://") {
		return src
	}
	base := src
	if i := strings.LastIndex(base, "/"); i >= 0 {
		base = base[i+1:]
	}
	if strings.Contains(base, ".") {
		return src
	}
	ext := p.st.defaultImageExt
	if !strings.HasPrefix(ext, ".") {
		ext = "." + ext
	}
	return src + ext
}

func (p *mdP) source() (string, string, bool) {
	save := p.pos
	if !p.char('(') {
		return "", "", false
	}
	p.skipSpaces()
	var src string
	if p.peek() == '<' {
		s := p.pos
		p.pos++
		if u, ok := p.manyTillLitChar('>'); ok {
			src = u
		} else {
			p.pos = s
			src = p.sourceURL()
		}
	} else {
		src = p.sourceURL()
	}
	tit := ""
	s := p.pos
	p.spnl()
	if t, ok := p.quotedTitle('"'); ok {
		tit = t
	} else if t, ok := p.quotedTitle('\''); ok {
		tit = t
	} else {
		p.pos = s
	}
	p.skipSpaces()
	if !p.char(')') {
		p.pos = save
		return "", "", false
	}
	return escapeURI(trimRight(src)), tit, true
}

func (p *mdP) sourceURL() string {
	var sb strings.Builder
	for {
		if p.eof() {
			break
		}
		r := p.peek()
		if r == '(' {
			if s, ok := p.parenthesizedChars(); ok {
				sb.WriteString(s)
				continue
			}
		}
		if r == ' ' || r == '\t' {
			// spaces allowed if not followed by quote or paren
			s := p.pos
			sp := p.many(isSpaceChar)
			n := p.peek()
			if n == '"' || n == '\'' || n == ')' || n == '\n' || p.eof() {
				p.pos = s
				break
			}
			sb.WriteString(sp)
			continue
		}
		if r == ')' || r == '\n' {
			break
		}
		c, ok := p.litChar()
		if !ok {
			break
		}
		sb.WriteString(c)
	}
	return strings.Join(strings.Fields(sb.String()), " ")
}

func (p *mdP) parenthesizedChars() (string, bool) {
	save := p.pos
	if !p.char('(') {
		return "", false
	}
	var sb strings.Builder
	sb.WriteByte('(')
	for !p.eof() {
		r := p.peek()
		if r == '(' {
			s, ok := p.parenthesizedChars()
			if !ok {
				p.pos = save
				return "", false
			}
			sb.WriteString(s)
			continue
		}
		if r == ')' {
			p.pos++
			sb.WriteByte(')')
			return sb.String(), true
		}
		if r == '\n' {
			break
		}
		c, ok := p.litChar()
		if !ok {
			break
		}
		sb.WriteString(c)
	}
	p.pos = save
	return "", false
}

func (p *mdP) referenceLink(isImage bool, lab []Inline, raw string) ([]Inline, bool) {
	save := p.pos
	sp := p.peek() == ' '
	raw2 := ""
	// optional second reference
	s := p.pos
	if !p.ext("spaced_reference_links") {
		// no space allowed between
	} else {
		p.spnl()
	}
	// citations: [label] [@cite] should not be treated as reference
	if p.ext("citations") {
		s2 := p.pos
		if p.ext("spaced_reference_links") {
			p.spnl()
		}
		if _, ok := p.normalCite(); ok {
			p.pos = s
			raw2 = ""
			goto done
		}
		p.pos = s2
	}
	if _, r2, ok := p.reference(); ok {
		raw2 = r2
	} else {
		p.pos = s
	}
done:
	if raw2 == "" && !p.ext("shortcut_reference_links") {
		p.pos = save
		return nil, false
	}
	return []Inline{&refLinkPH{isImage: isImage, lab: lab, raw: raw, raw2: raw2, sp: sp}}, true
}

func (p *mdP) bracketedSpan() ([]Inline, bool) {
	if !p.ext("bracketed_spans") {
		return nil, false
	}
	save := p.pos
	lab, _, ok := p.reference()
	if !ok {
		p.pos = save
		return nil, false
	}
	attr, ok := p.attributes()
	if !ok {
		p.pos = save
		return nil, false
	}
	if attr.ID == "" && len(attr.KVs) == 0 && len(attr.Classes) == 1 && attr.Classes[0] == "smallcaps" {
		return []Inline{&SmallCaps{Inlines: lab}}, true
	}
	if attr.HasClass("smallcaps") && false {
	}
	if attr.ID == "" && len(attr.KVs) == 0 && len(attr.Classes) == 1 && attr.Classes[0] == "underline" {
		return []Inline{&Underline{Inlines: lab}}, true
	}
	if attr.ID == "" && len(attr.KVs) == 0 && len(attr.Classes) == 1 && attr.Classes[0] == "mark" && p.ext("mark") {
		return []Inline{&Span{Attr: attr, Inlines: lab}}, true
	}
	return []Inline{&Span{Attr: attr, Inlines: lab}}, true
}

// ---- autolinks ----

func (p *mdP) autoLink() ([]Inline, bool) {
	if !p.allowLinks {
		return nil, false
	}
	save := p.pos
	if !p.char('<') {
		return nil, false
	}
	orig, src, ok := p.uriOrEmail()
	if !ok {
		p.pos = save
		return nil, false
	}
	// extra chars until '>'
	extra := p.many(func(r rune) bool { return !unicode.IsSpace(r) && r != '>' })
	if !p.char('>') {
		p.pos = save
		return nil, false
	}
	extra = decodeEntities(extra)
	attr := Attr{}
	if p.ext("link_attributes") {
		if a, ok := p.attributes(); ok {
			attr = a
		}
	}
	return []Inline{&Link{Attr: attr, Inlines: []Inline{&Str{Text: orig + extra}}, Target: Target{URL: src + escapeURI(extra)}}}, true
}

var uriSchemes = map[string]bool{}

func init() {
	for _, s := range strings.Fields(`aaa aaas about acap adiumxtra afp afs aim apt attachment aw beshare bitcoin bolo callto cap chrome chrome-extension cid coap com-eventbrite-attendee content crid cvs data dav dict dlna-playcontainer dlna-playsingle dns doi dtn dvb ed2k facetime feed file finger fish ftp geo gg git gizmoproject go gopher gtalk h323 hcp http https iax icap icon im imap info ipn ipp irc irc6 ircs iris iris.beep iris.lwz iris.xpc iris.xpcs itms jar javascript jms keyparc lastfm ldap ldaps magnet mailto maps market message mid mms ms-help msnim msrp msrps mtqp mumble mupdate mvn news nfs ni nih nntp notes oid opaquelocktoken palm paparazzi platform pop pres proxy psyc query res resource rmi rsync rtmp rtsp secondlife service session sftp sgn shttp sieve sip sips skype smb sms snmp soap.beep soap.beeps soldat spotify ssh steam svn tag teamspeak tel telnet tftp things thismessage tip tn3270 tv udp unreal urn ut2004 vemmi ventrilo view-source webcal wss ws wtai wyciwyg xcon xcon-userid xfire xmlrpc.beep xmlrpc.beeps xmpp xri ymsgr z39.50r z39.50s isbn pmid`) {
		uriSchemes[s] = true
	}
}

// uriOrEmail parses a URI or email address at the current position.
func (p *mdP) uriOrEmail() (string, string, bool) {
	save := p.pos
	if orig, src, ok := p.uri(); ok {
		return orig, src, true
	}
	p.pos = save
	if orig, src, ok := p.emailAddress(); ok {
		return orig, src, true
	}
	p.pos = save
	return "", "", false
}

func (p *mdP) uri() (string, string, bool) {
	save := p.pos
	scheme := p.many(func(r rune) bool { return isAlphaNum(r) || r == '+' || r == '.' || r == '-' })
	if scheme == "" || !uriSchemes[strings.ToLower(scheme)] {
		p.pos = save
		return "", "", false
	}
	if !p.char(':') {
		p.pos = save
		return "", "", false
	}
	// the rest: nonspace chars, with balanced parens, excluding trailing punctuation
	start := p.pos
	var sb strings.Builder
	for !p.eof() {
		r := p.peek()
		if unicode.IsSpace(r) || r == '<' || r == '>' {
			break
		}
		if r == '(' {
			s, ok := p.parenthesizedCharsRaw()
			if ok {
				sb.WriteString(s)
				continue
			}
			break
		}
		if r == ')' {
			break
		}
		// trailing punctuation not included unless followed by more uri chars
		if strings.ContainsRune(".,;:!?'\"*_~", r) {
			// check if followed by a uri char
			n := p.peekAt(1)
			if n == 0 || unicode.IsSpace(n) || n == '<' || n == '>' || n == ')' || strings.ContainsRune(".,;:!?'\"*_~", n) {
				// stop before it, unless this is part of trailing punctuation sequence
				if strings.ContainsRune(".,;:!?'\"*_~", n) {
					// look further
					j := p.pos
					for j < len(p.s) && strings.ContainsRune(".,;:!?'\"*_~", p.s[j]) {
						j++
					}
					if j >= len(p.s) || unicode.IsSpace(p.s[j]) || p.s[j] == '<' || p.s[j] == '>' || p.s[j] == ')' {
						break
					}
				} else {
					break
				}
			}
		}
		sb.WriteRune(r)
		p.pos++
	}
	if p.pos == start {
		p.pos = save
		return "", "", false
	}
	rest := sb.String()
	// must contain something beyond scheme
	orig := scheme + ":" + rest
	return orig, escapeURI(orig), true
}

func (p *mdP) parenthesizedCharsRaw() (string, bool) {
	save := p.pos
	if !p.char('(') {
		return "", false
	}
	var sb strings.Builder
	sb.WriteByte('(')
	for !p.eof() {
		r := p.peek()
		if r == '(' {
			s, ok := p.parenthesizedCharsRaw()
			if !ok {
				p.pos = save
				return "", false
			}
			sb.WriteString(s)
			continue
		}
		if r == ')' {
			p.pos++
			sb.WriteByte(')')
			return sb.String(), true
		}
		if unicode.IsSpace(r) {
			break
		}
		sb.WriteRune(r)
		p.pos++
	}
	p.pos = save
	return "", false
}

func (p *mdP) emailAddress() (string, string, bool) {
	save := p.pos
	first, ok := p.satisfy(isAlphaNum)
	if !ok {
		return "", "", false
	}
	local := string(first) + p.many(func(r rune) bool { return isAlphaNum(r) || strings.ContainsRune("-+_.~", r) })
	if !p.char('@') {
		p.pos = save
		return "", "", false
	}
	var domParts []string
	for {
		part := p.many(func(r rune) bool { return isAlphaNum(r) || r == '-' })
		if part == "" {
			p.pos = save
			return "", "", false
		}
		domParts = append(domParts, part)
		if p.peek() == '.' && isAlphaNum(p.peekAt(1)) {
			p.pos++
			continue
		}
		break
	}
	if len(domParts) < 2 {
		p.pos = save
		return "", "", false
	}
	addr := local + "@" + strings.Join(domParts, ".")
	return addr, escapeURI("mailto:" + addr), true
}

func (p *mdP) bareURL() ([]Inline, bool) {
	if !p.allowLinks {
		return nil, false
	}
	save := p.pos
	orig, src, ok := p.uriOrEmail()
	if !ok {
		p.pos = save
		return nil, false
	}
	// must not be followed by alnum? pandoc: notFollowedBy $ try $ spaces >> htmlTag
	return []Inline{&Link{Inlines: []Inline{&Str{Text: orig}}, Target: Target{URL: src}}}, true
}

// ---- raw HTML inline ----

func (p *mdP) spanHtml() ([]Inline, bool) {
	if !p.ext("native_spans") {
		return nil, false
	}
	save := p.pos
	tag, n, ok := p.htmlTagAt()
	if !ok || tag.Kind != tagOpen || tag.Name != "span" || tag.SelfClosing {
		return nil, false
	}
	p.pos += n
	var contents []Inline
	for {
		if t, m, ok := p.htmlTagAt(); ok && t.Kind == tagClose && t.Name == "span" {
			p.pos += m
			attr := attrFromHTML(tag.Attrs)
			if attr.ID == "" && len(attr.KVs) == 0 && len(attr.Classes) == 1 && attr.Classes[0] == "smallcaps" {
				return []Inline{&SmallCaps{Inlines: contents}}, true
			}
			if attr.ID == "" && len(attr.KVs) == 0 && len(attr.Classes) == 1 && attr.Classes[0] == "underline" {
				return []Inline{&Underline{Inlines: contents}}, true
			}
			// style="font-variant:small-caps" → SmallCaps
			if style, ok := attr.Get("style"); ok && strings.Contains(strings.ReplaceAll(style, " ", ""), "font-variant:small-caps") && attr.ID == "" && len(attr.Classes) == 0 && len(attr.KVs) == 1 {
				return []Inline{&SmallCaps{Inlines: contents}}, true
			}
			return []Inline{&Span{Attr: attr, Inlines: contents}}, true
		}
		x, ok := p.inline()
		if !ok {
			p.pos = save
			return nil, false
		}
		contents = meldInlines(contents, x)
	}
}

func (p *mdP) rawHtmlInline() ([]Inline, bool) {
	if !p.ext("raw_html") {
		return nil, false
	}
	tag, n, ok := p.htmlTagAt()
	if !ok {
		return nil, false
	}
	if tag.Kind == tagDecl {
		return nil, false
	}
	mdInHtml := p.ext("markdown_in_html_blocks") || p.ext("markdown_attribute")
	if mdInHtml {
		if !tag.IsInlineTag() {
			return nil, false
		}
		if p.inHtmlBlock != "" && tag.Kind == tagClose && tag.Name == p.inHtmlBlock {
			return nil, false
		}
	}
	p.pos += n
	if tag.Kind == tagComment && p.st.exts.Has("__strip_comments") {
		return []Inline{}, true
	}
	return []Inline{&RawInline{Format: "html", Text: tag.Raw}}, true
}

// ---- raw LaTeX inline ----

func (p *mdP) rawLaTeXInline() ([]Inline, bool) {
	if !p.ext("raw_tex") {
		return nil, false
	}
	save := p.pos
	if p.peek() != '\\' {
		return nil, false
	}
	if p.lookingAt("\\begin{") {
		s, env, ok := p.texEnvironment()
		if !ok {
			p.pos = save
			return nil, false
		}
		_ = env
		return []Inline{&RawInline{Format: "tex", Text: s}}, true
	}
	if !unicode.IsLetter(p.peekAt(1)) {
		return nil, false
	}
	s, ok := p.texCommand()
	if !ok {
		p.pos = save
		return nil, false
	}
	return []Inline{&RawInline{Format: "tex", Text: s}}, true
}

// ---- notes ----

func (p *mdP) note() ([]Inline, bool) {
	if !p.ext("footnotes") {
		return nil, false
	}
	save := p.pos
	label, ok := p.noteMarker()
	if !ok {
		p.pos = save
		return nil, false
	}
	if p.inNote {
		// pandoc disallows notes within notes? It allows but let's keep.
	}
	return []Inline{&notePH{label: label}}, true
}

func (p *mdP) inlineNote() ([]Inline, bool) {
	if !p.ext("inline_notes") {
		return nil, false
	}
	save := p.pos
	if !p.char('^') {
		return nil, false
	}
	if p.peek() != '[' {
		p.pos = save
		return nil, false
	}
	oldInNote := p.inNote
	p.inNote = true
	ils, _, ok := p.reference()
	p.inNote = oldInNote
	if !ok {
		p.pos = save
		return nil, false
	}
	return []Inline{&Note{Blocks: []Block{&Para{Inlines: ils}}}}, true
}

// ---- citations ----

func (p *mdP) cite() ([]Inline, bool) {
	if !p.ext("citations") {
		return nil, false
	}
	save := p.pos
	if cits, ok := p.textualCite(); ok {
		return cits, true
	}
	p.pos = save
	cits, ok := p.normalCite()
	if !ok {
		p.pos = save
		return nil, false
	}
	raw := string(p.s[save:p.pos])
	return []Inline{&Cite{Citations: cits, Inlines: []Inline{&Str{Text: raw}}}}, true
}

func (p *mdP) citeKey() (bool, string, bool) {
	save := p.pos
	if !p.notAfterString() {
		return false, "", false
	}
	suppress := p.char('-')
	if !p.char('@') {
		p.pos = save
		return false, "", false
	}
	// key: {...} form or regular
	if p.char('{') {
		key := p.many(func(r rune) bool { return r != '}' && r != '\n' })
		if !p.char('}') || key == "" {
			p.pos = save
			return false, "", false
		}
		return suppress, key, true
	}
	first, ok := p.satisfy(func(r rune) bool { return isAlphaNum(r) || r == '_' })
	if !ok {
		p.pos = save
		return false, "", false
	}
	var sb strings.Builder
	sb.WriteRune(first)
	for !p.eof() {
		r := p.peek()
		if isAlphaNum(r) || r == '_' {
			sb.WriteRune(r)
			p.pos++
			continue
		}
		if strings.ContainsRune(":.#$%&-+?<>~/", r) {
			// internal punctuation must be followed by alnum
			n := p.peekAt(1)
			if isAlphaNum(n) || n == '_' {
				sb.WriteRune(r)
				p.pos++
				continue
			}
		}
		break
	}
	return suppress, sb.String(), true
}

func (p *mdP) textualCite() ([]Inline, bool) {
	save := p.pos
	suppress, key, ok := p.citeKey()
	if !ok {
		return nil, false
	}
	mode := AuthorInText
	if suppress {
		mode = SuppressAuthor
	}
	first := Citation{ID: key, Mode: mode}
	// optional following bracketed suffix/citations
	s := p.pos
	p.spnl()
	if p.peek() == '[' {
		s2 := p.pos
		if rest, ok := p.normalCite(); ok {
			cits := append([]Citation{first}, rest...)
			raw := string(p.s[save:p.pos])
			if suppress {
				// -@key [...] → all normal? pandoc: if suppress, first becomes SuppressAuthor and rest...
			}
			return []Inline{&Cite{Citations: cits, Inlines: []Inline{&Str{Text: raw}}}}, true
		}
		p.pos = s2
		// bare locator [p. 33]
		if p.char('[') {
			start := p.pos
			depth := 1
			for !p.eof() && depth > 0 {
				if p.peek() == '[' {
					depth++
				} else if p.peek() == ']' {
					depth--
				}
				if depth > 0 {
					p.pos++
				}
			}
			if depth == 0 {
				inner := string(p.s[start:p.pos])
				p.pos++
				// must not look like a citation key inside
				if !strings.Contains(inner, "@") {
					suffix := p.parseInlinesStr(inner)
					first.Suffix = suffix
					raw := string(p.s[save:p.pos])
					return []Inline{&Cite{Citations: []Citation{first}, Inlines: []Inline{&Str{Text: raw}}}}, true
				}
			}
		}
	}
	p.pos = s
	raw := string(p.s[save:p.pos])
	return []Inline{&Cite{Citations: []Citation{first}, Inlines: []Inline{&Str{Text: raw}}}}, true
}

func (p *mdP) normalCite() ([]Citation, bool) {
	save := p.pos
	if !p.char('[') {
		return nil, false
	}
	p.spnl()
	var cits []Citation
	for {
		c, ok := p.citation()
		if !ok {
			p.pos = save
			return nil, false
		}
		cits = append(cits, c)
		p.spnl()
		if p.char(';') {
			p.spnl()
			continue
		}
		break
	}
	if !p.char(']') {
		p.pos = save
		return nil, false
	}
	return cits, true
}

func (p *mdP) citation() (Citation, bool) {
	save := p.pos
	// prefix: inlines until @ or -@
	var prefix []Inline
	for !p.eof() {
		if p.peek() == '@' || (p.peek() == '-' && p.peekAt(1) == '@') || p.peek() == ';' || p.peek() == ']' {
			break
		}
		s := p.pos
		if _, ok := p.citeKeyAhead(); ok {
			break
		}
		p.pos = s
		x, ok := p.inline()
		if !ok {
			break
		}
		prefix = meldInlines(prefix, x)
	}
	suppress, key, ok := p.citeKey()
	if !ok {
		p.pos = save
		return Citation{}, false
	}
	// suffix: until ; or ]
	var suffix []Inline
	start := p.pos
	depth := 0
	for !p.eof() {
		r := p.peek()
		if r == '[' {
			depth++
		} else if r == ']' {
			if depth == 0 {
				break
			}
			depth--
		} else if r == ';' && depth == 0 {
			break
		}
		p.pos++
	}
	if p.pos > start {
		suffix = p.parseInlinesStr(string(p.s[start:p.pos]))
		// pandoc keeps leading comma/space in suffix: e.g. ", p. 33"
		raw := string(p.s[start:p.pos])
		q := p.sub(raw)
		suffix = trimInlines(q.inlines())
	}
	mode := NormalCitation
	if suppress {
		mode = SuppressAuthor
	}
	return Citation{ID: key, Prefix: trimInlines(prefix), Suffix: suffix, Mode: mode}, true
}

func (p *mdP) citeKeyAhead() (string, bool) {
	save := p.pos
	defer func() { p.pos = save }()
	_, k, ok := p.citeKey()
	return k, ok
}

func (p *mdP) exampleRef() ([]Inline, bool) {
	if !p.ext("example_lists") {
		return nil, false
	}
	save := p.pos
	if !p.char('@') {
		return nil, false
	}
	label, ok := p.many1(func(r rune) bool { return isAlphaNum(r) || r == '_' || r == '-' })
	if !ok {
		p.pos = save
		return nil, false
	}
	return []Inline{&exampleRefPH{label: label}}, true
}

