actions.command:
cd /workspace && cat > src/mdlists.go <<'EOF'
package main

import (
	"strings"
	"unicode"
)

// ---- List markers ----

func isBulletMarker(r rune) bool { return r == '*' || r == '+' || r == '-' }

// bulletListStart parses a bullet list marker at the current position.
func (p *mdP) bulletListStart() bool {
	save := p.pos
	p.skipNonindentSpaces()
	// not an hrule
	s := p.pos
	if _, ok := p.hrule(); ok {
		p.pos = save
		return false
	}
	p.pos = s
	if !isBulletMarker(p.peek()) {
		p.pos = save
		return false
	}
	p.pos++
	if p.peek() == '\n' {
		return true
	}
	if !p.char(' ') {
		p.pos = save
		return false
	}
	// gobble up to 3 more spaces, not followed by a space
	s2 := p.pos
	n := p.gobbleAtMostSpaces(3)
	if isSpaceChar(p.peek()) {
		// more than 4 spaces: it's a code block within the item; back off
		p.pos = s2
	}
	_ = n
	return true
}

// anyOrderedListStart parses an ordered list marker, returning start, style, delim.
func (p *mdP) anyOrderedListStart() (int, ListNumberStyle, ListNumberDelim, bool) {
	save := p.pos
	p.skipNonindentSpaces()
	// not a header "#."
	s := p.pos
	if p.peek() == '#' && p.peekAt(1) != '.' && p.peekAt(1) != ')' {
		p.pos = save
		return 0, 0, 0, false
	}
	p.pos = s
	start, style, delim, ok := p.listMarkerCore()
	if !ok {
		p.pos = save
		return 0, 0, 0, false
	}
	if p.peek() == '\n' {
		return start, style, delim, true
	}
	if !p.char(' ') {
		p.pos = save
		return 0, 0, 0, false
	}
	s2 := p.pos
	p.gobbleAtMostSpaces(3)
	if isSpaceChar(p.peek()) {
		p.pos = s2
	}
	return start, style, delim, true
}

// listMarkerCore parses the number/letter + delimiter portion.
func (p *mdP) listMarkerCore() (int, ListNumberStyle, ListNumberDelim, bool) {
	save := p.pos
	fancy := p.ext("fancy_lists")
	paren := false
	if fancy && p.char('(') {
		paren = true
	}
	var start int
	var style ListNumberStyle
	r := p.peek()
	switch {
	case isDigitR(r):
		num := p.many(isDigitR)
		if len(num) > 9 {
			p.pos = save
			return 0, 0, 0, false
		}
		start = atoi(num)
		style = Decimal
	case r == '#':
		p.pos++
		start = 1
		style = DefaultStyle
	case r == '@' && p.ext("example_lists"):
		p.pos++
		start = 1
		style = Example
		// optional label
		label := p.many(func(r rune) bool { return isAlphaNum(r) || r == '_' || r == '-' })
		p.pendingExampleLabel = label
	case fancy && unicode.IsLower(r) && r < 128:
		// could be roman or alpha
		s := p.pos
		letters := p.many(func(r rune) bool { return r >= 'a' && r <= 'z' })
		if len(letters) == 1 {
			// single letter: alpha (but 'i', 'v', 'x', 'l', 'c', 'd', 'm' ambiguous -> roman if followed by delimiter? pandoc: lowerAlpha first except...)
			// pandoc tries: lowerRoman first via romanNumeral, which requires... actually anyOrderedListMarker order:
			// decimal, exampleNum, defaultNum, lowerAlpha, lowerRoman, upperAlpha, upperRoman
			if isRomanLetter(letters[0]) && false {
			}
			start = int(letters[0]-'a') + 1
			style = LowerAlpha
		} else {
			p.pos = s
			rn, ok := p.romanNumeral(false)
			if !ok {
				p.pos = save
				return 0, 0, 0, false
			}
			start = rn
			style = LowerRoman
		}
	case fancy && unicode.IsUpper(r) && r < 128:
		s := p.pos
		letters := p.many(func(r rune) bool { return r >= 'A' && r <= 'Z' })
		if len(letters) == 1 {
			start = int(letters[0]-'A') + 1
			style = UpperAlpha
		} else {
			p.pos = s
			rn, ok := p.romanNumeral(true)
			if !ok {
				p.pos = save
				return 0, 0, 0, false
			}
			start = rn
			style = UpperRoman
		}
	default:
		p.pos = save
		return 0, 0, 0, false
	}
	var delim ListNumberDelim
	if paren {
		if !p.char(')') {
			p.pos = save
			return 0, 0, 0, false
		}
		delim = TwoParens
	} else if p.char('.') {
		delim = Period
	} else if fancy && p.char(')') {
		delim = OneParen
	} else {
		p.pos = save
		return 0, 0, 0, false
	}
	// upper alpha with period requires two spaces after (to avoid "A. Smith")
	if style == UpperAlpha && delim == Period {
		if !(p.peek() == ' ' && p.peekAt(1) == ' ') && p.peek() != '\n' {
			p.pos = save
			return 0, 0, 0, false
		}
	}
	// single lowercase/uppercase letter roman handled above as alpha; but 'i.' etc.: pandoc parses lowerRoman after lowerAlpha, so 'i.' -> LowerAlpha? No: pandoc tries lowerAlpha first, which would accept 'i'. Hmm, but observed "(i) roman" gave type="i". Handle below.
	return start, style, delim, true
}

func isRomanLetter(r byte) bool {
	return strings.IndexByte("ivxlcdm", r) >= 0
}

func (p *mdP) romanNumeral(upper bool) (int, bool) {
	save := p.pos
	s := p.many(func(r rune) bool {
		if upper {
			return strings.ContainsRune("IVXLCDM", r)
		}
		return strings.ContainsRune("ivxlcdm", r)
	})
	if s == "" {
		return 0, false
	}
	n := romanToInt(strings.ToUpper(s))
	if n <= 0 {
		p.pos = save
		return 0, false
	}
	return n, true
}

func romanToInt(s string) int {
	vals := map[byte]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
	total := 0
	for i := 0; i < len(s); i++ {
		v := vals[s[i]]
		if i+1 < len(s) && vals[s[i+1]] > v {
			total -= v
		} else {
			total += v
		}
	}
	return total
}

func atoi(s string) int {
	n := 0
	for _, r := range s {
		n = n*10 + int(r-'0')
	}
	return n
}

// listStart: bullet or ordered list start
func (p *mdP) listStart() bool {
	save := p.pos
	if p.bulletListStart() {
		p.pos = save
		return true
	}
	p.pos = save
	_, _, _, ok := p.anyOrderedListStart()
	p.pos = save
	return ok
}

// orderedListStart with required style/delim
func (p *mdP) orderedListStart(style ListNumberStyle, delim ListNumberDelim) bool {
	save := p.pos
	_, st, dl, ok := p.anyOrderedListStart()
	if !ok || st != style || dl != delim {
		p.pos = save
		return false
	}
	return true
}

// ---- List items ----

// listLineCommon: rest of the line (handling code spans and comments spanning lines is skipped)
func (p *mdP) listLineCommon() string {
	var sb strings.Builder
	for !p.eof() {
		r := p.peek()
		if r == '\n' {
			p.pos++
			break
		}
		if r == '`' {
			s := p.pos
			if _, ok := p.code(); ok {
				sb.WriteString(string(p.s[s:p.pos]))
				continue
			}
			p.pos = s
		}
		if r == '<' && p.lookingAt("<!--") {
			s := p.pos
			if t, n, ok := p.htmlTagAt(); ok && t.Kind == tagComment {
				p.pos += n
				sb.WriteString(string(p.s[s:p.pos]))
				continue
			}
		}
		sb.WriteRune(r)
		p.pos++
	}
	return sb.String()
}

func (p *mdP) notFollowedByHtmlCloser() bool {
	if p.inHtmlBlock == "" {
		return true
	}
	return !p.lookingAtCloseTag(p.inHtmlBlock)
}

func (p *mdP) notFollowedByDivCloser() bool {
	if p.divLevel == 0 {
		return true
	}
	return !p.lookingAtDivFenceEnd()
}

// listLine: a continuation line of a list item (not starting a new list item)
func (p *mdP) listLine(continuationIndent int) (string, bool) {
	save := p.pos
	// not a list start after indentation
	s := p.pos
	p.gobbleSpaces(continuationIndent)
	p.skipSpaces()
	if p.listStart() {
		p.pos = save
		return "", false
	}
	p.pos = s
	if !p.notFollowedByHtmlCloser() || !p.notFollowedByDivCloser() {
		p.pos = save
		return "", false
	}
	p.gobbleSpaces(continuationIndent)
	return p.listLineCommon(), true
}

// rawListItem parses the first part of a list item (start marker + lines until blank)
func (p *mdP) rawListItem(fourSpaceRule bool, start func() bool) (string, int, bool) {
	save := p.pos
	pos1 := p.pos
	if !start() {
		p.pos = save
		return "", 0, false
	}
	pos2 := p.pos
	continuationIndent := pos2 - pos1
	// compute column difference (the marker may span lines? no)
	if fourSpaceRule {
		continuationIndent = 4
	}
	first := p.listLineCommon()
	var rest []string
	for {
		s := p.pos
		if p.lookingAtListStart() {
			break
		}
		if p.lookingAtFencedCode() {
			break
		}
		if p.isBlankLineAhead() {
			break
		}
		l, ok := p.listLine(continuationIndent)
		if !ok {
			p.pos = s
			break
		}
		rest = append(rest, l)
	}
	blanks, _ := p.blanklines()
	var sb strings.Builder
	sb.WriteString(first)
	sb.WriteByte('\n')
	for _, l := range rest {
		sb.WriteString(l)
		sb.WriteByte('\n')
	}
	sb.WriteString(blanks)
	return sb.String(), continuationIndent, true
}

func (p *mdP) listContinuation(continuationIndent int) (string, bool) {
	save := p.pos
	if p.isBlankLineAhead() || !p.notFollowedByHtmlCloser() || !p.notFollowedByDivCloser() {
		return "", false
	}
	if !p.gobbleSpaces(continuationIndent) {
		p.pos = save
		return "", false
	}
	x, ok := p.anyLineNewline()
	if !ok {
		p.pos = save
		return "", false
	}
	var sb strings.Builder
	sb.WriteString(x)
	for {
		s := p.pos
		if p.isBlankLineAhead() || !p.notFollowedByHtmlCloser() || !p.notFollowedByDivCloser() {
			break
		}
		if !p.gobbleSpaces(continuationIndent) {
			if p.lookingAtListStart() {
				p.pos = s
				break
			}
		}
		l, ok := p.anyLineNewline()
		if !ok {
			p.pos = s
			break
		}
		sb.WriteString(l)
	}
	blanks, _ := p.blanklines()
	sb.WriteString(blanks)
	return sb.String(), true
}

func (p *mdP) listItem(fourSpaceRule bool, start func() bool) ([]Block, bool) {
	save := p.pos
	first, continuationIndent, ok := p.rawListItem(fourSpaceRule, start)
	if !ok {
		p.pos = save
		return nil, false
	}
	var sb strings.Builder
	sb.WriteString(first)
	for {
		s := p.pos
		c, ok := p.listContinuation(continuationIndent)
		if !ok {
			p.pos = s
			break
		}
		sb.WriteString(c)
	}
	raw := sb.String()
	q := p.sub(raw)
	q.inList = true
	contents := q.parseBlocks()
	if p.ext("task_lists") {
		contents = taskListItemFromAscii(contents)
	}
	return contents, true
}

func taskListItemFromAscii(bs []Block) []Block {
	if len(bs) == 0 {
		return bs
	}
	convert := func(ils []Inline) ([]Inline, bool) {
		if len(ils) < 2 {
			return ils, false
		}
		s, ok := ils[0].(*Str)
		if !ok {
			return ils, false
		}
		if _, ok := ils[1].(*Space); !ok {
			return ils, false
		}
		switch s.Text {
		case "[", "[]":
			// "[ ]" is parsed as Str "[" Space Str "]"
			if s.Text == "[" {
				if len(ils) >= 4 {
					if s2, ok := ils[2].(*Str); ok && s2.Text == "]" {
						if _, ok := ils[3].(*Space); ok {
							return append([]Inline{&Str{Text: "\u2610"}, &Space{}}, ils[4:]...), true
						}
					}
				}
			}
			return ils, false
		case "[x]", "[X]":
			return append([]Inline{&Str{Text: "\u2612"}, &Space{}}, ils[2:]...), true
		}
		return ils, false
	}
	switch b := bs[0].(type) {
	case *Plain:
		if ils, ok := convert(b.Inlines); ok {
			return append([]Block{&Plain{Inlines: ils}}, bs[1:]...)
		}
	case *Para:
		if ils, ok := convert(b.Inlines); ok {
			return append([]Block{&Para{Inlines: ils}}, bs[1:]...)
		}
	}
	return bs
}

func (p *mdP) bulletList() ([]Block, bool) {
	save := p.pos
	fourSpaceRule := p.ext("four_space_rule")
	var items [][]Block
	for {
		s := p.pos
		it, ok := p.listItem(fourSpaceRule, p.bulletListStart)
		if !ok {
			p.pos = s
			break
		}
		items = append(items, it)
	}
	if len(items) == 0 {
		p.pos = save
		return nil, false
	}
	return []Block{&BulletList{Items: compactify(items)}}, true
}

func (p *mdP) orderedList() ([]Block, bool) {
	save := p.pos
	start, style, delim, ok := p.anyOrderedListStart()
	p.pos = save
	if !ok {
		return nil, false
	}
	if !((style == DefaultStyle || style == Decimal || style == Example) && (delim == DefaultDelim || delim == Period)) {
		if !p.ext("fancy_lists") {
			return nil, false
		}
	}
	if style == Example && !p.ext("example_lists") {
		return nil, false
	}
	fourSpaceRule := p.ext("four_space_rule") || style == Example
	var items [][]Block
	for {
		s := p.pos
		it, ok := p.listItem(fourSpaceRule, func() bool {
			if style == Example {
				p.pendingExampleLabel = ""
			}
			ok := p.orderedListStart(style, delim)
			if ok && style == Example {
				p.st.exampleCount++
				if p.pendingExampleLabel != "" {
					p.st.exampleLabels[p.pendingExampleLabel] = p.st.exampleCount
				}
			}
			return ok
		})
		if !ok {
			p.pos = s
			break
		}
		items = append(items, it)
	}
	if len(items) == 0 {
		p.pos = save
		return nil, false
	}
	start2 := 1
	if style == Example {
		start2 = p.st.exampleCount - len(items) + 1
	} else if p.ext("startnum") {
		start2 = start
	}
	// pandoc: roman numeral detection -- a single-letter start like "i." with fancy lists
	return []Block{&OrderedList{Attrs: ListAttributes{Start: start2, Style: style, Delim: delim}, Items: compactify(items)}}, true
}

// compactify: change final list item from Para to Plain if the list contains no other Para
func compactify(items [][]Block) [][]Block {
	if len(items) == 0 {
		return items
	}
	final := items[len(items)-1]
	if len(final) == 0 {
		return items
	}
	lastBlock, ok := final[len(final)-1].(*Para)
	if !ok {
		return items
	}
	paraCount := 0
	for _, it := range items {
		for _, b := range it {
			if _, ok := b.(*Para); ok {
				paraCount++
			}
		}
	}
	if paraCount == 1 {
		newFinal := append([]Block{}, final[:len(final)-1]...)
		newFinal = append(newFinal, &Plain{Inlines: lastBlock.Inlines})
		out := append([][]Block{}, items[:len(items)-1]...)
		return append(out, newFinal)
	}
	return items
}

// ---- Definition lists ----

func (p *mdP) defListMarker() bool {
	save := p.pos
	sps := p.nonindentSpaces()
	if !(p.char(':') || p.char('~')) {
		p.pos = save
		return false
	}
	remaining := p.st.tabStop - (len(sps) + 1)
	if remaining > 0 {
		s := p.pos
		if p.gobbleSpaces(remaining) {
			return true
		}
		p.pos = s
		if p.char('\t') {
			return true
		}
		p.pos = save
		return false
	}
	p.pos = save
	return false
}

func (p *mdP) definitionList() ([]Block, bool) {
	if !p.ext("definition_lists") {
		return nil, false
	}
	save := p.pos
	// lookahead: a line, optional blank line, then a def marker
	s := p.pos
	if _, ok := p.anyLine(); !ok {
		p.pos = save
		return nil, false
	}
	s2 := p.pos
	if p.blankline() {
		// don't capture table caption as def list
		s3 := p.pos
		if _, ok := p.table(); ok {
			p.pos = save
			return nil, false
		}
		p.pos = s3
	}
	if !p.defListMarker() {
		p.pos = s2
		if !p.defListMarker() {
			p.pos = save
			return nil, false
		}
	}
	p.pos = s
	var items []DefItem
	for {
		s := p.pos
		it, ok := p.definitionListItem()
		if !ok {
			p.pos = s
			break
		}
		items = append(items, it)
	}
	if len(items) == 0 {
		p.pos = save
		return nil, false
	}
	return []Block{&DefinitionList{Items: compactifyDL(items)}}, true
}

func (p *mdP) definitionListItem() (DefItem, bool) {
	save := p.pos
	rawLine, ok := p.anyLine()
	if !ok {
		return DefItem{}, false
	}
	var raws []string
	for {
		s := p.pos
		r, ok := p.defRawBlock()
		if !ok {
			p.pos = s
			break
		}
		raws = append(raws, r)
	}
	if len(raws) == 0 {
		p.pos = save
		return DefItem{}, false
	}
	term := p.parseInlinesStr(rawLine)
	var defs [][]Block
	for _, r := range raws {
		defs = append(defs, p.parseBlocksStr(r+"\n"))
	}
	p.blanklines()
	return DefItem{Term: term, Defs: defs}, true
}

func (p *mdP) defRawBlock() (string, bool) {
	save := p.pos
	hasBlank := p.blankline()
	if !p.defListMarker() {
		p.pos = save
		return "", false
	}
	firstline, _ := p.anyLineNewline()
	dline := func() (string, bool) {
		s := p.pos
		if p.isBlankLineAhead() || !p.notFollowedByHtmlCloser() || !p.notFollowedByDivCloser() {
			return "", false
		}
		if !p.indentSpaces() {
			// lazy continuation allowed if not a def marker
			s2 := p.pos
			if p.defListMarker() {
				p.pos = s
				return "", false
			}
			p.pos = s2
		}
		l, ok := p.anyLine()
		if !ok {
			p.pos = s
			return "", false
		}
		return l, true
	}
	var rawlines []string
	for {
		l, ok := dline()
		if !ok {
			break
		}
		rawlines = append(rawlines, l)
	}
	var cont strings.Builder
	for {
		s := p.pos
		trailing, _ := p.blanklines()
		if !p.indentSpaces() {
			p.pos = s
			break
		}
		if p.isBlankLineAhead() {
			p.pos = s
			break
		}
		ln, ok := p.anyLine()
		if !ok {
			p.pos = s
			break
		}
		lns := []string{ln}
		for {
			l, ok := dline()
			if !ok {
				break
			}
			lns = append(lns, l)
		}
		cont.WriteString(trailing)
		for _, l := range lns {
			cont.WriteString(l)
			cont.WriteByte('\n')
		}
	}
	var sb strings.Builder
	sb.WriteString(firstline)
	for _, l := range rawlines {
		sb.WriteString(l)
		sb.WriteByte('\n')
	}
	sb.WriteString(cont.String())
	result := trimRight(sb.String())
	if hasBlank || cont.Len() > 0 {
		result += "\n\n"
	}
	return result, true
}

func compactifyDL(items []DefItem) []DefItem {
	var defs [][]Block
	for _, it := range items {
		defs = append(defs, it.Defs...)
	}
	if len(defs) == 0 {
		return items
	}
	var all []Block
	for _, d := range defs {
		all = append(all, d...)
	}
	if len(all) == 0 {
		return items
	}
	lastPara, ok := all[len(all)-1].(*Para)
	if !ok {
		return items
	}
	isPara := func(d []Block) bool {
		for _, b := range d {
			if _, ok := b.(*Para); ok {
				return true
			}
		}
		return false
	}
	for _, d := range defs[:len(defs)-1] {
		if isPara(d) {
			return items
		}
	}
	lastDef := defs[len(defs)-1]
	// check the last def has only one para (the final one)
	count := 0
	for _, b := range lastDef {
		if _, ok := b.(*Para); ok {
			count++
		}
	}
	if count != 1 {
		return items
	}
	lastItem := items[len(items)-1]
	newDefs := append([][]Block{}, lastItem.Defs[:len(lastItem.Defs)-1]...)
	newLast := append([]Block{}, lastDef[:len(lastDef)-1]...)
	newLast = append(newLast, &Plain{Inlines: lastPara.Inlines})
	newDefs = append(newDefs, newLast)
	out := append([]DefItem{}, items[:len(items)-1]...)
	return append(out, DefItem{Term: lastItem.Term, Defs: newDefs})
}
