package main

import (
	"sort"
	"strings"
)

type rawTable struct {
	aligns []Alignment
	widths []float64
	heads  [][]Block // header cells (may be empty → no header)
	rows   [][][]Block
}

func (p *mdP) table() ([]Block, bool) {
	save := p.pos
	var frontCaption []Inline
	hasFront := false
	if c, ok := p.tableCaption(); ok {
		frontCaption = c
		hasFront = true
	}
	var t rawTable
	var ok bool
	s := p.pos
	if p.ext("pipe_tables") && p.scanForPipe() {
		t, ok = p.pipeTable()
	}
	if !ok {
		p.pos = s
		if p.ext("multiline_tables") {
			t, ok = p.multilineTable(false)
		}
	}
	if !ok {
		p.pos = s
		if p.ext("simple_tables") {
			t, ok = p.simpleTable(true)
			if !ok {
				p.pos = s
				t, ok = p.simpleTable(false)
			}
		}
	}
	if !ok {
		p.pos = s
		if p.ext("multiline_tables") {
			t, ok = p.multilineTable(true)
		}
	}
	if !ok {
		p.pos = s
		if p.ext("grid_tables") {
			t, ok = p.gridTable(false)
			if !ok {
				p.pos = s
				t, ok = p.gridTable(true)
			}
		}
	}
	if !ok {
		p.pos = save
		return nil, false
	}
	p.blanklines()
	caption := frontCaption
	if !hasFront {
		if c, ok := p.tableCaption(); ok {
			caption = c
		}
	}
	return []Block{buildTable(caption, t)}, true
}

func buildTable(caption []Inline, t rawTable) *Table {
	ncols := len(t.aligns)
	specs := make([]ColSpec, ncols)
	total := 0.0
	for _, w := range t.widths {
		total += w
	}
	for i := 0; i < ncols; i++ {
		w := 0.0
		if i < len(t.widths) {
			w = t.widths[i]
		}
		if total > 1 {
			w = w / total
		}
		specs[i] = ColSpec{Align: t.aligns[i], Width: ColWidth{Default: true}}
		if w > 0 {
			specs[i].Width = ColWidth{Width: w}
		}
	}
	mkRow := func(cells [][]Block) Row {
		r := Row{}
		for i := 0; i < ncols; i++ {
			var bs []Block
			if i < len(cells) {
				bs = cells[i]
			}
			r.Cells = append(r.Cells, Cell{Align: AlignDefault, RowSpan: 1, ColSpan: 1, Blocks: bs})
		}
		return r
	}
	tbl := &Table{}
	if len(caption) > 0 {
		tbl.Caption = Caption{Blocks: []Block{&Plain{Inlines: caption}}}
	}
	tbl.ColSpecs = specs
	if len(t.heads) > 0 {
		allEmpty := true
		for _, h := range t.heads {
			if len(h) > 0 {
				allEmpty = false
			}
		}
		if !allEmpty {
			tbl.Head = TableHead{Rows: []Row{mkRow(t.heads)}}
		}
	}
	body := TableBody{}
	for _, r := range t.rows {
		body.Body = append(body.Body, mkRow(r))
	}
	tbl.Bodies = []TableBody{body}
	return tbl
}

func (p *mdP) tableCaption() ([]Inline, bool) {
	if !p.ext("table_captions") {
		return nil, false
	}
	save := p.pos
	p.skipNonindentSpaces()
	if p.str("Table:") {
	} else if p.char(':') {
		if isPunctuationR(p.peek()) {
			p.pos = save
			return nil, false
		}
	} else {
		p.pos = save
		return nil, false
	}
	ils, ok := p.inlines1()
	if !ok {
		p.pos = save
		return nil, false
	}
	if _, ok := p.blanklines(); !ok {
		p.pos = save
		return nil, false
	}
	return trimInlines(ils), true
}

// ---- pipe tables ----

func (p *mdP) scanForPipe() bool {
	// current line (or next if current is empty) contains a pipe
	i := p.pos
	for i < len(p.s) && p.s[i] != '\n' {
		if p.s[i] == '|' {
			return true
		}
		i++
	}
	return false
}

func (p *mdP) pipeTable() (rawTable, bool) {
	save := p.pos
	p.nonindentSpaces()
	if p.eof() || p.peek() == '\n' || isSpaceChar(p.peek()) {
		p.pos = save
		return rawTable{}, false
	}
	heads, ok := p.pipeTableRow()
	if !ok {
		p.pos = save
		return rawTable{}, false
	}
	aligns, seplengths, ok := p.pipeBreak()
	if !ok {
		p.pos = save
		return rawTable{}, false
	}
	ncols := len(aligns)
	if len(heads) > ncols {
		heads = heads[:ncols]
	}
	var rows [][][]Block
	for {
		s := p.pos
		r, ok := p.pipeTableRow()
		if !ok {
			p.pos = s
			break
		}
		if len(r) > ncols {
			r = r[:ncols]
		}
		rows = append(rows, r)
	}
	// widths
	maxlen := 0
	measure := func(cells [][]Block) {
		for _, c := range cells {
			n := len([]rune(stringifyBlocks(c)))
			if n > maxlen {
				maxlen = n
			}
		}
	}
	measure(heads)
	for _, r := range rows {
		measure(r)
	}
	// pandoc measures the raw line lengths? It uses: maximum of T.length . stringify of cells.
	widths := make([]float64, ncols)
	if maxlen > p.st.columns {
		total := 0
		for _, l := range seplengths {
			total += l
		}
		for i, l := range seplengths {
			widths[i] = float64(l) / float64(total)
		}
	}
	return rawTable{aligns: aligns, widths: widths, heads: heads, rows: rows}, true
}

func (p *mdP) pipeTableRow() ([][]Block, bool) {
	save := p.pos
	if !p.scanForPipe() {
		return nil, false
	}
	p.skipSpaces()
	openPipe := p.char('|')
	var cells [][]Block
	for {
		start := p.pos
		// chunk until | or newline, handling code/math/escapes
		for !p.eof() {
			r := p.peek()
			if r == '|' || r == '\n' || r == '\r' {
				break
			}
			if r == '`' {
				s := p.pos
				if _, ok := p.code(); ok {
					continue
				}
				p.pos = s + 1
				continue
			}
			if r == '$' {
				s := p.pos
				if _, ok := p.math(); ok {
					continue
				}
				p.pos = s + 1
				continue
			}
			if r == '\\' {
				s := p.pos
				if _, ok := p.escapedCharRaw(); ok {
					continue
				}
				p.pos = s + 1
				continue
			}
			if r == '<' {
				s := p.pos
				if _, ok := p.rawHtmlInline(); ok {
					continue
				}
				p.pos = s + 1
				continue
			}
			p.pos++
		}
		raw := trimSpace(string(p.s[start:p.pos]))
		cells = append(cells, p.pipeTableCell(raw))
		if p.char('|') {
			continue
		}
		break
	}
	if len(cells) == 1 && !openPipe {
		p.pos = save
		return nil, false
	}
	if !p.blankline() {
		p.pos = save
		return nil, false
	}
	// drop trailing empty cell produced by closing pipe
	if len(cells) > 1 && len(cells[len(cells)-1]) == 0 {
		// pandoc keeps it but truncates with take; emulate by removing the trailing empty only if there was a closing pipe
		// we detect: the last chunk was empty (after the final '|')
		cells = cells[:len(cells)-1]
	}
	return cells, true
}

func (p *mdP) pipeTableCell(raw string) []Block {
	if raw == "" {
		return nil
	}
	q := p.sub(raw)
	q.inTable = true
	ils := q.inlines()
	if len(ils) == 0 {
		return nil
	}
	return []Block{&Plain{Inlines: ils}}
}

func (p *mdP) pipeBreak() ([]Alignment, []int, bool) {
	save := p.pos
	p.nonindentSpaces()
	openPipe := p.char('|')
	var aligns []Alignment
	var lens []int
	a, l, ok := p.pipeTableHeaderPart()
	if !ok {
		p.pos = save
		return nil, nil, false
	}
	aligns = append(aligns, a)
	lens = append(lens, l)
	for {
		s := p.pos
		if !(p.char('|') || p.char('+')) {
			break
		}
		if p.isBlankLineAhead() {
			p.pos = s
			break
		}
		a, l, ok := p.pipeTableHeaderPart()
		if !ok {
			p.pos = s
			break
		}
		aligns = append(aligns, a)
		lens = append(lens, l)
	}
	if len(aligns) == 1 && !openPipe {
		p.pos = save
		return nil, nil, false
	}
	p.char('|')
	if !p.blankline() {
		p.pos = save
		return nil, nil, false
	}
	return aligns, lens, true
}

func (p *mdP) pipeTableHeaderPart() (Alignment, int, bool) {
	save := p.pos
	p.skipSpaces()
	left := p.char(':')
	dashes := p.many(func(r rune) bool { return r == '-' })
	if dashes == "" {
		p.pos = save
		return 0, 0, false
	}
	right := p.char(':')
	p.skipSpaces()
	n := len(dashes)
	if left {
		n++
	}
	if right {
		n++
	}
	switch {
	case left && right:
		return AlignCenter, n, true
	case left:
		return AlignLeft, n, true
	case right:
		return AlignRight, n, true
	}
	return AlignDefault, n, true
}

// ---- simple and multiline tables ----

// dashedLine parses dashes followed by optional spaces; returns (dashes, dashes+spaces)
func (p *mdP) dashedLine(ch rune) (int, int, bool) {
	d := p.many(func(r rune) bool { return r == ch })
	if d == "" {
		return 0, 0, false
	}
	sp := p.many(isSpaceChar)
	return len(d), len(d) + len(sp), true
}

func (p *mdP) dashedLines(ch rune) ([]int, []int, bool) {
	var lens, lines []int
	for {
		l, t, ok := p.dashedLine(ch)
		if !ok {
			break
		}
		lens = append(lens, l)
		lines = append(lines, t)
	}
	return lens, lines, len(lens) > 0
}

func alignType(strs []string, length int) Alignment {
	var nonempties []string
	for _, s := range strs {
		t := trimRight(s)
		if t != "" {
			nonempties = append(nonempties, t)
		}
	}
	if len(nonempties) == 0 {
		return AlignDefault
	}
	sort.SliceStable(nonempties, func(i, j int) bool { return len([]rune(nonempties[i])) < len([]rune(nonempties[j])) })
	x := nonempties[0]
	rs := []rune(x)
	leftSpace := rs[0] == ' ' || rs[0] == '\t'
	rightSpace := len(rs) < length
	switch {
	case leftSpace && !rightSpace:
		return AlignRight
	case !leftSpace && rightSpace:
		return AlignLeft
	case leftSpace && rightSpace:
		return AlignCenter
	}
	return AlignDefault
}

func scanl(init int, xs []int) []int {
	out := []int{init}
	acc := init
	for _, x := range xs {
		acc += x
		out = append(out, acc)
	}
	return out
}

func (p *mdP) parseCellBlocks(s string) []Block {
	q := p.sub(s)
	var out []Block
	for {
		bs, ok := q.plain()
		if !ok {
			break
		}
		out = append(out, bs...)
		if q.eof() {
			break
		}
		// skip whitespace between
		if _, ok := q.blanklines(); !ok {
			if !q.newline() {
				break
			}
		}
	}
	return out
}

func (p *mdP) simpleTableHeader(headless bool) ([][]Block, []Alignment, []int, bool) {
	save := p.pos
	rawContent := ""
	if !headless {
		l, ok := p.anyLine()
		if !ok {
			return nil, nil, nil, false
		}
		rawContent = l
	}
	initSp := p.nonindentSpaces()
	lengths, lines, ok := p.dashedLines('-')
	if !ok || !p.newline() {
		p.pos = save
		return nil, nil, nil, false
	}
	indices := scanl(len(initSp), lines)
	var rawHeads []string
	if headless {
		s := p.pos
		l, _ := p.anyLine()
		p.pos = s
		rawHeads = splitTextByIndices(indices[:len(indices)-1], l)[1:]
	} else {
		rawHeads = splitTextByIndices(indices[:len(indices)-1], rawContent)[1:]
	}
	aligns := make([]Alignment, len(lengths))
	for i := range lengths {
		h := ""
		if i < len(rawHeads) {
			h = rawHeads[i]
		}
		aligns[i] = alignType([]string{h}, lengths[i])
	}
	var heads [][]Block
	if !headless {
		for _, h := range rawHeads {
			heads = append(heads, p.parseCellBlocks(trimSpace(h)))
		}
	}
	return heads, aligns, indices, true
}

func (p *mdP) tableFooter() bool {
	save := p.pos
	p.skipNonindentSpaces()
	if _, _, ok := p.dashedLines('-'); !ok {
		p.pos = save
		return false
	}
	if _, ok := p.blanklines(); !ok {
		p.pos = save
		return false
	}
	return true
}

func (p *mdP) tableSep() bool {
	save := p.pos
	p.skipNonindentSpaces()
	if _, _, ok := p.dashedLines('-'); !ok {
		p.pos = save
		return false
	}
	if !p.char('\n') {
		p.pos = save
		return false
	}
	return true
}

func (p *mdP) rawTableLine(indices []int) ([]string, bool) {
	save := p.pos
	if p.isBlankLineAhead() {
		return nil, false
	}
	s := p.pos
	if p.tableFooter() {
		p.pos = save
		return nil, false
	}
	p.pos = s
	line, ok := p.anyLine()
	if !ok {
		p.pos = save
		return nil, false
	}
	parts := splitTextByIndices(indices[:len(indices)-1], line)[1:]
	for i := range parts {
		parts[i] = trimSpace(parts[i])
	}
	return parts, true
}

func (p *mdP) tableLine(indices []int) ([][]Block, bool) {
	parts, ok := p.rawTableLine(indices)
	if !ok {
		return nil, false
	}
	var cells [][]Block
	for _, s := range parts {
		cells = append(cells, p.parseCellBlocks(s))
	}
	return cells, true
}

func (p *mdP) multilineRow(indices []int) ([][]Block, bool) {
	var colLines [][]string
	for {
		s := p.pos
		parts, ok := p.rawTableLine(indices)
		if !ok {
			p.pos = s
			break
		}
		colLines = append(colLines, parts)
	}
	if len(colLines) == 0 {
		return nil, false
	}
	ncols := len(indices) - 1
	var cells [][]Block
	for c := 0; c < ncols; c++ {
		var sb strings.Builder
		for _, l := range colLines {
			if c < len(l) {
				sb.WriteString(l[c])
			}
			sb.WriteByte('\n')
		}
		cells = append(cells, p.parseCellBlocks(sb.String()))
	}
	return cells, true
}

func (p *mdP) simpleTable(headless bool) (rawTable, bool) {
	save := p.pos
	heads, aligns, indices, ok := p.simpleTableHeader(headless)
	if !ok {
		p.pos = save
		return rawTable{}, false
	}
	var rows [][][]Block
	for {
		s := p.pos
		r, ok := p.tableLine(indices)
		if !ok {
			p.pos = s
			break
		}
		rows = append(rows, r)
	}
	if len(rows) == 0 {
		p.pos = save
		return rawTable{}, false
	}
	if headless {
		if !p.tableFooter() {
			p.pos = save
			return rawTable{}, false
		}
	} else {
		if !p.tableFooter() {
			if _, ok := p.blanklines(); !ok {
				p.pos = save
				return rawTable{}, false
			}
		}
	}
	widths := make([]float64, len(aligns))
	return rawTable{aligns: aligns, widths: widths, heads: heads, rows: rows}, true
}

func (p *mdP) multilineTableHeader(headless bool) ([][]Block, []Alignment, []int, bool) {
	save := p.pos
	if !headless {
		if !p.tableSep() || p.isBlankLineAhead() {
			p.pos = save
			return nil, nil, nil, false
		}
	}
	var rawContent []string
	if !headless {
		for {
			s := p.pos
			if p.tableSep() {
				p.pos = s
				break
			}
			p.pos = s
			l, ok := p.anyLine()
			if !ok {
				p.pos = save
				return nil, nil, nil, false
			}
			rawContent = append(rawContent, l)
		}
		if len(rawContent) == 0 {
			p.pos = save
			return nil, nil, nil, false
		}
	}
	initSp := p.nonindentSpaces()
	lengths, lines, ok := p.dashedLines('-')
	if !ok || !p.newline() {
		p.pos = save
		return nil, nil, nil, false
	}
	indices := scanl(len(initSp), lines)
	// compensate: last index +1
	indices[len(indices)-1]++
	ncols := len(lengths)
	var rawHeadsList [][]string
	if headless {
		s := p.pos
		l, _ := p.anyLine()
		p.pos = s
		parts := splitTextByIndices(indices[:len(indices)-1], l)[1:]
		for _, pt := range parts {
			rawHeadsList = append(rawHeadsList, []string{pt})
		}
	} else {
		rawHeadsList = make([][]string, ncols)
		for _, l := range rawContent {
			parts := splitTextByIndices(indices[:len(indices)-1], l)[1:]
			for i := 0; i < ncols; i++ {
				v := ""
				if i < len(parts) {
					v = parts[i]
				}
				rawHeadsList[i] = append(rawHeadsList[i], v)
			}
		}
	}
	aligns := make([]Alignment, ncols)
	for i := 0; i < ncols; i++ {
		var strs []string
		if i < len(rawHeadsList) {
			strs = rawHeadsList[i]
		}
		aligns[i] = alignType(strs, lengths[i])
	}
	var heads [][]Block
	if !headless {
		for i := 0; i < ncols; i++ {
			var sb strings.Builder
			for _, l := range rawHeadsList[i] {
				sb.WriteString(trimSpace(l))
				sb.WriteByte('\n')
			}
			heads = append(heads, p.parseCellBlocks(trimSpace(sb.String())))
		}
	}
	return heads, aligns, indices, true
}

func (p *mdP) multilineTable(headless bool) (rawTable, bool) {
	save := p.pos
	heads, aligns, indices, ok := p.multilineTableHeader(headless)
	if !ok {
		p.pos = save
		return rawTable{}, false
	}
	var rows [][][]Block
	for {
		s := p.pos
		r, ok := p.multilineRow(indices)
		if !ok {
			p.pos = s
			break
		}
		rows = append(rows, r)
		if _, ok := p.blanklines(); !ok {
			break
		}
	}
	if len(rows) == 0 {
		p.pos = save
		return rawTable{}, false
	}
	if !p.tableFooter() {
		p.pos = save
		return rawTable{}, false
	}
	widths := widthsFromIndices(p.st.columns, indices)
	return rawTable{aligns: aligns, widths: widths, heads: heads, rows: rows}, true
}

func widthsFromIndices(numColumns0 int, indices []int) []float64 {
	if len(indices) == 0 {
		return nil
	}
	numColumns := numColumns0
	if indices[len(indices)-1] > numColumns {
		numColumns = indices[len(indices)-1]
	}
	lengths := make([]int, len(indices))
	prev := 0
	for i, x := range indices {
		lengths[i] = x - prev
		prev = x
	}
	// compensate for intercolumn spaces counted in all but the last
	n := len(lengths)
	if n >= 2 {
		x := lengths[n-1]
		y := lengths[n-2]
		if x < y && y-x <= 2 {
			lengths[n-1] = y
		}
	}
	tot := 0
	for _, l := range lengths {
		tot += l
	}
	quotient := float64(numColumns)
	if tot > numColumns {
		quotient = float64(tot)
	}
	out := make([]float64, 0, n-1)
	for _, l := range lengths[1:] {
		out = append(out, float64(l)/quotient)
	}
	return out
}

// ---- grid tables ----

func (p *mdP) gridTable(headless bool) (rawTable, bool) {
	save := p.pos
	// collect lines of the table
	s := p.pos
	p.skipNonindentSpaces()
	if p.peek() != '+' {
		p.pos = save
		return rawTable{}, false
	}
	p.pos = s
	var lines []string
	for !p.eof() {
		s2 := p.pos
		if p.isBlankLineAhead() {
			break
		}
		l, ok := p.anyLine()
		if !ok {
			p.pos = s2
			break
		}
		t := trimLeft(l)
		if !strings.HasPrefix(t, "+") && !strings.HasPrefix(t, "|") {
			p.pos = s2
			break
		}
		lines = append(lines, l)
	}
	if len(lines) < 2 {
		p.pos = save
		return rawTable{}, false
	}
	// strip common indentation (nonindent spaces)
	first := lines[0]
	indent := len(first) - len(trimLeft(first))
	for i := range lines {
		if len(lines[i]) >= indent {
			lines[i] = lines[i][indent:]
		}
	}
	first = lines[0]
	if !strings.HasPrefix(first, "+") || !strings.HasSuffix(trimRight(first), "+") {
		p.pos = save
		return rawTable{}, false
	}
	last := trimRight(lines[len(lines)-1])
	if !strings.HasPrefix(last, "+") || !strings.HasSuffix(last, "+") {
		p.pos = save
		return rawTable{}, false
	}
	// column boundaries from first line
	frs := []rune(trimRight(first))
	var bounds []int
	for i, r := range frs {
		if r == '+' {
			bounds = append(bounds, i)
		}
	}
	if len(bounds) < 2 {
		p.pos = save
		return rawTable{}, false
	}
	ncols := len(bounds) - 1
	// parse alignment from the header separator (=== line) or first line
	parseSep := func(line string) ([]Alignment, bool) {
		rs := []rune(trimRight(line))
		if len(rs) < len(frs) {
			return nil, false
		}
		aligns := make([]Alignment, ncols)
		for c := 0; c < ncols; c++ {
			seg := rs[bounds[c]+1 : bounds[c+1]]
			if len(seg) == 0 {
				return nil, false
			}
			left := seg[0] == ':'
			right := seg[len(seg)-1] == ':'
			for _, r := range seg[1 : len(seg)-1] {
				if r != '=' && r != '-' {
					return nil, false
				}
			}
			switch {
			case left && right:
				aligns[c] = AlignCenter
			case left:
				aligns[c] = AlignLeft
			case right:
				aligns[c] = AlignRight
			default:
				aligns[c] = AlignDefault
			}
		}
		return aligns, true
	}
	isSepLine := func(line string, ch rune) bool {
		t := trimRight(line)
		if !strings.HasPrefix(t, "+") {
			return false
		}
		for _, r := range t {
			if r != '+' && r != ch && r != ':' {
				return false
			}
		}
		return strings.ContainsRune(t, ch)
	}
	aligns, ok := parseSep(first)
	if !ok {
		p.pos = save
		return rawTable{}, false
	}
	// split into row groups
	var heads [][]Block
	var rows [][][]Block
	var cur []string
	hasHeadSep := false
	headSepIdx := -1
	for i := 1; i < len(lines); i++ {
		if isSepLine(lines[i], '=') {
			hasHeadSep = true
			headSepIdx = i
			if a, ok := parseSep(lines[i]); ok {
				aligns = a
			}
			break
		}
	}
	if headless && hasHeadSep {
		p.pos = save
		return rawTable{}, false
	}
	if !headless && !hasHeadSep {
		p.pos = save
		return rawTable{}, false
	}
	cellText := func(ls []string) [][]Block {
		cells := make([][]Block, ncols)
		for c := 0; c < ncols; c++ {
			var sb strings.Builder
			for _, l := range ls {
				rs := []rune(l)
				end := bounds[c+1]
				if end > len(rs) {
					end = len(rs)
				}
				st := bounds[c] + 1
				if st > len(rs) {
					st = len(rs)
				}
				seg := string(rs[st:end])
				sb.WriteString(strings.TrimRight(seg, " "))
				sb.WriteByte('\n')
			}
			// remove common indentation of 1 space
			txt := sb.String()
			lns := strings.Split(txt, "\n")
			for j := range lns {
				lns[j] = strings.TrimPrefix(lns[j], " ")
			}
			txt = strings.Join(lns, "\n")
			cells[c] = p.parseBlocksStr(trimSpace(txt) + "\n\n")
		}
		return cells
	}
	for i := 1; i < len(lines); i++ {
		l := lines[i]
		if isSepLine(l, '-') || isSepLine(l, '=') {
			if len(cur) > 0 {
				if i == headSepIdx || (headSepIdx >= 0 && i < headSepIdx && false) {
					heads = cellText(cur)
				} else if headSepIdx >= 0 && i <= headSepIdx {
					heads = cellText(cur)
				} else {
					rows = append(rows, cellText(cur))
				}
				cur = nil
			}
			continue
		}
		cur = append(cur, l)
	}
	// widths: relative to total width
	widths := make([]float64, ncols)
	total := len(frs) - 2 - (ncols - 1)
	_ = total
	lineW := len(frs)
	numColumns := p.st.columns
	if lineW > numColumns {
		numColumns = lineW
	}
	for c := 0; c < ncols; c++ {
		widths[c] = float64(bounds[c+1]-bounds[c]-1+2) / float64(numColumns+2)
	}
	// pandoc: widths = map (\w -> fromIntegral w / fromIntegral (numColumns)) where numColumns = max readerColumns lineWidth; w = colwidth+? 
	// Use simpler: (width of column incl. one separator)/(total line width)
	for c := 0; c < ncols; c++ {
		widths[c] = float64(bounds[c+1]-bounds[c]) / float64(lineW-1)
	}
	return rawTable{aligns: aligns, widths: widths, heads: heads, rows: rows}, true
}
