func (p *mdP) resolveMeta(m MetaValue) MetaValue {
	switch x := m.(type) {
	case *MetaInlines:
		return &MetaInlines{Inlines: walkInlines(x.Inlines, p.resolveInlineList)}
	case *MetaBlocks:
		return &MetaBlocks{Blocks: p.resolveBlocks(x.Blocks)}
	case *MetaList:
		out := &MetaList{}
		for _, it := range x.Items {
			out.Items = append(out.Items, p.resolveMeta(it))
		}
		return out
	case *MetaMap:
		out := newMetaMap()
		for _, k := range x.Keys {
			out.Set(k, p.resolveMeta(x.Values[k]))
		}
		return out
	}
	return m
}

// resolveInlineList resolves placeholders in a list (children already resolved) and re-melds.
func (p *mdP) resolveInlineList(ils []Inline) []Inline {
	var out []Inline
	changed := false
	for _, il := range ils {
		switch x := il.(type) {
		case *refLinkPH:
			out = meldInlines(out, p.resolveRefLink(x))
			changed = true
		case *notePH:
			out = meldInlines(out, p.resolveNote(x))
			changed = true
		case *exampleRefPH:
			if n, ok := p.st.exampleLabels[x.label]; ok {
				out = meldInlines(out, []Inline{&Str{Text: strconv.Itoa(n)}})
			} else {
				out = meldInlines(out, []Inline{&Str{Text: "@" + x.label}})
			}
			changed = true
		default:
			out = meldInlines(out, []Inline{il})
		}
	}
	_ = changed
	return out
}

func (p *mdP) resolveRefLink(x *refLinkPH) []Inline {
	labIsRef := x.raw2 == "" || x.raw2 == "[]"
	var key string
	if labIsRef {
		key = toKey(x.raw)
	} else {
		key = toKey(x.raw2)
	}
	lab := walkInlines(x.lab, p.resolveInlineList)
	mk := func(def refDef) []Inline {
		if x.isImage {
			return []Inline{&Image{Attr: def.Attr, Inlines: lab, Target: Target{URL: p.addImageExt(def.URL), Title: def.Title}}}
		}
		return []Inline{&Link{Attr: def.Attr, Inlines: lab, Target: Target{URL: def.URL, Title: def.Title}}}
	}
	if def, ok := p.st.refs[key]; ok {
		return mk(def)
	}
	if p.ext("implicit_header_references") {
		if def, ok := p.st.headerKeys[key]; ok {
			d := refDef{URL: def.URL, Title: def.Title}
			return mk(d)
		}
	}
	// fallback
	var out []Inline
	if x.isImage {
		out = meldInlines(out, []Inline{&Str{Text: "!["}})
	} else {
		out = meldInlines(out, []Inline{&Str{Text: "["}})
	}
	// fallback: parse raw label without brackets as inlines
	inner := x.raw
	if len(inner) >= 2 {
		inner = inner[1 : len(inner)-1]
	}
	fb := p.sub(inner)
	fallback := fb.inlines()
	fallback = walkInlines(fallback, p.resolveInlineList)
	out = meldInlines(out, fallback)
	out = meldInlines(out, []Inline{&Str{Text: "]"}})
	if x.sp && x.raw2 != "" {
		out = meldInlines(out, []Inline{&Space{}})
	}
	if x.raw2 != "" {
		q := p.sub(x.raw2)
		parsedRaw := q.inlines()
		parsedRaw = walkInlines(parsedRaw, p.resolveInlineList)
		out = meldInlines(out, parsedRaw)
	}
	return out
}

func (p *mdP) resolveNote(x *notePH) []Inline {
	blocks, ok := p.st.notes[x.label]
	if !ok {
		return []Inline{&Str{Text: "[^" + x.label + "]"}}
	}
	// resolve inside note, but nested note refs are left unresolved
	saved := p.st.notes
	p.st.notes = map[string][]Block{}
	resolved := p.resolveBlocks(blocks)
	p.st.notes = saved
	return []Inline{&Note{Blocks: resolved}}
}
