cat > src/yaml.go <<'EOF'
package main

import (
	"errors"
	"regexp"
	"strconv"
	"strings"
)

// A small YAML subset parser producing MetaValues (pandoc semantics).

type yamlNode struct {
	kind    int // 0 scalar, 1 map, 2 seq, 3 null
	scalar  string
	quoted  bool // quoted or block scalar => always string
	isBlock bool // block scalar (ends with newline)
	keys    []string
	mapv    map[string]*yamlNode
	seq     []*yamlNode
	tag     string
}

type yamlLine struct {
	indent int
	text   string // without indentation
	raw    string
}

type yamlParser struct {
	lines []yamlLine
	i     int
}

func parseYAMLMeta(raw string, p *mdP) (*MetaMap, error) {
	node, err := parseYAML(raw)
	if err != nil {
		return nil, err
	}
	if node == nil || node.kind == 3 {
		return newMetaMap(), nil
	}
	if node.kind != 1 {
		return nil, errors.New("expected YAML object")
	}
	mv := yamlToMeta(node, p)
	mm, ok := mv.(*MetaMap)
	if !ok {
		return newMetaMap(), nil
	}
	// drop keys ending with underscore
	out := newMetaMap()
	for _, k := range mm.Keys {
		if strings.HasSuffix(k, "_") {
			continue
		}
		out.Set(k, mm.Values[k])
	}
	return out, nil
}

func yamlToMeta(n *yamlNode, p *mdP) MetaValue {
	switch n.kind {
	case 1:
		m := newMetaMap()
		for _, k := range n.keys {
			m.Set(k, yamlToMeta(n.mapv[k], p))
		}
		return m
	case 2:
		l := &MetaList{}
		for _, it := range n.seq {
			l.Items = append(l.Items, yamlToMeta(it, p))
		}
		return l
	case 3:
		return &MetaString{Text: ""}
	}
	s := n.scalar
	if !n.quoted {
		switch strings.ToLower(s) {
		case "true", "yes", "on":
			if n.tag != "!!str" {
				return &MetaBool{Value: true}
			}
		case "false", "no", "off":
			if n.tag != "!!str" {
				return &MetaBool{Value: false}
			}
		case "null", "~", "":
			if n.tag != "!!str" {
				return &MetaString{Text: ""}
			}
		}
		if n.tag != "!!str" {
			if f, ok := yamlNumber(s); ok {
				s = f
			}
		}
	}
	if n.isBlock || strings.HasSuffix(s, "\n") {
		bs := p.parseBlocksStr(s + "\n")
		bs = p.resolveBlocks(bs)
		return asMetaBlocks(bs)
	}
	bs := p.parseBlocksStr(s)
	bs = p.resolveBlocks(bs)
	return asMetaInlines(bs)
}

func asMetaInlines(bs []Block) MetaValue {
	if len(bs) == 0 {
		return &MetaInlines{Inlines: nil}
	}
	if len(bs) == 1 {
		switch b := bs[0].(type) {
		case *Plain:
			return &MetaInlines{Inlines: b.Inlines}
		case *Para:
			return &MetaInlines{Inlines: b.Inlines}
		}
	}
	return &MetaBlocks{Blocks: bs}
}

func asMetaBlocks(bs []Block) MetaValue {
	return &MetaBlocks{Blocks: bs}
}

var yamlIntRe = regexp.MustCompile(`^[-+]?(0|[1-9][0-9_]*)$`)
var yamlFloatRe = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9][0-9_]*(\.[0-9_]*)?)([eE][-+]?[0-9]+)?$`)
var yamlHexRe = regexp.MustCompile(`^0x[0-9a-fA-F_]+$`)
var yamlOctRe = regexp.MustCompile(`^0o[0-7_]+$`)

// yamlNumber normalizes numeric scalars like Haskell's show would.
func yamlNumber(s string) (string, bool) {
	if yamlIntRe.MatchString(s) {
		t := strings.ReplaceAll(s, "_", "")
		t = strings.TrimPrefix(t, "+")
		n, err := strconv.ParseInt(t, 10, 64)
		if err != nil {
			return s, true
		}
		return strconv.FormatInt(n, 10), true
	}
	if yamlHexRe.MatchString(s) {
		n, err := strconv.ParseInt(strings.ReplaceAll(s[2:], "_", ""), 16, 64)
		if err == nil {
			return strconv.FormatInt(n, 10), true
		}
	}
	if yamlOctRe.MatchString(s) {
		n, err := strconv.ParseInt(strings.ReplaceAll(s[2:], "_", ""), 8, 64)
		if err == nil {
			return strconv.FormatInt(n, 10), true
		}
	}
	if yamlFloatRe.MatchString(s) && strings.ContainsAny(s, ".eE") {
		t := strings.ReplaceAll(s, "_", "")
		f, err := strconv.ParseFloat(t, 64)
		if err != nil {
			return s, true
		}
		return haskellShowDouble(f), true
	}
	switch s {
	case ".inf", ".Inf", ".INF", "+.inf":
		return "Infinity", true
	case "-.inf", "-.Inf", "-.INF":
		return "-Infinity", true
	case ".nan", ".NaN", ".NAN":
		return "NaN", true
	}
	return s, false
}

func parseYAML(raw string) (*yamlNode, error) {
	var lines []yamlLine
	for _, l := range strings.Split(raw, "\n") {
		trimmed := strings.TrimLeft(l, " ")
		indent := len(l) - len(trimmed)
		lines = append(lines, yamlLine{indent: indent, text: trimmed, raw: l})
	}
	yp := &yamlParser{lines: lines}
	yp.skipBlank()
	if yp.i >= len(yp.lines) {
		return &yamlNode{kind: 3}, nil
	}
	// flow at top-level?
	first := yp.lines[yp.i]
	if strings.HasPrefix(first.text, "{") || strings.HasPrefix(first.text, "[") {
		s := strings.Join(yp.remainingTexts(), "\n")
		fp := &flowParser{s: []rune(s)}
		n, err := fp.parseValue()
		if err != nil {
			return nil, err
		}
		return n, nil
	}
	n, err := yp.parseNode(first.indent, false)
	if err != nil {
		return nil, err
	}
	yp.skipBlank()
	if yp.i < len(yp.lines) {
		return nil, errors.New("unexpected content at line " + strconv.Itoa(yp.i+1))
	}
	return n, nil
}

func (yp *yamlParser) remainingTexts() []string {
	var out []string
	for _, l := range yp.lines[yp.i:] {
		out = append(out, l.raw)
	}
	return out
}

func isBlankOrComment(s string) bool {
	t := strings.TrimSpace(s)
	return t == "" || strings.HasPrefix(t, "#")
}

func (yp *yamlParser) skipBlank() {
	for yp.i < len(yp.lines) && isBlankOrComment(yp.lines[yp.i].text) {
		yp.i++
	}
}

func stripComment(s string) string {
	// remove " #..." comments outside quotes
	inS, inD := false, false
	rs := []rune(s)
	for i, r := range rs {
		switch {
		case r == '\'' && !inD:
			inS = !inS
		case r == '"' && !inS:
			inD = !inD
		case r == '#' && !inS && !inD && (i == 0 || rs[i-1] == ' ' || rs[i-1] == '\t'):
			return strings.TrimRight(string(rs[:i]), " \t")
		}
	}
	return strings.TrimRight(s, " \t")
}

// splitKey finds "key:" at the start of a mapping entry. Returns key, rest, ok.
func splitMapKey(text string) (string, string, bool) {
	if strings.HasPrefix(text, "- ") || text == "-" {
		return "", "", false
	}
	rs := []rune(text)
	if len(rs) == 0 {
		return "", "", false
	}
	if rs[0] == '"' || rs[0] == '\'' {
		q := rs[0]
		j := 1
		for j < len(rs) && rs[j] != q {
			if rs[j] == '\\' && q == '"' {
				j++
			}
			j++
		}
		if j >= len(rs) {
			return "", "", false
		}
		key := string(rs[1:j])
		if q == '"' {
			key = unescapeDoubleQuoted(key)
		}
		rest := string(rs[j+1:])
		if !strings.HasPrefix(rest, ":") {
			return "", "", false
		}
		rest = rest[1:]
		if rest != "" && rest[0] != ' ' && rest[0] != '\t' {
			return "", "", false
		}
		return key, strings.TrimLeft(rest, " \t"), true
	}
	inFlow := 0
	for j := 0; j < len(rs); j++ {
		r := rs[j]
		if r == '[' || r == '{' {
			inFlow++
		}
		if r == ']' || r == '}' {
			inFlow--
		}
		if r == '#' && j > 0 && rs[j-1] == ' ' {
			return "", "", false
		}
		if r == ':' && inFlow <= 0 && (j+1 == len(rs) || rs[j+1] == ' ' || rs[j+1] == '\t') {
			key := strings.TrimRight(string(rs[:j]), " \t")
			if key == "" {
				return "", "", false
			}
			return key, strings.TrimLeft(string(rs[j+1:]), " \t"), true
		}
	}
	return "", "", false
}

func (yp *yamlParser) parseNode(indent int, inSeqItem bool) (*yamlNode, error) {
	yp.skipBlank()
	if yp.i >= len(yp.lines) {
		return &yamlNode{kind: 3}, nil
	}
	l := yp.lines[yp.i]
	if l.text == "-" || strings.HasPrefix(l.text, "- ") {
		return yp.parseSeq(l.indent)
	}
	if _, _, ok := splitMapKey(stripComment(l.text)); ok {
		return yp.parseMap(l.indent)
	}
	// scalar (possibly multi-line plain)
	return yp.parseScalarLines(indent)
}

func (yp *yamlParser) parseSeq(indent int) (*yamlNode, error) {
	n := &yamlNode{kind: 2}
	for yp.i < len(yp.lines) {
		yp.skipBlank()
		if yp.i >= len(yp.lines) {
			break
		}
		l := yp.lines[yp.i]
		if l.indent != indent || !(l.text == "-" || strings.HasPrefix(l.text, "- ")) {
			if l.indent < indent || (l.indent == indent) {
				break
			}
			return nil, errors.New("bad indentation in sequence at line " + strconv.Itoa(yp.i+1))
		}
		rest := strings.TrimLeft(strings.TrimPrefix(l.text, "-"), " \t")
		if rest == "" || isBlankOrComment(rest) {
			yp.i++
			// nested node on following lines with greater indent
			yp.skipBlank()
			if yp.i < len(yp.lines) && yp.lines[yp.i].indent > indent {
				child, err := yp.parseNode(yp.lines[yp.i].indent, true)
				if err != nil {
					return nil, err
				}
				n.seq = append(n.seq, child)
			} else {
				n.seq = append(n.seq, &yamlNode{kind: 3})
			}
			continue
		}
		// inline content after "- ": treat as a node at virtual indent
		childIndent := indent + 2
		// replace current line with the rest at childIndent
		yp.lines[yp.i] = yamlLine{indent: childIndent, text: rest, raw: strings.Repeat(" ", childIndent) + rest}
		child, err := yp.parseNode(childIndent, true)
		if err != nil {
			return nil, err
		}
		n.seq = append(n.seq, child)
	}
	return n, nil
}

func (yp *yamlParser) parseMap(indent int) (*yamlNode, error) {
	n := &yamlNode{kind: 1, mapv: map[string]*yamlNode{}}
	for yp.i < len(yp.lines) {
		yp.skipBlank()
		if yp.i >= len(yp.lines) {
			break
		}
		l := yp.lines[yp.i]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			return nil, errors.New("bad indentation in mapping at line " + strconv.Itoa(yp.i+1))
		}
		key, rest, ok := splitMapKey(stripComment(l.text))
		if !ok {
			if strings.HasPrefix(l.text, "- ") || l.text == "-" {
				break
			}
			return nil, errors.New("could not parse mapping entry at line " + strconv.Itoa(yp.i+1))
		}
		yp.i++
		var child *yamlNode
		var err error
		if rest == "" {
			yp.skipBlank()
			if yp.i < len(yp.lines) && (yp.lines[yp.i].indent > indent || (yp.lines[yp.i].indent == indent && (yp.lines[yp.i].text == "-" || strings.HasPrefix(yp.lines[yp.i].text, "- ")))) {
				child, err = yp.parseNode(yp.lines[yp.i].indent, false)
				if err != nil {
					return nil, err
				}
			} else {
				child = &yamlNode{kind: 3}
			}
		} else {
			child, err = yp.parseInlineValue(rest, indent)
			if err != nil {
				return nil, err
			}
		}
		if _, exists := n.mapv[key]; !exists {
			n.keys = append(n.keys, key)
		}
		n.mapv[key] = child
	}
	return n, nil
}

// parseInlineValue parses the value part following "key: " (may continue on following lines).
func (yp *yamlParser) parseInlineValue(rest string, indent int) (*yamlNode, error) {
	tag := ""
	if strings.HasPrefix(rest, "!!") {
		sp := strings.IndexAny(rest, " \t")
		if sp < 0 {
			tag = rest
			rest = ""
		} else {
			tag = rest[:sp]
			rest = strings.TrimLeft(rest[sp:], " \t")
		}
	}
	if rest == "" {
		yp.skipBlank()
		if yp.i < len(yp.lines) && yp.lines[yp.i].indent > indent {
			n, err := yp.parseNode(yp.lines[yp.i].indent, false)
			if err != nil {
				return nil, err
			}
			n.tag = tag
			return n, nil
		}
		return &yamlNode{kind: 3, tag: tag}, nil
	}
	if rest[0] == '|' || rest[0] == '>' {
		n, err := yp.parseBlockScalar(rest, indent)
		if err != nil {
			return nil, err
		}
		n.tag = tag
		return n, nil
	}
	if rest[0] == '[' || rest[0] == '{' {
		// flow collection, possibly spanning lines
		s := rest
		j := yp.i
		for !flowComplete(s) && j < len(yp.lines) {
			s += "\n" + yp.lines[j].text
			j++
		}
		fp := &flowParser{s: []rune(s)}
		n, err := fp.parseValue()
		if err != nil {
			return nil, err
		}
		yp.i = j
		n.tag = tag
		return n, nil
	}
	if rest[0] == '"' || rest[0] == '\'' {
		// quoted scalar possibly multi-line
		s := rest
		j := yp.i
		for !quotedComplete(s) && j < len(yp.lines) {
			s += "\n" + strings.TrimSpace(yp.lines[j].raw)
			j++
		}
		yp.i = j
		v, err := parseQuotedScalar(s)
		if err != nil {
			return nil, err
		}
		return &yamlNode{kind: 0, scalar: v, quoted: true, tag: tag}, nil
	}
	// plain scalar, possibly continued on more-indented lines
	s := rest
	for yp.i < len(yp.lines) {
		l := yp.lines[yp.i]
		if isBlankOrComment(l.text) {
			break
		}
		if l.indent <= indent {
			break
		}
		if _, _, ok := splitMapKey(l.text); ok && false {
			break
		}
		s += " " + stripComment(l.text)
		yp.i++
	}
	return &yamlNode{kind: 0, scalar: strings.TrimSpace(s), tag: tag}, nil
}

func (yp *yamlParser) parseScalarLines(indent int) (*yamlNode, error) {
	l := yp.lines[yp.i]
	yp.i++
	return yp.parseInlineValue(stripComment(l.text), indent-1)
}

func (yp *yamlParser) parseBlockScalar(header string, indent int) (*yamlNode, error) {
	style := header[0]
	chomp := byte(0)
	explicitIndent := 0
	for _, c := range header[1:] {
		switch {
		case c == '-' || c == '+':
			chomp = byte(c)
		case c >= '1' && c <= '9':
			explicitIndent = int(c - '0')
		case c == ' ' || c == '#':
			break
		}
	}
	var lines []string
	blockIndent := -1
	for yp.i < len(yp.lines) {
		l := yp.lines[yp.i]
		if strings.TrimSpace(l.raw) == "" {
			lines = append(lines, "")
			yp.i++
			continue
		}
		if blockIndent < 0 {
			if explicitIndent > 0 {
				blockIndent = indent + explicitIndent
			} else {
				blockIndent = l.indent
			}
			if blockIndent <= indent {
				break
			}
		}
		if l.indent < blockIndent {
			break
		}
		lines = append(lines, l.raw[blockIndent:])
		yp.i++
	}
	// trailing blank lines handling
	trailing := 0
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailing++
	}
	var sb strings.Builder
	if style == '|' {
		for i, l := range lines {
			if i > 0 {
				sb.WriteByte('\n')
			}
			sb.WriteString(l)
		}
	} else {
		// folded
		for i, l := range lines {
			if i > 0 {
				prev := lines[i-1]
				if l == "" || prev == "" || strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " ") {
					sb.WriteByte('\n')
				} else {
					sb.WriteByte(' ')
				}
			}
			sb.WriteString(l)
		}
	}
	s := sb.String()
	switch chomp {
	case '-':
	case '+':
		s += "\n" + strings.Repeat("\n", trailing)
	default:
		if len(lines) > 0 {
			s += "\n"
		}
	}
	return &yamlNode{kind: 0, scalar: s, quoted: true, isBlock: chomp != '-'}, nil
}

func flowComplete(s string) bool {
	depth := 0
	inS, inD := false, false
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		r := rs[i]
		switch {
		case inD:
			if r == '\\' {
				i++
			} else if r == '"' {
				inD = false
			}
		case inS:
			if r == '\'' {
				inS = false
			}
		case r == '"':
			inD = true
		case r == '\'':
			inS = true
		case r == '[' || r == '{':
			depth++
		case r == ']' || r == '}':
			depth--
			if depth == 0 {
				return true
			}
		}
	}
	return false
}

func quotedComplete(s string) bool {
	rs := []rune(s)
	if len(rs) == 0 {
		return true
	}
	q := rs[0]
	for i := 1; i < len(rs); i++ {
		if q == '"' && rs[i] == '\\' {
			i++
			continue
		}
		if rs[i] == q {
			if q == '\'' && i+1 < len(rs) && rs[i+1] == '\'' {
				i++
				continue
			}
			return true
		}
	}
	return false
}

func parseQuotedScalar(s string) (string, error) {
	rs := []rune(s)
	q := rs[0]
	var sb strings.Builder
	i := 1
	for i < len(rs) {
		r := rs[i]
		if q == '\'' {
			if r == '\'' {
				if i+1 < len(rs) && rs[i+1] == '\'' {
					sb.WriteRune('\'')
					i += 2
					continue
				}
				break
			}
			sb.WriteRune(r)
			i++
			continue
		}
		if r == '\\' && i+1 < len(rs) {
			i++
			switch rs[i] {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case ' ':
				sb.WriteByte(' ')
			case 'r':
				sb.WriteByte('\r')
			case '0':
				sb.WriteByte(0)
			case 'x':
				if i+2 < len(rs) {
					v, _ := strconv.ParseInt(string(rs[i+1:i+3]), 16, 32)
					sb.WriteRune(rune(v))
					i += 2
				}
			case 'u':
				if i+4 < len(rs) {
					v, _ := strconv.ParseInt(string(rs[i+1:i+5]), 16, 32)
					sb.WriteRune(rune(v))
					i += 4
				}
			case '\n':
				// line continuation
			default:
				sb.WriteRune(rs[i])
			}
			i++
			continue
		}
		if r == '"' {
			break
		}
		if r == '\n' {
			// folding: newline -> space (blank line -> newline)
			j := i + 1
			blank := 0
			for j < len(rs) && (rs[j] == '\n' || rs[j] == ' ' || rs[j] == '\t') {
				if rs[j] == '\n' {
					blank++
				}
				j++
			}
			if blank > 0 {
				sb.WriteString(strings.Repeat("\n", blank))
			} else {
				sb.WriteByte(' ')
			}
			i = j
			continue
		}
		sb.WriteRune(r)
		i++
	}
	return sb.String(), nil
}

func unescapeDoubleQuoted(s string) string {
	v, _ := parseQuotedScalar("\"" + s + "\"")
	return v
}

// ---- flow (JSON-like) parser ----

type flowParser struct {
	s   []rune
	pos int
}

func (f *flowParser) skipWS() {
	for f.pos < len(f.s) {
		r := f.s[f.pos]
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			f.pos++
			continue
		}
		if r == '#' {
			for f.pos < len(f.s) && f.s[f.pos] != '\n' {
				f.pos++
			}
			continue
		}
		break
	}
}

func (f *flowParser) parseValue() (*yamlNode, error) {
	f.skipWS()
	if f.pos >= len(f.s) {
		return &yamlNode{kind: 3}, nil
	}
	switch f.s[f.pos] {
	case '[':
		f.pos++
		n := &yamlNode{kind: 2}
		for {
			f.skipWS()
			if f.pos >= len(f.s) {
				return nil, errors.New("unterminated flow sequence")
			}
			if f.s[f.pos] == ']' {
				f.pos++
				return n, nil
			}
			v, err := f.parseValue()
			if err != nil {
				return nil, err
			}
			n.seq = append(n.seq, v)
			f.skipWS()
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
			}
		}
	case '{':
		f.pos++
		n := &yamlNode{kind: 1, mapv: map[string]*yamlNode{}}
		for {
			f.skipWS()
			if f.pos >= len(f.s) {
				return nil, errors.New("unterminated flow mapping")
			}
			if f.s[f.pos] == '}' {
				f.pos++
				return n, nil
			}
			k, err := f.parseValue()
			if err != nil {
				return nil, err
			}
			f.skipWS()
			if f.pos < len(f.s) && f.s[f.pos] == ':' {
				f.pos++
			}
			v, err := f.parseValue()
			if err != nil {
				return nil, err
			}
			key := k.scalar
			if _, exists := n.mapv[key]; !exists {
				n.keys = append(n.keys, key)
			}
			n.mapv[key] = v
			f.skipWS()
			if f.pos < len(f.s) && f.s[f.pos] == ',' {
				f.pos++
			}
		}
	case '"', '\'':
		start := f.pos
		q := f.s[f.pos]
		f.pos++
		for f.pos < len(f.s) {
			if q == '"' && f.s[f.pos] == '\\' {
				f.pos += 2
				continue
			}
			if f.s[f.pos] == q {
				if q == '\'' && f.pos+1 < len(f.s) && f.s[f.pos+1] == '\'' {
					f.pos += 2
					continue
				}
				break
			}
			f.pos++
		}
		f.pos++
		v, err := parseQuotedScalar(string(f.s[start:f.pos]))
		if err != nil {
			return nil, err
		}
		return &yamlNode{kind: 0, scalar: v, quoted: true}, nil
	}
	// plain scalar until , ] } : (followed by space) or newline
	start := f.pos
	for f.pos < len(f.s) {
		r := f.s[f.pos]
		if r == ',' || r == ']' || r == '}' || r == '\n' {
			break
		}
		if r == ':' && (f.pos+1 >= len(f.s) || f.s[f.pos+1] == ' ') {
			break
		}
		f.pos++
	}
	v := strings.TrimSpace(string(f.s[start:f.pos]))
	if v == "" || v == "null" || v == "~" {
		return &yamlNode{kind: 3}, nil
	}
	return &yamlNode{kind: 0, scalar: v}, nil
}
