			i++
			from = args[i]
		case a == "-t" || a == "-w":
			i++
			to = args[i]
		case a == "-s":
			opts.Standalone = true
		case len(a) > 10 && a[:10] == "--columns=":
			fmt.Sscanf(a[10:], "%d", &opts.Columns)
		default:
			files = append(files, a)
		}
	}
	var input []byte
	if len(files) == 0 {
		input, _ = io.ReadAll(os.Stdin)
	} else {
		for _, f := range files {
			b, err := os.ReadFile(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%v\n", err)
				return 1
			}
			input = append(input, b...)
		}
	}
	var doc *Pandoc
	var err error
	switch from {
	case "json":
		doc, err = readJSON(string(input))
	case "markdown":
		exts := defaultExtensions("markdown")
		doc, _ = readMarkdown(string(input), exts, &ReaderOptions{TabStop: 4, Columns: opts.Columns})
	default:
		fmt.Fprintf(os.Stderr, "Unknown input format %s\n", from)
		return 21
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		return 64
	}
