package main

import (
	"strings"
)

// A minimal blaze-like HTML tree.

type hkind int

const (
	hElem hkind = iota
	hText       // escaped text
	hRaw        // pre-escaped text
	hSeq        // sequence of nodes
	hComment
)

type H struct {
	kind     hkind
	tag      string
	attrs    [][2]string
	children []*H
	leaf     bool // self-closing
	text     string
}

func hText_(s string) *H { return &H{kind: hText, text: s} }
func hRaw_(s string) *H  { return &H{kind: hRaw, text: s} }
func hSeq_(xs ...*H) *H {
	var out []*H
	for _, x := range xs {
		if x == nil {
			continue
		}
		out = append(out, x)
	}
	return &H{kind: hSeq, children: out}
}

func hEl(tag string, children ...*H) *H {
	var out []*H
	for _, c := range children {
		if c == nil {
			continue
		}
		out = append(out, c)
	}
	return &H{kind: hElem, tag: tag, children: out}
}

func hLeaf(tag string) *H { return &H{kind: hElem, tag: tag, leaf: true} }

// attr adds an attribute (applied in order).
func (h *H) attr(k, v string) *H {
	h.attrs = append(h.attrs, [2]string{k, v})
	return h
}

func (h *H) isEmpty() bool {
	if h == nil {
		return true
	}
	switch h.kind {
	case hSeq:
		for _, c := range h.children {
			if !c.isEmpty() {
				return false
			}
		}
		return true
	case hText, hRaw:
		return h.text == ""
	}
	return false
}

var hNl = hRaw_("\n")

// escapeHTMLText escapes text content (blaze style: & < > " ' ).
func escapeHTMLText(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			sb.WriteString("&amp;")
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '"':
			sb.WriteString("&quot;")
		case '\'':
			sb.WriteString("&#39;")
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

// strToHtml: pandoc escapes ' and " as themselves (pre-escaped) in content.
func strToHtmlEscape(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			sb.WriteString("&amp;")
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		default:
			sb.WriteRune(r)
			if needsVariationSelector(r) {
				sb.WriteRune(0xFE0E)
			}
		}
	}
	return sb.String()
}

func needsVariationSelector(r rune) bool {
	return r == 0x26A0 || r == 0x2194 || r == 0x2195 || r == 0x2196 || r == 0x2197 || r == 0x2198 || r == 0x2199 // sample
}

// ---- Rendering to string (no wrapping) ----

func (h *H) renderString(sb *strings.Builder) {
	if h == nil {
		return
	}
	switch h.kind {
	case hText:
		sb.WriteString(escapeHTMLText(h.text))
	case hRaw:
		sb.WriteString(h.text)
	case hComment:
		sb.WriteString("<!--")
		sb.WriteString(h.text)
		sb.WriteString("-->")
	case hSeq:
		for _, c := range h.children {
			c.renderString(sb)
		}
	case hElem:
		sb.WriteByte('<')
		sb.WriteString(h.tag)
		for _, a := range h.attrs {
			sb.WriteByte(' ')
			sb.WriteString(a[0])
			sb.WriteString("=\"")
			sb.WriteString(escapeHTMLText(a[1]))
			sb.WriteByte('"')
		}
		if h.leaf {
			sb.WriteString(" />")
			return
		}
		sb.WriteByte('>')
		for _, c := range h.children {
			c.renderString(sb)
		}
		sb.WriteString("</")
		sb.WriteString(h.tag)
		sb.WriteByte('>')
	}
}

func (h *H) String() string {
	var sb strings.Builder
	h.renderString(&sb)
	return sb.String()
}

// ---- Layout to Doc (with breaking spaces) ----

var noWrapTags = map[string]bool{"pre": true, "code": true, "textarea": true, "script": true, "style": true, "title": true}

func (h *H) layout(wrap bool) *Doc {
	if h == nil {
		return Empty
	}
	switch h.kind {
	case hText:
		if wrap {
			return toBreakable(escapeHTMLText(h.text))
		}
		return Literal(escapeHTMLText(h.text))
	case hRaw:
		if wrap {
			return toBreakable(h.text)
		}
		return Literal(h.text)
	case hComment:
		return Cat(Literal("<!--"), Literal(h.text), Literal("-->"))
	case hSeq:
		docs := make([]*Doc, 0, len(h.children))
		for _, c := range h.children {
			docs = append(docs, c.layout(wrap))
		}
		return Cat(docs...)
	case hElem:
		docs := []*Doc{Literal("<" + h.tag)}
		for _, a := range h.attrs {
			docs = append(docs, BreakingSpace, Literal(a[0]+"=\""+escapeHTMLText(a[1])+"\""))
		}
		if h.leaf {
			docs = append(docs, Literal(" />"))
			return Cat(docs...)
		}
		docs = append(docs, Literal(">"))
		wrap2 := wrap && !noWrapTags[h.tag]
		for _, c := range h.children {
			docs = append(docs, c.layout(wrap2))
		}
		docs = append(docs, Literal("</"+h.tag+">"))
		return Cat(docs...)
	}
	return Empty
}

// toBreakable converts spaces to breaking spaces, keeping newlines.
func toBreakable(s string) *Doc {
	if s == "" {
		return Empty
	}
	var docs []*Doc
	var cur strings.Builder
	flush := func() {
		if cur.Len() > 0 {
			docs = append(docs, TextD(cur.String()))
			cur.Reset()
		}
	}
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		r := rs[i]
		switch r {
		case ' ', '\t':
			flush()
			docs = append(docs, BreakingSpace)
			for i+1 < len(rs) && (rs[i+1] == ' ' || rs[i+1] == '\t') {
				i++
			}
		case '\n':
			flush()
			docs = append(docs, NewLineDoc)
		default:
			cur.WriteRune(r)
		}
	}
	flush()
	return Cat(docs...)
}
