func (h *H) layout(wrap bool) *Doc {
	if h == nil {
		return Empty
	}
	switch h.kind {
	case hText:
		if wrap {
			return toBreakable(escapeHTMLText(h.text))
		}
		return Literal(escapeHTMLText(h.text))
	case hRaw:
		if wrap {
			return toBreakable(h.text)
		}
		return Literal(h.text)
	case hComment:
		return Cat(Literal("<!--"), Literal(h.text), Literal("-->"))
	case hSeq:
		docs := make([]*Doc, 0, len(h.children))
		for _, c := range h.children {
			docs = append(docs, c.layout(wrap))
		}
		return Cat(docs...)
	case hElem:
		docs := []*Doc{Literal("<" + h.tag)}
		for _, a := range h.attrs {
			docs = append(docs, BreakingSpace, Literal(a[0]+"=\""+escapeHTMLText(a[1])+"\""))
		}
		if h.leaf {
			docs = append(docs, Literal(" />"))
			return Cat(docs...)
		}
		docs = append(docs, Literal(">"))
		wrap2 := wrap && !noWrapTags[h.tag]
		for _, c := range h.children {
			docs = append(docs, c.layout(wrap2))
		}
		docs = append(docs, Literal("</"+h.tag+">"))
		return Cat(docs...)
	}
	return Empty
}

// toBreakable converts spaces to breaking spaces, keeping newlines.
func toBreakable(s string) *Doc {
	if s == "" {
		return Empty
	}
	var docs []*Doc
	var cur strings.Builder
	flush := func() {
		if cur.Len() > 0 {
			docs = append(docs, TextD(cur.String()))
			cur.Reset()
		}
	}
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		r := rs[i]
		switch r {
		case ' ', '\t':
			flush()
			docs = append(docs, BreakingSpace)
			for i+1 < len(rs) && (rs[i+1] == ' ' || rs[i+1] == '\t') {
				i++
			}
		case '\n':
			flush()
			docs = append(docs, NewLineDoc)
		default:
			cur.WriteRune(r)
		}
	}
	flush()
	return Cat(docs...)
}
