func (w *htmlWriter) toAttrs(kvs [][2]string) [][2]string {
	var out [][2]string
	seen := map[string]bool{}
	for _, kv := range kvs {
		k, v := kv[0], kv[1]
		if k == "" {
			continue
		}
		if seen[k] {
			w.warnings = append(w.warnings, fmt.Sprintf("[WARNING] Ignoring duplicate attribute %s=\"%s\".", k, v))
