func writeHTML(doc *Pandoc, opts *WriterOptions, html5 bool) (string, []string) {
	w := &htmlWriter{opts: opts, html5: html5}
	body, toc := w.pandocBody(doc)
	var ctx map[string]tmplValue
	if opts.Standalone {
		ctx = w.metaContext(doc.Meta)
	}
	_ = toc
	if !opts.Standalone {
		return w.renderDoc(body), w.warnings
	}
	// standalone: template
	vars := ctx
	vars["body"] = tmplStr(w.renderDoc(body))
	if toc != nil {
		vars["toc"] = tmplStr(w.renderDoc(toc))
		vars["table-of-contents"] = vars["toc"]
	}
	w.setStandaloneVars(vars, doc)
	tmpl := opts.Template
	if tmpl == "" {
		tmpl = defaultHTMLTemplate
	}
	out := renderTemplate(tmpl, vars)
