func (w *htmlWriter) blockListToHtml(bs []Block) *H {
	var out []*H
	for _, b := range bs {
		h := w.blockToHtml(b)
		if h == nil || h.isEmpty() {
			continue
		}
		if len(out) > 0 {
			out = append(out, hNl)
		}
		out = append(out, h)
	}
	return hSeq_(out...)
}

func isSectionDiv(b Block) bool {
	if d, ok := b.(*Div); ok {
		if len(d.Attr.Classes) > 0 && d.Attr.Classes[0] == "section" {
			if len(d.Blocks) > 0 {
				if _, ok := d.Blocks[0].(*Header); ok {
					return true
				}
			}
		}
	}
	return false
}

func (w *htmlWriter) blockToHtml(b Block) *H {
	switch x := b.(type) {
	case *Plain:
		return w.inlineListToHtml(x.Inlines)
	case *Para:
		if len(x.Inlines) == 1 {
			if img, ok := x.Inlines[0].(*Image); ok && false {
				_ = img
			}
		}
		if len(x.Inlines) == 0 {
			return nil
		}
		return hEl("p", w.inlineListToHtml(x.Inlines))
	case *LineBlock:
		var items []*H
		for i, l := range x.Lines {
			if i > 0 {
				items = append(items, hLeaf("br"), hNl)
			}
			items = append(items, w.inlineListToHtml(l))
		}
		return hEl("div", items...).attr("class", "line-block")
	case *CodeBlock:
		return w.codeBlockToHtml(x)
	case *RawBlock:
		if x.Format == "html" || x.Format == "html5" || x.Format == "html4" {
			return hRaw_(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return nil
	case *BlockQuote:
		return hEl("blockquote", hNl, w.blockListToHtml(x.Blocks), hNl)
	case *Header:
		return w.headerToHtml(x)
	case *HorizontalRule:
		return hLeaf("hr")
	case *BulletList:
		var items []*H
		items = append(items, hNl)
		isTask := false
		for _, it := range x.Items {
			items = append(items, w.listItemToHtml(it, &isTask), hNl)
		}
		ul := hEl("ul", items...)
		if isTask {
			ul.attr("class", "task-list")
		}
		return ul
	case *OrderedList:
		var items []*H
		items = append(items, hNl)
		isTask := false
		for _, it := range x.Items {
			items = append(items, w.listItemToHtml(it, &isTask), hNl)
		}
		ol := hEl("ol", items...)
		if x.Attrs.Start != 1 {
			ol.attr("start", strconv.Itoa(x.Attrs.Start))
		}
		switch x.Attrs.Style {
		case Decimal:
			ol.attr("type", "1")
		case LowerAlpha:
			ol.attr("type", "a")
		case UpperAlpha:
			ol.attr("type", "A")
		case LowerRoman:
			ol.attr("type", "i")
		case UpperRoman:
			ol.attr("type", "I")
		}
		if x.Attrs.Style == Example {
			ol.attr("class", "example")
		}
		if isTask {
			ol.attr("class", "task-list")
		}
		return ol
	case *DefinitionList:
		var items []*H
		items = append(items, hNl)
		for _, it := range x.Items {
			items = append(items, hEl("dt", w.inlineListToHtml(it.Term)), hNl)
			for _, d := range it.Defs {
				items = append(items, hEl("dd", hNl, w.blockListToHtml(d), hNl), hNl)
			}
		}
		return hEl("dl", items...)
	case *Div:
		return w.divToHtml(x)
	case *Figure:
		return w.figureToHtml(x)
	case *Table:
		return w.tableToHtml(x)
	}
	return nil
}

func (w *htmlWriter) listItemToHtml(bs []Block, isTask *bool) *H {
	// task list detection
	if len(bs) > 0 {
		var ils []Inline
		var rest []Block
		isPara := false
		switch f := bs[0].(type) {
		case *Plain:
			ils = f.Inlines
			rest = bs[1:]
		case *Para:
			ils = f.Inlines
			rest = bs[1:]
			isPara = true
		}
		if len(ils) >= 2 {
			if s, ok := ils[0].(*Str); ok && (s.Text == "\u2610" || s.Text == "\u2612") {
				if _, ok := ils[1].(*Space); ok {
					*isTask = true
					cb := hLeaf("input").attr("type", "checkbox")
					if s.Text == "\u2612" {
						cb.attr("checked", "")
					}
					var label *H
					if w.html5 || true {
						label = hEl("label", cb, w.inlineListToHtml(ils[2:]))
					}
					var first *H
					if isPara {
						first = hEl("p", label)
					} else {
						first = label
					}
					restH := w.blockListToHtml(rest)
					if restH.isEmpty() {
						return hEl("li", first)
					}
					return hEl("li", first, hNl, restH)
				}
			}
		}
	}
	return hEl("li", w.blockListToHtml(bs))
}

func (w *htmlWriter) headerToHtml(x *Header) *H {
	contents := w.inlineListToHtml(x.Inlines)
	secnum, _ := x.Attr.Get("number")
	if w.opts.NumberSections && secnum != "" && !x.Attr.HasClass("unnumbered") {
		contents = hSeq_(hEl("span", strToHtml(secnum)).attr("class", "header-section-number"), strToHtml(" "), contents)
	}
	kvs := x.Attr.KVs
	if !w.html5 {
		var k2 [][2]string
		for _, kv := range kvs {
			switch kv[0] {
			case "lang", "dir", "title", "style", "align":
				k2 = append(k2, kv)
			}
		}
		kvs = k2
	}
	var h *H
	switch x.Level {
	case 1, 2, 3, 4, 5, 6:
		h = hEl("h"+strconv.Itoa(x.Level), contents)
	default:
		h = hEl("p", contents)
		attr := Attr{ID: x.Attr.ID, Classes: append([]string{"heading"}, x.Attr.Classes...), KVs: kvs}
		return w.addAttrs(attr, h)
	}
	return w.addAttrs(Attr{ID: x.Attr.ID, Classes: x.Attr.Classes, KVs: kvs}, h)
}

func (w *htmlWriter) codeBlockToHtml(x *CodeBlock) *H {
	id := x.Attr.ID
	if id == "" {
		w.codeBlockNum++
		id = w.prefixedId("cb" + strconv.Itoa(w.codeBlockNum))
	} else {
		id = w.prefixedId(id)
	}
	if w.opts.Highlight {
		if h, ok := highlightBlock(id, x.Attr, x.Text); ok {
			w.highlighting = true
			return w.addAttrsNoPrefix(Attr{ID: id, KVs: x.Attr.KVs}, h)
		}
	}
	return w.addAttrs(x.Attr, hEl("pre", hEl("code", hText_(x.Text))))
}

func (w *htmlWriter) addAttrsNoPrefix(attr Attr, h *H) *H {
	old := w.opts.IdentifierPrefix
	w.opts.IdentifierPrefix = ""
	r := w.addAttrs(attr, h)
	w.opts.IdentifierPrefix = old
	return r
}

func (w *htmlWriter) divToHtml(x *Div) *H {
	attr := x.Attr
	// section divs
	if len(attr.Classes) > 0 && attr.Classes[0] == "section" {
		if len(x.Blocks) > 0 {
			if hdr, ok := x.Blocks[0].(*Header); ok {
				return w.sectionToHtml(x, hdr)
			}
		}
	}
	classes := attr.Classes
	// speaker notes etc. skipped
	opts := w.opts
	_ = opts
	contents := w.blockListToHtml(x.Blocks)
	var el *H
	isCslEntry := attr.HasClass("csl-entry")
	if w.html5 && attr.HasClass("csl-entry") && false {
		_ = isCslEntry
	}
	el = hEl("div", hNl, contents, hNl)
	if contents.isEmpty() {
		el = hEl("div", hNl)
		el = hEl("div")
		// pandoc: `H.div $ nl <> contents' <> nl` ; with empty contents yields "<div>\n\n</div>"? Actually nl <> mempty <> nl = two newlines but doclayout collapses.
		el = hEl("div", hNl, hNl)
	}
	_ = classes
	return w.addAttrs(attr, el)
}

func (w *htmlWriter) sectionToHtml(d *Div, hdr *Header) *H {
	ident := d.Attr.ID
	dclasses := d.Attr.Classes[1:]
	dkvs := d.Attr.KVs
	level := hdr.Level
	headerH := w.blockToHtml(hdr)
	rest := d.Blocks[1:]
	inner := w.blockListToHtml(rest)
	var classes []string
	if w.opts.SectionDivs {
		if !w.html5 {
			classes = append(classes, "section")
		}
		classes = append(classes, "level"+strconv.Itoa(level))
	}
	classes = append(classes, dclasses...)
	attr := Attr{ID: ident, Classes: classes, KVs: dkvs}
	hclasses := hdr.Attr.Classes
	hkvs := hdr.Attr.KVs
	hident := hdr.Attr.ID
	differ := (hident != ident && hident != "" && ident != "") || !strSliceEq(hclasses, dclasses) || !kvSliceEq(hkvs, dkvs)
	if w.opts.SectionDivs || differ {
		tag := "div"
		if w.html5 {
			tag = "section"
		}
		var items []*H
		items = append(items, hNl, headerH, hNl)
		if !inner.isEmpty() {
			items = append(items, inner, hNl)
		}
		return w.addAttrs(attr, hEl(tag, items...))
	}
	// no section divs: attach id to header
	attr2 := Attr{ID: ident, Classes: diffStrs(classes, hclasses), KVs: diffKVs(dkvs, hkvs)}
	t := w.addAttrs(attr2, headerH)
	if inner.isEmpty() {
		return t
	}
	return hSeq_(t, hNl, inner)
}

func strSliceEq(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func kvSliceEq(a, b [][2]string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func diffStrs(a, b []string) []string {
	var out []string
	rem := append([]string{}, b...)
outer:
	for _, x := range a {
		for i, y := range rem {
			if x == y {
				rem = append(rem[:i], rem[i+1:]...)
				continue outer
			}
		}
		out = append(out, x)
	}
	return out
}

func diffKVs(a, b [][2]string) [][2]string {
	var out [][2]string
	rem := append([][2]string{}, b...)
outer:
	for _, x := range a {
		for i, y := range rem {
			if x == y {
				rem = append(rem[:i], rem[i+1:]...)
				continue outer
			}
		}
		out = append(out, x)
	}
	return out
}

func (w *htmlWriter) figureToHtml(x *Figure) *H {
	var capt *H
	captBlocks := x.Caption.Blocks
	if len(captBlocks) > 0 {
		var ils []Inline
		isSimple := false
		if len(captBlocks) == 1 {
			switch c := captBlocks[0].(type) {
			case *Plain:
				ils = c.Inlines
				isSimple = true
			case *Para:
				ils = c.Inlines
				isSimple = true
			}
		}
		if isSimple {
			capt = hEl("figcaption", w.inlineListToHtml(ils))
		} else {
			capt = hEl("figcaption", w.blockListToHtml(captBlocks))
		}
		// aria-hidden if the image alt text equals the caption
		if len(x.Blocks) == 1 {
			if pl, ok := x.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
				if img, ok := pl.Inlines[0].(*Image); ok {
					if stringify(img.Inlines) == stringify(blocksInlines(captBlocks)) && w.html5 {
						capt.attr("aria-hidden", "true")
					}
				}
			}
		}
	}
	// contents: images in Plain are rendered directly
	var contents []*H
	for _, b := range x.Blocks {
		if pl, ok := b.(*Plain); ok {
			contents = append(contents, w.inlineListToHtml(pl.Inlines))
		} else {
			contents = append(contents, w.blockToHtml(b))
		}
	}
	var items []*H
	items = append(items, hNl)
	for _, c := range contents {
		items = append(items, c, hNl)
	}
	if capt != nil {
		if w.opts.FigureCaptionPosition == "above" {
			items = append([]*H{hNl, capt, hNl}, items[1:]...)
		} else {
			items = append(items, capt, hNl)
		}
	}
	tag := "figure"
	if !w.html5 {
		tag = "div"
	}
	el := hEl(tag, items...)
	if !w.html5 {
		attr := x.Attr
		attr.Classes = append([]string{"figure"}, attr.Classes...)
		return w.addAttrs(attr, el)
	}
	return w.addAttrs(x.Attr, el)
}

// ---- tables ----

func alignStyle(a Alignment) string {
	switch a {
	case AlignLeft:
		return "text-align: left;"
	case AlignRight:
		return "text-align: right;"
	case AlignCenter:
		return "text-align: center;"
	}
	return ""
}

func (w *htmlWriter) tableToHtml(t *Table) *H {
	var items []*H
	items = append(items, hNl)
	// caption
	captBlocks := t.Caption.Blocks
	if len(captBlocks) > 0 {
		var cap *H
		if len(captBlocks) == 1 {
			switch c := captBlocks[0].(type) {
			case *Plain:
				cap = hEl("caption", w.inlineListToHtml(c.Inlines))
			case *Para:
				cap = hEl("caption", w.inlineListToHtml(c.Inlines))
			}
		}
		if cap == nil {
			cap = hEl("caption", w.blockListToHtml(captBlocks))
		}
		items = append(items, cap, hNl)
	}
	// colgroup if any widths given
	hasWidths := false
	for _, s := range t.ColSpecs {
		if !s.Width.Default {
			hasWidths = true
		}
	}
	if hasWidths {
		var cols []*H
		cols = append(cols, hNl)
		for _, s := range t.ColSpecs {
			col := hLeaf("col")
			if !s.Width.Default {
				pct := s.Width.Width * 100
				col.attr("style", "width: "+formatPct(pct)+"%;")
			}
			cols = append(cols, col, hNl)
		}
		items = append(items, hEl("colgroup", cols...), hNl)
	}
	aligns := make([]Alignment, len(t.ColSpecs))
	for i, s := range t.ColSpecs {
		aligns[i] = s.Align
	}
	// head
	if len(t.Head.Rows) > 0 && !rowsAllEmpty(t.Head.Rows) {
		var rows []*H
		rows = append(rows, hNl)
		for _, r := range t.Head.Rows {
			rows = append(rows, w.rowToHtml(r, aligns, "th", true), hNl)
		}
		thead := w.addAttrs(t.Head.Attr, hEl("thead", rows...))
		items = append(items, thead, hNl)
	}
	for _, body := range t.Bodies {
		var rows []*H
		rows = append(rows, hNl)
		for _, r := range body.Head {
			rows = append(rows, w.rowToHtml(r, aligns, "th", true), hNl)
		}
		for _, r := range body.Body {
			rows = append(rows, w.rowToHtml(r, aligns, "td", false), hNl)
		}
		tbody := w.addAttrs(body.Attr, hEl("tbody", rows...))
		items = append(items, tbody, hNl)
	}
	if len(t.Foot.Rows) > 0 {
		var rows []*H
		rows = append(rows, hNl)
		for _, r := range t.Foot.Rows {
			rows = append(rows, w.rowToHtml(r, aligns, "td", false), hNl)
		}
		items = append(items, w.addAttrs(t.Foot.Attr, hEl("tfoot", rows...)), hNl)
	}
	tbl := hEl("table", items...)
	return w.addAttrs(t.Attr, tbl)
}

func rowsAllEmpty(rows []Row) bool {
	for _, r := range rows {
		for _, c := range r.Cells {
			if len(c.Blocks) > 0 {
				return false
			}
		}
	}
	return true
}

func formatPct(f float64) string {
	// pandoc: showFFloat (Just 2)? It uses: tshow (truncate? ) Actually `percent w = show (truncate (100*w) :: Integer)`? Use integer when whole, else 2 decimals.
	s := strconv.FormatFloat(f, 'f', 2, 64)
	s = strings.TrimRight(strings.TrimRight(s, "0"), ".")
	if s == "" || s == "-" {
		s = "0"
	}
	return s
}

func (w *htmlWriter) rowToHtml(r Row, aligns []Alignment, tag string, isHeader bool) *H {
	var cells []*H
	cells = append(cells, hNl)
	col := 0
	for _, c := range r.Cells {
		align := c.Align
		if align == AlignDefault && col < len(aligns) {
			align = aligns[col]
		}
		cells = append(cells, w.cellToHtml(c, align, tag), hNl)
		col += c.ColSpan
		if c.ColSpan == 0 {
			col++
		}
	}
	return w.addAttrs(r.Attr, hEl("tr", cells...))
}

func (w *htmlWriter) cellToHtml(c Cell, align Alignment, tag string) *H {
	var contents *H
	if len(c.Blocks) == 1 {
		if pl, ok := c.Blocks[0].(*Plain); ok {
			contents = w.inlineListToHtml(pl.Inlines)
		}
	}
	if contents == nil {
		contents = w.blockListToHtml(c.Blocks)
	}
	el := hEl(tag, contents)
	attr := c.Attr
	el = w.addAttrs(attr, el)
	if st := alignStyle(align); st != "" {
		if w.html5 {
			el.attr("style", st)
		} else {
			switch align {
			case AlignLeft:
				el.attr("align", "left")
			case AlignRight:
				el.attr("align", "right")
			case AlignCenter:
				el.attr("align", "center")
			}
		}
	}
	if c.RowSpan > 1 {
		el.attr("rowspan", strconv.Itoa(c.RowSpan))
	}
	if c.ColSpan > 1 {
		el.attr("colspan", strconv.Itoa(c.ColSpan))
	}
	return el
}

// ---- inlines ----

func (w *htmlWriter) inlineListToHtml(ils []Inline) *H {
	var out []*H
	for _, il := range ils {
		out = append(out, w.inlineToHtml(il))
	}
	return hSeq_(out...)
}

func (w *htmlWriter) inlineToHtml(il Inline) *H {
	switch x := il.(type) {
	case *Str:
		return strToHtml(x.Text)
	case *Space:
		return strToHtml(" ")
	case *SoftBreak:
		if w.opts.WrapText == WrapPreserve {
			return hRaw_("\n")
		}
		return hRaw_(" ")
	case *LineBreak:
		return hSeq_(hLeaf("br"), hRaw_("\n"))
	case *Emph:
		return hEl("em", w.inlineListToHtml(x.Inlines))
	case *Underline:
		return hEl("u", w.inlineListToHtml(x.Inlines))
	case *Strong:
		return hEl("strong", w.inlineListToHtml(x.Inlines))
	case *Strikeout:
		return hEl("del", w.inlineListToHtml(x.Inlines))
	case *Superscript:
		return hEl("sup", w.inlineListToHtml(x.Inlines))
	case *Subscript:
		return hEl("sub", w.inlineListToHtml(x.Inlines))
	case *SmallCaps:
		return hEl("span", w.inlineListToHtml(x.Inlines)).attr("class", "smallcaps")
	case *Code:
		return w.codeToHtml(x)
	case *Quoted:
		var open, close string
		if x.Type == SingleQuote {
			open, close = "\u2018", "\u2019"
		} else {
			open, close = "\u201c", "\u201d"
		}
		if w.opts.HTMLQTags {
			return hEl("q", w.inlineListToHtml(x.Inlines))
		}
		return hSeq_(strToHtml(open), w.inlineListToHtml(x.Inlines), strToHtml(close))
	case *Math:
		return w.mathToHtml(x)
	case *RawInline:
		if x.Format == "html" || x.Format == "html5" || x.Format == "html4" {
			return hRaw_(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return nil
	case *Link:
		return w.linkToHtml(x)
	case *Image:
		return w.imageToHtml(x)
	case *Note:
		return w.noteToHtml(x)
	case *Span:
		return w.spanToHtml(x)
	case *Cite:
		cites := make([]string, len(x.Citations))
		for i, c := range x.Citations {
			cites[i] = c.ID
		}
		return hEl("span", w.inlineListToHtml(x.Inlines)).attr("class", "citation").attr("data-cites", strings.Join(cites, " "))
	}
	return nil
}

func (w *htmlWriter) codeToHtml(x *Code) *H {
	attr := x.Attr
	// highlighting inline code
	if w.opts.Highlight && len(attr.Classes) > 0 {
		if h, ok := highlightInline(attr, x.Text); ok {
			w.highlighting = true
			return w.addAttrs(Attr{ID: attr.ID, KVs: attr.KVs}, h)
		}
	}
	return w.addAttrs(attr, hEl("code", strToHtml(x.Text)))
}

func (w *htmlWriter) spanToHtml(x *Span) *H {
	attr := x.Attr
	contents := w.inlineListToHtml(x.Inlines)
	return w.addAttrs(attr, hEl("span", contents))
}

func (w *htmlWriter) linkToHtml(x *Link) *H {
	url := x.Target.URL
	title := x.Target.Title
	attr := x.Attr
	if strings.HasPrefix(url, "mailto:") {
		return w.obfuscateLink(x)
	}
	a := hEl("a", w.inlineListToHtml(x.Inlines))
	a.attr("href", url)
	if title != "" {
		a.attr("title", title)
	}
	a = w.addAttrs(attr, a)
	// uri class if link text == url
	if len(x.Inlines) == 1 {
		if s, ok := x.Inlines[0].(*Str); ok && s.Text == url {
			a.attr("class", "uri")
		}
	}
	return a
}

func (w *htmlWriter) obfuscateLink(x *Link) *H {
	url := x.Target.URL
	txt := stringify(x.Inlines)
	meth := w.opts.EmailObfuscation
	if meth == "none" || meth == "" {
		a := hEl("a", w.inlineListToHtml(x.Inlines)).attr("href", url)
		if x.Target.Title != "" {
			a.attr("title", x.Target.Title)
		}
		a = w.addAttrs(x.Attr, a)
		if len(x.Inlines) == 1 {
			if s, ok := x.Inlines[0].(*Str); ok && ("mailto:"+s.Text == url || s.Text == url) {
				a.attr("class", "email")
			}
		}
		return a
	}
	// javascript / references obfuscation
	s := strings.TrimPrefix(url, "mailto:")
	parts := strings.SplitN(s, "@", 2)
	if len(parts) != 2 {
		a := hEl("a", w.inlineListToHtml(x.Inlines)).attr("href", url)
		return a
	}
	name, domain := parts[0], parts[1]
	name = strings.ReplaceAll(name, ".", " dot ")
	domain = strings.ReplaceAll(domain, ".", " dot ")
	linkText := txt
	if txt == s {
		linkText = "e-mail"
	} else {
		linkText = "'" + txt + "'"
	}
	altText := ""
	if txt == s {
		altText = "<a href=\"mailto:" + escapeHTMLText(name+" at "+domain) + "\">" + escapeHTMLText(name+" at "+domain) + "</a>"
	} else {
		altText = escapeHTMLText(txt) + " (" + escapeHTMLText(name+" at "+domain) + ")"
	}
	_ = altText
	switch meth {
	case "references":
		mailto := obfuscateString("mailto:" + s)
		a := hEl("a", hRaw_(obfuscateString(txt))).attr("href", mailto)
		return a
	default: // javascript
		js := "document.write('" + obfuscateString(fmt.Sprintf("<a href=\"mailto:%s@%s\">%s</a>", name, domain, linkText)) + "');"
		_ = js
		script := hEl("script", hRaw_("\n<!--\nh='"+obfuscateString(domain)+"';a='&#64;';n='"+obfuscateString(name)+"';e=n+a+h;\ndocument.write('<a h'+'ref'+'=\"ma'+'ilto'+':'+e+'\" clas'+'s=\"em' + 'ail\">'+"+(func() string {
			if txt == s {
				return "e"
			}
			return "'" + obfuscateString(txt) + "'"
		})()+"+'<\\/'+'a'+'>');\n// -->\n")).attr("type", "text/javascript")
		noscript := hEl("noscript", hRaw_(obfuscateString(func() string {
			if txt == s {
				return name + " at " + domain
			}
			return txt + " (" + name + " at " + domain + ")"
		}())))
		return hSeq_(script, noscript)
	}
}

func obfuscateString(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if r == ' ' {
			sb.WriteRune(r)
			continue
		}
		if r > 0x7f {
			sb.WriteRune(r)
			continue
		}
		if int(r)%2 == 0 {
			sb.WriteString("&#" + strconv.Itoa(int(r)) + ";")
		} else {
			sb.WriteString(fmt.Sprintf("&#x%X;", r))
		}
	}
	return sb.String()
}

func (w *htmlWriter) imageToHtml(x *Image) *H {
	alt := stringify(x.Inlines)
	img := hLeaf("img")
	img.attr("src", x.Target.URL)
	if x.Target.Title != "" {
		img.attr("title", x.Target.Title)
	}
	img.attr("alt", alt)
	// width/height attributes from kvs
	attr := x.Attr
	var kvs [][2]string
	var styles []string
	for _, kv := range attr.KVs {
		k, v := kv[0], kv[1]
		if k == "width" || k == "height" {
			if dim, ok := parseDimension(v); ok {
				if dim.unit == "px" || dim.unit == "" {
					kvs = append(kvs, [2]string{k, dim.numStr()})
				} else {
					styles = append(styles, k+":"+dim.String())
				}
				continue
			}
		}
		kvs = append(kvs, kv)
	}
	if len(styles) > 0 {
		kvs = append(kvs, [2]string{"style", strings.Join(styles, ";")})
	}
	attr.KVs = kvs
	return w.addAttrs(attr, img)
}

type dimension struct {
	val  float64
	unit string
	raw  string
}

func (d dimension) numStr() string {
	s := strconv.FormatFloat(d.val, 'f', -1, 64)
	return s
}

func (d dimension) String() string {
	return d.numStr() + d.unit
}

func parseDimension(s string) (dimension, bool) {
	s = strings.TrimSpace(s)
	i := 0
	for i < len(s) && (s[i] >= '0' && s[i] <= '9' || s[i] == '.') {
		i++
	}
	if i == 0 {
		return dimension{}, false
	}
	v, err := strconv.ParseFloat(s[:i], 64)
	if err != nil {
		return dimension{}, false
	}
	unit := s[i:]
	switch unit {
	case "", "px", "%", "cm", "mm", "in", "pt", "em", "ex", "pc", "rem", "vw", "vh":
		return dimension{val: v, unit: unit, raw: s}, true
	}
	return dimension{}, false
}

func (w *htmlWriter) noteToHtml(x *Note) *H {
	w.noteCount++
	ref := strconv.Itoa(w.noteCount)
	// build note item
	backlink := hEl("a", strToHtml("\u21a9\ufe0e")).attr("href", "#"+w.prefixedId("fnref"+ref)).attr("class", "footnote-back")
	if w.html5 {
		backlink.attr("role", "doc-backlink")
	}
	blocks := x.Blocks
	var contents *H
	if len(blocks) > 0 {
		last := blocks[len(blocks)-1]
		switch l := last.(type) {
		case *Para:
			front := w.blockListToHtml(blocks[:len(blocks)-1])
			lastH := hEl("p", w.inlineListToHtml(l.Inlines), backlink)
			if front.isEmpty() {
				contents = lastH
			} else {
				contents = hSeq_(front, hNl, lastH)
			}
		case *Plain:
			front := w.blockListToHtml(blocks[:len(blocks)-1])
			lastH := hSeq_(w.inlineListToHtml(l.Inlines), backlink)
			if front.isEmpty() {
				contents = lastH
			} else {
				contents = hSeq_(front, hNl, lastH)
			}
		default:
			contents = hSeq_(w.blockListToHtml(blocks), hNl, hEl("p", backlink))
		}
	} else {
		contents = hEl("p", backlink)
	}
	li := hEl("li", contents).attr("id", w.prefixedId("fn"+ref))
	w.notes = append(w.notes, li)
	link := hEl("a", hEl("sup", strToHtml(ref))).attr("href", "#"+w.prefixedId("fn"+ref)).attr("class", "footnote-ref").attr("id", w.prefixedId("fnref"+ref))
	if w.html5 {
		link.attr("role", "doc-noteref")
	}
	return link
}

func (w *htmlWriter) mathToHtml(x *Math) *H {
	w.math = true
	cls := "math inline"
	if x.Type == DisplayMath {
		cls = "math display"
	}
	switch w.opts.HTMLMathMethod {
	case "mathjax":
		var txt string
		if x.Type == InlineMath {
			txt = "\\(" + x.Text + "\\)"
		} else {
			txt = "\\[" + x.Text + "\\]"
		}
		return hEl("span", strToHtml(txt)).attr("class", cls)
	case "katex":
		return hEl("span", strToHtml(x.Text)).attr("class", cls)
	case "mathml":
		ils, ok := texMathToInlines(x.Type, x.Text)
		_ = ils
		_ = ok
		fallthrough
	case "webtex":
		if w.opts.HTMLMathMethod == "webtex" {
			url := w.opts.MathURL
			if url == "" {
				url = "https://latex.codecogs.com/png.latex?"
			}
			txt := x.Text
			if x.Type == DisplayMath {
				txt = "\\displaystyle " + txt
			}
			img := hLeaf("img").attr("src", url+urlEncode(txt)).attr("alt", x.Text).attr("title", x.Text).attr("class", cls)
			if x.Type == DisplayMath {
				return hSeq_(hLeaf("br"), img, hLeaf("br"))
			}
			return img
		}
		fallthrough
	default:
		ils, ok := texMathToInlines(x.Type, x.Text)
		if !ok {
			w.warnings = append(w.warnings, "[WARNING] Could not convert TeX math "+x.Text+", rendering as TeX:\n  "+x.Text)
			delim := "$"
			if x.Type == DisplayMath {
				delim = "$$"
			}
			ils = []Inline{&Str{Text: delim + x.Text + delim}}
		}
		return hEl("span", w.inlineListToHtml(ils)).attr("class", cls)
	}
}

func urlEncode(s string) string {
	var sb strings.Builder
	for _, b := range []byte(s) {
		if (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') || b == '-' || b == '_' || b == '.' || b == '~' {
			sb.WriteByte(b)
		} else {
			sb.WriteString("%" + hex2(b))
		}
	}
	return sb.String()
}

// ---- table of contents ----

func (w *htmlWriter) tableOfContents(sects []Block) *H {
	entries := tocEntries(sects, w.opts.TOCDepth)
	if len(entries) == 0 {
		return nil
	}
	list := w.tocList(entries)
	if list == nil {
		return nil
	}
	tag := "div"
	if w.html5 {
		tag = "nav"
	}
	nav := hEl(tag, hNl, list, hNl).attr("id", w.prefixedId("TOC"))
	if w.html5 {
		nav.attr("role", "doc-toc")
	}
	return nav
}

type tocEntry struct {
	level    int
	id       string
	num      string
	title    []Inline
	children []tocEntry
	unnum    bool
}

func tocEntries(bs []Block, depth int) []tocEntry {
	var out []tocEntry
	for _, b := range bs {
		d, ok := b.(*Div)
		if !ok {
			continue
		}
		if len(d.Attr.Classes) > 0 && d.Attr.Classes[0] == "section" && len(d.Blocks) > 0 {
			if h, ok := d.Blocks[0].(*Header); ok {
				if h.Level > depth {
					continue
				}
				num, _ := h.Attr.Get("number")
				e := tocEntry{level: h.Level, id: d.Attr.ID, num: num, title: h.Inlines, unnum: h.Attr.HasClass("unnumbered") || d.Attr.HasClass("unlisted")}
				if d.Attr.HasClass("unlisted") {
					continue
				}
				e.children = tocEntries(d.Blocks[1:], depth)
				out = append(out, e)
				continue
			}
		}
		out = append(out, tocEntries(d.Blocks, depth)...)
	}
	return out
}

func (w *htmlWriter) tocList(entries []tocEntry) *H {
	if len(entries) == 0 {
		return nil
	}
	var items []*H
	items = append(items, hNl)
	for _, e := range entries {
		var titleH *H
		// remove notes and links from title
		title := removeNotesAndLinks(e.title)
		if w.opts.NumberSections && e.num != "" && !e.unnum {
			titleH = hSeq_(hEl("span", strToHtml(e.num)).attr("class", "toc-section-number"), strToHtml(" "), w.inlineListToHtml(title))
		} else {
			titleH = w.inlineListToHtml(title)
		}
		var link *H
		if e.id == "" {
			link = titleH
		} else {
			link = hEl("a", titleH).attr("href", "#"+w.prefixedId(e.id))
			if w.opts.NumberSections && e.num != "" && !e.unnum {
				link.attr("id", w.prefixedId("toc-"+e.id))
			} else {
				link.attr("id", w.prefixedId("toc-"+e.id))
			}
		}
		sub := w.tocList(e.children)
		if sub != nil {
			items = append(items, hEl("li", link, hNl, sub, hNl), hNl)
		} else {
			items = append(items, hEl("li", link), hNl)
		}
	}
	return hEl("ul", items...)
}

func removeNotesAndLinks(ils []Inline) []Inline {
	var out []Inline
	for _, il := range ils {
		switch x := il.(type) {
		case *Note:
			continue
		case *Link:
			out = append(out, removeNotesAndLinks(x.Inlines)...)
		default:
			out = append(out, walkInline(il, func(xs []Inline) []Inline { return removeNotesAndLinks2(xs) }))
		}
	}
	return out
}

func removeNotesAndLinks2(ils []Inline) []Inline {
	var out []Inline
	for _, il := range ils {
		switch x := il.(type) {
		case *Note:
			continue
		case *Link:
			out = append(out, x.Inlines...)
		default:
			out = append(out, il)
		}
	}
	return out
}

func getSlideLevel(bs []Block) int {
	// minimum header level followed by a non-header block
	best := 0
	for i := 0; i < len(bs); i++ {
		if h, ok := bs[i].(*Header); ok {
			if i+1 < len(bs) {
				if _, isH := bs[i+1].(*Header); !isH {
					if best == 0 || h.Level < best {
						best = h.Level
					}
				}
			}
		}
	}
	if best == 0 {
		return 1
	}
	return best
}
