// makeSections wraps header sections in Divs with class "section".
func makeSections(numbering bool, baseLevel int, bs []Block) []Block {
	ms := &sectionMaker{numbering: numbering, mbLevel: baseLevel}
	return ms.go_(bs)
}

type sectionMaker struct {
	numbering bool
	mbLevel   int // 0 => Nothing
	lastnum   []int
}

func headerLtEq(level int, b Block) bool {
	switch x := b.(type) {
	case *Header:
		return x.Level <= level
	case *Div:
		if x.Attr.ID == "" && len(x.Attr.Classes) == 1 && x.Attr.Classes[0] == "references" && len(x.Attr.KVs) == 0 && len(x.Blocks) > 0 {
			if h, ok := x.Blocks[0].(*Header); ok {
				return h.Level <= level
			}
		}
	}
	return false
}

func (ms *sectionMaker) go_(bs []Block) []Block {
	var out []Block
	for i := 0; i < len(bs); i++ {
		switch x := bs[i].(type) {
		case *Header:
			level := x.Level
			levelP := level
			if ms.mbLevel > 0 {
				levelP = ms.mbLevel
			}
			lastnumP := ms.lastnum
			if len(lastnumP) > levelP {
				lastnumP = lastnumP[:levelP]
			}
			var newnum []int
			if levelP > 0 {
				if x.Attr.HasClass("unnumbered") {
					newnum = nil
				} else if len(lastnumP) >= levelP {
					newnum = append(append([]int{}, lastnumP[:len(lastnumP)-1]...), lastnumP[len(lastnumP)-1]+1)
				} else {
					newnum = append([]int{}, ms.lastnum...)
					for len(newnum) < levelP-1 {
						newnum = append(newnum, 0)
					}
					newnum = append(newnum, 1)
				}
			}
			if len(newnum) > 0 {
				ms.lastnum = newnum
			}
			// section contents
			j := i + 1
			for j < len(bs) && !headerLtEq(level, bs[j]) {
				j++
			}
			contents := bs[i+1 : j]
			if ms.mbLevel > 0 {
				ms.mbLevel++
			}
			contentsP := ms.go_(contents)
			if ms.mbLevel > 0 {
				ms.mbLevel--
			}
			kvs := x.Attr.KVs
			if _, has := x.Attr.Get("number"); !has && ms.numbering && !x.Attr.HasClass("unnumbered") {
				parts := make([]string, len(newnum))
				for k, n := range newnum {
					parts[k] = strconv.Itoa(n)
				}
				kvs = append([][2]string{{"number", strings.Join(parts, ".")}}, kvs...)
			}
			divattr := Attr{ID: x.Attr.ID, Classes: append([]string{"section"}, x.Attr.Classes...), KVs: kvs}
			hattr := Attr{ID: "", Classes: x.Attr.Classes, KVs: kvs}
			div := &Div{Attr: divattr, Blocks: append([]Block{&Header{Level: levelP, Attr: hattr, Inlines: x.Inlines}}, contentsP...)}
			out = append(out, div)
			i = j - 1
		case *Div:
			// treat div with header as section div if appropriate
			if len(x.Blocks) > 0 && !x.Attr.HasClass("column") && !x.Attr.HasClass("columns") {
				if h, ok := x.Blocks[0].(*Header); ok {
					allDeeper := true
					for _, y := range x.Blocks[1:] {
						if hh, ok := y.(*Header); ok && hh.Level <= h.Level {
							allDeeper = false
						}
					}
					if allDeeper {
						// process: header becomes section with the div's attrs merged
						inner := ms.go_(x.Blocks)
						if len(inner) == 1 {
							if d2, ok := inner[0].(*Div); ok && len(d2.Attr.Classes) > 0 && d2.Attr.Classes[0] == "section" {
								id := x.Attr.ID
								if id == "" {
									id = d2.Attr.ID
								}
								classes := append([]string{"section"}, x.Attr.Classes...)
								for _, c := range d2.Attr.Classes[1:] {
									if !containsStr(classes, c) {
										classes = append(classes, c)
									}
								}
								kvs := append([][2]string{}, x.Attr.KVs...)
								for _, kv := range d2.Attr.KVs {
									kvs = append(kvs, kv)
								}
								out = append(out, &Div{Attr: Attr{ID: id, Classes: classes, KVs: kvs}, Blocks: d2.Blocks})
								continue
							}
						}
						out = append(out, &Div{Attr: x.Attr, Blocks: inner})
						continue
					}
				}
			}
			out = append(out, &Div{Attr: x.Attr, Blocks: ms.go_(x.Blocks)})
		default:
			out = append(out, bs[i])
		}
	}
	return out
}

func containsStr(xs []string, s string) bool {
	for _, x := range xs {
		if x == s {
			return true
		}
	}
	return false
}

// adjustNumbers applies --number-offset.
func adjustNumbers(offset []int, bs []Block) []Block {
	fix := func(num string) string {
		parts := strings.Split(num, ".")
		for i := range parts {
			n, err := strconv.Atoi(parts[i])
			if err != nil {
				continue
			}
			if i < len(offset) {
				n += offset[i]
			}
			parts[i] = strconv.Itoa(n)
		}
		return strings.Join(parts, ".")
	}
	var fixAttr func(a Attr) Attr
	fixAttr = func(a Attr) Attr {
		var kvs [][2]string
		for _, kv := range a.KVs {
			if kv[0] == "number" {
				kvs = append(kvs, [2]string{"number", fix(kv[1])})
			} else {
				kvs = append(kvs, kv)
			}
		}
		a.KVs = kvs
		return a
	}
	var walk func(bs []Block) []Block
	walk = func(bs []Block) []Block {
		out := make([]Block, 0, len(bs))
		for _, b := range bs {
			switch x := b.(type) {
			case *Header:
				out = append(out, &Header{Level: x.Level, Attr: fixAttr(x.Attr), Inlines: x.Inlines})
			case *Div:
				out = append(out, &Div{Attr: fixAttr(x.Attr), Blocks: walk(x.Blocks)})
			default:
				out = append(out, b)
			}
		}
		return out
	}
	return walk(bs)
}

// headerShift implements --shift-heading-level-by.
func headerShift(n int, doc *Pandoc) *Pandoc {
	if n == 0 {
		return doc
	}
	blocks := doc.Blocks
	meta := doc.Meta
	if n < 0 {
		// if the first block is a level-1 header (when shifting up), promote it to title
		if _, hasTitle := meta.Get("title"); !hasTitle && len(blocks) > 0 {
			if h, ok := blocks[0].(*Header); ok && h.Level+n < 1 {
				meta.Set("title", &MetaInlines{Inlines: h.Inlines})
				blocks = blocks[1:]
			}
		}
	}
	blocks = walkBlocks(blocks, func(bs []Block) []Block {
		out := make([]Block, 0, len(bs))
		for _, b := range bs {
			if h, ok := b.(*Header); ok {
				lvl := h.Level + n
				if lvl < 1 {
					out = append(out, &Para{Inlines: h.Inlines})
				} else {
					out = append(out, &Header{Level: lvl, Attr: h.Attr, Inlines: h.Inlines})
				}
				continue
			}
			out = append(out, b)
		}
		return out
	})
	return &Pandoc{Meta: meta, Blocks: blocks}
}

// stripComments removes HTML comments from raw html.
func stripHTMLComments(doc *Pandoc) *Pandoc {
	blocks := walkBlocks(doc.Blocks, func(bs []Block) []Block {
		out := make([]Block, 0, len(bs))
		for _, b := range bs {
			if r, ok := b.(*RawBlock); ok && r.Format == "html" {
				t := removeHTMLComments(r.Text)
				if strings.TrimSpace(t) == "" {
					continue
				}
				out = append(out, &RawBlock{Format: "html", Text: t})
				continue
			}
			out = append(out, b)
		}
		return out
	})
	blocks = walkInlinesInBlocks(blocks, func(ils []Inline) []Inline {
		out := make([]Inline, 0, len(ils))
		for _, il := range ils {
			if r, ok := il.(*RawInline); ok && r.Format == "html" {
				t := removeHTMLComments(r.Text)
				if t == "" {
					continue
				}
				out = append(out, &RawInline{Format: "html", Text: t})
				continue
			}
			out = append(out, il)
		}
		return out
	})
	return &Pandoc{Meta: doc.Meta, Blocks: blocks}
}

func removeHTMLComments(s string) string {
	for {
		i := strings.Index(s, "<!--")
		if i < 0 {
			return s
		}
		j := strings.Index(s[i:], "-->")
		if j < 0 {
			return s
		}
		s = s[:i] + s[i+j+3:]
	}
}

// eastAsianLineBreakFilter etc. omitted.

// normalizeDate tries to convert a date string to YYYY-MM-DD.
func normalizeDate(s string) (string, bool) {
	s = strings.TrimSpace(s)
	layouts := []string{"2006-01-02", "2006-1-2", "January 2, 2006", "Jan 2, 2006", "January 2 2006", "2 January 2006", "02 January 2006", "2 Jan 2006", "2006-01-02T15:04:05Z07:00", "01/02/2006", "1/2/2006", "2006/01/02", "2006/1/2", "January 2006", "Jan 2006", "2006"}
	for _, l := range layouts {
		if t, err := parseTime(l, s); err == nil {
			return t, true
		}
	}
	return "", false
}
