package main

import (
	"strings"
)

// ---- Template values ----

type tmplValue interface{}

// string, bool, []tmplValue, map[string]tmplValue (with tmplMap for ordering)

type tmplMap struct {
	keys []string
	vals map[string]tmplValue
}

func newTmplMap() *tmplMap { return &tmplMap{vals: map[string]tmplValue{}} }

func (m *tmplMap) set(k string, v tmplValue) {
	if _, ok := m.vals[k]; !ok {
		m.keys = append(m.keys, k)
	}
	m.vals[k] = v
}

func tmplStr(s string) tmplValue { return s }

// ---- Template AST ----

type tnKind int

const (
	tnText tnKind = iota
	tnVar
	tnIf
	tnFor
	tnPartial
)

type tnode struct {
	kind   tnKind
	text   string
	name   string   // variable name (dotted)
	pipes  []string // pipe names
	indent string   // indentation prefix for interpolation
	cond   []tcond  // for if: list of (name, body); last may have name "" for else
	body   []*tnode // for loop body
	sep    []*tnode
}

type tcond struct {
	name string
	body []*tnode
}

type tmplParser struct {
	s   []rune
	pos int
}

func parseTemplate(src string) []*tnode {
	tp := &tmplParser{s: []rune(src)}
	nodes, _ := tp.parseNodes("")
	return nodes
}

func (tp *tmplParser) eof() bool { return tp.pos >= len(tp.s) }

// parseNodes parses until a closing directive (endif, else, elseif, endfor, sep) is found.
func (tp *tmplParser) parseNodes(stop string) ([]*tnode, string) {
	var nodes []*tnode
	var text strings.Builder
	flush := func() {
		if text.Len() > 0 {
			nodes = append(nodes, &tnode{kind: tnText, text: text.String()})
			text.Reset()
		}
	}
	for !tp.eof() {
		c := tp.s[tp.pos]
		if c != '$' {
			text.WriteRune(c)
			tp.pos++
			continue
		}
		// $$ literal
		if tp.pos+1 < len(tp.s) && tp.s[tp.pos+1] == '$' {
			text.WriteRune('$')
			tp.pos += 2
			continue
		}
		// comment $-- to end of line
		if hasPrefixRunes(tp.s, tp.pos, "$--") {
			// remove the whole line if only whitespace before
			tp.removeLinePrefix(&text)
			for !tp.eof() && tp.s[tp.pos] != '\n' {
				tp.pos++
			}
			if !tp.eof() {
				tp.pos++
			}
			continue
		}
		// directive or variable
		start := tp.pos
		tp.pos++
		braces := false
		if !tp.eof() && tp.s[tp.pos] == '{' {
			braces = true
			tp.pos++
		}
		inner := tp.readDirective(braces)
		if inner == "" {
			text.WriteRune('$')
			tp.pos = start + 1
			continue
		}
		innerT := strings.TrimSpace(inner)
		switch {
		case innerT == "endif" || innerT == "endfor" || innerT == "else" || innerT == "sep" || strings.HasPrefix(innerT, "elseif(") || strings.HasPrefix(innerT, "elseif "):
			// standalone line removal
			tp.removeLinePrefix(&text)
			tp.skipLineIfBlank()
			flush()
			return nodes, innerT
		case strings.HasPrefix(innerT, "if(") || strings.HasPrefix(innerT, "if "):
			tp.removeLinePrefix(&text)
			tp.skipLineIfBlank()
			flush()
			name := extractParen(innerT)
			node := &tnode{kind: tnIf}
			for {
				body, stopper := tp.parseNodes("if")
				node.cond = append(node.cond, tcond{name: name, body: body})
				if strings.HasPrefix(stopper, "elseif") {
					name = extractParen(stopper)
					continue
				}
				if stopper == "else" {
					body2, _ := tp.parseNodes("if")
					node.cond = append(node.cond, tcond{name: "", body: body2})
				}
				break
			}
			nodes = append(nodes, node)
		case strings.HasPrefix(innerT, "for(") || strings.HasPrefix(innerT, "for "):
			tp.removeLinePrefix(&text)
			tp.skipLineIfBlank()
			flush()
			name := extractParen(innerT)
			node := &tnode{kind: tnFor, name: name}
			body, stopper := tp.parseNodes("for")
			node.body = body
			if stopper == "sep" {
				sep, _ := tp.parseNodes("for")
				node.sep = sep
			}
			nodes = append(nodes, node)
		default:
			// variable or partial
			indent := trailingIndent(&text)
			name := innerT
			var pipes []string
			parts := strings.Split(name, "/")
			name = strings.TrimSpace(parts[0])
			for _, p := range parts[1:] {
				pipes = append(pipes, strings.TrimSpace(p))
			}
			if strings.HasSuffix(name, "()") {
				flush()
				nodes = append(nodes, &tnode{kind: tnPartial, name: strings.TrimSuffix(name, "()"), indent: indent, pipes: pipes})
				continue
			}
			flush()
			nodes = append(nodes, &tnode{kind: tnVar, name: name, pipes: pipes, indent: indent})
		}
	}
	flush()
	return nodes, ""
}

func extractParen(s string) string {
	i := strings.Index(s, "(")
	j := strings.LastIndex(s, ")")
	if i < 0 || j < i {
		return strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(s, "if"), "for"))
	}
	return strings.TrimSpace(s[i+1 : j])
}

// trailingIndent returns the whitespace at the end of text if it constitutes the whole current line.
func trailingIndent(text *strings.Builder) string {
	s := text.String()
	i := strings.LastIndex(s, "\n")
	line := s[i+1:]
	if strings.TrimSpace(line) == "" {
		return line
	}
	return ""
}

// removeLinePrefix removes trailing whitespace of the current line from text if the line is blank so far.
func (tp *tmplParser) removeLinePrefix(text *strings.Builder) {
	s := text.String()
	i := strings.LastIndex(s, "\n")
	line := s[i+1:]
	if strings.TrimSpace(line) == "" {
		tp.pendingBlankLine = true
		text.Reset()
		text.WriteString(s[:i+1])
	} else {
		tp.pendingBlankLine = false
	}
}

// skipLineIfBlank: if the rest of the line after a directive is blank, consume it (incl. newline)
func (tp *tmplParser) skipLineIfBlank() {
	if !tp.pendingBlankLine {
		return
	}
	j := tp.pos
	for j < len(tp.s) && (tp.s[j] == ' ' || tp.s[j] == '\t') {
		j++
	}
	if j < len(tp.s) && tp.s[j] == '\n' {
		tp.pos = j + 1
	} else if j >= len(tp.s) {
		tp.pos = j
	}
}

func (tp *tmplParser) readDirective(braces bool) string {
	start := tp.pos
	if braces {
		depth := 0
		for !tp.eof() {
			c := tp.s[tp.pos]
			if c == '{' {
				depth++
			} else if c == '}' {
				if depth == 0 {
					s := string(tp.s[start:tp.pos])
					tp.pos++
					return s
				}
				depth--
			} else if c == '\n' {
				return ""
			}
			tp.pos++
		}
		return ""
	}
	depth := 0
	for !tp.eof() {
		c := tp.s[tp.pos]
		if c == '(' {
			depth++
		} else if c == ')' {
			depth--
		} else if c == '$' && depth <= 0 {
			s := string(tp.s[start:tp.pos])
			tp.pos++
			return s
		} else if c == '\n' {
			return ""
		}
		tp.pos++
	}
	return ""
}

// ---- Rendering ----

type tmplCtx struct {
	vars  map[string]tmplValue
	stack []map[string]tmplValue
	partials map[string]string
}

func (c *tmplCtx) lookup(name string) (tmplValue, bool) {
	parts := strings.Split(name, ".")
	var v tmplValue
	found := false
	for i := len(c.stack) - 1; i >= 0; i-- {
		if x, ok := c.stack[i][parts[0]]; ok {
			v = x
			found = true
			break
		}
	}
	if !found {
		if x, ok := c.vars[parts[0]]; ok {
			v = x
			found = true
		}
	}
	if !found {
		return nil, false
	}
	for _, p := range parts[1:] {
		m, ok := v.(*tmplMap)
		if !ok {
			return nil, false
		}
		x, ok := m.vals[p]
		if !ok {
			return nil, false
		}
		v = x
	}
	return v, true
}

func tmplTruthy(v tmplValue) bool {
	switch x := v.(type) {
	case nil:
		return false
	case string:
		return x != ""
	case bool:
		return x
	case []tmplValue:
		return len(x) > 0
	case *tmplMap:
		return len(x.keys) > 0
	}
	return true
}

func tmplToString(v tmplValue) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return x
	case bool:
		if x {
			return "true"
		}
		return "false"
	case []tmplValue:
		var sb strings.Builder
		for _, it := range x {
			sb.WriteString(tmplToString(it))
		}
		return sb.String()
	case *tmplMap:
		// a map renders as empty? pandoc renders maps as concatenation? Use "true"?
		var sb strings.Builder
		for _, k := range x.keys {
			sb.WriteString(tmplToString(x.vals[k]))
		}
		return sb.String()
	}
	return ""
}

func renderTemplate(src string, vars map[string]tmplValue) string {
	nodes := parseTemplate(src)
	ctx := &tmplCtx{vars: vars}
	var sb strings.Builder
	ctx.render(nodes, &sb)
	return sb.String()
}

func (c *tmplCtx) render(nodes []*tnode, sb *strings.Builder) {
	for _, n := range nodes {
		switch n.kind {
		case tnText:
			sb.WriteString(n.text)
		case tnVar:
			v, _ := c.lookup(n.name)
			s := c.applyPipes(v, n.pipes)
			sb.WriteString(indentLines(s, n.indent))
		case tnPartial:
			if p, ok := c.partials[n.name]; ok {
				var sub strings.Builder
				c.render(parseTemplate(p), &sub)
				s := strings.TrimSuffix(sub.String(), "\n")
				sb.WriteString(indentLines(s, n.indent))
			}
		case tnIf:
			for _, cond := range n.cond {
				if cond.name == "" {
					c.render(cond.body, sb)
					break
				}
				v, _ := c.lookup(cond.name)
				if tmplTruthy(v) {
					c.render(cond.body, sb)
					break
				}
			}
		case tnFor:
			v, _ := c.lookup(n.name)
			var items []tmplValue
			switch x := v.(type) {
			case []tmplValue:
				items = x
			case nil:
			default:
				if tmplTruthy(v) {
					items = []tmplValue{v}
				}
			}
			for i, it := range items {
				if i > 0 && n.sep != nil {
					c.render(n.sep, sb)
				}
				c.stack = append(c.stack, map[string]tmplValue{n.name: it, "it": it})
				c.render(n.body, sb)
				c.stack = c.stack[:len(c.stack)-1]
			}
		}
	}
}

func indentLines(s, indent string) string {
	if indent == "" || !strings.Contains(s, "\n") {
		return s
	}
	lines := strings.Split(s, "\n")
	for i := 1; i < len(lines); i++ {
		if lines[i] != "" {
			lines[i] = indent + lines[i]
		}
	}
	return strings.Join(lines, "\n")
}

func (c *tmplCtx) applyPipes(v tmplValue, pipes []string) string {
	for _, p := range pipes {
		fields := strings.Fields(p)
		if len(fields) == 0 {
			continue
		}
		switch fields[0] {
		case "uppercase":
			v = strings.ToUpper(tmplToString(v))
		case "lowercase":
			v = strings.ToLower(tmplToString(v))
		case "length":
			switch x := v.(type) {
			case []tmplValue:
				v = intToStr(len(x))
			case *tmplMap:
				v = intToStr(len(x.keys))
			default:
				v = intToStr(len([]rune(tmplToString(v))))
			}
		case "reverse":
			if x, ok := v.([]tmplValue); ok {
				r := make([]tmplValue, len(x))
				for i := range x {
					r[len(x)-1-i] = x[i]
				}
				v = r
			} else {
				rs := []rune(tmplToString(v))
				for i, j := 0, len(rs)-1; i < j; i, j = i+1, j-1 {
					rs[i], rs[j] = rs[j], rs[i]
				}
				v = string(rs)
			}
		case "first":
			if x, ok := v.([]tmplValue); ok && len(x) > 0 {
				v = x[0]
			}
		case "last":
			if x, ok := v.([]tmplValue); ok && len(x) > 0 {
				v = x[len(x)-1]
			}
		case "rest":
			if x, ok := v.([]tmplValue); ok && len(x) > 0 {
				v = x[1:]
			}
		case "allbutlast":
			if x, ok := v.([]tmplValue); ok && len(x) > 0 {
				v = x[:len(x)-1]
			}
		case "chomp":
			v = strings.TrimRight(tmplToString(v), "\n ")
		case "nowrap":
			v = tmplToString(v)
		case "alpha":
			n := atoi(tmplToString(v))
			if n > 0 {
				v = string(rune('a' + (n-1)%26))
			}
		case "roman":
			n := atoi(tmplToString(v))
			v = toRoman(n)
		case "pairs":
			if m, ok := v.(*tmplMap); ok {
				var items []tmplValue
				for _, k := range m.keys {
					pm := newTmplMap()
					pm.set("key", k)
					pm.set("value", m.vals[k])
					items = append(items, pm)
				}
				v = items
			}
		}
	}
	return tmplToString(v)
}

func toRoman(n int) string {
	if n <= 0 || n >= 4000 {
		return ""
	}
	vals := []int{1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1}
	syms := []string{"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"}
	var sb strings.Builder
	for i, v := range vals {
		for n >= v {
			sb.WriteString(syms[i])
			n -= v
		}
	}
	return sb.String()
}
