		return sb.String()
	case *tmplMap:
		// a map renders as empty? pandoc renders maps as concatenation? Use "true"?
		var sb strings.Builder
		for _, k := range x.keys {
			sb.WriteString(tmplToString(x.vals[k]))
		}
		return sb.String()
	}
	return ""
}

