package main

import (
	"strings"
)

// metaToContext converts metadata to template variables using the given renderers.
func metaToContext(meta *MetaMap, renderBlocks func([]Block) string, renderInlines func([]Inline) string) map[string]tmplValue {
	vars := map[string]tmplValue{}
	for _, k := range meta.Keys {
		vars[k] = metaValueToTmpl(meta.Values[k], renderBlocks, renderInlines)
	}
	return vars
}

func metaValueToTmpl(m MetaValue, renderBlocks func([]Block) string, renderInlines func([]Inline) string) tmplValue {
	switch x := m.(type) {
	case *MetaMap:
		tm := newTmplMap()
		for _, k := range x.Keys {
			tm.set(k, metaValueToTmpl(x.Values[k], renderBlocks, renderInlines))
		}
		return tm
	case *MetaList:
		var items []tmplValue
		for _, it := range x.Items {
			items = append(items, metaValueToTmpl(it, renderBlocks, renderInlines))
		}
		return items
	case *MetaBool:
		return x.Value
	case *MetaString:
		return x.Text
	case *MetaInlines:
		return renderInlines(x.Inlines)
	case *MetaBlocks:
		return renderBlocks(x.Blocks)
	}
	return ""
}

func (w *htmlWriter) metaContext(meta *MetaMap) map[string]tmplValue {
	rb := func(bs []Block) string {
		return w.renderDoc(w.blockListToHtml(bs))
	}
	ri := func(ils []Inline) string {
		return w.renderDoc(w.inlineListToHtml(ils))
	}
	return metaToContext(meta, rb, ri)
}

func escapeStringForXML(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			sb.WriteString("&amp;")
		case '<':
			sb.WriteString("&lt;")
		case '>':
