// metaToContext converts metadata to template variables using the given renderers.
func metaToContext(meta *MetaMap, renderBlocks func([]Block) string, renderInlines func([]Inline) string) map[string]tmplValue {
	vars := map[string]tmplValue{}
	for _, k := range meta.Keys {
		vars[k] = metaValueToTmpl(meta.Values[k], renderBlocks, renderInlines)
	}
	return vars
