var texOperators = map[string]bool{}

func init() {
	for _, o := range strings.Fields("sin cos tan cot sec csc arcsin arccos arctan sinh cosh tanh coth log ln lg exp lim limsup liminf max min sup inf det dim ker deg gcd hom arg Pr mod") {
		texOperators[o] = true
