	"{": {symOpen, "{"}, "}": {symClose, "}"}, "|": {symOrd, "‖"}, "_": {symOrd, "_"}, "#": {symOrd, "#"}, "&": {symOrd, "&"}, "%": {symOrd, "%"}, "$": {symOrd, "$"},
}

var texOperators = map[string]bool{}

func init() {
	for _, o := range strings.Fields("sin cos tan cot sec csc arcsin arccos arctan sinh cosh tanh coth log ln lg exp lim limsup liminf max min sup inf det dim ker deg gcd hom arg Pr mod") {
		texOperators[o] = true
	}
}

var texSpaces = map[string]float64{",": 0.167, ":": 0.222, ";": 0.278, " ": 0.333, "!": -0.167, "quad": 1, "qquad": 2, "enspace": 0.5, "thinspace": 0.167, "medspace": 0.222, "thickspace": 0.278, "negthinspace": -0.167}

type texParser struct {
	s   []rune
	pos int
	ok  bool
}

func parseTeXMath(s string) ([]*texExp, bool) {
	p := &texParser{s: []rune(s), ok: true}
	exps := p.parseExprs(func() bool { return p.pos >= len(p.s) })
	if !p.ok || p.pos < len(p.s) {
		return nil, false
	}
	return exps, true
}

func (p *texParser) skipWS() {
	for p.pos < len(p.s) && unicode.IsSpace(p.s[p.pos]) {
		p.pos++
	}
}

func (p *texParser) parseExprs(stop func() bool) []*texExp {
	var out []*texExp
	for {
		p.skipWS()
		if stop() || !p.ok || p.pos >= len(p.s) {
			break
		}
		if p.s[p.pos] == '}' {
			break
		}
		e := p.parseExpr()
		if e == nil {
			break
		}
		out = append(out, e)
	}
	return out
}

func (p *texParser) peekCmd() string {
	if p.pos < len(p.s) && p.s[p.pos] == '\\' {
		j := p.pos + 1
		if j < len(p.s) && !unicode.IsLetter(p.s[j]) {
			return string(p.s[p.pos : j+1])
		}
		for j < len(p.s) && unicode.IsLetter(p.s[j]) {
			j++
		}
		return string(p.s[p.pos:j])
	}
	return ""
}

func (p *texParser) parseExpr() *texExp {
	base := p.parseAtom()
	if base == nil {
		return nil
	}
	// sub/superscripts
	var sub, sup *texExp
	for {
		p.skipWS()
		if p.pos >= len(p.s) {
			break
		}
		c := p.s[p.pos]
		if c == '_' && sub == nil {
			p.pos++
			sub = p.parseArg()
			if sub == nil {
				p.ok = false
				return nil
			}
			continue
		}
		if c == '^' && sup == nil {
			p.pos++
			sup = p.parseArg()
			if sup == nil {
				p.ok = false
				return nil
			}
			continue
		}
		if c == '\'' {
			// primes
			n := 0
			for p.pos < len(p.s) && p.s[p.pos] == '\'' {
				n++
				p.pos++
			}
			primes := strings.Repeat("′", n)
			if sup == nil {
				sup = &texExp{kind: tSymbol, symT: symOrd, text: primes}
			} else {
				sup = &texExp{kind: tGrouped, kids: []*texExp{sup, {kind: tSymbol, symT: symOrd, text: primes}}}
			}
			continue
		}
		break
	}
	switch {
	case sub != nil && sup != nil:
		return &texExp{kind: tSubsup, base: base, sub: sub, sup: sup}
	case sub != nil:
		return &texExp{kind: tSub, base: base, sub: sub}
	case sup != nil:
		return &texExp{kind: tSuper, base: base, sup: sup}
	}
	return base
}

// parseArg parses a group or a single atom (for sub/superscripts and command args).
func (p *texParser) parseArg() *texExp {
	p.skipWS()
	if p.pos >= len(p.s) {
		return nil
	}
	if p.s[p.pos] == '{' {
		return p.parseGroup()
	}
	return p.parseAtom()
}

func (p *texParser) parseGroup() *texExp {
	if p.pos >= len(p.s) || p.s[p.pos] != '{' {
		return nil
	}
	p.pos++
	kids := p.parseExprs(func() bool { return p.pos < len(p.s) && p.s[p.pos] == '}' })
	if p.pos >= len(p.s) || p.s[p.pos] != '}' {
		p.ok = false
		return nil
	}
	p.pos++
	if len(kids) == 1 {
		return kids[0]
	}
	return &texExp{kind: tGrouped, kids: kids}
}

func (p *texParser) parseAtom() *texExp {
	p.skipWS()
	if p.pos >= len(p.s) {
		return nil
	}
	c := p.s[p.pos]
	switch {
	case c == '{':
		return p.parseGroup()
	case c == '}':
		return nil
	case c >= '0' && c <= '9':
		start := p.pos
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
		if p.pos+1 < len(p.s) && p.s[p.pos] == '.' && p.s[p.pos+1] >= '0' && p.s[p.pos+1] <= '9' {
			p.pos++
			for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
				p.pos++
			}
		}
		return &texExp{kind: tNumber, text: string(p.s[start:p.pos])}
	case unicode.IsLetter(c):
		p.pos++
		return &texExp{kind: tIdent, text: string(c)}
	case c == '\\':
		return p.parseCommand()
	case c == '^' || c == '_':
		p.ok = false
		return nil
	}
	p.pos++
	switch c {
	case '+':
		return &texExp{kind: tSymbol, symT: symBin, text: "+"}
	case '-':
		return &texExp{kind: tSymbol, symT: symBin, text: "−"}
	case '*':
		return &texExp{kind: tSymbol, symT: symBin, text: "∗"}
	case '/':
		return &texExp{kind: tSymbol, symT: symOrd, text: "/"}
	case '=':
		return &texExp{kind: tSymbol, symT: symRel, text: "="}
	case '<':
		return &texExp{kind: tSymbol, symT: symRel, text: "<"}
	case '>':
		return &texExp{kind: tSymbol, symT: symRel, text: ">"}
	case ':':
		return &texExp{kind: tSymbol, symT: symRel, text: ":"}
	case ',':
		return &texExp{kind: tSymbol, symT: symPun, text: ","}
	case ';':
		return &texExp{kind: tSymbol, symT: symPun, text: ";"}
	case '.':
		return &texExp{kind: tSymbol, symT: symOrd, text: "."}
	case '!':
		return &texExp{kind: tSymbol, symT: symOrd, text: "!"}
	case '?':
		return &texExp{kind: tSymbol, symT: symOrd, text: "?"}
	case '(':
		return &texExp{kind: tSymbol, symT: symOpen, text: "("}
	case ')':
		return &texExp{kind: tSymbol, symT: symClose, text: ")"}
	case '[':
		return &texExp{kind: tSymbol, symT: symOpen, text: "["}
	case ']':
		return &texExp{kind: tSymbol, symT: symClose, text: "]"}
	case '|':
		return &texExp{kind: tSymbol, symT: symOrd, text: "|"}
	case '@', '"', '`', '~':
		return &texExp{kind: tSymbol, symT: symOrd, text: string(c)}
	case '&':
		p.ok = false
		return nil
	}
	if c > 127 {
		return &texExp{kind: tIdent, text: string(c)}
	}
	p.ok = false
	return nil
}

func (p *texParser) parseCommand() *texExp {
	cmd := p.peekCmd()
	if cmd == "" {
		p.ok = false
		return nil
	}
	p.pos += len([]rune(cmd))
	name := cmd[1:]
	if w, ok := texSpaces[name]; ok {
		return &texExp{kind: tSpace, width: w}
	}
	if s, ok := texSymbols[name]; ok {
		return &texExp{kind: tSymbol, symT: s.t, text: s.s}
	}
	if texOperators[name] {
		return &texExp{kind: tOp, text: name}
	}
	switch name {
	case "text", "textrm", "mbox", "textit", "textbf", "texttt", "textsf":
		p.skipWS()
		if p.pos >= len(p.s) || p.s[p.pos] != '{' {
			p.ok = false
			return nil
		}
		depth := 0
		start := p.pos + 1
		for p.pos < len(p.s) {
			if p.s[p.pos] == '{' {
				depth++
			} else if p.s[p.pos] == '}' {
				depth--
				if depth == 0 {
					break
				}
			}
			p.pos++
		}
		if p.pos >= len(p.s) {
			p.ok = false
			return nil
		}
		txt := string(p.s[start:p.pos])
		p.pos++
		style := "normal"
		switch name {
		case "textit":
			style = "italic"
		case "textbf":
			style = "bold"
		case "texttt":
			style = "mono"
		}
		return &texExp{kind: tText, text: txt, style: style}
	case "mathrm", "mathbf", "mathit", "mathsf", "mathtt", "mathcal", "mathbb", "mathfrak", "boldsymbol", "bm", "mathscr", "operatorname":
		arg := p.parseArg()
		if arg == nil {
			p.ok = false
			return nil
		}
		if name == "operatorname" {
			return &texExp{kind: tOp, text: texExpText(arg)}
		}
		return &texExp{kind: tStyled, style: name, kids: []*texExp{arg}}
	case "left":
		p.skipWS()
		open := p.parseDelim()
		if open == "" {
			p.ok = false
			return nil
		}
		kids := p.parseExprs(func() bool { return p.peekCmd() == "\\right" })
		if p.peekCmd() != "\\right" {
			p.ok = false
			return nil
		}
		p.pos += 6
		p.skipWS()
		close := p.parseDelim()
		if close == "" {
			p.ok = false
			return nil
		}
		if open == "." {
			open = ""
		}
		if close == "." {
			close = ""
		}
		return &texExp{kind: tDelimited, open: open, close: close, kids: kids}
	case "right":
		p.ok = false
		return nil
	case "frac", "dfrac", "tfrac", "binom", "sqrt", "overline", "underline", "hat", "bar", "vec", "dot", "ddot", "tilde", "widehat", "widetilde", "overbrace", "underbrace", "stackrel", "overset", "underset", "begin", "end", "limits", "nolimits", "displaystyle", "textstyle", "scriptstyle", "scriptscriptstyle", "label", "tag", "notag", "nonumber", "phantom", "hphantom", "vphantom", "cfrac", "genfrac", "substack", "mathop", "mathbin", "mathrel", "mathord", "mathpunct", "mathopen", "mathclose", "mathinner", "not", "cancel", "boxed", "color", "textcolor", "raisebox", "hspace", "vspace", "rule", "ensuremath", "big", "Big", "bigg", "Bigg", "bigl", "bigr", "Bigl", "Bigr", "biggl", "biggr", "Biggl", "Biggr", "atop", "over", "choose", "newline", "cr", "\\", "mathstrut", "smash", "hfill", "mkern", "mskern", "kern", "mspace", "lim", "xrightarrow", "xleftarrow", "intertext", "shortintertext", "allowbreak", "unicode", "ce", "pu", "require", "mathllap", "mathrlap", "mathclap":
		// unrenderable in plain inlines
		p.consumeArgs()
		return &texExp{kind: tUnrenderable}
	}
	// unknown command
	p.ok = false
	return nil
}

func (p *texParser) consumeArgs() {
	// consume following groups/brackets loosely
	for {
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == '{' {
			depth := 0
			for p.pos < len(p.s) {
				if p.s[p.pos] == '{' {
					depth++
				} else if p.s[p.pos] == '}' {
					depth--
					if depth == 0 {
						p.pos++
						break
					}
				}
				p.pos++
			}
			continue
		}
		if p.pos < len(p.s) && p.s[p.pos] == '[' {
			for p.pos < len(p.s) && p.s[p.pos] != ']' {
				p.pos++
			}
			if p.pos < len(p.s) {
				p.pos++
			}
			continue
		}
		break
	}
}

func (p *texParser) parseDelim() string {
	if p.pos >= len(p.s) {
		return ""
	}
	c := p.s[p.pos]
	if c == '\\' {
		cmd := p.peekCmd()
		p.pos += len([]rune(cmd))
		if s, ok := texSymbols[cmd[1:]]; ok {
			return s.s
		}
		return ""
	}
	p.pos++
	switch c {
	case '(', ')', '[', ']', '|', '.', '/', '<', '>':
		if c == '<' {
			return "⟨"
		}
		if c == '>' {
			return "⟩"
		}
		return string(c)
	}
	return ""
}

func texExpText(e *texExp) string {
	switch e.kind {
	case tIdent, tNumber, tOp, tSymbol, tText:
		return e.text
	case tGrouped, tStyled:
		var sb strings.Builder
		for _, k := range e.kids {
			sb.WriteString(texExpText(k))
		}
		return sb.String()
	}
	return ""
}

// ---- writer to pandoc inlines ----

func texMathToInlines(mt MathType, s string) ([]Inline, bool) {
	exps, ok := parseTeXMath(s)
	if !ok {
		return nil, false
	}
	var out []Inline
	for _, e := range exps {
		ils, ok := texExpToInlines(e)
		if !ok {
			return nil, false
		}
		out = append(out, ils...)
	}
	return out, true
}

func texExpToInlines(e *texExp) ([]Inline, bool) {
	switch e.kind {
	case tNumber:
		return []Inline{&Str{Text: e.text}}, true
	case tIdent:
		return []Inline{&Emph{Inlines: []Inline{&Str{Text: e.text}}}}, true
	case tOp:
		return []Inline{&Str{Text: e.text}}, true
	case tSymbol:
		x := &Str{Text: e.text}
		switch e.symT {
		case symOp:
			return []Inline{x, &Str{Text: "\u2006"}}, true
		case symBin:
			return []Inline{&Str{Text: "\u2005"}, x, &Str{Text: "\u2005"}}, true
		case symRel:
			return []Inline{&Str{Text: "\u2004"}, x, &Str{Text: "\u2004"}}, true
		case symPun:
			return []Inline{x, &Str{Text: "\u2006"}}, true
		}
		return []Inline{x}, true
	case tSpace:
		n := int(e.width * 4)
		if n <= 0 {
			return nil, true
		}
		return []Inline{&Str{Text: strings.Repeat("\u00a0", n)}}, true
	case tGrouped:
		var out []Inline
		for _, k := range e.kids {
			ils, ok := texExpToInlines(k)
			if !ok {
				return nil, false
			}
			out = append(out, ils...)
		}
		return out, true
	case tDelimited:
		var out []Inline
		if e.open != "" {
			out = append(out, &Str{Text: e.open})
		}
		for _, k := range e.kids {
			ils, ok := texExpToInlines(k)
			if !ok {
				return nil, false
			}
			out = append(out, ils...)
		}
		if e.close != "" {
			out = append(out, &Str{Text: e.close})
		}
		return out, true
	case tSub:
		b, ok := texExpToInlines(e.base)
		if !ok {
			return nil, false
		}
		s, ok := texExpToInlines(e.sub)
		if !ok {
			return nil, false
		}
		return append(b, &Subscript{Inlines: s}), true
	case tSuper:
		b, ok := texExpToInlines(e.base)
		if !ok {
			return nil, false
		}
		s, ok := texExpToInlines(e.sup)
		if !ok {
			return nil, false
		}
		return append(b, &Superscript{Inlines: s}), true
	case tSubsup:
		b, ok := texExpToInlines(e.base)
		if !ok {
			return nil, false
		}
		s1, ok := texExpToInlines(e.sub)
		if !ok {
			return nil, false
		}
		s2, ok := texExpToInlines(e.sup)
		if !ok {
			return nil, false
		}
		return append(b, &Subscript{Inlines: s1}, &Superscript{Inlines: s2}), true
	case tText:
		switch e.style {
		case "bold":
			return []Inline{&Strong{Inlines: []Inline{&Str{Text: e.text}}}}, true
		case "italic":
			return []Inline{&Emph{Inlines: []Inline{&Str{Text: e.text}}}}, true
		case "mono":
			return []Inline{&Code{Text: e.text}}, true
		}
		return []Inline{&Str{Text: e.text}}, true
	case tStyled:
		var out []Inline
		for _, k := range e.kids {
			ils, ok := texExpToInlines(k)
			if !ok {
				return nil, false
			}
			out = append(out, ils...)
		}
		switch e.style {
		case "mathrm", "mathsf", "mathtt", "mathbb", "mathcal", "mathfrak", "mathscr":
			// remove emphasis: render identifiers as plain
			out = unemph(out)
			if e.style == "mathbf" {
				return []Inline{&Strong{Inlines: out}}, true
			}
			return out, true
		case "mathbf", "boldsymbol", "bm":
			return []Inline{&Strong{Inlines: unemph(out)}}, true
		}
		return out, true
	}
	return nil, false
}

func unemph(ils []Inline) []Inline {
	var out []Inline
	for _, il := range ils {
		if e, ok := il.(*Emph); ok {
			out = append(out, e.Inlines...)
		} else {
			out = append(out, il)
		}
	}
	return out
}
