		{"track-changes", "", 1}, {"strip-comments", "", 2}, {"reference-links", "", 2}, {"reference-location", "", 1},
		{"figure-caption-position", "", 1}, {"table-caption-position", "", 1}, {"markdown-headings", "", 1},
		{"list-tables", "", 2}, {"listings", "", 2}, {"incremental", "i", 2}, {"slide-level", "", 1},
		{"section-divs", "", 2}, {"html-q-tags", "", 2}, {"email-obfuscation", "", 1}, {"id-prefix", "", 1},
		{"title-prefix", "T", 1}, {"css", "c", 1}, {"epub-subdirectory", "", 1}, {"epub-cover-image", "", 1},
		{"epub-title-page", "", 2}, {"epub-metadata", "", 1}, {"epub-embed-font", "", 1}, {"split-level", "", 1},
		{"chunk-template", "", 1}, {"epub-chapter-level", "", 1}, {"ipynb-output", "", 1}, {"citeproc", "C", 0},
		{"bibliography", "", 1}, {"csl", "", 1}, {"citation-abbreviations", "", 1}, {"natbib", "", 0}, {"biblatex", "", 0},
		{"mathml", "", 0}, {"webtex", "", 2}, {"mathjax", "", 2}, {"katex", "", 2}, {"gladtex", "", 0},
		{"trace", "", 2}, {"dump-args", "", 2}, {"ignore-args", "", 2}, {"verbose", "", 0}, {"quiet", "", 0},
		{"fail-if-warnings", "", 2}, {"log", "", 1}, {"bash-completion", "", 0}, {"list-input-formats", "", 0},
		{"list-output-formats", "", 0}, {"list-extensions", "", 2}, {"list-highlight-languages", "", 0},
		{"list-highlight-styles", "", 0}, {"print-default-template", "D", 1}, {"print-default-data-file", "", 1},
		{"print-highlight-style", "", 1}, {"version", "v", 0}, {"help", "h", 0},
	}
	byLong := map[string]optSpec{}
	byShort := map[string]optSpec{}
	for _, s := range specs {
		byLong[s.long] = s
		if s.short != "" {
			byShort[s.short] = s
		}
	}
	type parsedOpt struct {
		name string
		val  string
		has  bool
	}
	var popts []parsedOpt
	var files []string
	var errs []string
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		if a == "--" {
			files = append(files, args[i:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			val := ""
			has := false
			if eq := strings.Index(name, "="); eq >= 0 {
				val = name[eq+1:]
				name = name[:eq]
				has = true
			}
			spec, ok := byLong[name]
			if !ok {
				// unique prefix match (GetOpt allows abbreviations)
				var matches []optSpec
				for _, s := range specs {
					if strings.HasPrefix(s.long, name) {
						matches = append(matches, s)
					}
				}
				if len(matches) == 1 {
					spec = matches[0]
					ok = true
				} else if len(matches) > 1 {
					errs = append(errs, "option `--"+name+"' is ambiguous; could be one of:")
					continue
				}
			}
			if !ok {
				errs = append(errs, "Unknown option --"+name+".")
				continue
			}
			switch spec.arg {
			case 0:
				if has {
					errs = append(errs, "option `--"+spec.long+"' doesn't allow an argument")
					continue
				}
			case 1:
				if !has {
					if i >= len(args) {
						errs = append(errs, "option `--"+spec.long+"' requires an argument "+argDesc(spec.long))
						continue
					}
					val = args[i]
					has = true
					i++
				}
			}
			popts = append(popts, parsedOpt{spec.long, val, has})
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			// short options, possibly combined
			j := 1
			for j < len(a) {
				ch := string(a[j])
				j++
				spec, ok := byShort[ch]
				if !ok {
					errs = append(errs, "Unknown option -"+ch+".")
					continue
				}
				switch spec.arg {
				case 0:
					popts = append(popts, parsedOpt{spec.long, "", false})
				case 1:
					val := a[j:]
					if val == "" {
						if i >= len(args) {
							errs = append(errs, "option `-"+ch+"' requires an argument "+argDesc(spec.long))
							j = len(a)
							continue
						}
						val = args[i]
						i++
					}
					popts = append(popts, parsedOpt{spec.long, val, true})
					j = len(a)
				case 2:
					val := a[j:]
					if val != "" {
						popts = append(popts, parsedOpt{spec.long, val, true})
					} else {
						popts = append(popts, parsedOpt{spec.long, "", false})
					}
					j = len(a)
				}
			}
			continue
		}
		files = append(files, a)
	}
	if len(errs) > 0 {
		for _, e := range errs {
			fmt.Fprintln(os.Stderr, e)
		}
		fmt.Fprintf(os.Stderr, "Try %s --help for more information.\n", progName)
		return 6
	}
	// Process options in order
	for _, po := range popts {
		switch po.name {
		case "version":
			fmt.Printf("%s 3.9.0.2\nFeatures: +server +lua\nScripting engine: Lua 5.4\nUser data directory: %s\nCopyright (C) 2006-2025 John MacFarlane. Web:  https://pandoc.org\nThis is free software; see the source for copying conditions. There is no\nwarranty, not even for merchantability or fitness for a particular purpose.\n", progName, userDataDir())
			return 0
		case "help":
			fmt.Print(helpText())
			return 0
		case "list-input-formats":
			for _, f := range inputFormats {
				fmt.Println(f)
			}
			return 0
		case "list-output-formats":
			for _, f := range outputFormats {
				fmt.Println(f)
			}
			return 0
		case "list-extensions":
			f := po.val
			if f == "" {
				f = "markdown"
			}
			return listExtensions(f)
		case "list-highlight-languages":
			for _, l := range highlightLanguages {
				fmt.Println(l)
			}
			return 0
		case "list-highlight-styles":
			for _, l := range []string{"pygments", "tango", "espresso", "zenburn", "kate", "monochrome", "breezedark", "haddock"} {
				fmt.Println(l)
			}
			return 0
		case "print-default-template":
			return printDefaultTemplate(po.val)
		case "print-default-data-file":
			fmt.Fprintf(os.Stderr, "Could not find data file %s\n", po.val)
			return 97
		case "print-highlight-style":
			return printHighlightStyle(po.val)
		case "bash-completion":
			fmt.Print(bashCompletion())
			return 0
		case "from", "read":
			o.from = po.val
			o.fromSet = true
		case "to", "write":
			o.to = po.val
			o.toSet = true
		case "output":
			o.output = po.val
		case "standalone":
			b, ok := parseBoolOpt(po)
			if !ok {
				return optErr("standalone expects true or false")
			}
			o.standalone = b
		case "variable":
			k, v := splitKeyVal(po.val)
			o.variables[k] = append(o.variables[k], v)
		case "variable-json":
			k, v := splitKeyVal(po.val)
			o.variables[k] = append(o.variables[k], v)
		case "metadata":
			k, v := splitKeyVal(po.val)
			if v == "" && !strings.Contains(po.val, ":") && !strings.Contains(po.val, "=") {
				o.setMeta(k, &MetaBool{Value: true})
			} else {
				o.setMeta(k, yamlLikeMetaValue(v))
			}
		case "metadata-file":
			b, err := os.ReadFile(po.val)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: %s: withBinaryFile: does not exist (No such file or directory)\n", progName, po.val)
				return 1
			}
			st := &mdState{refs: map[string]refDef{}, notes: map[string][]Block{}, headerKeys: map[string]refDef{}, identifiers: map[string]bool{}, meta: newMetaMap(), exts: defaultExtensions("markdown"), tabStop: 4, columns: 72, abbrevs: defaultAbbrevs(), exampleLabels: map[string]int{}}
			p := newMdP("", st)
			raw := strings.TrimSpace(string(b))
			raw = strings.TrimPrefix(raw, "---")
			raw = strings.TrimSuffix(raw, "---")
			raw = strings.TrimSuffix(raw, "...")
			m, err := parseYAMLMeta(raw, p)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error parsing YAML metadata file: %v\n", err)
				return 64
			}
			for _, k := range m.Keys {
				if _, exists := o.metadata.Get(k); !exists {
					o.metadata.Set(k, m.Values[k])
				}
			}
		case "wrap":
			switch po.val {
			case "auto":
				o.wrap = WrapAuto
			case "none":
				o.wrap = WrapNone
			case "preserve":
				o.wrap = WrapPreserve
			default:
				return optErr("--wrap must be auto, none, or preserve")
			}
		case "columns":
			n, err := strconv.Atoi(po.val)
			if err != nil {
				return optErr("columns must be a number greater than 0")
			}
			o.columns = n
		case "tab-stop":
			n, err := strconv.Atoi(po.val)
			if err != nil {
				return optErr("tab-stop must be a number greater than 0")
			}
			o.tabStop = n
		case "preserve-tabs":
			b, _ := parseBoolOpt(po)
			o.preserveTabs = b
		case "toc", "table-of-contents":
			b, _ := parseBoolOpt(po)
			o.toc = b
		case "toc-depth":
			n, err := strconv.Atoi(po.val)
			if err != nil {
				return optErr("TOC level must be a number 1-6")
			}
			o.tocDepth = n
		case "number-sections":
			b, _ := parseBoolOpt(po)
			o.numberSections = b
		case "number-offset":
			for _, s := range strings.Split(po.val, ",") {
				n, err := strconv.Atoi(strings.TrimSpace(s))
				if err != nil {
					return optErr("number-offset must be a comma-separated list of numbers")
				}
				o.numberOffset = append(o.numberOffset, n)
			}
			o.numberSections = true
		case "section-divs":
			b, _ := parseBoolOpt(po)
			o.sectionDivs = b
		case "html-q-tags":
			b, _ := parseBoolOpt(po)
			o.htmlQTags = b
		case "ascii":
			b, _ := parseBoolOpt(po)
			o.ascii = b
		case "id-prefix":
			o.idPrefix = po.val
		case "title-prefix":
			o.titlePrefix = po.val
			o.variables["title-prefix"] = []string{po.val}
			o.standalone = true
		case "css":
			o.css = append(o.css, po.val)
			o.variables["css"] = append(o.variables["css"], po.val)
		case "email-obfuscation":
			switch po.val {
			case "none", "javascript", "references":
				o.emailObfuscation = po.val
			default:
				return optErr("--email-obfuscation must be none, javascript, or references")
			}
		case "no-highlight":
			o.highlight = false
		case "highlight-style":
			o.highlightStyle = po.val
			o.highlight = true
		case "syntax-highlighting":
			switch po.val {
			case "none":
				o.highlight = false
			case "default":
				o.highlight = true
				o.highlightStyle = "pygments"
			case "idiomatic":
				o.highlight = true
			default:
				o.highlight = true
				o.highlightStyle = po.val
			}
		case "syntax-definition":
		case "mathml":
			o.mathMethod = "mathml"
		case "mathjax":
			o.mathMethod = "mathjax"
			o.mathURL = po.val
		case "katex":
			o.mathMethod = "katex"
			o.mathURL = po.val
		case "webtex":
			o.mathMethod = "webtex"
			o.mathURL = po.val
		case "gladtex":
			o.mathMethod = "gladtex"
		case "shift-heading-level-by":
			n, err := strconv.Atoi(po.val)
