			}
			o.shiftHeading = n - 1
		case "strip-comments":
			b, _ := parseBoolOpt(po)
			o.stripComments = b
		case "reference-links":
			b, _ := parseBoolOpt(po)
			o.referenceLinks = b
		case "reference-location":
			switch po.val {
			case "block", "section", "document":
