		case "default-image-extension":
			o.defaultImageExt = po.val
		case "indented-code-classes":
			o.indentedCodeClasses = strings.Fields(strings.ReplaceAll(po.val, ",", " "))
		case "quiet":
			o.quiet = true
		case "verbose":
			o.verbose = true
		case "fail-if-warnings":
			b, _ := parseBoolOpt(po)
			o.failIfWarnings = b
		case "file-scope":
			b, _ := parseBoolOpt(po)
			o.fileScope = b
		case "dump-args":
			b, _ := parseBoolOpt(po)
			o.dumpArgs = b
		case "ignore-args":
			b, _ := parseBoolOpt(po)
			o.ignoreArgs = b
		case "trace":
		case "sandbox":
		case "epub-chapter-level":
			n, _ := strconv.Atoi(po.val)
			o.epubChapterLevel = n
		case "split-level":
			n, _ := strconv.Atoi(po.val)
			o.splitLevel = n
		case "dpi":
			n, _ := strconv.Atoi(po.val)
			o.dpi = n
		case "citeproc":
			o.citeproc = true
		case "log":
			o.logFile = po.val
		case "resource-path":
			o.resourcePath = strings.Split(po.val, ":")
		case "data-dir", "defaults", "extract-media", "pdf-engine", "pdf-engine-opt", "reference-doc", "self-contained", "embed-resources", "link-images", "request-header", "no-check-certificate", "abbreviations", "filter", "lua-filter", "track-changes", "epub-subdirectory", "epub-cover-image", "epub-title-page", "epub-metadata", "epub-embed-font", "chunk-template", "ipynb-output", "bibliography", "csl", "citation-abbreviations", "natbib", "biblatex", "lof", "list-of-figures", "lot", "list-of-tables":
			// accepted but ignored
		}
	}
	if o.dumpArgs {
		fmt.Println(orDash(o.output))
		for _, f := range files {
			fmt.Println(f)
		}
		return 0
	}
	if o.ignoreArgs {
		files = nil
	}
	o.files = files
	return convert(o)
}

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

func argDesc(long string) string {
	return ""
}

func parseBoolOpt(po struct {
	name string
	val  string
	has  bool
}) (bool, bool) {
	if !po.has {
		return true, true
	}
	switch strings.ToLower(po.val) {
	case "true", "yes", "on":
		return true, true
	case "false", "no", "off":
		return false, true
	}
	return false, false
}

func splitKeyVal(s string) (string, string) {
	if i := strings.IndexAny(s, ":="); i >= 0 {
		return s[:i], s[i+1:]
	}
	return s, ""
}

func (o *cliOpts) setMeta(k string, v MetaValue) {
	if old, ok := o.metadata.Get(k); ok {
		// multiple values -> list
		if l, ok := old.(*MetaList); ok {
			l.Items = append(l.Items, v)
			return
		}
		o.metadata.Set(k, &MetaList{Items: []MetaValue{old, v}})
		return
	}
	o.metadata.Set(k, v)
}

func yamlLikeMetaValue(v string) MetaValue {
	switch v {
	case "true", "True", "TRUE":
		return &MetaBool{Value: true}
	case "false", "False", "FALSE":
		return &MetaBool{Value: false}
	}
	return &MetaString{Text: v}
}

func userDataDir() string {
	home := os.Getenv("HOME")
	if xdg := os.Getenv("XDG_DATA_HOME"); xdg != "" {
		return filepath.Join(xdg, "pandoc")
	}
	return filepath.Join(home, ".local", "share", "pandoc")
}

