func listExtensions(format string) int {
	base, exts, err := parseFormatSpec(format)
	if err != "" {
		fmt.Fprintln(os.Stderr, err)
		return 6
	}
	if !isKnownFormat(base) {
		fmt.Fprintf(os.Stderr, "Unknown format %s\n", base)
		return 6
	}
	def := defaultExtensions(base)
	for k, v := range exts.m {
		def.Set(k, v)
	}
	var all []string
	switch {
	case strings.HasPrefix(base, "markdown") || base == "gfm" || base == "commonmark" || base == "commonmark_x":
		all = allMarkdownExts
	default:
		all = allMarkdownExts
	}
	sorted := append([]string{}, all...)
	sort.Strings(sorted)
	for _, e := range sorted {
		if def.Has(e) {
			fmt.Println("+" + e)
		} else {
			fmt.Println("-" + e)
		}
	}
	return 0
}

func isKnownFormat(f string) bool {
	for _, x := range inputFormats {
		if x == f {
			return true
		}
	}
	for _, x := range outputFormats {
		if x == f {
			return true
		}
	}
	return false
}

// parseFormatSpec parses "markdown+ext-ext".
func parseFormatSpec(spec string) (string, *ExtSet, string) {
	exts := &ExtSet{m: map[string]bool{}}
	i := strings.IndexAny(spec, "+-")
	if i < 0 {
		return spec, exts, ""
	}
	base := spec[:i]
	rest := spec[i:]
	for rest != "" {
		sign := rest[0]
		rest = rest[1:]
		j := strings.IndexAny(rest, "+-")
		var name string
		if j < 0 {
			name = rest
			rest = ""
		} else {
			name = rest[:j]
			rest = rest[j:]
		}
		if name == "" {
			return base, exts, "Unknown extension: "
		}
		exts.Set(name, sign == '+')
	}
	return base, exts, ""
}

func convert(o *cliOpts) int {
	// read input
	var input string
	if len(o.files) == 0 {
		b, _ := io.ReadAll(os.Stdin)
		input = string(b)
	} else {
		var parts []string
		for _, f := range o.files {
			var b []byte
			var err error
			if f == "-" {
				b, err = io.ReadAll(os.Stdin)
			} else {
				b, err = os.ReadFile(f)
			}
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: %s: withBinaryFile: does not exist (No such file or directory)\n", progName, f)
				return 1
			}
			parts = append(parts, string(b))
		}
		input = strings.Join(parts, "\n")
	}
	// determine formats
	from := o.from
	if !o.fromSet {
		from = ""
		if len(o.files) > 0 {
			fs := map[string]bool{}
			for _, f := range o.files {
				fmtName := formatFromExt(f)
				if fmtName != "" {
					fs[fmtName] = true
				}
			}
			if len(fs) == 1 {
				for k := range fs {
					from = k
				}
			}
		}
		if from == "" {
			from = "markdown"
		}
	}
	to := o.to
	if !o.toSet {
		to = ""
		if o.output != "" {
			to = formatFromExt(o.output)
			if to == "" {
				ext := filepath.Ext(o.output)
				if ext != "" && !o.quiet {
					fmt.Fprintf(os.Stderr, "[WARNING] Could not deduce format from file extension %s\n  Defaulting to html\n", ext)
				}
				to = "html"
			}
		} else {
			to = "html"
		}
	}
	if to == "pdf" {
		fmt.Fprintln(os.Stderr, "pdflatex not found. Please select a different --pdf-engine or install pdflatex")
		return 47
	}
	fromBase, fromExts, ferr := parseFormatSpec(from)
	if ferr != "" {
		fmt.Fprintln(os.Stderr, ferr)
		return 21
	}
	toBase, toExts, terr := parseFormatSpec(to)
	if terr != "" {
		fmt.Fprintln(os.Stderr, terr)
		return 22
	}
	if !isInputFormat(fromBase) {
		fmt.Fprintf(os.Stderr, "Unknown input format %s\n", fromBase)
		return 21
	}
	if !isOutputFormat(toBase) {
		fmt.Fprintf(os.Stderr, "Unknown output format %s\n", toBase)
		return 22
	}
	readerExts := defaultExtensions(fromBase)
	for k, v := range fromExts.m {
		if !containsStr(allMarkdownExts, k) && !isReaderExt(k) {
			fmt.Fprintf(os.Stderr, "The extension %s is not supported for %s\n", k, fromBase)
			return 21
		}
		readerExts.Set(k, v)
	}
	writerExts := defaultExtensions(toBase)
	for k, v := range toExts.m {
		writerExts.Set(k, v)
	}
	var warnings []string
	var doc *Pandoc
	ropts := &ReaderOptions{TabStop: o.tabStop, Columns: o.columns, PreserveTabs: o.preserveTabs, IndentedCodeClasses: o.indentedCodeClasses, DefaultImageExtension: o.defaultImageExt, StripComments: o.stripComments}
	switch {
	case fromBase == "json":
		d, err := readJSON(input)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error in $: %v\n", err)
			return 64
		}
		doc = d
	case fromBase == "native":
		d, err := readNative(input)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%v\n", err)
			return 64
		}
		doc = d
	case strings.HasPrefix(fromBase, "markdown") || fromBase == "gfm" || fromBase == "commonmark" || fromBase == "commonmark_x":
		if o.stripComments {
			readerExts.Set("__strip_comments", true)
		}
		d, ws := readMarkdown(input, readerExts, ropts)
		doc = d
		warnings = append(warnings, ws...)
	case fromBase == "html":
		d, ws := readHTML(input, readerExts, ropts)
		doc = d
		warnings = append(warnings, ws...)
	default:
		d, ws := readMarkdown(input, defaultExtensions("markdown"), ropts)
		doc = d
		warnings = append(warnings, ws...)
	}
	// metadata from command line (overrides document metadata)
	for _, k := range o.metadata.Keys {
		doc.Meta.Set(k, o.metadata.Values[k])
	}
	// transforms
	if o.shiftHeading != 0 {
		doc = headerShift(o.shiftHeading, doc)
	}
	if o.stripComments {
		doc = stripHTMLComments(doc)
	}
	// writer options
	wo := defaultWriterOptions()
	wo.Standalone = o.standalone
	wo.Columns = o.columns
	wo.WrapText = o.wrap
	wo.TabStop = o.tabStop
	wo.TOC = o.toc
	wo.TOCDepth = o.tocDepth
	wo.NumberSections = o.numberSections
	wo.NumberOffset = o.numberOffset
	wo.SectionDivs = o.sectionDivs
	wo.HTMLQTags = o.htmlQTags
	wo.Ascii = o.ascii
	wo.IdentifierPrefix = o.idPrefix
	wo.EmailObfuscation = o.emailObfuscation
	wo.Highlight = o.highlight
	wo.HighlightStyle = o.highlightStyle
	wo.HTMLMathMethod = o.mathMethod
	wo.MathURL = o.mathURL
	wo.Variables = o.variables
	wo.Template = o.template
	wo.ReferenceLinks = o.referenceLinks
	wo.ReferenceLocation = o.referenceLocation
	wo.Extensions = writerExts
	wo.Listings = o.listings
	wo.Incremental = o.incremental
	wo.SlideLevel = o.slideLevel
	wo.TopLevelDivision = o.topLevelDivision
	wo.SetextHeaders = o.markdownHeadings == "setext"
	wo.FigureCaptionPosition = o.figCaptionPos
	wo.TableCaptionPosition = o.tableCaptionPos
	wo.ListTables = o.listTables
	wo.Format = toBase
	wo.EpubChapterLevel = o.epubChapterLevel
	wo.SplitLevel = o.splitLevel
	// title fallback for standalone HTML
	var out string
	var wws []string
	switch toBase {
	case "html", "html5", "html4", "slidy", "slideous", "dzslides", "revealjs", "s5":
		html5 := toBase != "html4" && toBase != "slidy" && toBase != "slideous" && toBase != "s5"
		if o.standalone {
			if _, ok := doc.Meta.Get("title"); !ok {
				if _, ok := o.variables["pagetitle"]; !ok {
					// default pagetitle from input file name
					if len(o.files) > 0 && o.files[0] != "-" {
						base := filepath.Base(o.files[0])
						base = strings.TrimSuffix(base, filepath.Ext(base))
						wo.Variables["pagetitle"] = []string{base}
					} else {
						wo.Variables["pagetitle"] = []string{"-"}
					}
					if !o.quiet && !(len(o.files) > 0 && o.files[0] != "-") {
						// pandoc warns only when no title and not from file? It uses the filename; for stdin "-".
					}
				}
			}
		}
		if toBase == "html4" && o.template == "" {
			wo.Template = defaultHTML4Template
		}
		out, wws = writeHTML(doc, wo, html5)
	case "native":
		out = writeNative(doc, wo)
	case "json":
		out = writeJSON(doc)
	case "markdown", "markdown_strict", "markdown_phpextra", "markdown_mmd", "markdown_github", "gfm", "commonmark", "commonmark_x", "plain":
		out, wws = writeMarkdown(doc, wo)
	case "latex", "beamer":
		out, wws = writeLaTeX(doc, wo)
	case "rst":
		out, wws = writeRST(doc, wo)
	default:
		out, wws = writeMarkdown(doc, wo)
	}
	warnings = append(warnings, wws...)
	if !o.quiet {
		for _, w := range warnings {
			fmt.Fprintln(os.Stderr, w)
		}
	}
	if o.failIfWarnings && len(warnings) > 0 {
		fmt.Fprintln(os.Stderr, "Failing because there were warnings.")
		return 3
	}
	if o.eol == "crlf" {
		out = strings.ReplaceAll(out, "\n", "\r\n")
	}
	if o.output == "" || o.output == "-" {
		os.Stdout.WriteString(out)
	} else {
		if err := os.WriteFile(o.output, []byte(out), 0644); err != nil {
			fmt.Fprintf(os.Stderr, "%s: %s: withBinaryFile: %v\n", progName, o.output, err)
			return 1
		}
	}
	return 0
}

func isReaderExt(k string) bool {
	switch k {
	case "smart", "raw_html", "raw_tex", "native_divs", "native_spans", "empty_paragraphs", "sourcepos", "epub_html_exts", "line_blocks", "task_lists", "literate_haskell", "tex_math_dollars", "tex_math_single_backslash", "tex_math_double_backslash", "raw_attribute", "fenced_code_attributes", "auto_identifiers", "gfm_auto_identifiers", "ascii_identifiers", "element_citations", "styles", "citations", "ntb", "tagging", "latex_macros", "amuse", "east_asian_line_breaks", "wikilinks_title_after_pipe", "wikilinks_title_before_pipe", "footnotes", "pipe_tables", "autolink_bare_uris", "hard_line_breaks", "strikeout", "emoji", "attributes", "bracketed_spans", "fenced_divs", "definition_lists", "implicit_figures", "implicit_header_references", "yaml_metadata_block", "rebase_relative_paths", "alerts", "subscript", "superscript", "smart_quotes", "fancy_lists", "short_subsuperscripts", "wrap_math", "mark":
		return true
	}
	return false
}

func isInputFormat(f string) bool {
	for _, x := range inputFormats {
		if x == f {
			return true
		}
	}
	return false
}

func isOutputFormat(f string) bool {
	for _, x := range outputFormats {
		if x == f {
			return true
		}
	}
	return false
}

