package main

import (
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

type mdVariant int

const (
	varMarkdown mdVariant = iota
	varCommonmark
	varPlain
)

type mdWriter struct {
	opts     *WriterOptions
	variant  mdVariant
	exts     *ExtSet
	notes    [][]Block
	noteNum  int
	refs     []mdRef
	ids      map[string]bool
	inList   bool
	warnings []string
	refShortcutable bool
	prevRefs []mdRef
	keys     map[string]bool
}

type mdRef struct {
	label string
	url   string
	title string
	attr  Attr
}

func (w *mdWriter) ext(name string) bool { return w.exts.Has(name) }

func writeMarkdown(doc *Pandoc, opts *WriterOptions) (string, []string) {
	w := &mdWriter{opts: opts, exts: opts.Extensions, ids: map[string]bool{}, refShortcutable: true, keys: map[string]bool{}}
	switch opts.Format {
	case "plain":
		w.variant = varPlain
		w.exts = newExtSet()
	case "commonmark", "gfm", "commonmark_x":
		w.variant = varCommonmark
	}
	if w.variant != varPlain && w.exts == nil {
		w.exts = defaultExtensions("markdown")
	}
	if opts.Format == "plain" {
		// plain: extensions relevant to writer are off, but keep a few
	}
	body := w.blockListToMarkdown(doc.Blocks)
	notesAndRefs := w.notesAndRefs()
	main := Cat(body, notesAndRefs)
	colwidth := 0
	if opts.WrapText == WrapAuto {
		colwidth = opts.Columns
	}
	if !opts.Standalone {
		return Render(colwidth, main), w.warnings
	}
	// standalone
	meta := doc.Meta
	ctx := metaToContext(meta, func(bs []Block) string { return Render(colwidth, Chomp(w.blockListToMarkdown(bs))) }, func(ils []Inline) string { return Render(colwidth, w.inlineListToMarkdown(ils)) })
	vars := ctx
	for k, vs := range opts.Variables {
		if len(vs) == 1 {
			vars[k] = vs[0]
		} else {
			var items []tmplValue
			for _, v := range vs {
				items = append(items, v)
			}
			vars[k] = items
		}
	}
	vars["body"] = Render(colwidth, main)
	if meta.Len() > 0 {
		var tb string
		switch {
		case w.variant == varPlain:
			tb = w.plainTitleBlock(meta, colwidth)
		case w.ext("yaml_metadata_block"):
			tb = w.yamlMetadataBlock(ctx, colwidth)
		case w.ext("pandoc_title_block"):
			tb = w.pandocTitleBlock(meta, colwidth)
		}
		if tb != "" {
			vars["titleblock"] = tb
		}
	}
	if opts.TOC {
		vars["toc"] = Render(colwidth, w.blockToMarkdown(tocToBlocks(doc.Blocks, opts.TOCDepth)))
		vars["table-of-contents"] = vars["toc"]
	}
	tmpl := opts.Template
	if tmpl == "" {
		tmpl = defaultMarkdownTemplate
	}
	return renderTemplate(tmpl, vars), w.warnings
}

func (w *mdWriter) plainTitleBlock(meta *MetaMap, colwidth int) string {
	var parts []*Doc
	if t, ok := meta.Get("title"); ok {
		parts = append(parts, w.inlineListToMarkdown(metaInlinesOf(t)))
	}
	if a, ok := meta.Get("author"); ok {
		var auths []*Doc
		if l, ok := a.(*MetaList); ok {
			for _, it := range l.Items {
				auths = append(auths, Nowrap(w.inlineListToMarkdown(metaInlinesOf(it))))
			}
		} else {
			auths = append(auths, Nowrap(w.inlineListToMarkdown(metaInlinesOf(a))))
		}
		parts = append(parts, Hsep(auths))
	}
	if d, ok := meta.Get("date"); ok {
		parts = append(parts, w.inlineListToMarkdown(metaInlinesOf(d)))
	}
	var docs []*Doc
	for _, p := range parts {
		docs = append(docs, p, CR)
	}
	return strings.TrimRight(Render(colwidth, Cat(docs...)), "\n")
}

func (w *mdWriter) pandocTitleBlock(meta *MetaMap, colwidth int) string {
	var docs []*Doc
	t, hasT := meta.Get("title")
	a, hasA := meta.Get("author")
	d, hasD := meta.Get("date")
	if !hasT && !hasA && !hasD {
		return ""
	}
	title := Empty
	if hasT {
		title = w.inlineListToMarkdown(metaInlinesOf(t))
	}
	docs = append(docs, Cat(TextD("% "), Nest(2, title)), CR)
	if hasA || hasD {
		var auths []*Doc
		if hasA {
			if l, ok := a.(*MetaList); ok {
				for _, it := range l.Items {
					auths = append(auths, w.inlineListToMarkdown(metaInlinesOf(it)))
				}
			} else {
				auths = append(auths, w.inlineListToMarkdown(metaInlinesOf(a)))
			}
		}
		var authDocs []*Doc
		for i, au := range auths {
			if i > 0 {
				authDocs = append(authDocs, TextD(";"), CR)
			}
			authDocs = append(authDocs, au)
		}
		docs = append(docs, Cat(TextD("% "), Nest(2, Cat(authDocs...))), CR)
	}
	if hasD {
		docs = append(docs, Cat(TextD("% "), w.inlineListToMarkdown(metaInlinesOf(d))), CR)
	}
	return strings.TrimRight(Render(colwidth, Cat(docs...)), "\n")
}

func (w *mdWriter) yamlMetadataBlock(ctx map[string]tmplValue, colwidth int) string {
	keys := make([]string, 0, len(ctx))
	for k := range ctx {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var sb strings.Builder
	sb.WriteString("---\n")
	for _, k := range keys {
		sb.WriteString(yamlKeyVal(k, ctx[k], 0))
	}
	sb.WriteString("---")
	return sb.String()
}

func yamlKeyVal(k string, v tmplValue, indent int) string {
	ind := strings.Repeat(" ", indent)
	switch x := v.(type) {
	case []tmplValue:
		if len(x) == 0 {
			return ""
		}
		var sb strings.Builder
		sb.WriteString(ind + k + ":\n")
		for _, it := range x {
			sb.WriteString(yamlListItem(it, indent))
		}
		return sb.String()
	case *tmplMap:
		if len(x.keys) == 0 {
			return ind + k + ": {}\n"
		}
		var sb strings.Builder
		sb.WriteString(ind + k + ":\n")
		for _, kk := range x.keys {
			sb.WriteString(yamlKeyVal(kk, x.vals[kk], indent+2))
		}
		return sb.String()
	case string:
		if x == "" {
			return ""
		}
		return ind + k + ": " + yamlScalar(x, indent+2) + "\n"
	case bool:
		if x {
			return ind + k + ": true\n"
		}
		return ind + k + ": false\n"
	}
	return ""
}

func yamlListItem(v tmplValue, indent int) string {
	ind := strings.Repeat(" ", indent)
	switch x := v.(type) {
	case string:
		return ind + "- " + yamlScalar(x, indent+2) + "\n"
	case bool:
		if x {
			return ind + "- true\n"
		}
		return ind + "- false\n"
	case []tmplValue:
		var sb strings.Builder
		for i, it := range x {
			if i == 0 {
				sb.WriteString(ind + "- " + strings.TrimLeft(yamlListItem(it, indent+2), " "))
			} else {
				sb.WriteString(yamlListItem(it, indent+2))
			}
		}
		return sb.String()
	case *tmplMap:
		var sb strings.Builder
		for i, kk := range x.keys {
			s := yamlKeyVal(kk, x.vals[kk], indent+2)
			if i == 0 {
				s = ind + "- " + strings.TrimLeft(s, " ")
			}
			sb.WriteString(s)
		}
		return sb.String()
	}
	return ""
}

func yamlScalar(s string, indent int) string {
	if strings.Contains(s, "\n") {
		lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
		var sb strings.Builder
		sb.WriteString("|")
		for _, l := range lines {
			sb.WriteString("\n")
			if l != "" {
				sb.WriteString(strings.Repeat(" ", indent) + l)
			}
		}
		return sb.String()
	}
	needsQuote := strings.ContainsAny(s, "#:")
	if !needsQuote && s != "" {
		first := []rune(s)[0]
		if strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", first) {
			needsQuote = true
		}
	}
	if !needsQuote {
		switch strings.ToLower(s) {
		case "true", "false", "yes", "no", "on", "off", "null", "~":
			needsQuote = true
		}
		if _, ok := yamlNumber(s); ok && (yamlIntRe.MatchString(s) || yamlFloatRe.MatchString(s)) {
			needsQuote = true
		}
	}
	if needsQuote {
		return "'" + strings.ReplaceAll(s, "'", "''") + "'"
	}
	return s
}

// ---- blocks ----

func isListBlock(b Block) bool {
	switch b.(type) {
	case *BulletList, *OrderedList, *DefinitionList:
		return true
	}
	return false
}

func (w *mdWriter) blockListToMarkdown(blocks []Block) *Doc {
	// fixBlocks
	var fixed []Block
	commentSep := func() Block {
		if w.variant == varPlain {
			return nil
		}
		if w.ext("raw_html") {
			return &RawBlock{Format: "html", Text: "<!-- -->\n"}
		}
		return &RawBlock{Format: "markdown", Text: "&nbsp;\n"}
	}
	for i := 0; i < len(blocks); i++ {
		b := blocks[i]
		var next Block
		if i+1 < len(blocks) {
			next = blocks[i+1]
		}
		if cb, ok := next.(*CodeBlock); ok && isListBlock(b) && (!w.ext("fenced_code_blocks") || cb.Attr.IsNull()) {
			fixed = append(fixed, b)
			if cs := commentSep(); cs != nil {
				fixed = append(fixed, cs)
			}
			continue
		}
		if next != nil {
			sameList := false
			switch b.(type) {
			case *BulletList:
				_, sameList = next.(*BulletList)
			case *OrderedList:
				_, sameList = next.(*OrderedList)
			case *DefinitionList:
				_, sameList = next.(*DefinitionList)
			}
			if sameList {
				fixed = append(fixed, b)
				if cs := commentSep(); cs != nil {
					fixed = append(fixed, cs)
				}
				continue
			}
		}
		if pl, ok := b.(*Plain); ok {
			if _, isRaw := next.(*RawBlock); isRaw {
				fixed = append(fixed, b)
				continue
			}
			if next != nil && isListBlock(next) {
				fixed = append(fixed, b)
				continue
			}
			if w.inList {
				fixed = append(fixed, b)
				continue
			}
			fixed = append(fixed, &Para{Inlines: pl.Inlines})
			continue
		}
		fixed = append(fixed, b)
	}
	var docs []*Doc
	for _, b := range fixed {
		docs = append(docs, w.blockToMarkdown(b))
	}
	return Cat(docs...)
}

func (w *mdWriter) blockToMarkdown(b Block) *Doc {
	switch x := b.(type) {
	case *Plain:
		return w.plainToMarkdown(x.Inlines)
	case *Para:
		return Cat(w.plainToMarkdown(x.Inlines), Blankline)
	case *LineBlock:
		if w.ext("line_blocks") {
			var lines []*Doc
			for _, l := range x.Lines {
				lines = append(lines, Hang(2, TextD("| "), w.inlineListToMarkdown(l)))
			}
			return Cat(Vcat(lines), Blankline)
		}
		return w.blockToMarkdown(linesToPara(x.Lines))
	case *RawBlock:
		return w.rawBlockToMarkdown(x)
	case *HorizontalRule:
		return Cat(Blankline, TextD(strings.Repeat("-", w.opts.Columns)), Blankline)
	case *Header:
		return w.headerToMarkdown(x)
	case *CodeBlock:
		return w.codeBlockToMarkdown(x)
	case *BlockQuote:
		leader := "> "
		if w.variant == varPlain {
			leader = "  "
		}
		contents := w.blockListToMarkdown(x.Blocks)
		return Cat(Prefixed(leader, contents), Blankline)
	case *Table:
		return w.tableToMarkdown(x)
	case *BulletList:
		old := w.inList
		w.inList = true
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, w.bulletListItem(it))
		}
		w.inList = old
		if isTightList(x.Items) {
			return Cat(Vcat(items), Blankline)
		}
		return Cat(Vsep(items), Blankline)
	case *OrderedList:
		start := 1
		if w.variant == varCommonmark || w.ext("startnum") {
			start = x.Attrs.Start
		}
		sty := DefaultStyle
		delim := DefaultDelim
		if w.ext("fancy_lists") {
			sty = x.Attrs.Style
			delim = x.Attrs.Delim
		} else if w.variant == varCommonmark {
			if x.Attrs.Delim == OneParen || x.Attrs.Delim == TwoParens {
				delim = OneParen
			}
		}
		markers := orderedListMarkers(start, sty, delim, len(x.Items))
		for i, m := range markers {
			if len(m) < 3 {
				markers[i] = m + strings.Repeat(" ", 3-len(m))
			}
		}
		old := w.inList
		w.inList = true
		var items []*Doc
		for i, it := range x.Items {
			items = append(items, w.orderedListItem(markers[i], it))
		}
		w.inList = old
		if isTightList(x.Items) {
			return Cat(Vcat(items), Blankline)
		}
		return Cat(Vsep(items), Blankline)
	case *DefinitionList:
		old := w.inList
		w.inList = true
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, w.definitionListItem(it))
		}
		w.inList = old
		return Cat(Cat(items...), Blankline)
	case *Div:
		return w.divToMarkdown(x)
	case *Figure:
		return w.figureToMarkdown(x)
	}
	return Empty
}

func linesToPara(lines [][]Inline) Block {
	var ils []Inline
	for i, l := range lines {
		if i > 0 {
			ils = append(ils, &LineBreak{})
		}
		ils = append(ils, l...)
	}
	return &Para{Inlines: ils}
}

var orderedMarkerRe = regexp.MustCompile(`^([0-9]+|[a-zA-Z]|#|@)[.)]$`)
var orderedMarkerRe2 = regexp.MustCompile(`^\(([0-9]+|[a-zA-Z]|#|@)\)$`)

func beginsWithOrderedListMarker(s string) bool {
	rs := []rune(s)
	if len(rs) > 10 {
		rs = rs[:10]
	}
	t := string(rs)
	// find delimiter
	for i := 1; i <= len(t); i++ {
		pre := t[:i]
		if orderedMarkerRe.MatchString(pre) || orderedMarkerRe2.MatchString(pre) {
			return true
		}
	}
	return false
}

func (w *mdWriter) plainToMarkdown(ils []Inline) *Doc {
	inlines := ils
	if w.variant != varPlain && len(ils) > 0 {
		if s, ok := ils[0].(*Str); ok {
			startsWithSpace := false
			if len(ils) > 1 {
				switch ils[1].(type) {
				case *Space, *SoftBreak:
					startsWithSpace = true
				}
			}
			if !startsWithSpace && beginsWithOrderedListMarker(s.Text) {
				esc := strings.NewReplacer(".", "\\.", "(", "\\(", ")", "\\)").Replace(s.Text)
				inlines = append([]Inline{&RawInline{Format: "markdown", Text: esc}}, ils[1:]...)
			} else if s.Text == "+" || s.Text == "-" || (s.Text == "*" && w.ext("all_symbols_escapable")) {
				inlines = append([]Inline{&RawInline{Format: "markdown", Text: "\\"}}, ils...)
			}
		}
	}
	return Cat(w.inlineListToMarkdown(inlines), CR)
}

func (w *mdWriter) rawBlockToMarkdown(x *RawBlock) *Doc {
	f := x.Format
	ok := false
	switch w.variant {
	case varPlain:
		ok = f == "plain"
	case varCommonmark:
		ok = f == "markdown" || f == "commonmark" || f == "gfm" || (w.ext("raw_html") && (f == "html" || f == "html5" || f == "html4"))
	default:
		ok = f == "markdown" || (w.ext("raw_html") && (f == "html" || f == "html5" || f == "html4")) || (w.ext("raw_tex") && (f == "latex" || f == "tex"))
	}
	if !ok {
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+f+"\") "+haskellShowString(x.Text))
		return Empty
	}
	if f == "markdown" && strings.TrimSpace(x.Text) == "" {
		return Empty
	}
	if strings.HasSuffix(x.Text, "\n") {
		return Cat(Literal(x.Text), Blankline)
	}
	return Cat(Literal(x.Text), Blankline)
}

func (w *mdWriter) headerToMarkdown(x *Header) *Doc {
	autoId := uniqueIdent(x.Inlines, w.ids, w.ext("gfm_auto_identifiers"), w.ext("ascii_identifiers"))
	w.ids[autoId] = true
	attrDoc := Empty
	switch {
	case x.Attr.IsNull():
	case x.Attr.ID != "" && len(x.Attr.Classes) == 0 && len(x.Attr.KVs) == 0 && w.ext("auto_identifiers") && x.Attr.ID == autoId:
	case w.ext("mmd_header_identifiers") && x.Attr.ID != "":
		attrDoc = Cat(BreakingSpace, TextD("["+x.Attr.ID+"]"))
	case w.ext("header_attributes"):
		attrDoc = Cat(BreakingSpace, w.attrsToMarkdown(x.Attr))
	}
	ils := walkInlines(x.Inlines, func(xs []Inline) []Inline {
		out := make([]Inline, 0, len(xs))
		for _, il := range xs {
			if _, ok := il.(*LineBreak); ok {
				out = append(out, &Space{})
			} else {
				out = append(out, il)
			}
		}
		return out
	})
	contents := w.inlineListToMarkdown(ils)
	plain := w.variant == varPlain
	setext := w.opts.SetextHeaders
	var hdr *Doc
	switch {
	case plain:
		hdr = Cat(contents, Blankline)
	case x.Level == 1 && setext:
		hdr = Cat(contents, attrDoc, CR, TextD(strings.Repeat("=", Offset(contents))), Blankline)
	case x.Level == 2 && setext:
		hdr = Cat(contents, attrDoc, CR, TextD(strings.Repeat("-", Offset(contents))), Blankline)
	default:
		hdr = Cat(TextD(strings.Repeat("#", x.Level)), BreakingSpace, contents, attrDoc, Blankline)
	}
	return Nowrap(hdr)
}

func (w *mdWriter) codeBlockToMarkdown(x *CodeBlock) *Doc {
	str := x.Text
	endlineLen := func(c byte) int {
		n := 3
		for _, ln := range strings.Split(str, "\n") {
			ln = strings.TrimSpace(ln)
			if len(ln) >= 3 && strings.Trim(ln, string(c)) == "" {
				if len(ln)+1 > n {
					n = len(ln) + 1
				}
			}
		}
		return n
	}
	var attrs *Doc
	if w.ext("fenced_code_attributes") {
		attrs = Nowrap(Cat(TextD(" "), w.classOrAttrsToMarkdown(x.Attr)))
	} else if len(x.Attr.Classes) > 0 {
		attrs = TextD(" " + x.Attr.Classes[0])
	} else {
		attrs = Empty
	}
	if !x.Attr.IsNull() {
		if w.variant == varCommonmark || w.ext("backtick_code_blocks") {
			bt := TextD(strings.Repeat("`", endlineLen('`')))
			return Cat(bt, attrs, CR, Literal(str), CR, bt, Blankline)
		}
		if w.ext("fenced_code_blocks") {
			td := TextD(strings.Repeat("~", endlineLen('~')))
			return Cat(td, attrs, CR, Literal(str), CR, td, Blankline)
		}
	}
	if w.variant == varCommonmark || (w.variant != varPlain && !w.ext("fenced_code_blocks") && !w.ext("backtick_code_blocks") && false) {
	}
	return Cat(Nest(w.opts.TabStop, Literal(str)), Blankline)
}

func (w *mdWriter) divToMarkdown(x *Div) *Doc {
	contents := w.blockListToMarkdown(x.Blocks)
	switch {
	case w.ext("fenced_divs") && !x.Attr.IsNull():
		var attrDoc *Doc
		if w.variant == varCommonmark {
			attrDoc = w.attrsToMarkdown(x.Attr)
		} else {
			attrDoc = w.classOrAttrsToMarkdown(x.Attr)
		}
		return Cat(Above(Above(Nowrap(SpaceCat(TextD(":::"), attrDoc)), Chomp(contents)), TextD(":::")), Blankline)
	case w.ext("native_divs") || (w.ext("raw_html") && (w.variant == varCommonmark || w.ext("markdown_in_html_blocks"))):
		return Cat(tagWithAttrs("div", x.Attr), Blankline, contents, Blankline, TextD("</div>"), Blankline)
	}
	return Cat(contents, Blankline)
}

func tagWithAttrs(tag string, attr Attr) *Doc {
	var sb strings.Builder
	sb.WriteString("<" + tag)
	if attr.ID != "" {
		sb.WriteString(" id=\"" + escapeHTMLText(attr.ID) + "\"")
	}
	if len(attr.Classes) > 0 {
		sb.WriteString(" class=\"" + escapeHTMLText(strings.Join(attr.Classes, " ")) + "\"")
	}
	for _, kv := range attr.KVs {
		sb.WriteString(" " + kv[0] + "=\"" + escapeHTMLText(kv[1]) + "\"")
	}
	sb.WriteString(">")
	return TextD(sb.String())
}

func (w *mdWriter) figureToMarkdown(x *Figure) *Doc {
	// simple figure: single image
	if len(x.Blocks) == 1 {
		if pl, ok := x.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
			if img, ok := pl.Inlines[0].(*Image); ok {
				capt := blocksInlines(x.Caption.Blocks)
				alt := img.Inlines
				if len(capt) > 0 {
					alt = capt
				}
				if len(alt) == 0 {
					alt = []Inline{&Str{Text: " "}}
				}
				if w.ext("implicit_figures") || w.variant == varCommonmark || w.variant == varPlain {
					img2 := &Image{Attr: img.Attr, Inlines: alt, Target: img.Target}
					return Cat(w.inlineListToMarkdown([]Inline{img2}), Blankline)
				}
			}
		}
	}
	// fenced div fallback
	contents := w.blockListToMarkdown(x.Blocks)
	var capt *Doc
	if len(x.Caption.Blocks) > 0 {
		capt = w.blockListToMarkdown(x.Caption.Blocks)
	}
	if w.ext("fenced_divs") {
		attr := x.Attr
		attr.Classes = append([]string{"figure"}, attr.Classes...)
		inner := contents
		if capt != nil {
			inner = Cat(contents, Blankline, Above(Nowrap(TextD("::: caption")), Cat(Chomp(capt), CR, TextD(":::"))))
		}
		return Cat(Above(Above(Nowrap(SpaceCat(TextD(":::"), w.classOrAttrsToMarkdown(attr))), Chomp(inner)), TextD(":::")), Blankline)
	}
	if capt != nil {
		return Cat(contents, Blankline, capt)
	}
	return contents
}

// ---- lists ----

func isTightList(items [][]Block) bool {
	for _, it := range items {
		if len(it) == 0 {
			continue
		}
		if _, ok := it[0].(*Plain); !ok {
			return false
		}
	}
	return true
}

func itemEndsWithTightList(bs []Block) bool {
	if len(bs) == 0 {
		return false
	}
	switch x := bs[len(bs)-1].(type) {
	case *BulletList:
		return isTightList(x.Items)
	case *OrderedList:
		return isTightList(x.Items)
	}
	return false
}

func (w *mdWriter) taskListItemToAscii(bs []Block) []Block {
	if !w.ext("task_lists") && w.variant != varPlain {
		return bs
	}
	conv := func(ils []Inline) []Inline {
		if len(ils) >= 2 {
			if s, ok := ils[0].(*Str); ok {
				if _, ok := ils[1].(*Space); ok {
					if s.Text == "\u2610" {
						return append([]Inline{&RawInline{Format: "markdown", Text: "[ ]"}, &Space{}}, ils[2:]...)
					}
					if s.Text == "\u2612" {
						return append([]Inline{&RawInline{Format: "markdown", Text: "[x]"}, &Space{}}, ils[2:]...)
					}
				}
			}
		}
		return ils
	}
	if len(bs) > 0 {
		switch b := bs[0].(type) {
		case *Plain:
			return append([]Block{&Plain{Inlines: conv(b.Inlines)}}, bs[1:]...)
		case *Para:
			return append([]Block{&Para{Inlines: conv(b.Inlines)}}, bs[1:]...)
		}
	}
	return bs
}

func (w *mdWriter) bulletListItem(bs []Block) *Doc {
	contents := w.blockListToMarkdown(w.taskListItemToAscii(bs))
	sps := strings.Repeat(" ", maxInt(0, w.opts.TabStop-2))
	start := TextD("- " + sps)
	if itemEndsWithTightList(bs) {
		contents = Cat(Chomp(contents), CR)
	}
	return Hang(w.opts.TabStop, start, contents)
}

func (w *mdWriter) orderedListItem(marker string, bs []Block) *Doc {
	contents := w.blockListToMarkdown(w.taskListItemToAscii(bs))
	n := w.opts.TabStop - len([]rune(marker))
	sps := " "
	if n > 0 {
		sps = strings.Repeat(" ", n)
	}
	ind := w.opts.TabStop
	if !w.ext("four_space_rule") {
		ind = maxInt(w.opts.TabStop, len([]rune(marker))+1)
	}
	start := TextD(marker + sps)
	if itemEndsWithTightList(bs) {
		contents = Cat(Chomp(contents), CR)
	}
	return Hang(ind, start, contents)
}

func (w *mdWriter) definitionListItem(it DefItem) *Doc {
	labelText := w.blockToMarkdown(&Plain{Inlines: it.Term})
	var defs [][]*Doc
	for _, d := range it.Defs {
		var ds []*Doc
		for _, b := range d {
			ds = append(ds, w.blockToMarkdown(b))
		}
		defs = append(defs, ds)
	}
	if w.ext("definition_lists") {
		tabStop := w.opts.TabStop
		leader := ":  "
		if w.variant == varPlain {
			leader = "   "
		}
		sps := " "
		if tabStop-3 > 0 {
			sps = strings.Repeat(" ", tabStop-3)
		}
		isTight := false
		if len(it.Defs) > 0 && len(it.Defs[0]) > 0 {
			if _, ok := it.Defs[0][0].(*Plain); ok {
				isTight = true
			}
		}
		var ddocs []*Doc
		for _, d := range defs {
			ddocs = append(ddocs, Hang(tabStop, TextD(leader+sps), Cat(Vcat(d), CR)))
		}
		var contents *Doc
		if isTight {
			contents = Vcat(ddocs)
		} else {
			contents = Vsep(ddocs)
		}
		sep := Empty
		if !isTight {
			sep = Blankline
		}
		return Cat(Above(Cat(Blankline, Nowrap(labelText)), Cat(sep, contents)), Blankline)
	}
	var ddocs []*Doc
	for _, d := range defs {
		ddocs = append(ddocs, Vsep(d))
	}
	return Cat(Nowrap(Cat(Chomp(labelText), TextD("  "), CR)), Vsep(ddocs), Blankline)
}

func orderedListMarkers(start int, sty ListNumberStyle, delim ListNumberDelim, n int) []string {
	markers := make([]string, n)
	for i := 0; i < n; i++ {
		num := start + i
		var s string
		switch sty {
		case DefaultStyle, Decimal:
			s = strconv.Itoa(num)
		case Example:
			s = "@"
		case LowerAlpha:
			s = string(rune('a' + (num-1)%26))
		case UpperAlpha:
			s = string(rune('A' + (num-1)%26))
		case LowerRoman:
			s = strings.ToLower(toRoman(num))
		case UpperRoman:
			s = toRoman(num)
		}
		if sty == DefaultStyle && false {
			s = "#"
		}
		switch delim {
		case DefaultDelim, Period:
			s = s + "."
		case OneParen:
			s = s + ")"
		case TwoParens:
			s = "(" + s + ")"
		}
		markers[i] = s
	}
	return markers
}

// ---- attributes ----

func (w *mdWriter) attrsToMarkdown(attr Attr) *Doc {
	var parts []string
	if attr.ID != "" {
		parts = append(parts, "#"+attr.ID)
	}
	for _, c := range attr.Classes {
		parts = append(parts, "."+c)
	}
	for _, kv := range attr.KVs {
		parts = append(parts, kv[0]+"=\""+escapeAttrVal(kv[1])+"\"")
	}
	return TextD("{" + strings.Join(parts, " ") + "}")
}

func escapeAttrVal(s string) string {
	return strings.ReplaceAll(strings.ReplaceAll(s, "\\", "\\\\"), "\"", "\\\"")
}

func (w *mdWriter) classOrAttrsToMarkdown(attr Attr) *Doc {
	if attr.ID == "" && len(attr.Classes) == 1 && len(attr.KVs) == 0 {
		return TextD(attr.Classes[0])
	}
	return w.attrsToMarkdown(attr)
}

func (w *mdWriter) linkAttributes(attr Attr) *Doc {
	if w.ext("link_attributes") && !attr.IsNull() {
		return w.attrsToMarkdown(attr)
	}
	return Empty
}

// ---- notes and refs ----

func (w *mdWriter) notesAndRefs() *Doc {
	var notesDoc *Doc = Empty
	if len(w.notes) > 0 {
		var ns []*Doc
		for i, n := range w.notes {
			ns = append(ns, w.noteToMarkdown(w.noteNum+i+1, n))
		}
		w.noteNum += len(w.notes)
		w.notes = nil
		notesDoc = Cat(Blankline, Vsep(ns))
	}
	var refsDoc *Doc = Empty
	if len(w.refs) > 0 {
		var rs []*Doc
		for _, r := range w.refs {
			rs = append(rs, w.refToMarkdown(r))
		}
		w.refs = nil
		refsDoc = Cat(Blankline, Vcat(rs))
	}
	return Cat(notesDoc, refsDoc)
}

func (w *mdWriter) refToMarkdown(r mdRef) *Doc {
	title := ""
	if r.title != "" {
		title = " \"" + r.title + "\""
	}
	return Cat(Nest(2, Cat(TextD("["+r.label+"]: "), TextD(r.url+title))), w.linkAttributes(r.attr))
}

func (w *mdWriter) noteToMarkdown(num int, blocks []Block) *Doc {
	contents := w.blockListToMarkdown(blocks)
	numS := w.opts.IdentifierPrefix + strconv.Itoa(num)
	var marker *Doc
	if w.ext("footnotes") {
		marker = TextD("[^" + numS + "]:")
	} else {
		marker = TextD("[" + numS + "]")
	}
	markerSize := 4 + len([]rune(numS))
	spacer := " "
	if n := w.opts.TabStop - markerSize; n > 0 {
		spacer = strings.Repeat(" ", n)
	}
	if w.ext("footnotes") {
		return Hang(w.opts.TabStop, Cat(marker, TextD(spacer)), contents)
	}
	return Cat(marker, TextD(spacer), contents)
}

// ---- inlines ----

func (w *mdWriter) inlineListToMarkdown(ils []Inline) *Doc {
	if w.inList {
		ils = avoidBadWrapsInList(ils)
	}
	var docs []*Doc
	for i, il := range ils {
		// handle shortcut reference link ambiguity
		if _, ok := il.(*Link); ok && w.opts.ReferenceLinks {
			unshortcutable := false
			rest := ils[i+1:]
			if len(rest) > 0 {
				switch n := rest[0].(type) {
				case *Link, *Cite:
					unshortcutable = true
				case *Str:
					if strings.HasPrefix(n.Text, "[") || strings.HasPrefix(n.Text, "(") || strings.HasPrefix(n.Text, ":") {
						unshortcutable = true
					}
				case *RawInline:
					if strings.HasPrefix(n.Text, "[") || strings.HasPrefix(n.Text, "(") || strings.HasPrefix(n.Text, ":") || strings.HasPrefix(n.Text, " [") {
						unshortcutable = true
					}
				case *Space, *SoftBreak, *LineBreak:
					if len(rest) > 1 {
						switch n2 := rest[1].(type) {
						case *Link, *Cite:
							unshortcutable = true
						case *Str:
							if strings.HasPrefix(n2.Text, "[") {
								unshortcutable = true
							}
						case *RawInline:
							if strings.HasPrefix(n2.Text, "[") {
								unshortcutable = true
							}
						}
					}
				}
			}
			old := w.refShortcutable
			w.refShortcutable = !unshortcutable
			docs = append(docs, w.inlineToMarkdown(il))
			w.refShortcutable = old
			continue
		}
		docs = append(docs, w.inlineToMarkdown(il))
	}
	return Cat(docs...)
}

func avoidBadWrapsInList(ils []Inline) []Inline {
	out := make([]Inline, 0, len(ils))
	for i := 0; i < len(ils); i++ {
		il := ils[i]
		if _, ok := il.(*Space); ok && i+1 < len(ils) {
			if s, ok := ils[i+1].(*Str); ok {
				t := s.Text
				isMarker := false
				if t == "-" || t == "*" || t == "+" {
					isMarker = true
				} else if len(t) >= 2 {
					j := 0
					for j < len(t) && t[j] >= '0' && t[j] <= '9' {
						j++
					}
					if j > 0 && j < len(t) && (t[j] == '.' || t[j] == ')') && j == len(t)-1 {
						isMarker = true
					}
				}
				if isMarker {
					out = append(out, &Str{Text: " "})
					continue
				}
			}
		}
		out = append(out, il)
	}
	return out
}

func (w *mdWriter) escapeText(s string) string {
	var sb strings.Builder
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		c := rs[i]
		var next rune
		if i+1 < len(rs) {
			next = rs[i+1]
		}
		switch c {
		case '<':
			if w.ext("all_symbols_escapable") {
				sb.WriteString("\\<")
			} else {
				sb.WriteString("&lt;")
			}
		case '>':
			if w.ext("all_symbols_escapable") {
				sb.WriteString("\\>")
			} else {
				sb.WriteString("&gt;")
			}
		case '@':
			if w.ext("citations") && (isAlphaNum(next) || next == '_' || next == '{') {
				sb.WriteString("\\@")
			} else {
				sb.WriteRune(c)
			}
		case '#':
			if (w.ext("space_in_atx_header") && (next == ' ' || next == '\t')) || !w.ext("space_in_atx_header") {
				sb.WriteString("\\#")
			} else {
				sb.WriteRune(c)
			}
		case '\\', '`', '*', '_', '[', ']':
			sb.WriteRune('\\')
			sb.WriteRune(c)
		case '|':
			if w.ext("pipe_tables") {
				sb.WriteString("\\|")
			} else {
				sb.WriteRune(c)
			}
		case '^':
			if w.ext("superscript") {
				sb.WriteString("\\^")
			} else {
				sb.WriteRune(c)
			}
		case '~':
			if w.ext("subscript") || w.ext("strikeout") {
				sb.WriteString("\\~")
			} else {
				sb.WriteRune(c)
			}
		case '$':
			if w.ext("tex_math_dollars") {
				sb.WriteString("\\$")
			} else {
				sb.WriteRune(c)
			}
		case '\'':
			if w.ext("smart") {
				sb.WriteString("\\'")
			} else {
				sb.WriteRune(c)
			}
		case '"':
			if w.ext("smart") {
				sb.WriteString("\\\"")
			} else {
				sb.WriteRune(c)
			}
		case '-':
			if w.ext("smart") && next == '-' {
				sb.WriteString("\\-")
			} else {
				sb.WriteRune(c)
			}
		case '.':
			if w.ext("smart") && next == '.' && i+2 < len(rs) && rs[i+2] == '.' {
				sb.WriteString("\\...")
				i += 2
			} else {
				sb.WriteRune(c)
			}
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func (w *mdWriter) unsmartify(s string) string {
	var sb strings.Builder
	for _, c := range s {
		switch c {
		case '\u2019':
			sb.WriteByte('\'')
		case '\u2026':
			sb.WriteString("...")
		case '\u2013':
			if w.ext("old_dashes") {
				sb.WriteString("-")
			} else {
				sb.WriteString("--")
			}
		case '\u2014':
			if w.ext("old_dashes") {
				sb.WriteString("--")
			} else {
				sb.WriteString("---")
			}
		case '\u201c', '\u201d':
			sb.WriteByte('"')
		case '\u2018':
			sb.WriteByte('\'')
		default:
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func (w *mdWriter) inlineToMarkdown(il Inline) *Doc {
	switch x := il.(type) {
	case *Str:
		s := x.Text
		if w.ext("smart") {
			s = w.unsmartify(s)
		}
		if w.variant != varPlain {
			s = w.escapeText(s)
		}
		if w.opts.Ascii {
			s = toHtml5Entities(s)
		}
		return Literal(s)
	case *Space:
		return BreakingSpace
	case *SoftBreak:
		switch w.opts.WrapText {
		case WrapPreserve:
			return CR
		}
		return BreakingSpace
	case *LineBreak:
		if w.variant == varPlain {
			return CR
		}
		if w.ext("hard_line_breaks") {
			return CR
		}
		if w.ext("escaped_line_breaks") {
			return Cat(TextD("\\"), CR)
		}
		return Cat(TextD("  "), CR)
	case *Emph:
		contents := w.inlineListToMarkdown(x.Inlines)
		if w.variant == varPlain {
			return Cat(TextD("_"), contents, TextD("_"))
		}
		return Cat(TextD("*"), contents, TextD("*"))
	case *Underline:
		contents := w.inlineListToMarkdown(x.Inlines)
		if w.variant == varPlain {
			return contents
		}
		if w.ext("bracketed_spans") {
			return Cat(TextD("["), contents, TextD("]{.underline}"))
		}
		if w.ext("native_spans") || w.ext("raw_html") {
			return Cat(TextD("<u>"), contents, TextD("</u>"))
		}
		return contents
	case *Strong:
		if w.variant == varPlain {
			return w.inlineListToMarkdown(capitalizeInlines(x.Inlines))
		}
		contents := w.inlineListToMarkdown(x.Inlines)
		return Cat(TextD("**"), contents, TextD("**"))
	case *Strikeout:
		contents := w.inlineListToMarkdown(x.Inlines)
		if w.ext("strikeout") {
			return Cat(TextD("~~"), contents, TextD("~~"))
		}
		if w.variant == varPlain {
			return contents
		}
		if w.ext("raw_html") {
			return Cat(TextD("<s>"), contents, TextD("</s>"))
		}
		return contents
	case *Superscript:
		if w.ext("superscript") {
			contents := w.inlineListToMarkdown(x.Inlines)
			return Cat(TextD("^"), Literal(strings.ReplaceAll(Render(0, contents), " ", "\\ ")), TextD("^"))
		}
		if w.variant == varPlain {
			s := stringify(x.Inlines)
			if sup, ok := toSuperscriptStr(s); ok {
				return TextD(sup)
			}
			return Cat(TextD("^("), w.inlineListToMarkdown(x.Inlines), TextD(")"))
		}
		contents := w.inlineListToMarkdown(x.Inlines)
		if w.ext("raw_html") {
			return Cat(TextD("<sup>"), contents, TextD("</sup>"))
		}
		s := stringify(x.Inlines)
		if sup, ok := toSuperscriptStr(s); ok {
			return TextD(sup)
		}
		return Cat(TextD("^("), contents, TextD(")"))
	case *Subscript:
		if w.ext("subscript") {
			contents := w.inlineListToMarkdown(x.Inlines)
			return Cat(TextD("~"), Literal(strings.ReplaceAll(Render(0, contents), " ", "\\ ")), TextD("~"))
		}
		if w.variant == varPlain {
			s := stringify(x.Inlines)
			if sub, ok := toSubscriptStr(s); ok {
				return TextD(sub)
			}
			return Cat(TextD("_("), w.inlineListToMarkdown(x.Inlines), TextD(")"))
		}
		contents := w.inlineListToMarkdown(x.Inlines)
		if w.ext("raw_html") {
			return Cat(TextD("<sub>"), contents, TextD("</sub>"))
		}
		s := stringify(x.Inlines)
		if sub, ok := toSubscriptStr(s); ok {
			return TextD(sub)
		}
		return Cat(TextD("_("), contents, TextD(")"))
	case *SmallCaps:
		if w.variant == varPlain {
			return w.inlineListToMarkdown(capitalizeInlines(x.Inlines))
		}
		contents := w.inlineListToMarkdown(x.Inlines)
		if w.ext("bracketed_spans") {
			return Cat(TextD("["), contents, TextD("]{.smallcaps}"))
		}
		if w.ext("raw_html") || w.ext("native_spans") {
			return Cat(TextD("<span class=\"smallcaps\">"), contents, TextD("</span>"))
		}
		return w.inlineListToMarkdown(capitalizeInlines(x.Inlines))
	case *Quoted:
		contents := w.inlineListToMarkdown(x.Inlines)
		if x.Type == SingleQuote {
			if w.ext("smart") {
				return Cat(TextD("'"), contents, TextD("'"))
			}
			return Cat(TextD("\u2018"), contents, TextD("\u2019"))
		}
		if w.ext("smart") {
			return Cat(TextD("\""), contents, TextD("\""))
		}
		return Cat(TextD("\u201c"), contents, TextD("\u201d"))
	case *Code:
		if w.variant == varPlain {
			return Literal(x.Text)
		}
		longest := 0
		run := 0
		for _, c := range x.Text {
			if c == '`' {
				run++
				if run > longest {
					longest = run
				}
			} else {
				run = 0
			}
		}
		marker := strings.Repeat("`", longest+1)
		spacer := ""
		if longest > 0 {
			spacer = " "
		}
		attrs := Empty
		if w.ext("inline_code_attributes") && !x.Attr.IsNull() {
			attrs = w.attrsToMarkdown(x.Attr)
		}
		return Cat(Literal(marker+spacer+x.Text+spacer+marker), attrs)
	case *Math:
		if w.variant == varPlain {
			ils, ok := texMathToInlines(x.Type, x.Text)
			if ok {
				return w.inlineListToMarkdown(ils)
			}
			if x.Type == InlineMath {
				return Literal("$" + x.Text + "$")
			}
			return Literal("$$" + x.Text + "$$")
		}
		if w.ext("tex_math_dollars") {
			if x.Type == InlineMath {
				return Literal("$" + x.Text + "$")
			}
			return Literal("$$" + x.Text + "$$")
		}
		if w.ext("tex_math_single_backslash") {
			if x.Type == InlineMath {
				return Literal("\\(" + x.Text + "\\)")
			}
			return Literal("\\[" + x.Text + "\\]")
		}
		if w.ext("tex_math_double_backslash") {
			if x.Type == InlineMath {
				return Literal("\\\\(" + x.Text + "\\\\)")
			}
			return Literal("\\\\[" + x.Text + "\\\\]")
		}
		ils, ok := texMathToInlines(x.Type, x.Text)
		if ok {
			return w.inlineListToMarkdown(ils)
		}
		if x.Type == InlineMath {
			return Literal("$" + x.Text + "$")
		}
		return Literal("$$" + x.Text + "$$")
	case *RawInline:
		f := x.Format
		ok := false
		switch w.variant {
		case varPlain:
			ok = f == "plain"
		case varCommonmark:
			ok = f == "markdown" || f == "commonmark" || f == "gfm" || (w.ext("raw_html") && (f == "html" || f == "html5" || f == "html4"))
		default:
			ok = f == "markdown" || (w.ext("raw_html") && (f == "html" || f == "html5" || f == "html4")) || (w.ext("raw_tex") && (f == "latex" || f == "tex"))
		}
		if !ok {
			w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+f+"\") "+haskellShowString(x.Text))
			return Empty
		}
		return Literal(x.Text)
	case *Link:
		return w.linkToMarkdown(x)
	case *Image:
		return w.imageToMarkdown(x)
	case *Note:
		w.notes = append(w.notes, x.Blocks)
		ref := strconv.Itoa(w.noteNum + len(w.notes))
		if w.ext("footnotes") {
			return TextD("[^" + ref + "]")
		}
		return TextD("[" + ref + "]")
	case *Span:
		contents := w.inlineListToMarkdown(x.Inlines)
		if w.variant == varPlain {
			return contents
		}
		if w.ext("bracketed_spans") {
			if x.Attr.IsNull() {
				return Cat(TextD("["), contents, TextD("]{}"))
			}
			return Cat(TextD("["), contents, TextD("]"), w.attrsToMarkdown(x.Attr))
		}
		if w.ext("raw_html") || w.ext("native_spans") {
			return Cat(tagWithAttrs("span", x.Attr), contents, TextD("</span>"))
		}
		return contents
	case *Cite:
		if w.variant == varPlain || !w.ext("citations") {
			return w.inlineListToMarkdown(x.Inlines)
		}
		return w.citeToMarkdown(x)
	}
	return Empty
}

func (w *mdWriter) citeToMarkdown(x *Cite) *Doc {
	if len(x.Citations) == 0 {
		return w.inlineListToMarkdown(x.Inlines)
	}
	first := x.Citations[0]
	if first.Mode == AuthorInText {
		sdoc := w.inlineListToMarkdown(first.Suffix)
		rest := x.Citations[1:]
		var restDoc *Doc = Empty
		if len(rest) > 0 {
			var parts []*Doc
			for i, c := range rest {
				parts = append(parts, w.citationToMarkdown(c))
				if i < len(rest)-1 {
					parts = append(parts, TextD(";"), BreakingSpace)
				}
			}
			restDoc = Cat(TextD(" ["), Cat(parts...), TextD("]"))
		} else if len(first.Suffix) > 0 {
			return Cat(TextD("@"+first.ID), TextD(" ["), sdoc, TextD("]"))
		}
		return Cat(TextD("@"+first.ID), restDoc)
	}
	var parts []*Doc
	for i, c := range x.Citations {
		parts = append(parts, w.citationToMarkdown(c))
		if i < len(x.Citations)-1 {
			parts = append(parts, TextD(";"), BreakingSpace)
		}
	}
	return Cat(TextD("["), Cat(parts...), TextD("]"))
}

func (w *mdWriter) citationToMarkdown(c Citation) *Doc {
	pdoc := w.inlineListToMarkdown(c.Prefix)
	sdoc := w.inlineListToMarkdown(c.Suffix)
	mode := ""
	if c.Mode == SuppressAuthor {
		mode = "-"
	}
	key := TextD(mode + "@" + c.ID)
	var out *Doc = key
	if len(c.Prefix) > 0 {
		out = Cat(pdoc, BreakingSpace, out)
	}
	if len(c.Suffix) > 0 {
		if len(c.Suffix) > 0 {
			if s, ok := c.Suffix[0].(*Str); ok && strings.HasPrefix(s.Text, ",") {
				out = Cat(out, sdoc)
			} else {
				out = Cat(out, BreakingSpace, sdoc)
			}
		}
	}
	return out
}

func isURI(s string) bool {
	i := strings.Index(s, ":")
	if i <= 0 {
		return false
	}
	scheme := s[:i]
	for j, r := range scheme {
		if j == 0 && !unicode.IsLetter(r) {
			return false
		}
		if !(isAlphaNum(r) || r == '+' || r == '-' || r == '.') {
			return false
		}
	}
	return uriSchemes[strings.ToLower(scheme)]
}

func (w *mdWriter) linkToMarkdown(x *Link) *Doc {
	src, tit := x.Target.URL, x.Target.Title
	linktext := w.inlineListToMarkdown(x.Inlines)
	linktitle := Empty
	if tit != "" {
		linktitle = Literal(" \"" + tit + "\"")
	}
	srcSuffix := strings.TrimPrefix(src, "mailto:")
	useAuto := false
	if isURI(src) && len(x.Inlines) == 1 {
		if s, ok := x.Inlines[0].(*Str); ok && escapeURI(s.Text) == srcSuffix {
			useAuto = true
		}
	}
	useRefLinks := w.opts.ReferenceLinks && !useAuto
	if w.variant == varPlain {
		if useAuto {
			return Literal(srcSuffix)
		}
		return linktext
	}
	if useAuto {
		return Cat(TextD("<"), Literal(srcSuffix), TextD(">"))
	}
	if useRefLinks {
		reftext := w.getReference(x.Attr, Render(0, linktext), src, tit)
		first := Cat(TextD("["), linktext, TextD("]"))
		var second *Doc
		if w.refShortcutable && w.ext("shortcut_reference_links") {
			if reftext == Render(0, linktext) {
				second = Empty
			} else {
				second = TextD("[" + reftext + "]")
			}
		} else {
			if reftext == Render(0, linktext) {
				second = TextD("[]")
			} else {
				second = TextD("[" + reftext + "]")
			}
		}
		return Cat(first, second)
	}
	if w.ext("raw_html") && !w.ext("link_attributes") && !x.Attr.IsNull() {
		hw := &htmlWriter{opts: w.opts, html5: true}
		return Literal(strings.TrimSpace(hw.inlineToHtml(x).String()))
	}
	return Cat(TextD("["), linktext, TextD("]("), Literal(src), linktitle, TextD(")"), w.linkAttributes(x.Attr))
}

func (w *mdWriter) getReference(attr Attr, label string, src, tit string) string {
	for _, r := range w.refs {
		if r.url == src && r.title == tit && r.label == label {
			return r.label
		}
	}
	for _, r := range w.prevRefs {
		if r.url == src && r.title == tit && r.label == label {
			return r.label
		}
	}
	lab := label
	if lab == "" || w.keys[lab] {
		i := 1
		for {
			cand := strconv.Itoa(i)
			if label != "" {
				cand = label + strconv.Itoa(i)
			}
			if !w.keys[cand] {
				lab = cand
				break
			}
			i++
		}
	}
	w.keys[lab] = true
	w.refs = append(w.refs, mdRef{label: lab, url: src, title: tit, attr: attr})
	return lab
}

func (w *mdWriter) imageToMarkdown(x *Image) *Doc {
	if w.ext("raw_html") && !w.ext("link_attributes") && !x.Attr.IsNull() {
		hw := &htmlWriter{opts: w.opts, html5: true}
		return Literal(strings.TrimSpace(hw.inlineToHtml(x).String()))
	}
	alt := x.Inlines
	if len(alt) == 0 || (len(alt) == 1 && stringify(alt) == x.Target.URL) {
		alt = []Inline{&Str{Text: ""}}
	}
	link := &Link{Attr: x.Attr, Inlines: alt, Target: x.Target}
	linkPart := w.linkToMarkdown(link)
	if w.variant == varPlain {
		return Cat(TextD("["), linkPart, TextD("]"))
	}
	return Cat(TextD("!"), linkPart)
}

func capitalizeInlines(ils []Inline) []Inline {
	return walkInlines(ils, func(xs []Inline) []Inline {
		out := make([]Inline, 0, len(xs))
		for _, il := range xs {
			if s, ok := il.(*Str); ok {
				out = append(out, &Str{Text: strings.ToUpper(s.Text)})
			} else {
				out = append(out, il)
			}
		}
		return out
	})
}

var superscriptMap = map[rune]rune{'0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹', '+': '⁺', '-': '⁻', '=': '⁼', '(': '⁽', ')': '⁾', 'n': 'ⁿ', 'i': 'ⁱ', ' ': ' '}
var subscriptMap = map[rune]rune{'0': '₀', '1': '₁', '2': '₂', '3': '₃', '4': '₄', '5': '₅', '6': '₆', '7': '₇', '8': '₈', '9': '₉', '+': '₊', '-': '₋', '=': '₌', '(': '₍', ')': '₎', ' ': ' '}

func toSuperscriptStr(s string) (string, bool) {
	var sb strings.Builder
	for _, r := range s {
		m, ok := superscriptMap[r]
		if !ok {
			return "", false
		}
		sb.WriteRune(m)
	}
	return sb.String(), true
}

func toSubscriptStr(s string) (string, bool) {
	var sb strings.Builder
	for _, r := range s {
		m, ok := subscriptMap[r]
		if !ok {
			return "", false
		}
		sb.WriteRune(m)
	}
	return sb.String(), true
}

func toHtml5Entities(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if r < 128 {
			sb.WriteRune(r)
		} else {
			sb.WriteString("&#" + strconv.Itoa(int(r)) + ";")
		}
	}
	return sb.String()
}

// ---- TOC ----

func tocToBlocks(bs []Block, depth int) Block {
	sects := makeSections(false, 0, bs)
	entries := tocEntries(sects, depth)
	return tocEntriesToList(entries)
}

func tocEntriesToList(entries []tocEntry) Block {
	var items [][]Block
	for _, e := range entries {
		var link Inline
		title := removeNotesAndLinks(e.title)
		if e.id == "" {
			link = &Span{Inlines: title}
			items = append(items, []Block{&Plain{Inlines: title}})
		} else {
			link = &Link{Inlines: title, Target: Target{URL: "#" + e.id}}
			item := []Block{&Plain{Inlines: []Inline{link}}}
			if len(e.children) > 0 {
				item = append(item, tocEntriesToList(e.children))
			}
			items = append(items, item)
		}
	}
	return &BulletList{Items: items}
}

// ---- tables ----

func onlySimpleTableCells(rows [][][]Block) bool {
	for _, r := range rows {
		for _, c := range r {
			if len(c) == 0 {
				continue
			}
			if len(c) != 1 {
				return false
			}
			switch b := c[0].(type) {
			case *Plain:
				if hasLineBreakInl(b.Inlines) {
					return false
				}
			case *Para:
				if hasLineBreakInl(b.Inlines) {
					return false
				}
			default:
				return false
			}
		}
	}
	return true
}

func hasLineBreakInl(ils []Inline) bool {
	found := false
	queryInlines(ils, func(il Inline) {
		if _, ok := il.(*LineBreak); ok {
			found = true
		}
	})
	return found
}

type legacyTable struct {
	caption []Inline
	aligns  []Alignment
	widths  []float64
	headers [][]Block
	rows    [][][]Block
}

func toLegacyTable(t *Table) legacyTable {
	lt := legacyTable{}
	lt.caption = blocksInlines(t.Caption.Blocks)
	for _, s := range t.ColSpecs {
		lt.aligns = append(lt.aligns, s.Align)
		if s.Width.Default {
			lt.widths = append(lt.widths, 0)
		} else {
			lt.widths = append(lt.widths, s.Width.Width)
		}
	}
	ncols := len(t.ColSpecs)
	cellsOf := func(r Row) [][]Block {
		var cells [][]Block
		for _, c := range r.Cells {
			cells = append(cells, c.Blocks)
			for i := 1; i < c.ColSpan; i++ {
				cells = append(cells, nil)
			}
		}
		for len(cells) < ncols {
			cells = append(cells, nil)
		}
		if len(cells) > ncols {
			cells = cells[:ncols]
		}
		return cells
	}
	if len(t.Head.Rows) > 0 {
		lt.headers = cellsOf(t.Head.Rows[0])
		for _, r := range t.Head.Rows[1:] {
			lt.rows = append(lt.rows, cellsOf(r))
		}
	} else {
		lt.headers = make([][]Block, ncols)
	}
	for _, b := range t.Bodies {
		for _, r := range b.Head {
			lt.rows = append(lt.rows, cellsOf(r))
		}
		for _, r := range b.Body {
			lt.rows = append(lt.rows, cellsOf(r))
		}
	}
	for _, r := range t.Foot.Rows {
		lt.rows = append(lt.rows, cellsOf(r))
	}
	return lt
}

func (w *mdWriter) tableToMarkdown(t *Table) *Doc {
	lt := toLegacyTable(t)
	numcols := len(lt.aligns)
	for _, r := range lt.rows {
		if len(r) > numcols {
			numcols = len(r)
		}
	}
	if len(lt.headers) > numcols {
		numcols = len(lt.headers)
	}
	caption := w.inlineListToMarkdown(lt.caption)
	var captionDoc *Doc
	switch {
	case len(lt.caption) == 0:
		captionDoc = Blankline
	case w.ext("table_captions"):
		captionDoc = Above(Above(Blankline, Cat(TextD(": "), caption)), Blankline)
	default:
		captionDoc = Above(Above(Blankline, caption), Blankline)
	}
	allRows := append([][][]Block{lt.headers}, lt.rows...)
	hasSimpleCells := onlySimpleTableCells(allRows)
	allZero := true
	for _, wd := range lt.widths {
		if wd != 0 {
			allZero = false
		}
	}
	isSimple := hasSimpleCells && allZero
	hasBlocks := false
	for _, r := range allRows {
		for _, c := range r {
			for _, b := range c {
				if _, ok := b.(*Plain); !ok {
					hasBlocks = true
				}
			}
		}
	}
	headless := true
	for _, h := range lt.headers {
		if len(h) > 0 {
			headless = false
		}
	}
	aligns := append([]Alignment{}, lt.aligns...)
	for len(aligns) < numcols {
		aligns = append(aligns, AlignDefault)
	}
	widths := append([]float64{}, lt.widths...)
	for len(widths) < numcols {
		widths = append(widths, 0)
	}
	renderRow := func(cells [][]Block) []*Doc {
		var out []*Doc
		for _, c := range cells {
			out = append(out, w.blockListToMarkdown(c))
		}
		for len(out) < numcols {
			out = append(out, Empty)
		}
		return out
	}
	var tbl *Doc
	nst := func(d *Doc) *Doc { return d }
	switch {
	case isSimple && w.ext("simple_tables"):
		rawHeaders := renderRow(lt.headers)
		var rawRows [][]*Doc
		for _, r := range lt.rows {
			rawRows = append(rawRows, renderRow(r))
		}
		tbl = w.pandocTable(false, headless, aligns, widths, rawHeaders, rawRows)
		nst = func(d *Doc) *Doc { return Nest(2, d) }
	case isSimple && w.ext("pipe_tables"):
		rawHeaders := renderRow(lt.headers)
		var rawRows [][]*Doc
		for _, r := range lt.rows {
			rawRows = append(rawRows, renderRow(r))
		}
		tbl = w.pipeTable(headless, aligns, widths, rawHeaders, rawRows)
	case !hasBlocks && w.ext("multiline_tables"):
		rawHeaders := renderRow(lt.headers)
		var rawRows [][]*Doc
		for _, r := range lt.rows {
			rawRows = append(rawRows, renderRow(r))
		}
		tbl = w.pandocTable(true, headless, aligns, widths, rawHeaders, rawRows)
		nst = func(d *Doc) *Doc { return Nest(2, d) }
	case w.ext("grid_tables") && w.opts.Columns >= 8*numcols:
		tbl = w.gridTable(headless, aligns, widths, lt.headers, lt.rows)
	case hasSimpleCells && w.ext("pipe_tables"):
		rawHeaders := renderRow(lt.headers)
		var rawRows [][]*Doc
		for _, r := range lt.rows {
			rawRows = append(rawRows, renderRow(r))
		}
		tbl = w.pipeTable(headless, aligns, widths, rawHeaders, rawRows)
	case w.ext("raw_html"):
		hw := &htmlWriter{opts: w.opts, html5: true}
		tbl = Literal(hw.renderDoc(hw.blockToHtml(t)))
	default:
		tbl = TextD("[TABLE]")
	}
	return Cat(Above(nst(Above(tbl, captionDoc)), Blankline))
}

func (w *mdWriter) pandocTable(multiline, headless bool, aligns []Alignment, widths []float64, rawHeaders []*Doc, rawRows [][]*Doc) *Doc {
	isSimple := true
	for _, wd := range widths {
		if wd != 0 {
			isSimple = false
		}
	}
	alignHeader := func(a Alignment) func(int, *Doc) *Doc {
		switch a {
		case AlignCenter:
			return CBlock
		case AlignRight:
			return RBlock
		}
		return LBlock
	}
	numChars := func(col []*Doc) int {
		m := 0
		for _, d := range col {
			if o := Offset(d); o > m {
				m = o
			}
		}
		return m + 2
	}
	minNumChars := func(col []*Doc) int {
		m := 0
		for _, d := range col {
			if o := MinOffset(d); o > m {
				m = o
			}
		}
		return m + 2
	}
	ncols := len(aligns)
	columns := make([][]*Doc, ncols)
	all := append([][]*Doc{rawHeaders}, rawRows...)
	for _, r := range all {
		for i := 0; i < ncols; i++ {
			if i < len(r) {
				columns[i] = append(columns[i], r[i])
			}
		}
	}
	widthsInChars := make([]int, ncols)
	for i := 0; i < ncols; i++ {
		if isSimple {
			widthsInChars[i] = numChars(columns[i])
		} else {
			a := int(float64(w.opts.Columns-1) * widths[i])
			var b int
			if w.opts.WrapText == WrapAuto {
				b = minNumChars(columns[i])
			} else {
				b = numChars(columns[i])
			}
			widthsInChars[i] = maxInt(a, b)
		}
	}
	makeRow := func(cells []*Doc) *Doc {
		var parts []*Doc
		for i := 0; i < ncols; i++ {
			if i > 0 {
				parts = append(parts, LBlock(1, TextD(" ")))
			}
			c := Empty
			if i < len(cells) {
				c = cells[i]
			}
			parts = append(parts, alignHeader(aligns[i])(widthsInChars[i], c))
		}
		return Hcat(parts)
	}
	var rows []*Doc
	for _, r := range rawRows {
		rows = append(rows, makeRow(r))
	}
	head := makeRow(rawHeaders)
	var ul []*Doc
	for i, wd := range widthsInChars {
		if i > 0 {
			ul = append(ul, TextD(" "))
		}
		ul = append(ul, TextD(strings.Repeat("-", wd)))
	}
	underline := Cat(ul...)
	var border *Doc
	switch {
	case multiline:
		total := 0
		for _, wd := range widthsInChars {
			total += wd
		}
		border = TextD(strings.Repeat("-", total+len(widthsInChars)-1))
	case headless:
		border = underline
	default:
		border = Empty
	}
	head2 := Empty
	if !headless {
		head2 = Cat(border, CR, head)
	}
	var body *Doc
	if multiline {
		body = Vsep(rows)
		if len(rows) < 2 {
			body = Above(body, Blankline)
		}
	} else {
		body = Vcat(rows)
	}
	bottom := border
	if headless {
		bottom = underline
	}
	return Above(Above(Above(head2, underline), body), bottom)
}

func (w *mdWriter) pipeTable(headless bool, aligns []Alignment, widths []float64, rawHeaders []*Doc, rawRows [][]*Doc) *Doc {
	sp := TextD(" ")
	blockFor := func(a Alignment, x int, y *Doc) *Doc {
		switch a {
		case AlignCenter:
			return Cat(CBlock(x+2, Cat(sp, y, sp)), LBlock(0, Empty))
		case AlignRight:
			return Cat(RBlock(x+2, Cat(y, sp)), LBlock(0, Empty))
		}
		return Cat(LBlock(x+2, Cat(sp, y)), LBlock(0, Empty))
	}
	ncols := len(aligns)
	contentWidths := make([]int, ncols)
	all := append([][]*Doc{rawHeaders}, rawRows...)
	for i := 0; i < ncols; i++ {
		m := 3
		for _, r := range all {
			if i < len(r) {
				if o := Offset(r[i]); o > m {
					m = o
				}
			}
		}
		contentWidths[i] = m
	}
	maxwidth := 0
	for _, cw := range contentWidths {
		maxwidth += cw
	}
	widthsP := contentWidths
	anyNonZero := false
	for _, wd := range widths {
		if wd != 0 {
			anyNonZero = true
		}
	}
	if maxwidth > w.opts.Columns && anyNonZero {
		widthsP = make([]int, ncols)
		for i := 0; i < ncols; i++ {
			widthsP[i] = maxInt(3, int(float64(w.opts.Columns-ncols-1)*widths[i]))
		}
	}
	torow := func(cs []*Doc) *Doc {
		var parts []*Doc
		parts = append(parts, TextD("|"))
		for i := 0; i < ncols; i++ {
			if i > 0 {
				parts = append(parts, TextD("|"))
			}
			c := Empty
			if i < len(cs) {
				c = Chomp(cs[i])
			}
			parts = append(parts, blockFor(aligns[i], widthsP[i], c))
		}
		parts = append(parts, TextD("|"))
		return Nowrap(Cat(parts...))
	}
	toborder := func(a Alignment, wd int) *Doc {
		switch a {
		case AlignLeft:
			return TextD(":" + strings.Repeat("-", wd+1))
		case AlignCenter:
			return TextD(":" + strings.Repeat("-", wd) + ":")
		case AlignRight:
			return TextD(strings.Repeat("-", wd+1) + ":")
		}
		return TextD(strings.Repeat("-", wd+2))
	}
	var header *Doc
	if headless {
		header = torow(make([]*Doc, ncols))
	} else {
		header = torow(rawHeaders)
	}
	var bparts []*Doc
	bparts = append(bparts, TextD("|"))
	for i := 0; i < ncols; i++ {
		if i > 0 {
			bparts = append(bparts, TextD("|"))
		}
		bparts = append(bparts, toborder(aligns[i], widthsP[i]))
	}
	bparts = append(bparts, TextD("|"))
	border := Nowrap(Cat(bparts...))
	var rows []*Doc
	for _, r := range rawRows {
		rows = append(rows, torow(r))
	}
	return Above(Above(header, border), Vcat(rows))
}

func (w *mdWriter) gridTable(headless bool, aligns []Alignment, widths []float64, headers [][]Block, rows [][][]Block) *Doc {
	ncols := len(aligns)
	// widths in chars
	widthsInChars := make([]int, ncols)
	allZero := true
	for _, wd := range widths {
		if wd != 0 {
			allZero = false
		}
	}
	renderCells := func(cells [][]Block, wd int) []*Doc {
		var out []*Doc
		for i := 0; i < ncols; i++ {
			var c []Block
			if i < len(cells) {
				c = cells[i]
			}
			out = append(out, w.blockListToMarkdown(c))
		}
		return out
	}
	hdrDocs := renderCells(headers, 0)
	var rowDocs [][]*Doc
	for _, r := range rows {
		rowDocs = append(rowDocs, renderCells(r, 0))
	}
	if allZero {
		// equal widths based on content
		all := append([][]*Doc{hdrDocs}, rowDocs...)
		for i := 0; i < ncols; i++ {
			m := 0
			for _, r := range all {
				if o := Offset(r[i]); o > m {
					m = o
				}
			}
			widthsInChars[i] = m + 2
		}
		total := 0
		for _, x := range widthsInChars {
			total += x
		}
		if total+ncols+1 > w.opts.Columns {
			avail := w.opts.Columns - ncols - 1
			for i := range widthsInChars {
				widthsInChars[i] = maxInt(3, avail/ncols)
			}
		}
	} else {
		for i := 0; i < ncols; i++ {
			widthsInChars[i] = maxInt(3, int(float64(w.opts.Columns-ncols-1)*widths[i]))
		}
	}
	alignBlock := func(a Alignment, wd int, d *Doc) *Doc {
		switch a {
		case AlignCenter:
			return CBlock(wd, d)
		case AlignRight:
			return RBlock(wd, d)
		}
		return LBlock(wd, d)
	}
	makeRow := func(cells []*Doc) *Doc {
		var parts []*Doc
		parts = append(parts, VFill(1, "|"))
		for i := 0; i < ncols; i++ {
			parts = append(parts, alignBlock(aligns[i], widthsInChars[i]-2, Cat(TextD(" "), cells[i])), VFill(1, " |"))
			_ = i
		}
		// simplified: build with lblock widths including padding
		var parts2 []*Doc
		parts2 = append(parts2, VFill(2, "| "))
		for i := 0; i < ncols; i++ {
			if i > 0 {
				parts2 = append(parts2, VFill(3, " | "))
			}
			parts2 = append(parts2, alignBlock(aligns[i], widthsInChars[i]-2, cells[i]))
		}
		parts2 = append(parts2, VFill(2, " |"))
		return Hcat(parts2)
	}
	borderLine := func(ch string, withAlign bool) *Doc {
		var sb strings.Builder
		sb.WriteString("+")
		for i := 0; i < ncols; i++ {
			seg := strings.Repeat(ch, widthsInChars[i])
			if withAlign {
				rs := []rune(seg)
				switch aligns[i] {
				case AlignLeft:
					rs[0] = ':'
				case AlignRight:
					rs[len(rs)-1] = ':'
				case AlignCenter:
					rs[0] = ':'
					rs[len(rs)-1] = ':'
				}
				seg = string(rs)
			}
			sb.WriteString(seg)
			sb.WriteString("+")
		}
		return TextD(sb.String())
	}
	var parts []*Doc
	parts = append(parts, borderLine("-", headless))
	if !headless {
		parts = append(parts, makeRow(hdrDocs), borderLine("=", true))
	}
	for i, r := range rowDocs {
		parts = append(parts, makeRow(r))
		if i < len(rowDocs)-1 {
			parts = append(parts, borderLine("-", false))
		}
	}
	parts = append(parts, borderLine("-", false))
	return Vcat(parts)
}
