func writeLaTeX(doc *Pandoc, opts *WriterOptions) (string, []string) {
	w := &latexWriter{opts: opts, beamer: opts.Format == "beamer"}
	blocks := doc.Blocks
	// determine chapters
	tld := opts.TopLevelDivision
	if tld == "" {
		dc := ""
		if v, ok := opts.Variables["documentclass"]; ok && len(v) > 0 {
			dc = v[0]
		} else if m := lookupMetaString(doc.Meta, "documentclass"); m != "" {
			dc = m
		}
		switch dc {
		case "book", "report", "memoir", "scrbook", "scrreprt", "scrreport", "ctexbook", "tufte-book", "amsbook", "ltxdoc", "ltxguide":
			w.hasChapters = true
		}
	}
	colwidth := 0
	if opts.WrapText == WrapAuto {
		colwidth = opts.Columns
	}
	// remove title block elements if handled by template
	body := w.blockListToLaTeX(blocks)
	main := Render(colwidth, body)
	if !opts.Standalone {
		return main, w.warnings
	}
	meta := doc.Meta
	ctx := metaToContext(meta, func(bs []Block) string { return Render(colwidth, Chomp(w.blockListToLaTeX(bs))) }, func(ils []Inline) string { return Render(colwidth, w.inlineListToLaTeX(ils)) })
	vars := ctx
	for k, vs := range opts.Variables {
