	}
	return renderTemplate(tmpl, vars), w.warnings
}

// ---- escaping ----

type strCtx int

const (
	ctxText strCtx = iota
	ctxURL
	ctxCode
)

func (w *latexWriter) stringToLaTeX(ctx strCtx, s string) string {
	ligatures := w.opts.Extensions.Has("smart") && ctx == ctxText
	isURL := ctx == ctxURL
	var sb strings.Builder
	rs := []rune(s)
	emitcseq := func(cs string, i int) {
		sb.WriteString(cs)
		sb.WriteString("{}")
	}
	for i := 0; i < len(rs); i++ {
		x := rs[i]
		var next rune
		if i+1 < len(rs) {
			next = rs[i+1]
		}
		switch {
		case x == '{':
			sb.WriteString("\\{")
		case x == '}':
			sb.WriteString("\\}")
		case x == '`' && ctx == ctxCode:
			emitcseq("\\textasciigrave", i)
		case x == '$' && !isURL:
			sb.WriteString("\\$")
		case x == '%':
			sb.WriteString("\\%")
		case x == '&':
			sb.WriteString("\\&")
		case x == '_' && !isURL:
			sb.WriteString("\\_")
		case x == '#':
			sb.WriteString("\\#")
		case x == '-' && !isURL:
			if next == '-' {
				sb.WriteString("-\\/")
			} else {
				sb.WriteRune('-')
			}
		case x == '~' && !isURL:
			emitcseq("\\textasciitilde", i)
		case x == '^':
			sb.WriteString("\\^{}")
		case x == '\\':
			if isURL {
				sb.WriteRune('/')
			} else {
				emitcseq("\\textbackslash", i)
			}
		case x == '|' && !isURL:
			emitcseq("\\textbar", i)
		case x == '<':
			emitcseq("\\textless", i)
		case x == '>':
			emitcseq("\\textgreater", i)
		case x == '[':
			sb.WriteString("{[}")
		case x == ']':
			sb.WriteString("{]}")
		case x == '\'' && ctx == ctxCode:
			emitcseq("\\textquotesingle", i)
		case x == '\u00a0':
			sb.WriteString("~")
		case x == '\u202f':
			sb.WriteString("\\,")
		case x == '\u2026':
			emitcseq("\\ldots", i)
		case x == '\u2018' && ligatures:
			sb.WriteString("`")
		case x == '\u2019' && ligatures:
			sb.WriteString("'")
		case x == '\u201c' && ligatures:
			sb.WriteString("``")
		case x == '\u201d' && ligatures:
			sb.WriteString("''")
		case x == '\u2014' && ligatures:
			sb.WriteString("---")
		case x == '\u2013' && ligatures:
			sb.WriteString("--")
		case x == '\u200c':
			w.zwnj = true
			sb.WriteString("\\zwnj{}")
		default:
			sb.WriteRune(x)
		}
	}
	return sb.String()
}

// ---- blocks ----

func (w *latexWriter) blockListToLaTeX(bs []Block) *Doc {
	var docs []*Doc
	for _, b := range bs {
		docs = append(docs, w.blockToLaTeX(b))
	}
	return Vsep(docs)
}

func (w *latexWriter) blockToLaTeX(b Block) *Doc {
	switch x := b.(type) {
	case *Plain:
		return w.inlineListToLaTeX(x.Inlines)
	case *Para:
		return w.inlineListToLaTeX(x.Inlines)
	case *LineBlock:
		var lines []*Doc
		for _, l := range x.Lines {
			if len(l) == 0 {
				lines = append(lines, TextD("~"))
			} else {
				lines = append(lines, w.inlineListToLaTeX(l))
			}
		}
		var parts []*Doc
		for i, l := range lines {
			if i > 0 {
				parts = append(parts, TextD("\\\\"), CR)
			}
			parts = append(parts, l)
		}
		return Cat(TextD("\\begin{verse}"), CR, Cat(parts...), CR, TextD("\\end{verse}"))
	case *RawBlock:
		if x.Format == "latex" || x.Format == "tex" {
			return Literal(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *BlockQuote:
		old := w.inQuote
		w.inQuote = true
		contents := w.blockListToLaTeX(x.Blocks)
		w.inQuote = old
		return Cat(TextD("\\begin{quote}"), CR, contents, CR, TextD("\\end{quote}"))
	case *CodeBlock:
		return w.codeBlockToLaTeX(x)
	case *HorizontalRule:
		return TextD("\\begin{center}\\rule{0.5\\linewidth}{0.5pt}\\end{center}")
	case *Header:
		return w.sectionHeader(x)
	case *BulletList:
		inc := ""
		if w.opts.Incremental && w.beamer {
			inc = "[<+->]"
		}
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, w.listItemToLaTeX(it))
		}
		var parts []*Doc
		parts = append(parts, TextD("\\begin{itemize}"+inc))
		if isTightList(x.Items) {
			parts = append(parts, TextD("\\tightlist"))
		}
		parts = append(parts, Vcat(items), TextD("\\end{itemize}"))
		return Vcat(parts)
	case *OrderedList:
		return w.orderedListToLaTeX(x)
	case *DefinitionList:
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, w.defListItemToLaTeX(it))
		}
		var parts []*Doc
		parts = append(parts, TextD("\\begin{description}"))
		var defs [][]Block
		for _, it := range x.Items {
			defs = append(defs, it.Defs...)
		}
		if isTightList(defs) {
			parts = append(parts, TextD("\\tightlist"))
		}
		parts = append(parts, Vcat(items), TextD("\\end{description}"))
		return Vcat(parts)
	case *Div:
		return w.divToLaTeX(x)
	case *Figure:
		return w.figureToLaTeX(x)
	case *Table:
		return w.tableToLaTeX(x)
	}
	return Empty
}

func (w *latexWriter) codeBlockToLaTeX(x *CodeBlock) *Doc {
	str := x.Text
	if w.opts.Listings {
		var params []string
		if len(x.Attr.Classes) > 0 {
			params = append(params, "language="+x.Attr.Classes[0])
		}
		if x.Attr.ID != "" {
			params = append(params, "label="+x.Attr.ID)
		}
		p := ""
		if len(params) > 0 {
			p = "[" + strings.Join(params, ", ") + "]"
		}
		return Cat(Flush(Cat(TextD("\\begin{lstlisting}"+p), CR, Literal(str), CR, TextD("\\end{lstlisting}"))), CR)
	}
	if w.opts.Highlight && len(x.Attr.Classes) > 0 {
		if h, ok := highlightLaTeX(x.Attr, str); ok {
			w.highlighting = true
			return Cat(Flush(h), CR)
		}
	}
	// verbatim
	env := "verbatim"
	if w.inNote {
		w.verbInNote = true
		env = "Verbatim"
	}
	return Cat(Flush(Cat(TextD("\\begin{"+env+"}"), CR, Literal(str), CR, TextD("\\end{"+env+"}"))), CR)
}

func (w *latexWriter) listItemToLaTeX(bs []Block) *Doc {
	if len(bs) > 0 {
		if _, ok := bs[0].(*Header); ok {
			return Cat(TextD("\\item ~"), CR, Nest(2, w.blockListToLaTeX(bs)))
		}
		var ils []Inline
		switch f := bs[0].(type) {
		case *Plain:
			ils = f.Inlines
		case *Para:
			ils = f.Inlines
		}
		if len(ils) >= 2 {
			if s, ok := ils[0].(*Str); ok && (s.Text == "\u2610" || s.Text == "\u2612") {
				if _, ok := ils[1].(*Space); ok {
					checkbox := "$\\square$"
					if s.Text == "\u2612" {
						checkbox = "$\\boxtimes$"
					}
					isContents := w.inlineListToLaTeX(ils[2:])
					bsContents := w.blockListToLaTeX(bs[1:])
					return Above(TextD("\\item["+checkbox+"]"), Nest(2, AboveBlank(isContents, bsContents)))
				}
			}
		}
	}
	return Above(TextD("\\item"), Nest(2, w.blockListToLaTeX(bs)))
}

func (w *latexWriter) orderedListToLaTeX(x *OrderedList) *Doc {
	inc := ""
	if w.opts.Incremental && w.beamer {
		inc = "[<+->]"
	}
	oldlevel := w.olLevel
	w.olLevel++
	var items []*Doc
	for _, it := range x.Items {
		items = append(items, w.listItemToLaTeX(it))
	}
	w.olLevel = oldlevel
	tostyle := func(s string) string {
		switch x.Attrs.Style {
		case UpperRoman:
			return "\\Roman{" + s + "}"
		case LowerRoman:
			return "\\roman{" + s + "}"
		case UpperAlpha:
			return "\\Alph{" + s + "}"
		case LowerAlpha:
			return "\\alph{" + s + "}"
		}
		return "\\arabic{" + s + "}"
	}
	todelim := func(s string) string {
		switch x.Attrs.Delim {
		case OneParen:
			return s + ")"
		case TwoParens:
			return "(" + s + ")"
		}
		return s + "."
	}
	enum := "enum" + strings.ToLower(toRoman(oldlevel+1))
	var stylecommand *Doc
	switch {
	case x.Attrs.Style == DefaultStyle && x.Attrs.Delim == DefaultDelim:
		stylecommand = Empty
	case w.beamer && x.Attrs.Style == Decimal && x.Attrs.Delim == Period:
		stylecommand = Empty
	case w.beamer:
		stylecommand = TextD("[" + todelim("1") + "]")
	default:
		stylecommand = TextD("\\def\\label" + enum + "{" + todelim(tostyle(enum)) + "}")
	}
	resetcounter := Empty
	if x.Attrs.Start != 1 && oldlevel+1 <= 4 {
		resetcounter = TextD("\\setcounter{" + enum + "}{" + strconv.Itoa(x.Attrs.Start-1) + "}")
	}
	var parts []*Doc
	parts = append(parts, TextD("\\begin{enumerate}"+inc), stylecommand, resetcounter)
	if isTightList(x.Items) {
		parts = append(parts, TextD("\\tightlist"))
	}
	parts = append(parts, Vcat(items), TextD("\\end{enumerate}"))
	return Vcat(parts)
}

func (w *latexWriter) defListItemToLaTeX(it DefItem) *Doc {
	term := w.inlineListToLaTeX(it.Term)
	hasInternal := false
	queryInlines(it.Term, func(il Inline) {
		if l, ok := il.(*Link); ok && strings.HasPrefix(l.Target.URL, "#") {
			hasInternal = true
		}
	})
	if hasInternal {
		term = Cat(TextD("{"), term, TextD("}"))
	}
	var defs []*Doc
	for _, d := range it.Defs {
		defs = append(defs, w.blockListToLaTeX(d))
	}
	def := Vsep(defs)
	if len(it.Defs) > 0 && len(it.Defs[0]) > 0 {
		switch it.Defs[0][0].(type) {
		case *Header, *CodeBlock:
			return Above(Cat(TextD("\\item["), term, TextD("] ~")), def)
		}
	}
	return Above(Cat(TextD("\\item["), term, TextD("]")), def)
}

func (w *latexWriter) sectionHeader(h *Header) *Doc {
	attr := h.Attr
	unnumbered := attr.HasClass("unnumbered")
	unlisted := attr.HasClass("unlisted")
	old := w.inHeading
	w.inHeading = true
	txt := w.inlineListToLaTeX(h.Inlines)
	plain := w.stringToLaTeX(ctxText, stringify(h.Inlines))
	// remove notes etc for pdf string
	var lstNoNotes []Inline
	hasInvalid := false
	for _, il := range h.Inlines {
		switch y := il.(type) {
		case *Note:
			hasInvalid = true
			continue
		case *Image:
			hasInvalid = true
			continue
		case *Span:
			if y.Attr.ID != "" {
				hasInvalid = true
				continue
			}
		}
		lstNoNotes = append(lstNoNotes, il)
	}
	txtNoNotes := w.inlineListToLaTeX(lstNoNotes)
	w.inHeading = old
	optional := Empty
	if !unnumbered && hasInvalid && len(lstNoNotes) > 0 {
		optional = Cat(TextD("["), txtNoNotes, TextD("]"))
	}
	var contents *Doc
	if Render(0, txt) == plain {
		contents = Cat(TextD("{"), txt, TextD("}"))
	} else {
		contents = Cat(TextD("{\\texorpdfstring{"), txt, TextD("}{"), TextD(plain), TextD("}}"))
	}
	level := h.Level
	tld := w.opts.TopLevelDivision
	if tld == "" || tld == "default" {
		if w.hasChapters {
			tld = "chapter"
		}
	}
	levelP := level
	if w.beamer && (tld == "part" || tld == "chapter") {
		if level == 1 {
			levelP = -1
		} else {
			levelP = level - 1
		}
	} else {
		switch tld {
		case "part":
			levelP = level - 2
		case "chapter":
			levelP = level - 1
		}
	}
	sectionType := ""
	switch levelP {
	case -1:
		sectionType = "part"
	case 0:
		sectionType = "chapter"
	case 1:
		sectionType = "section"
	case 2:
		sectionType = "subsection"
	case 3:
		sectionType = "subsubsection"
	case 4:
		sectionType = "paragraph"
	case 5:
		sectionType = "subparagraph"
	}
	prefix := Empty
	if w.inQuote && levelP >= 4 {
		prefix = TextD("\\mbox{}%")
	}
	lab := Empty
	if attr.ID != "" {
		lab = TextD("\\label{" + w.toLabel(attr.ID) + "}")
	}
	star := Empty
	if unnumbered && levelP < 4 {
		star = TextD("*")
	}
	if levelP > 5 {
		return txt
	}
	stuffing := Cat(TextD("\\"+sectionType), star, optional, contents, lab)
	out := Above(prefix, stuffing)
	if unnumbered && !unlisted {
		out = Above(out, Cat(TextD("\\addcontentsline{toc}{"+sectionType+"}{"), txtNoNotes, TextD("}")))
	}
	return out
}

func (w *latexWriter) toLabel(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '-' || r == ':' || r == '_' || r == '.' {
			sb.WriteRune(r)
		} else if r > 127 {
			sb.WriteRune(r)
		} else {
			sb.WriteString(fmt.Sprintf("ux%X", r))
		}
	}
	return sb.String()
}

func (w *latexWriter) divToLaTeX(x *Div) *Doc {
	attr := x.Attr
	contents := w.blockListToLaTeX(x.Blocks)
	lang, hasLang := attr.Get("lang")
	_ = lang
	_ = hasLang
	if attr.ID != "" {
		contents = Above(TextD("\\phantomsection\\label{"+w.toLabel(attr.ID)+"}"), contents)
	}
	if attr.HasClass("center") {
		return Cat(TextD("\\begin{center}"), CR, contents, CR, TextD("\\end{center}"))
	}
	return contents
}

func (w *latexWriter) figureToLaTeX(x *Figure) *Doc {
	w.graphics = true
	var capt *Doc
	captBlocks := x.Caption.Blocks
	if len(captBlocks) > 0 {
		capt = Cat(TextD("\\caption"), TextD("{"), w.blockListToLaTeX(captBlocks), TextD("}"))
		if x.Attr.ID != "" {
			capt = Cat(capt, TextD("\\label{"+w.toLabel(x.Attr.ID)+"}"))
		}
	} else if x.Attr.ID != "" {
		capt = TextD("\\label{" + w.toLabel(x.Attr.ID) + "}")
	}
	var contents []*Doc
	for _, b := range x.Blocks {
		if pl, ok := b.(*Plain); ok && len(pl.Inlines) == 1 {
			if img, ok := pl.Inlines[0].(*Image); ok {
				contents = append(contents, w.imageToLaTeX(img, true))
				continue
			}
		}
		contents = append(contents, w.blockToLaTeX(b))
	}
	var parts []*Doc
	parts = append(parts, TextD("\\begin{figure}"), TextD("\\centering"))
	parts = append(parts, contents...)
	if capt != nil {
		parts = append(parts, capt)
	}
	parts = append(parts, TextD("\\end{figure}"))
	return Vcat(parts)
}

// ---- tables ----

func (w *latexWriter) tableToLaTeX(t *Table) *Doc {
	w.tables = true
	ncols := len(t.ColSpecs)
	var capt *Doc = Empty
	captBlocks := t.Caption.Blocks
	hasCaption := len(captBlocks) > 0
	if hasCaption {
		capt = Cat(TextD("\\caption"), TextD("{"), w.blockListToLaTeX(captBlocks), TextD("}"))
		if t.Attr.ID != "" {
			capt = Cat(capt, TextD("\\label{"+w.toLabel(t.Attr.ID)+"}"))
		}
		capt = Cat(capt, TextD(" \\\\"))
	}
	// colspecs
	hasWidths := false
	for _, s := range t.ColSpecs {
		if !s.Width.Default {
			hasWidths = true
		}
	}
	var colDescs []string
	for _, s := range t.ColSpecs {
		align := ""
		switch s.Align {
		case AlignLeft, AlignDefault:
			align = "l"
		case AlignRight:
			align = "r"
		case AlignCenter:
			align = "c"
		}
		if hasWidths {
			ragged := "\\raggedright"
			switch s.Align {
			case AlignRight:
				ragged = "\\raggedleft"
			case AlignCenter:
				ragged = "\\centering"
			}
			wd := s.Width.Width
			if s.Width.Default {
				wd = 0
			}
			colDescs = append(colDescs, fmt.Sprintf(">{%s\\arraybackslash}p{(\\linewidth - %d\\tabcolsep) * \\real{%s}}", ragged, 2*(ncols-1), formatReal(wd)))
		} else {
			colDescs = append(colDescs, align)
		}
	}
	var colSpec *Doc
	if hasWidths {
		var parts []*Doc
		parts = append(parts, TextD("@{}"))
		for _, cd := range colDescs {
			parts = append(parts, CR, TextD("  "+cd))
		}
		parts = append(parts, TextD("@{}}"))
		colSpec = Cat(TextD("\\begin{longtable}[]{"), Cat(parts...))
	} else {
		colSpec = TextD("\\begin{longtable}[]{@{}" + strings.Join(colDescs, "") + "@{}}")
	}
	var parts []*Doc
	parts = append(parts, colSpec)
	if hasCaption {
		parts = append(parts, capt)
	}
	// header
	hasHead := len(t.Head.Rows) > 0 && !rowsAllEmpty(t.Head.Rows)
	if hasHead {
		parts = append(parts, TextD("\\toprule\\noalign{}"))
		for _, r := range t.Head.Rows {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, true))
		}
		parts = append(parts, TextD("\\midrule\\noalign{}"), TextD("\\endfirsthead"))
		parts = append(parts, TextD("\\toprule\\noalign{}"))
		for _, r := range t.Head.Rows {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, true))
		}
		parts = append(parts, TextD("\\midrule\\noalign{}"), TextD("\\endhead"))
	} else {
		parts = append(parts, TextD("\\toprule\\noalign{}"), TextD("\\endhead"))
	}
	// foot
	if len(t.Foot.Rows) > 0 {
		parts = append(parts, TextD("\\midrule\\noalign{}"))
		for _, r := range t.Foot.Rows {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, false))
		}
		parts = append(parts, TextD("\\bottomrule\\noalign{}"), TextD("\\endlastfoot"))
	} else {
		parts = append(parts, TextD("\\bottomrule\\noalign{}"), TextD("\\endlastfoot"))
	}
	for _, body := range t.Bodies {
		for _, r := range body.Head {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, true))
		}
		for _, r := range body.Body {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, false))
		}
	}
	parts = append(parts, TextD("\\end{longtable}"))
	return Vcat(parts)
}

func formatReal(f float64) string {
	return strconv.FormatFloat(f, 'f', 4, 64)
}

func (w *latexWriter) rowToLaTeX(r Row, specs []ColSpec, isHeader bool) *Doc {
	var cells []*Doc
	for i, c := range r.Cells {
		var content *Doc
		if len(c.Blocks) == 1 {
			switch b := c.Blocks[0].(type) {
			case *Plain:
				content = w.inlineListToLaTeX(b.Inlines)
			case *Para:
				content = w.inlineListToLaTeX(b.Inlines)
			}
		}
		if content == nil {
			if len(c.Blocks) == 0 {
				content = Empty
			} else {
				old := w.inMinipage
				w.inMinipage = true
				content = w.blockListToLaTeX(c.Blocks)
				w.inMinipage = old
				align := AlignDefault
				if i < len(specs) {
					align = specs[i].Align
				}
				_ = align
			}
		}
		if c.ColSpan > 1 {
			content = Cat(TextD(fmt.Sprintf("\\multicolumn{%d}{l}{", c.ColSpan)), content, TextD("}"))
		}
		cells = append(cells, content)
	}
	var parts []*Doc
	for i, c := range cells {
		if i > 0 {
			parts = append(parts, TextD(" & "))
		}
		parts = append(parts, c)
	}
	parts = append(parts, TextD(" \\\\"))
	return Cat(parts...)
}

// ---- inlines ----

func (w *latexWriter) inlineListToLaTeX(ils []Inline) *Doc {
	// fix: Str starting with [ after a LineBreak etc.
	var docs []*Doc
	for i, il := range ils {
		d := w.inlineToLaTeX(il)
		// avoid `] ` interpretation: handled by escaping
		_ = i
		docs = append(docs, d)
	}
	return Cat(docs...)
}

func isQuotedInl(il Inline) bool {
	_, ok := il.(*Quoted)
	return ok
}

func (w *latexWriter) inlineToLaTeX(il Inline) *Doc {
	switch x := il.(type) {
	case *Str:
		return Literal(w.stringToLaTeX(ctxText, x.Text))
	case *Space:
		return BreakingSpace
	case *SoftBreak:
		switch w.opts.WrapText {
		case WrapPreserve:
			return CR
		}
		return BreakingSpace
	case *LineBreak:
		return Cat(TextD("\\\\"), CR)
	case *Emph:
		return Cat(TextD("\\emph{"), w.inlineListToLaTeX(x.Inlines), TextD("}"))
	case *Underline:
		return Cat(TextD("\\ul{"), w.inlineListToLaTeX(x.Inlines), TextD("}"))
	case *Strong:
		return Cat(TextD("\\textbf{"), w.inlineListToLaTeX(x.Inlines), TextD("}"))
	case *Strikeout:
		w.strikeout = true
		return Cat(TextD("\\st{"), w.inlineListToLaTeX(x.Inlines), TextD("}"))
	case *Superscript:
		return Cat(TextD("\\textsuperscript{"), w.inlineListToLaTeX(x.Inlines), TextD("}"))
	case *Subscript:
		return Cat(TextD("\\textsubscript{"), w.inlineListToLaTeX(x.Inlines), TextD("}"))
	case *SmallCaps:
		return Cat(TextD("\\textsc{"), w.inlineListToLaTeX(x.Inlines), TextD("}"))
	case *Quoted:
		contents := w.inlineListToLaTeX(x.Inlines)
		if w.csquotes {
			return Cat(TextD("\\enquote{"), contents, TextD("}"))
		}
		s1 := Empty
		s2 := Empty
		if len(x.Inlines) > 0 && isQuotedInl(x.Inlines[0]) {
			s1 = TextD("\\,")
		}
		if len(x.Inlines) > 0 && isQuotedInl(x.Inlines[len(x.Inlines)-1]) {
			s2 = TextD("\\,")
		}
		inner := Cat(s1, contents, s2)
		smart := w.opts.Extensions.Has("smart")
		if x.Type == DoubleQuote {
			if smart {
				return Cat(TextD("``"), inner, TextD("''"))
			}
			return Cat(TextD("\u201c"), inner, TextD("\u201d"))
		}
		if smart {
			return Cat(TextD("`"), inner, TextD("'"))
		}
		return Cat(TextD("\u2018"), inner, TextD("\u2019"))
	case *Code:
		return w.codeToLaTeX(x)
	case *Math:
		if x.Type == InlineMath {
			return Cat(TextD("\\("), Literal(x.Text), TextD("\\)"))
		}
		return Cat(TextD("\\["), Literal(x.Text), TextD("\\]"))
	case *RawInline:
		if x.Format == "latex" || x.Format == "tex" {
			return Literal(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *Link:
		return w.linkToLaTeX(x)
	case *Image:
		return w.imageToLaTeX(x, false)
	case *Note:
		old := w.inNote
		w.inNote = true
		contents := w.blockListToLaTeX(x.Blocks)
		w.inNote = old
		beamer := w.beamer
		_ = beamer
		noteContents := Nest(2, Chomp(contents))
		if w.inMinipage {
			return Cat(TextD("\\footnotemark{}"))
		}
		return Cat(TextD("\\footnote{"), noteContents, TextD("}"))
	case *Span:
		return w.spanToLaTeX(x)
	case *Cite:
		return w.inlineListToLaTeX(x.Inlines)
	}
	return Empty
}

func (w *latexWriter) codeToLaTeX(x *Code) *Doc {
	str := x.Text
	if w.opts.Listings {
		// choose delimiter
		for _, c := range "!\"'&#%@^_~" {
			if !strings.ContainsRune(str, c) {
				return TextD("\\lstinline" + string(c) + str + string(c))
			}
		}
		return TextD("\\lstinline{" + str + "}")
	}
	if w.opts.Highlight && len(x.Attr.Classes) > 0 {
		if h, ok := highlightLaTeXInline(x.Attr, str); ok {
			w.highlighting = true
			return h
		}
	}
	return Cat(TextD("\\texttt{"), Literal(w.stringToLaTeX(ctxCode, str)), TextD("}"))
}

func (w *latexWriter) spanToLaTeX(x *Span) *Doc {
	contents := w.inlineListToLaTeX(x.Inlines)
	attr := x.Attr
	if attr.HasClass("smallcaps") {
		contents = Cat(TextD("\\textsc{"), contents, TextD("}"))
	}
	if attr.HasClass("underline") {
		contents = Cat(TextD("\\ul{"), contents, TextD("}"))
	}
	if attr.ID != "" {
		contents = Cat(TextD("\\protect\\hypertarget{"+w.toLabel(attr.ID)+"}{}"), contents)
	}
	if attr.IsNull() {
		return contents
	}
	return Cat(TextD("{"), contents, TextD("}"))
}

func (w *latexWriter) linkToLaTeX(x *Link) *Doc {
	src := x.Target.URL
	if strings.HasPrefix(src, "#") {
		lab := w.toLabel(src[1:])
		contents := w.inlineListToLaTeX(x.Inlines)
		return Cat(TextD("\\hyperref[" + lab + "]{"), contents, TextD("}"))
	}
	// autolink?
	if len(x.Inlines) == 1 {
		if s, ok := x.Inlines[0].(*Str); ok {
			if escapeURI(s.Text) == src || s.Text == src {
				return TextD("\\url{" + w.stringToLaTeX(ctxURL, src) + "}")
			}
			if strings.HasPrefix(src, "mailto:") && ("mailto:"+s.Text == src) {
				return TextD("\\href{" + w.stringToLaTeX(ctxURL, src) + "}{\\nolinkurl{" + w.stringToLaTeX(ctxURL, s.Text) + "}}")
			}
		}
	}
	contents := w.inlineListToLaTeX(x.Inlines)
	return Cat(TextD("\\href{"+w.stringToLaTeX(ctxURL, src)+"}{"), contents, TextD("}"))
}

func (w *latexWriter) imageToLaTeX(x *Image, inFigure bool) *Doc {
	w.graphics = true
	src := x.Target.URL
	var opts []string
	showDim := func(k string) (string, bool) {
		v, ok := x.Attr.Get(k)
		if !ok {
			return "", false
		}
		d, ok := parseDimension(v)
		if !ok {
			return "", false
		}
		switch d.unit {
		case "%":
			ref := "\\linewidth"
			if k == "height" {
				ref = "\\textheight"
			}
			return formatFloatShort(d.val/100) + ref, true
		case "px", "":
			return formatFloatShort(d.val/96) + "in", true
		}
		return d.numStr() + d.unit, true
	}
	if wd, ok := showDim("width"); ok {
		opts = append(opts, "width="+wd)
	}
	if ht, ok := showDim("height"); ok {
		opts = append(opts, "height="+ht)
	}
	opts = append(opts, "keepaspectratio")
	srcEsc := w.stringToLaTeX(ctxURL, src)
	inc := TextD("\\includegraphics[" + strings.Join(opts, ",") + "]{" + srcEsc + "}")
	_, hasW := x.Attr.Get("width")
	_, hasH := x.Attr.Get("height")
	if !hasW && !hasH {
		inc = Cat(TextD("\\pandocbounded{"), inc, TextD("}"))
	}
	if inFigure {
		return inc
	}
	return inc
}

func formatFloatShort(f float64) string {
	s := strconv.FormatFloat(f, 'f', -1, 64)
	if strings.Contains(s, ".") {
		// pandoc shows e.g. 0.5, 1.0 for Double show... use up to 5 decimals
		s = strconv.FormatFloat(f, 'f', 5, 64)
		s = strings.TrimRight(s, "0")
		s = strings.TrimSuffix(s, ".")
	}
	return s
}

