func writeLaTeX(doc *Pandoc, opts *WriterOptions) (string, []string) {
	w := &latexWriter{opts: opts, beamer: opts.Format == "beamer"}
	blocks := doc.Blocks
	// determine chapters
	tld := opts.TopLevelDivision
	if tld == "" {
		dc := ""
