		allRows = append(allRows, b.Body...)
	}
	allRows = append(allRows, t.Foot.Rows...)
	for _, r := range allRows {
		for _, c := range r.Cells {
			if !isSimpleCell(c) {
				isSimpleTable = false
			}
		}
	}
	colAlign := func(a Alignment) string {
		switch a {
		case AlignRight:
			return "r"
		case AlignCenter:
			return "c"
		}
		return "l"
	}
	var colSpec *Doc
	if defaultWidthsOnly && isSimpleTable {
		var sb strings.Builder
		for _, s := range t.ColSpecs {
			sb.WriteString(colAlign(s.Align))
		}
		colSpec = TextD("\\\\begin{longtable}[]{@{}" + sb.String() + "@{}}")
	} else {
		var parts []*Doc
		parts = append(parts, TextD("@{}"))
		for _, s := range t.ColSpecs {
			wd := s.Width.Width
			if defaultWidthsOnly {
				wd = 1 / float64(ncols)
			} else if s.Width.Default {
				wd = 0
			}
			parts = append(parts, CR, TextD("  "+fmt.Sprintf(">{%s\\\\arraybackslash}p{(\\\\linewidth - %d\\\\tabcolsep) * \\\\real{%s}}", alignCommand(s.Align), 2*(ncols-1), formatReal(wd))))
		}
		parts = append(parts, TextD("@{}}"))
		colSpec = Cat(TextD("\\\\begin{longtable}[]{"), Cat(parts...))
	}
	var parts []*Doc
	parts = append(parts, colSpec)
	if hasCaption {
		parts = append(parts, capt)
	}
	hasHead := len(t.Head.Rows) > 0 && !rowsAllEmpty(t.Head.Rows)
	headDoc := func() []*Doc {
		var hp []*Doc
		hp = append(hp, TextD("\\\\toprule\\\\noalign{}"))
		for _, r := range t.Head.Rows {
			hp = append(hp, w.rowToLaTeX(r, t.ColSpecs, true))
		}
		hp = append(hp, TextD("\\\\midrule\\\\noalign{}"))
		return hp
	}
	if hasHead {
		if hasCaption {
			parts = append(parts, headDoc()...)
			parts = append(parts, TextD("\\\\endfirsthead"))
		}
		parts = append(parts, headDoc()...)
	} else {
		parts = append(parts, TextD("\\\\toprule\\\\noalign{}"))
	}
	parts = append(parts, TextD("\\\\endhead"))
	if len(t.Foot.Rows) > 0 {
		parts = append(parts, TextD("\\\\midrule\\\\noalign{}"))
		for _, r := range t.Foot.Rows {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, false))
		}
	}
	parts = append(parts, TextD("\\\\bottomrule\\\\noalign{}"), TextD("\\\\endlastfoot"))
	for _, body := range t.Bodies {
		for _, r := range body.Head {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, true))
		}
		for _, r := range body.Body {
			parts = append(parts, w.rowToLaTeX(r, t.ColSpecs, false))
		}
	}
	parts = append(parts, TextD("\\\\end{longtable}"))
	return Vcat(parts)
}

func alignCommand(a Alignment) string {
	switch a {
	case AlignRight:
		return "\\\\raggedleft"
	case AlignCenter:
		return "\\\\centering"
	}
	return "\\\\raggedright"
}

