cd /workspace && git add -A && git commit -qm "latex writer + template" -q; cat > src/nativereader.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// ---- Native (Haskell show syntax) reader ----

type hvKind int

const (
	hvCon hvKind = iota
	hvList
	hvTuple
	hvStr
	hvNum
	hvRec
)

type hval struct {
	kind   hvKind
	name   string
	args   []*hval
	str    string
	num    string
	fields map[string]*hval
}

type nparser struct {
	s   []rune
	pos int
}

func (p *nparser) skipWS() {
	for p.pos < len(p.s) && unicode.IsSpace(p.s[p.pos]) {
		p.pos++
	}
}

func (p *nparser) errorf(format string, a ...interface{}) error {
	return fmt.Errorf(format, a...)
}

func (p *nparser) parseValue() (*hval, error) {
	p.skipWS()
	if p.pos >= len(p.s) {
		return nil, errors.New("unexpected end of input")
	}
	c := p.s[p.pos]
	switch {
	case c == '[':
		p.pos++
		v := &hval{kind: hvList}
		for {
			p.skipWS()
			if p.pos < len(p.s) && p.s[p.pos] == ']' {
				p.pos++
				return v, nil
			}
			item, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			v.args = append(v.args, item)
			p.skipWS()
			if p.pos < len(p.s) && p.s[p.pos] == ',' {
				p.pos++
			}
		}
	case c == '(':
		p.pos++
		v := &hval{kind: hvTuple}
		for {
			p.skipWS()
			if p.pos < len(p.s) && p.s[p.pos] == ')' {
				p.pos++
				if len(v.args) == 1 {
					return v.args[0], nil
				}
				return v, nil
			}
			item, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			v.args = append(v.args, item)
			p.skipWS()
			if p.pos < len(p.s) && p.s[p.pos] == ',' {
				p.pos++
			}
		}
	case c == '"':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		return &hval{kind: hvStr, str: s}, nil
	case c == '-' || (c >= '0' && c <= '9'):
		start := p.pos
		p.pos++
		for p.pos < len(p.s) && (unicode.IsDigit(p.s[p.pos]) || p.s[p.pos] == '.' || p.s[p.pos] == 'e' || p.s[p.pos] == 'E' || p.s[p.pos] == '-' || p.s[p.pos] == '+') {
			p.pos++
		}
		return &hval{kind: hvNum, num: string(p.s[start:p.pos])}, nil
	case unicode.IsLetter(c):
		start := p.pos
		for p.pos < len(p.s) && (isAlphaNum(p.s[p.pos]) || p.s[p.pos] == '_' || p.s[p.pos] == '\'' || p.s[p.pos] == '.') {
			p.pos++
		}
		name := string(p.s[start:p.pos])
		v := &hval{kind: hvCon, name: name}
		// record syntax?
		p.skipWS()
		if p.pos < len(p.s) && p.s[p.pos] == '{' {
			p.pos++
			v.kind = hvRec
			v.fields = map[string]*hval{}
			for {
				p.skipWS()
				if p.pos < len(p.s) && p.s[p.pos] == '}' {
					p.pos++
					break
				}
				fstart := p.pos
				for p.pos < len(p.s) && (isAlphaNum(p.s[p.pos]) || p.s[p.pos] == '_') {
					p.pos++
				}
				fname := string(p.s[fstart:p.pos])
				p.skipWS()
				if p.pos < len(p.s) && p.s[p.pos] == '=' {
					p.pos++
				}
				fv, err := p.parseValue()
				if err != nil {
					return nil, err
				}
				v.fields[fname] = fv
				p.skipWS()
				if p.pos < len(p.s) && p.s[p.pos] == ',' {
					p.pos++
				}
			}
			return v, nil
		}
		// arguments: atoms until a delimiter
		for {
			p.skipWS()
			if p.pos >= len(p.s) {
				break
			}
			d := p.s[p.pos]
			if d == ',' || d == ']' || d == ')' || d == '}' {
				break
			}
			if unicode.IsLetter(d) {
				// a constructor without args (atom) e.g. Space, DoubleQuote, or Format? Format takes args but appears parenthesized.
				astart := p.pos
				for p.pos < len(p.s) && (isAlphaNum(p.s[p.pos]) || p.s[p.pos] == '_' || p.s[p.pos] == '\'') {
					p.pos++
				}
				aname := string(p.s[astart:p.pos])
				v.args = append(v.args, &hval{kind: hvCon, name: aname})
				continue
			}
			arg, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			v.args = append(v.args, arg)
		}
		return v, nil
	}
	return nil, p.errorf("unexpected character %q", c)
}

func (p *nparser) parseString() (string, error) {
	if p.s[p.pos] != '"' {
		return "", errors.New("expected string")
	}
	p.pos++
	var sb strings.Builder
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.s) {
				break
			}
			e := p.s[p.pos]
			switch {
			case e == 'n':
				sb.WriteByte('\n')
				p.pos++
			case e == 't':
				sb.WriteByte('\t')
				p.pos++
			case e == 'r':
				sb.WriteByte('\r')
				p.pos++
			case e == '\\':
				sb.WriteByte('\\')
				p.pos++
			case e == '"':
				sb.WriteByte('"')
				p.pos++
			case e == '\'':
				sb.WriteByte('\'')
				p.pos++
			case e == 'a':
				sb.WriteByte(7)
				p.pos++
			case e == 'b':
				sb.WriteByte(8)
				p.pos++
			case e == 'f':
				sb.WriteByte(12)
				p.pos++
			case e == 'v':
				sb.WriteByte(11)
				p.pos++
			case e == '&':
				p.pos++
			case unicode.IsDigit(e):
				start := p.pos
				for p.pos < len(p.s) && unicode.IsDigit(p.s[p.pos]) {
					p.pos++
				}
				n, _ := strconv.Atoi(string(p.s[start:p.pos]))
				sb.WriteRune(rune(n))
			case e == 'x':
				p.pos++
				start := p.pos
				for p.pos < len(p.s) && strings.ContainsRune("0123456789abcdefABCDEF", p.s[p.pos]) {
					p.pos++
				}
				n, _ := strconv.ParseInt(string(p.s[start:p.pos]), 16, 32)
				sb.WriteRune(rune(n))
			case e == 'o':
				p.pos++
				start := p.pos
				for p.pos < len(p.s) && strings.ContainsRune("01234567", p.s[p.pos]) {
					p.pos++
				}
				n, _ := strconv.ParseInt(string(p.s[start:p.pos]), 8, 32)
				sb.WriteRune(rune(n))
			default:
				// named control chars
				matched := false
				for code, name := range asciiTab {
					if hasPrefixRunes(p.s, p.pos, name) {
						// prefer longest match (SO vs SOH)
						if name == "SO" && hasPrefixRunes(p.s, p.pos, "SOH") {
							continue
						}
						sb.WriteRune(rune(code))
						p.pos += len(name)
						matched = true
						break
					}
				}
				if !matched {
					if hasPrefixRunes(p.s, p.pos, "DEL") {
						sb.WriteRune(127)
						p.pos += 3
					} else if e == '^' && p.pos+1 < len(p.s) {
						sb.WriteRune(p.s[p.pos+1] - 64)
						p.pos += 2
					} else {
						sb.WriteRune(e)
						p.pos++
					}
				}
			}
			continue
		}
		sb.WriteRune(c)
		p.pos++
	}
	return "", errors.New("unterminated string")
}

func readNative(input string) (*Pandoc, error) {
	p := &nparser{s: []rune(input)}
	v, err := p.parseValue()
	if err != nil {
		return nil, fmt.Errorf("Error at line %d: %v", 1, err)
	}
	doc := &Pandoc{Meta: newMetaMap()}
	switch {
	case v.kind == hvCon && v.name == "Pandoc":
		if len(v.args) != 2 {
			return nil, errors.New("Pandoc expects 2 arguments")
		}
		m, err := hvToMeta(v.args[0])
		if err != nil {
			return nil, err
		}
		doc.Meta = m
		bs, err := hvToBlocks(v.args[1])
		if err != nil {
			return nil, err
		}
		doc.Blocks = bs
	case v.kind == hvList:
		if len(v.args) > 0 && isInlineCon(v.args[0].name) && v.args[0].kind == hvCon {
			ils, err := hvToInlines(v)
			if err != nil {
				return nil, err
			}
			doc.Blocks = []Block{&Plain{Inlines: ils}}
		} else {
			bs, err := hvToBlocks(v)
			if err != nil {
				return nil, err
			}
			doc.Blocks = bs
		}
	default:
		b, err := hvToBlock(v)
		if err != nil {
			return nil, err
		}
		doc.Blocks = []Block{b}
	}
	return doc, nil
}

func isInlineCon(name string) bool {
	switch name {
	case "Str", "Emph", "Underline", "Strong", "Strikeout", "Superscript", "Subscript", "SmallCaps", "Quoted", "Cite", "Code", "Space", "SoftBreak", "LineBreak", "Math", "RawInline", "Link", "Image", "Note", "Span":
		return true
	}
	return false
}

func hvToMeta(v *hval) (*MetaMap, error) {
	m := newMetaMap()
	if v.kind == hvRec && v.name == "Meta" {
		if um, ok := v.fields["unMeta"]; ok {
			return hvToMetaMap(um)
		}
		return m, nil
	}
	return hvToMetaMap(v)
}

func hvToMetaMap(v *hval) (*MetaMap, error) {
	m := newMetaMap()
	if v.kind == hvCon && v.name == "fromList" && len(v.args) == 1 {
		v = v.args[0]
	}
	if v.kind != hvList {
		return nil, errors.New("expected list for Meta")
	}
	for _, it := range v.args {
		if it.kind != hvTuple || len(it.args) != 2 {
			return nil, errors.New("expected pair in Meta")
		}
		mv, err := hvToMetaValue(it.args[1])
		if err != nil {
			return nil, err
		}
		m.Set(it.args[0].str, mv)
	}
	return m, nil
}

func hvToMetaValue(v *hval) (MetaValue, error) {
	if v.kind != hvCon {
		return nil, errors.New("expected MetaValue")
	}
	switch v.name {
	case "MetaMap":
		return hvToMetaMap(v.args[0])
	case "MetaList":
		l := &MetaList{}
		for _, it := range v.args[0].args {
			mv, err := hvToMetaValue(it)
			if err != nil {
				return nil, err
			}
			l.Items = append(l.Items, mv)
		}
		return l, nil
	case "MetaBool":
		return &MetaBool{Value: v.args[0].name == "True"}, nil
	case "MetaString":
		return &MetaString{Text: v.args[0].str}, nil
	case "MetaInlines":
		ils, err := hvToInlines(v.args[0])
		return &MetaInlines{Inlines: ils}, err
	case "MetaBlocks":
		bs, err := hvToBlocks(v.args[0])
		return &MetaBlocks{Blocks: bs}, err
	}
	return nil, fmt.Errorf("unknown MetaValue %s", v.name)
}

func hvToAttr(v *hval) (Attr, error) {
	if v.kind != hvTuple || len(v.args) != 3 {
		return Attr{}, errors.New("expected Attr")
	}
	a := Attr{ID: v.args[0].str}
	for _, c := range v.args[1].args {
		a.Classes = append(a.Classes, c.str)
	}
	for _, kv := range v.args[2].args {
		if kv.kind == hvTuple && len(kv.args) == 2 {
			a.KVs = append(a.KVs, [2]string{kv.args[0].str, kv.args[1].str})
		}
	}
	return a, nil
}

func hvToBlocks(v *hval) ([]Block, error) {
	if v.kind != hvList {
		return nil, errors.New("expected list of blocks")
	}
	var out []Block
	for _, it := range v.args {
		b, err := hvToBlock(it)
		if err != nil {
			return nil, err
		}
		out = append(out, b)
	}
	return out, nil
}

func hvToBlocksList(v *hval) ([][]Block, error) {
	var out [][]Block
	for _, it := range v.args {
		bs, err := hvToBlocks(it)
		if err != nil {
			return nil, err
		}
		out = append(out, bs)
	}
	return out, nil
}

func hvInt(v *hval) int {
	n, _ := strconv.Atoi(v.num)
	return n
}

func hvToBlock(v *hval) (Block, error) {
	if v.kind != hvCon {
		return nil, errors.New("expected block constructor")
	}
	need := func(n int) error {
		if len(v.args) < n {
			return fmt.Errorf("%s expects %d arguments", v.name, n)
		}
		return nil
	}
	switch v.name {
	case "Plain":
		if err := need(1); err != nil {
			return nil, err
		}
		ils, err := hvToInlines(v.args[0])
		return &Plain{Inlines: ils}, err
	case "Para":
		if err := need(1); err != nil {
			return nil, err
		}
		ils, err := hvToInlines(v.args[0])
		return &Para{Inlines: ils}, err
	case "LineBlock":
		lb := &LineBlock{}
		for _, l := range v.args[0].args {
			ils, err := hvToInlines(l)
			if err != nil {
				return nil, err
			}
			lb.Lines = append(lb.Lines, ils)
		}
		return lb, nil
	case "CodeBlock":
		if err := need(2); err != nil {
			return nil, err
		}
		a, err := hvToAttr(v.args[0])
		return &CodeBlock{Attr: a, Text: v.args[1].str}, err
	case "RawBlock":
		if err := need(2); err != nil {
			return nil, err
		}
		f := v.args[0]
		format := ""
		if f.kind == hvCon && len(f.args) > 0 {
			format = f.args[0].str
		} else {
			format = f.str
		}
		return &RawBlock{Format: format, Text: v.args[1].str}, nil
	case "BlockQuote":
		bs, err := hvToBlocks(v.args[0])
		return &BlockQuote{Blocks: bs}, err
	case "OrderedList":
		if err := need(2); err != nil {
			return nil, err
		}
		la := v.args[0]
		attrs := ListAttributes{Start: hvInt(la.args[0])}
		styles := map[string]ListNumberStyle{"DefaultStyle": DefaultStyle, "Example": Example, "Decimal": Decimal, "LowerRoman": LowerRoman, "UpperRoman": UpperRoman, "LowerAlpha": LowerAlpha, "UpperAlpha": UpperAlpha}
		delims := map[string]ListNumberDelim{"DefaultDelim": DefaultDelim, "Period": Period, "OneParen": OneParen, "TwoParens": TwoParens}
		attrs.Style = styles[la.args[1].name]
		attrs.Delim = delims[la.args[2].name]
		items, err := hvToBlocksList(v.args[1])
		return &OrderedList{Attrs: attrs, Items: items}, err
	case "BulletList":
		items, err := hvToBlocksList(v.args[0])
		return &BulletList{Items: items}, err
	case "DefinitionList":
		dl := &DefinitionList{}
		for _, it := range v.args[0].args {
			term, err := hvToInlines(it.args[0])
			if err != nil {
				return nil, err
			}
			defs, err := hvToBlocksList(it.args[1])
			if err != nil {
				return nil, err
			}
			dl.Items = append(dl.Items, DefItem{Term: term, Defs: defs})
		}
		return dl, nil
	case "Header":
		if err := need(3); err != nil {
			return nil, err
		}
		a, err := hvToAttr(v.args[1])
		if err != nil {
			return nil, err
		}
		ils, err := hvToInlines(v.args[2])
		return &Header{Level: hvInt(v.args[0]), Attr: a, Inlines: ils}, err
	case "HorizontalRule":
		return &HorizontalRule{}, nil
	case "Table":
		return hvToTable(v)
	case "Figure":
		if err := need(3); err != nil {
			return nil, err
		}
		a, err := hvToAttr(v.args[0])
		if err != nil {
			return nil, err
		}
		capt, err := hvToCaption(v.args[1])
		if err != nil {
			return nil, err
		}
		bs, err := hvToBlocks(v.args[2])
		return &Figure{Attr: a, Caption: capt, Blocks: bs}, err
	case "Div":
		if err := need(2); err != nil {
			return nil, err
		}
		a, err := hvToAttr(v.args[0])
		if err != nil {
			return nil, err
		}
		bs, err := hvToBlocks(v.args[1])
		return &Div{Attr: a, Blocks: bs}, err
	case "Null":
		return &Div{}, nil
	}
	return nil, fmt.Errorf("unknown block %s", v.name)
}

func hvToCaption(v *hval) (Caption, error) {
	c := Caption{}
	if v.kind != hvCon || v.name != "Caption" || len(v.args) != 2 {
		return c, errors.New("expected Caption")
	}
	if v.args[0].kind == hvCon && v.args[0].name == "Just" && len(v.args[0].args) == 1 {
		ils, err := hvToInlines(v.args[0].args[0])
		if err != nil {
			return c, err
		}
		c.HasShort = true
		c.Short = ils
	}
	bs, err := hvToBlocks(v.args[1])
	c.Blocks = bs
	return c, err
}

func hvAlign(v *hval) Alignment {
	switch v.name {
	case "AlignLeft":
		return AlignLeft
	case "AlignRight":
		return AlignRight
	case "AlignCenter":
		return AlignCenter
	}
	return AlignDefault
}

func hvToRows(v *hval) ([]Row, error) {
	var rows []Row
	for _, rv := range v.args {
		if rv.kind != hvCon || rv.name != "Row" {
			return nil, errors.New("expected Row")
		}
		a, err := hvToAttr(rv.args[0])
		if err != nil {
			return nil, err
		}
		r := Row{Attr: a}
		for _, cv := range rv.args[1].args {
			ca, err := hvToAttr(cv.args[0])
			if err != nil {
				return nil, err
			}
			bs, err := hvToBlocks(cv.args[4])
			if err != nil {
				return nil, err
			}
			r.Cells = append(r.Cells, Cell{Attr: ca, Align: hvAlign(cv.args[1]), RowSpan: hvInt(cv.args[2].args[0]), ColSpan: hvInt(cv.args[3].args[0]), Blocks: bs})
		}
		rows = append(rows, r)
	}
	return rows, nil
}

func hvToTable(v *hval) (Block, error) {
	if len(v.args) != 6 {
		return nil, errors.New("Table expects 6 arguments")
	}
	a, err := hvToAttr(v.args[0])
	if err != nil {
		return nil, err
	}
	capt, err := hvToCaption(v.args[1])
	if err != nil {
		return nil, err
	}
	t := &Table{Attr: a, Caption: capt}
	for _, sv := range v.args[2].args {
		cs := ColSpec{Align: hvAlign(sv.args[0])}
		if sv.args[1].name == "ColWidth" {
			f, _ := strconv.ParseFloat(sv.args[1].args[0].num, 64)
			cs.Width = ColWidth{Width: f}
		} else {
			cs.Width = ColWidth{Default: true}
		}
		t.ColSpecs = append(t.ColSpecs, cs)
	}
	th := v.args[3]
	ha, err := hvToAttr(th.args[0])
	if err != nil {
		return nil, err
	}
	hr, err := hvToRows(th.args[1])
	if err != nil {
		return nil, err
	}
	t.Head = TableHead{Attr: ha, Rows: hr}
	for _, bv := range v.args[4].args {
		ba, err := hvToAttr(bv.args[0])
		if err != nil {
			return nil, err
		}
		hd, err := hvToRows(bv.args[2])
		if err != nil {
			return nil, err
		}
		bd, err := hvToRows(bv.args[3])
		if err != nil {
			return nil, err
		}
		t.Bodies = append(t.Bodies, TableBody{Attr: ba, RowHeadColumns: hvInt(bv.args[1].args[0]), Head: hd, Body: bd})
	}
	tf := v.args[5]
	fa, err := hvToAttr(tf.args[0])
	if err != nil {
		return nil, err
	}
	fr, err := hvToRows(tf.args[1])
	if err != nil {
		return nil, err
	}
	t.Foot = TableFoot{Attr: fa, Rows: fr}
	return t, nil
}

func hvToInlines(v *hval) ([]Inline, error) {
	if v.kind != hvList {
		return nil, errors.New("expected list of inlines")
	}
	var out []Inline
	for _, it := range v.args {
		il, err := hvToInline(it)
		if err != nil {
			return nil, err
		}
		out = append(out, il)
	}
	return out, nil
}

func hvToInline(v *hval) (Inline, error) {
	if v.kind != hvCon {
		return nil, errors.New("expected inline constructor")
	}
	need := func(n int) error {
		if len(v.args) < n {
			return fmt.Errorf("%s expects %d arguments", v.name, n)
		}
		return nil
	}
	sub := func(i int) ([]Inline, error) { return hvToInlines(v.args[i]) }
	switch v.name {
	case "Str":
		if err := need(1); err != nil {
			return nil, err
		}
		return &Str{Text: v.args[0].str}, nil
	case "Emph":
		ils, err := sub(0)
		return &Emph{Inlines: ils}, err
	case "Underline":
		ils, err := sub(0)
		return &Underline{Inlines: ils}, err
	case "Strong":
		ils, err := sub(0)
		return &Strong{Inlines: ils}, err
	case "Strikeout":
		ils, err := sub(0)
		return &Strikeout{Inlines: ils}, err
	case "Superscript":
		ils, err := sub(0)
		return &Superscript{Inlines: ils}, err
	case "Subscript":
		ils, err := sub(0)
		return &Subscript{Inlines: ils}, err
	case "SmallCaps":
		ils, err := sub(0)
		return &SmallCaps{Inlines: ils}, err
	case "Quoted":
		if err := need(2); err != nil {
			return nil, err
		}
		ils, err := sub(1)
		q := &Quoted{Type: DoubleQuote, Inlines: ils}
		if v.args[0].name == "SingleQuote" {
			q.Type = SingleQuote
		}
		return q, err
	case "Cite":
		if err := need(2); err != nil {
			return nil, err
		}
		c := &Cite{}
		for _, cv := range v.args[0].args {
			cit := Citation{}
			if cv.kind == hvRec {
				cit.ID = cv.fields["citationId"].str
				cit.Prefix, _ = hvToInlines(cv.fields["citationPrefix"])
				cit.Suffix, _ = hvToInlines(cv.fields["citationSuffix"])
				switch cv.fields["citationMode"].name {
				case "AuthorInText":
					cit.Mode = AuthorInText
				case "SuppressAuthor":
					cit.Mode = SuppressAuthor
				default:
					cit.Mode = NormalCitation
				}
				cit.NoteNum = hvInt(cv.fields["citationNoteNum"])
				cit.Hash = hvInt(cv.fields["citationHash"])
			}
			c.Citations = append(c.Citations, cit)
		}
		ils, err := sub(1)
		c.Inlines = ils
		return c, err
	case "Code":
		if err := need(2); err != nil {
			return nil, err
		}
		a, err := hvToAttr(v.args[0])
		return &Code{Attr: a, Text: v.args[1].str}, err
	case "Space":
		return &Space{}, nil
	case "SoftBreak":
		return &SoftBreak{}, nil
	case "LineBreak":
		return &LineBreak{}, nil
	case "Math":
		if err := need(2); err != nil {
			return nil, err
		}
		m := &Math{Type: InlineMath, Text: v.args[1].str}
		if v.args[0].name == "DisplayMath" {
			m.Type = DisplayMath
		}
		return m, nil
	case "RawInline":
		if err := need(2); err != nil {
			return nil, err
		}
		f := v.args[0]
		format := f.str
		if f.kind == hvCon && len(f.args) > 0 {
			format = f.args[0].str
		}
		return &RawInline{Format: format, Text: v.args[1].str}, nil
	case "Link", "Image":
		if err := need(3); err != nil {
			return nil, err
		}
		a, err := hvToAttr(v.args[0])
		if err != nil {
			return nil, err
		}
		ils, err := sub(1)
		if err != nil {
			return nil, err
		}
		tgt := v.args[2]
		if tgt.kind != hvTuple || len(tgt.args) != 2 {
			return nil, errors.New("expected Target")
		}
		t := Target{URL: tgt.args[0].str, Title: tgt.args[1].str}
		if v.name == "Link" {
			return &Link{Attr: a, Inlines: ils, Target: t}, nil
		}
		return &Image{Attr: a, Inlines: ils, Target: t}, nil
	case "Note":
		bs, err := hvToBlocks(v.args[0])
		return &Note{Blocks: bs}, err
	case "Span":
		if err := need(2); err != nil {
			return nil, err
		}
		a, err := hvToAttr(v.args[0])
		if err != nil {
			return nil, err
		}
		ils, err := sub(1)
		return &Span{Attr: a, Inlines: ils}, err
	}
	return nil, fmt.Errorf("unknown inline %s", v.name)
}
