func (w *rstWriter) notesToRST() *Doc {
	if len(w.notes) == 0 {
		return Empty
	}
	var docs []*Doc
	for i, n := range w.notes {
		contents := w.blockListToRST(n)
		marker := TextD(".. [" + strconv.Itoa(i+1) + "]")
		docs = append(docs, Hang(3, Cat(marker, BreakingSpace), contents))
	}
	return Cat(Blankline, Vsep(docs))
}

func (w *rstWriter) refsToRST() *Doc {
	if len(w.images) == 0 {
		return Empty
	}
	var docs []*Doc
	for _, img := range w.images {
		label := w.inlineListToRST(img.alt)
		docs = append(docs, Cat(Nowrap(Cat(TextD(".. |"), label, TextD("| image:: "), TextD(img.src))), w.imageDimsToRST(img.attr)))
	}
	return Cat(Blankline, Vcat(docs))
}

func (w *rstWriter) imageDimsToRST(attr Attr) *Doc {
	var parts []*Doc
	if v, ok := attr.Get("width"); ok {
		parts = append(parts, CR, TextD("   :width: "+v))
	}
	if v, ok := attr.Get("height"); ok {
		parts = append(parts, CR, TextD("   :height: "+v))
	}
	return Cat(parts...)
}

func (w *rstWriter) blockListToRST(bs []Block) *Doc {
	var docs []*Doc
	for i, b := range bs {
		d := w.blockToRST(b)
		// a Plain/Para followed by a list needs blank line
		_ = i
		docs = append(docs, d)
	}
	return Vcat(docs)
}

func (w *rstWriter) blockToRST(b Block) *Doc {
	switch x := b.(type) {
	case *Plain:
		return w.inlineListToRST(x.Inlines)
	case *Para:
		if len(x.Inlines) == 1 {
			if img, ok := x.Inlines[0].(*Image); ok {
				return w.figureToRST(img.Attr, img.Inlines, img.Target.URL, img.Target.Title, nil)
			}
		}
		return Cat(w.inlineListToRST(x.Inlines), Blankline)
	case *LineBlock:
		var lines []*Doc
		for _, l := range x.Lines {
			if len(l) == 0 {
				lines = append(lines, TextD("|"))
			} else {
				lines = append(lines, Hang(2, TextD("| "), w.inlineListToRST(l)))
			}
		}
		return Cat(Vcat(lines), Blankline)
	case *RawBlock:
		if x.Format == "rst" {
			return Cat(Literal(x.Text), Blankline)
		}
		if x.Format == "tex" || x.Format == "latex" {
			return Cat(TextD(".. raw:: latex"), Blankline, Nest(3, Literal(x.Text)), Blankline)
		}
		if x.Format == "html" {
			return Cat(TextD(".. raw:: html"), Blankline, Nest(3, Literal(x.Text)), Blankline)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *HorizontalRule:
		return Cat(Blankline, TextD("--------------"), Blankline)
	case *Header:
		contents := w.inlineListToRST(x.Inlines)
		isTop := w.topLevel
		var attr *Doc = Empty
		if x.Attr.ID != "" && x.Attr.ID != inlineListToIdentifier(x.Inlines, false, false) {
			attr = Cat(TextD(".. _"+x.Attr.ID+":"), Blankline)
		}
		if isTop {
			chars := []string{"=", "-", "~", "^", "'"}
			ch := "'"
			if x.Level-1 < len(chars) {
				ch = chars[x.Level-1]
			}
			border := TextD(strings.Repeat(ch, Offset(contents)))
			return Cat(attr, Nowrap(Cat(contents, CR, border)), Blankline)
		}
		// in list/blockquote: use rubric
		return Cat(attr, TextD(".. rubric:: "), contents, Blankline)
	case *CodeBlock:
		str := x.Text
		if len(x.Attr.Classes) > 0 && x.Attr.Classes[0] != "" {
			lang := x.Attr.Classes[0]
			numberLines := x.Attr.HasClass("numberLines") || x.Attr.HasClass("number-lines")
			var opts []*Doc
			if numberLines {
				start, _ := x.Attr.Get("startFrom")
				if start == "" {
					opts = append(opts, TextD("   :number-lines:"))
				} else {
					opts = append(opts, TextD("   :number-lines: "+start))
				}
			}
			return Cat(TextD(".. code:: "+lang), CR, Vcat(opts), Blankline, Nest(3, Literal(str)), Blankline)
		}
		return Cat(TextD("::"), Blankline, Nest(3, Literal(str)), Blankline)
	case *BlockQuote:
		old := w.topLevel
		w.topLevel = false
		contents := w.blockListToRST(x.Blocks)
		w.topLevel = old
		return Cat(Nest(3, contents), Blankline)
	case *BulletList:
		old := w.topLevel
		w.topLevel = false
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, Hang(3, TextD("-  "), w.blockListToRST(it)))
		}
		w.topLevel = old
		return Cat(Blankline, Vcat(items), Blankline)
	case *OrderedList:
		old := w.topLevel
		w.topLevel = false
		markers := orderedListMarkers(x.Attrs.Start, x.Attrs.Style, x.Attrs.Delim, len(x.Items))
		if x.Attrs.Style == DefaultStyle && x.Attrs.Delim == DefaultDelim {
			for i := range markers {
				markers[i] = "#."
			}
		}
		maxLen := 0
		for _, m := range markers {
			if len(m) > maxLen {
				maxLen = len(m)
			}
		}
		var items []*Doc
		for i, it := range x.Items {
			m := markers[i] + strings.Repeat(" ", maxLen-len(markers[i]))
			items = append(items, Hang(maxLen+1, TextD(m+" "), w.blockListToRST(it)))
		}
		w.topLevel = old
		return Cat(Blankline, Vcat(items), Blankline)
	case *DefinitionList:
		old := w.topLevel
		w.topLevel = false
		var items []*Doc
		for _, it := range x.Items {
			label := w.inlineListToRST(it.Term)
			var defs []*Doc
			for _, d := range it.Defs {
				defs = append(defs, w.blockListToRST(d))
			}
			items = append(items, Cat(Nowrap(label), CR, Nest(3, Vcat(defs)), Blankline))
		}
		w.topLevel = old
		return Cat(Blankline, Cat(items...))
	case *Div:
		old := w.topLevel
		contents := w.blockListToRST(x.Blocks)
		w.topLevel = old
		if x.Attr.IsNull() {
			return contents
		}
		var parts []*Doc
		parts = append(parts, TextD(".. container::"))
		if len(x.Attr.Classes) > 0 {
			parts = append(parts, TextD(" "+strings.Join(x.Attr.Classes, " ")))
		}
		var opts []*Doc
		if x.Attr.ID != "" {
			opts = append(opts, TextD("   :name: "+x.Attr.ID))
		}
		return Cat(Cat(parts...), CR, Vcat(opts), Blankline, Nest(3, contents), Blankline)
	case *Figure:
		if len(x.Blocks) == 1 {
			if pl, ok := x.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
				if img, ok := pl.Inlines[0].(*Image); ok {
					return w.figureToRST(img.Attr, img.Inlines, img.Target.URL, img.Target.Title, x.Caption.Blocks)
				}
			}
		}
		return w.blockListToRST(x.Blocks)
	case *Table:
		return w.tableToRST(x)
	}
	return Empty
}

func (w *rstWriter) figureToRST(attr Attr, alt []Inline, src, tit string, capt []Block) *Doc {
	var captDoc *Doc = Empty
	if len(capt) > 0 {
		captDoc = w.blockListToRST(capt)
	} else if len(alt) > 0 && !(len(alt) == 1 && stringify(alt) == src) {
		captDoc = w.inlineListToRST(alt)
	}
	var opts []*Doc
	altText := stringify(alt)
	if altText != "" && len(capt) > 0 {
		opts = append(opts, TextD("   :alt: "+altText))
	}
	if v, ok := attr.Get("width"); ok {
		opts = append(opts, TextD("   :width: "+v))
	}
	if v, ok := attr.Get("height"); ok {
		opts = append(opts, TextD("   :height: "+v))
	}
	if attr.ID != "" {
		opts = append(opts, TextD("   :name: "+attr.ID))
	}
	return Cat(Hang(3, TextD(".. figure:: "), TextD(src)), CR, Vcat(opts), Blankline, Nest(3, captDoc), Blankline)
}

func (w *rstWriter) tableToRST(t *Table) *Doc {
	lt := toLegacyTable(t)
	ncols := len(lt.aligns)
	caption := w.inlineListToRST(lt.caption)
	// simple table or grid table
	renderCell := func(bs []Block) *Doc {
		return w.blockListToRST(bs)
	}
	var headerDocs []*Doc
	for _, h := range lt.headers {
		headerDocs = append(headerDocs, renderCell(h))
	}
	var rowDocs [][]*Doc
	for _, r := range lt.rows {
		var rd []*Doc
		for _, c := range r {
			rd = append(rd, renderCell(c))
		}
		rowDocs = append(rowDocs, rd)
	}
	headless := true
	for _, h := range lt.headers {
		if len(h) > 0 {
			headless = false
		}
	}
	isSimple := onlySimpleTableCells(append([][][]Block{lt.headers}, lt.rows...))
	allZero := true
	for _, wd := range lt.widths {
		if wd != 0 {
			allZero = false
		}
	}
	var tbl *Doc
	if isSimple && allZero {
		widthsInChars := make([]int, ncols)
		all := append([][]*Doc{headerDocs}, rowDocs...)
		for i := 0; i < ncols; i++ {
			m := 0
			for _, r := range all {
				if i < len(r) {
					if o := Offset(r[i]); o > m {
						m = o
					}
				}
			}
			widthsInChars[i] = m
		}
		makeRow := func(cells []*Doc) *Doc {
			var parts []*Doc
			for i := 0; i < ncols; i++ {
				if i > 0 {
					parts = append(parts, LBlock(1, TextD(" ")))
				}
				c := Empty
				if i < len(cells) {
					c = cells[i]
				}
				parts = append(parts, LBlock(widthsInChars[i], c))
			}
			return Hcat(parts)
		}
		var ul []*Doc
		for i, wd := range widthsInChars {
			if i > 0 {
				ul = append(ul, TextD(" "))
			}
			ul = append(ul, TextD(strings.Repeat("=", wd)))
		}
		border := Cat(ul...)
		var rows []*Doc
		for _, r := range rowDocs {
			rows = append(rows, makeRow(r))
		}
		if headless {
			tbl = Vcat([]*Doc{border, Vcat(rows), border})
		} else {
			tbl = Vcat([]*Doc{border, makeRow(headerDocs), border, Vcat(rows), border})
		}
	} else {
		// grid table
		mw := &mdWriter{opts: w.opts, exts: newExtSet("grid_tables")}
		mw.variant = varMarkdown
		tbl = mw.gridTable(headless, lt.aligns, lt.widths, lt.headers, lt.rows)
		_ = mw
	}
	if len(lt.caption) > 0 {
		return Cat(TextD(".. table:: "), caption, Blankline, Nest(3, tbl), Blankline)
	}
	return Cat(tbl, Blankline)
}

// ---- inlines ----

func (w *rstWriter) inlineListToRST(ils []Inline) *Doc {
	// insert escapes between adjacent inline markup where needed
	var docs []*Doc
	ils = rstFixInlines(ils)
	for _, il := range ils {
		docs = append(docs, w.inlineToRST(il))
	}
	return Cat(docs...)
}

func isComplexRST(il Inline) bool {
	switch il.(type) {
	case *Emph, *Strong, *Strikeout, *Superscript, *Subscript, *SmallCaps, *Code, *Link, *Image, *Math, *Span, *Underline:
		return true
	}
	return false
}

// rstFixInlines inserts backslash-space separators between adjacent complex inlines
// and strips/escapes as pandoc does.
func rstFixInlines(ils []Inline) []Inline {
	var out []Inline
	for i := 0; i < len(ils); i++ {
		il := ils[i]
		if i > 0 && isComplexRST(il) {
			prev := ils[i-1]
			if isComplexRST(prev) {
				out = append(out, &RawInline{Format: "rst", Text: "\\ "})
			} else if s, ok := prev.(*Str); ok && s.Text != "" {
				last := []rune(s.Text)[len([]rune(s.Text))-1]
				if !isRSTBoundaryBefore(last) {
					out = append(out, &RawInline{Format: "rst", Text: "\\ "})
				}
			}
		}
		if i > 0 && !isComplexRST(il) && isComplexRST(ils[i-1]) {
			if s, ok := il.(*Str); ok && s.Text != "" {
				first := []rune(s.Text)[0]
				if !isRSTBoundaryAfter(first) {
					out = append(out, &RawInline{Format: "rst", Text: "\\ "})
				}
			}
		}
		out = append(out, il)
	}
	return out
}

func isRSTBoundaryBefore(r rune) bool {
	return r == ' ' || r == '\n' || strings.ContainsRune("-:/'\"<([{", r) || r == '\u2018' || r == '\u201c'
}

func isRSTBoundaryAfter(r rune) bool {
	return r == ' ' || r == '\n' || strings.ContainsRune("-.,:;!?\\/'\")]}>", r) || r == '\u2019' || r == '\u201d'
}

func rstEscape(s string) string {
	var sb strings.Builder
	rs := []rune(s)
	for i, c := range rs {
		switch c {
		case '\\', '`', '*', '_', '|':
			sb.WriteRune('\\')
			sb.WriteRune(c)
		case '[':
			// escape [ if followed by text and ] ... keep simple
			sb.WriteRune(c)
		default:
			if (c == '.' || c == ')') && i == len(rs)-1 && len(rs) > 1 {
				// trailing period after number could be list marker; handled elsewhere
			}
			sb.WriteRune(c)
		}
	}
	return sb.String()
}

func (w *rstWriter) inlineToRST(il Inline) *Doc {
	switch x := il.(type) {
	case *Str:
		s := x.Text
		if w.opts.Extensions.Has("smart") {
			s = (&mdWriter{exts: w.opts.Extensions}).unsmartify(s)
		}
		return Literal(rstEscape(s))
	case *Space:
		return BreakingSpace
	case *SoftBreak:
		if w.opts.WrapText == WrapPreserve {
			return CR
		}
		return BreakingSpace
	case *LineBreak:
		return CR
	case *Emph:
		return Cat(TextD("*"), w.inlineListToRST(x.Inlines), TextD("*"))
	case *Underline:
		return Cat(TextD(":underline:`"), w.inlineListToRST(x.Inlines), TextD("`"))
	case *Strong:
		return Cat(TextD("**"), w.inlineListToRST(x.Inlines), TextD("**"))
	case *Strikeout:
		return Cat(TextD("[STRIKEOUT:"), w.inlineListToRST(x.Inlines), TextD("]"))
	case *Superscript:
		return Cat(TextD(":sup:`"), w.inlineListToRST(x.Inlines), TextD("`"))
	case *Subscript:
		return Cat(TextD(":sub:`"), w.inlineListToRST(x.Inlines), TextD("`"))
	case *SmallCaps:
		return Cat(TextD(":sc:`"), w.inlineListToRST(x.Inlines), TextD("`"))
	case *Quoted:
		contents := w.inlineListToRST(x.Inlines)
		if x.Type == SingleQuote {
			if w.opts.Extensions.Has("smart") {
				return Cat(TextD("'"), contents, TextD("'"))
			}
			return Cat(TextD("\u2018"), contents, TextD("\u2019"))
		}
		if w.opts.Extensions.Has("smart") {
			return Cat(TextD("\""), contents, TextD("\""))
		}
		return Cat(TextD("\u201c"), contents, TextD("\u201d"))
	case *Code:
		return TextD("``" + x.Text + "``")
	case *Math:
		w.hasMath = true
		if x.Type == InlineMath {
			return TextD(":math:`" + x.Text + "`")
		}
		return Cat(Blankline, TextD(".. math::"), Blankline, Nest(3, Literal(x.Text)), Blankline)
	case *RawInline:
		if x.Format == "rst" {
			return Literal(x.Text)
		}
		if x.Format == "latex" || x.Format == "tex" {
			w.hasRaw = true
			return TextD(":raw-latex:`" + x.Text + "`")
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *Link:
		src := x.Target.URL
		if len(x.Inlines) == 1 {
			if s, ok := x.Inlines[0].(*Str); ok && (s.Text == src || "mailto:"+s.Text == src) {
				return TextD(strings.TrimPrefix(src, "mailto:"))
			}
		}
		linktext := w.inlineListToRST(x.Inlines)
		if strings.HasPrefix(src, "#") {
			return Cat(TextD("`"), linktext, TextD("`_"))
		}
		return Cat(TextD("`"), linktext, TextD(" <"+src+">`__"))
	case *Image:
		alt := x.Inlines
		if len(alt) == 0 || stringify(alt) == x.Target.URL {
			alt = []Inline{&Str{Text: "image" + strconv.Itoa(len(w.images))}}
		}
		w.images = append(w.images, rstImg{attr: x.Attr, alt: alt, src: x.Target.URL, tit: x.Target.Title})
		return Cat(TextD("|"), w.inlineListToRST(alt), TextD("|"))
	case *Note:
		w.notes = append(w.notes, x.Blocks)
		return TextD(" [" + strconv.Itoa(len(w.notes)) + "]_")
	case *Span:
		return w.inlineListToRST(x.Inlines)
	case *Cite:
		return w.inlineListToRST(x.Inlines)
	}
	return Empty
}
