// ---- HTML tokenizer ----

type htok struct {
	kind htmlTagKind // tagOpen, tagClose, tagComment, tagDecl
	isText bool
	text   string // for text tokens (already entity-decoded)
	tag    HTMLTag
}

var rawTextTags = map[string]bool{"script": true, "style": true, "textarea": true, "title": true}

func tokenizeHTML(s string) []htok {
	rs := []rune(s)
	var toks []htok
	i := 0
	var text strings.Builder
	flush := func() {
		if text.Len() > 0 {
			toks = append(toks, htok{isText: true, text: html.UnescapeString(text.String())})
			text.Reset()
		}
	}
	for i < len(rs) {
		if rs[i] == '<' {
			if tag, n, ok := parseHTMLTag(rs, i); ok {
				flush()
				toks = append(toks, htok{kind: tag.Kind, tag: tag})
				i += n
				if tag.Kind == tagOpen && rawTextTags[tag.Name] && !tag.SelfClosing {
					// raw text until closing tag
					end := indexRunesFold(rs, i, "</"+tag.Name)
					if end < 0 {
						end = len(rs)
					}
					raw := string(rs[i:end])
					toks = append(toks, htok{isText: true, text: raw})
					i = end
				}
				continue
			}
		}
		text.WriteRune(rs[i])
		i++
	}
	flush()
	return toks
}

func indexRunesFold(rs []rune, from int, s string) int {
	ls := []rune(strings.ToLower(s))
	for i := from; i+len(ls) <= len(rs); i++ {
		match := true
		for j, r := range ls {
			if unicode.ToLower(rs[i+j]) != r {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

// ---- HTML reader ----

type htmlReader struct {
	toks        []htok
	pos         int
	exts        *ExtSet
	opts        *ReaderOptions
	meta        *MetaMap
	identifiers map[string]bool
	warnings    []string
	inChapter   bool
	inPlain     bool
	inTable     bool
	notes       map[string][]Block
}

func readHTML(input string, exts *ExtSet, opts *ReaderOptions) (*Pandoc, []string) {
	input = strings.ReplaceAll(input, "\r\n", "\n")
	r := &htmlReader{toks: tokenizeHTML(input), exts: exts, opts: opts, meta: newMetaMap(), identifiers: map[string]bool{}}
	blocks := r.parseBlocks(func(t *htok) bool { return false })
	// strip leading/trailing empty
	return &Pandoc{Meta: r.meta, Blocks: blocks}, r.warnings
}

func (r *htmlReader) eof() bool { return r.pos >= len(r.toks) }

func (r *htmlReader) peek() *htok {
	if r.pos < len(r.toks) {
		return &r.toks[r.pos]
	}
	return nil
}

func (r *htmlReader) next() *htok {
	t := r.peek()
	if t != nil {
		r.pos++
	}
	return t
}

func isBlockLevelName(name string) bool {
	return blockHtmlTags[name] && !eitherBlockOrInlineTags[name]
}

// closes: does an opening tag t1 implicitly close an open element t2?
func closesTag(t1, t2 string) bool {
	switch t2 {
	case "body", "html":
		return false
	}
	if t1 == "body" && t2 == "head" {
		return true
	}
	if t1 == "a" && t2 == "a" {
		return true
	}
	if t1 == "li" && t2 == "li" {
		return true
	}
	if t1 == "th" && (t2 == "th" || t2 == "td") {
		return true
	}
	if t1 == "td" && (t2 == "th" || t2 == "td") {
		return true
	}
	if t1 == "tr" && (t2 == "th" || t2 == "td" || t2 == "tr") {
		return true
	}
	if (t1 == "dd" || t1 == "dt") && (t2 == "dt" || t2 == "dd") {
		return true
	}
	if t2 == "p" {
		switch t1 {
		case "address", "article", "aside", "blockquote", "dir", "div", "dl", "fieldset", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hr", "menu", "nav", "ol", "p", "pre", "section", "table", "ul":
			return true
		}
	}
	if t1 == "meta" && t2 == "meta" {
		return true
	}
	switch t2 {
	case "option", "style", "script", "textarea", "title":
		return true
	}
	if t1 == "thead" && t2 == "colgroup" {
		return true
	}
	if t1 == "tfoot" && (t2 == "thead" || t2 == "colgroup") {
		return true
	}
	if t1 == "tbody" && (t2 == "tbody" || t2 == "tfoot" || t2 == "thead" || t2 == "colgroup") {
		return true
	}
	switch t1 {
	case "h1", "h2", "h3", "h4", "h5", "h6", "dl", "ol", "ul", "table", "div", "main", "p":
		switch t2 {
		case "h1", "h2", "h3", "h4", "h5", "h6", "p":
			return true
		}
	}
	if blockHtmlTags[t1] && !blockHtmlTags[t2] && !eitherBlockOrInlineTags[t2] {
		return true
	}
	return false
}

// atCloseOf checks whether the current token closes the given open tag (without consuming unless it's the exact close).
func (r *htmlReader) atCloseOf(tagtype string) bool {
	t := r.peek()
	if t == nil {
		return true
	}
	if t.isText {
		return false
	}
	switch t.kind {
	case tagClose:
		n := t.tag.Name
		if n == tagtype {
			return true
		}
		if (n == "ul" || n == "ol") && tagtype == "li" {
			return true
		}
		if n == "dl" && (tagtype == "dd" || tagtype == "dt") {
			return true
		}
		if n == "table" && (tagtype == "td" || tagtype == "th" || tagtype == "tr") {
			return true
		}
		if (n == "td" || n == "th") && blockHtmlTags[tagtype] {
			return true
		}
		if tagtype == "p" && blockHtmlTags[n] {
			return true
		}
		if (n == "tr" || n == "thead" || n == "tbody" || n == "tfoot") && (tagtype == "td" || tagtype == "th") {
			return true
		}
		if n == "body" || n == "html" {
			return true
		}
		return false
	case tagOpen:
		return closesTag(t.tag.Name, tagtype)
	}
	return false
}

// consumeClose consumes the closing tag for tagtype if present.
func (r *htmlReader) consumeClose(tagtype string) {
	t := r.peek()
	if t != nil && !t.isText && t.kind == tagClose && t.tag.Name == tagtype {
		r.pos++
	}
}

func attrFromTag(tag HTMLTag) Attr {
	return attrFromHTML(tag.Attrs)
}

// parseBlocks parses blocks until stop(tok) or eof.
func (r *htmlReader) parseBlocks(stop func(*htok) bool) []Block {
	var out []Block
	for !r.eof() {
		t := r.peek()
		if stop(t) {
			break
		}
		bs := r.block()
		out = append(out, bs...)
	}
	return out
}

func (r *htmlReader) parseBlocksIn(tagtype string) []Block {
	var out []Block
	for !r.eof() {
		if r.atCloseOf(tagtype) {
			break
		}
		bs := r.block()
		out = append(out, bs...)
	}
	r.consumeClose(tagtype)
	return out
}

func (r *htmlReader) block() []Block {
	t := r.peek()
	if t == nil {
		return nil
	}
	if t.isText {
		if strings.TrimSpace(t.text) == "" {
			r.pos++
