	return r.plain()
}

func (r *htmlReader) parseHead() {
	for !r.eof() {
		t := r.peek()
		if !t.isText && t.kind == tagClose && t.tag.Name == "head" {
			r.pos++
			return
		}
		if !t.isText && t.kind == tagOpen && t.tag.Name == "body" {
