package main

import (
	"html"
	"strconv"
	"strings"
	"unicode"
)

// ---- HTML tokenizer ----

type htok struct {
	kind htmlTagKind // tagOpen, tagClose, tagComment, tagDecl
	isText bool
	text   string // for text tokens (already entity-decoded)
	tag    HTMLTag
}

var rawTextTags = map[string]bool{"script": true, "style": true, "textarea": true, "title": true}

func tokenizeHTML(s string) []htok {
	rs := []rune(s)
	var toks []htok
	i := 0
	var text strings.Builder
	flush := func() {
		if text.Len() > 0 {
			toks = append(toks, htok{isText: true, text: html.UnescapeString(text.String())})
			text.Reset()
		}
	}
	for i < len(rs) {
		if rs[i] == '<' {
			if tag, n, ok := parseHTMLTag(rs, i); ok {
				flush()
				toks = append(toks, htok{kind: tag.Kind, tag: tag})
				i += n
				if tag.Kind == tagOpen && rawTextTags[tag.Name] && !tag.SelfClosing {
					// raw text until closing tag
					end := indexRunesFold(rs, i, "</"+tag.Name)
					if end < 0 {
						end = len(rs)
					}
					raw := string(rs[i:end])
					toks = append(toks, htok{isText: true, text: raw})
					i = end
				}
				continue
			}
		}
		text.WriteRune(rs[i])
		i++
	}
	flush()
	return toks
}

func indexRunesFold(rs []rune, from int, s string) int {
	ls := []rune(strings.ToLower(s))
	for i := from; i+len(ls) <= len(rs); i++ {
		match := true
		for j, r := range ls {
			if unicode.ToLower(rs[i+j]) != r {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

// ---- HTML reader ----

type htmlReader struct {
	toks        []htok
	pos         int
	exts        *ExtSet
	opts        *ReaderOptions
	meta        *MetaMap
	identifiers map[string]bool
	warnings    []string
	inChapter   bool
	inPlain     bool
	inTable     bool
	notes       map[string][]Block
}

func readHTML(input string, exts *ExtSet, opts *ReaderOptions) (*Pandoc, []string) {
	input = strings.ReplaceAll(input, "\r\n", "\n")
	r := &htmlReader{toks: tokenizeHTML(input), exts: exts, opts: opts, meta: newMetaMap(), identifiers: map[string]bool{}}
	blocks := r.parseBlocks(func(t *htok) bool { return false })
	// strip leading/trailing empty
	return &Pandoc{Meta: r.meta, Blocks: blocks}, r.warnings
}

func (r *htmlReader) eof() bool { return r.pos >= len(r.toks) }

func (r *htmlReader) peek() *htok {
	if r.pos < len(r.toks) {
		return &r.toks[r.pos]
	}
	return nil
}

func (r *htmlReader) next() *htok {
	t := r.peek()
	if t != nil {
		r.pos++
	}
	return t
}

func isBlockLevelName(name string) bool {
	return blockHtmlTags[name] && !eitherBlockOrInlineTags[name]
}

// closes: does an opening tag t1 implicitly close an open element t2?
func closesTag(t1, t2 string) bool {
	switch t2 {
	case "body", "html":
		return false
	}
	if t1 == "body" && t2 == "head" {
		return true
	}
	if t1 == "a" && t2 == "a" {
		return true
	}
	if t1 == "li" && t2 == "li" {
		return true
	}
	if t1 == "th" && (t2 == "th" || t2 == "td") {
		return true
	}
	if t1 == "td" && (t2 == "th" || t2 == "td") {
		return true
	}
	if t1 == "tr" && (t2 == "th" || t2 == "td" || t2 == "tr") {
		return true
	}
	if (t1 == "dd" || t1 == "dt") && (t2 == "dt" || t2 == "dd") {
		return true
	}
	if t2 == "p" {
		switch t1 {
		case "address", "article", "aside", "blockquote", "dir", "div", "dl", "fieldset", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hr", "menu", "nav", "ol", "p", "pre", "section", "table", "ul":
			return true
		}
	}
	if t1 == "meta" && t2 == "meta" {
		return true
	}
	switch t2 {
	case "option", "style", "script", "textarea", "title":
		return true
	}
	if t1 == "thead" && t2 == "colgroup" {
		return true
	}
	if t1 == "tfoot" && (t2 == "thead" || t2 == "colgroup") {
		return true
	}
	if t1 == "tbody" && (t2 == "tbody" || t2 == "tfoot" || t2 == "thead" || t2 == "colgroup") {
		return true
	}
	switch t1 {
	case "h1", "h2", "h3", "h4", "h5", "h6", "dl", "ol", "ul", "table", "div", "main", "p":
		switch t2 {
		case "h1", "h2", "h3", "h4", "h5", "h6", "p":
			return true
		}
	}
	if blockHtmlTags[t1] && !blockHtmlTags[t2] && !eitherBlockOrInlineTags[t2] {
		return true
	}
	return false
}

// atCloseOf checks whether the current token closes the given open tag (without consuming unless it's the exact close).
func (r *htmlReader) atCloseOf(tagtype string) bool {
	t := r.peek()
	if t == nil {
		return true
	}
	if t.isText {
		return false
	}
	switch t.kind {
	case tagClose:
		n := t.tag.Name
		if n == tagtype {
			return true
		}
		if (n == "ul" || n == "ol") && tagtype == "li" {
			return true
		}
		if n == "dl" && (tagtype == "dd" || tagtype == "dt") {
			return true
		}
		if n == "table" && (tagtype == "td" || tagtype == "th" || tagtype == "tr") {
			return true
		}
		if (n == "td" || n == "th") && blockHtmlTags[tagtype] {
			return true
		}
		if tagtype == "p" && blockHtmlTags[n] {
			return true
		}
		if (n == "tr" || n == "thead" || n == "tbody" || n == "tfoot") && (tagtype == "td" || tagtype == "th") {
			return true
		}
		if n == "body" || n == "html" {
			return true
		}
		return false
	case tagOpen:
		return closesTag(t.tag.Name, tagtype)
	}
	return false
}

// consumeClose consumes the closing tag for tagtype if present.
func (r *htmlReader) consumeClose(tagtype string) {
	t := r.peek()
	if t != nil && !t.isText && t.kind == tagClose && t.tag.Name == tagtype {
		r.pos++
	}
}

func attrFromTag(tag HTMLTag) Attr {
	return attrFromHTML(tag.Attrs)
}

// parseBlocks parses blocks until stop(tok) or eof.
func (r *htmlReader) parseBlocks(stop func(*htok) bool) []Block {
	var out []Block
	for !r.eof() {
		t := r.peek()
		if stop(t) {
			break
		}
		bs := r.block()
		out = append(out, bs...)
	}
	return out
}

func (r *htmlReader) parseBlocksIn(tagtype string) []Block {
	var out []Block
	for !r.eof() {
		if r.atCloseOf(tagtype) {
			break
		}
		bs := r.block()
		out = append(out, bs...)
	}
	r.consumeClose(tagtype)
	return out
}

func (r *htmlReader) block() []Block {
	t := r.peek()
	if t == nil {
		return nil
	}
	if t.isText {
		if strings.TrimSpace(t.text) == "" {
			r.pos++
			return nil
		}
		return r.plain()
	}
	switch t.kind {
	case tagComment:
		r.pos++
		if r.exts.Has("raw_html") {
			return []Block{&RawBlock{Format: "html", Text: t.tag.Raw}}
		}
		return nil
	case tagDecl:
		r.pos++
		return nil
	case tagClose:
		// stray close tag: skip
		r.pos++
		return nil
	}
	name := t.tag.Name
	switch name {
	case "html", "body":
		r.pos++
		return nil
	case "head":
		r.pos++
		r.parseHead()
		return nil
	case "p":
		r.pos++
		ils := r.parseInlinesIn("p")
		ils = trimInlines(ils)
		if len(ils) == 0 {
			return nil
		}
		return []Block{&Para{Inlines: ils}}
	case "h1", "h2", "h3", "h4", "h5", "h6":
		r.pos++
		level := int(name[1] - '0')
		ils := trimInlines(r.parseInlinesIn(name))
		attr := attrFromTag(t.tag)
		if attr.ID == "" && r.exts.Has("auto_identifiers") {
			attr.ID = uniqueIdent(ils, r.identifiers, r.exts.Has("gfm_auto_identifiers"), r.exts.Has("ascii_identifiers"))
		}
		if attr.ID != "" {
			r.identifiers[attr.ID] = true
		}
		if name == "h1" && attr.HasClass("title") {
			// body title: skip
			return nil
		}
		return []Block{&Header{Level: level, Attr: attr, Inlines: ils}}
	case "blockquote":
		r.pos++
		bs := r.parseBlocksIn("blockquote")
		return []Block{&BlockQuote{Blocks: bs}}
	case "pre":
		return r.codeBlock()
	case "ul":
		return r.bulletList()
	case "ol":
		return r.orderedList()
	case "dl":
		return r.definitionList()
	case "table":
		return r.table()
	case "hr":
		r.pos++
		r.consumeClose("hr")
		return []Block{&HorizontalRule{}}
	case "figure":
		return r.figure()
	case "div", "main", "section", "article", "aside", "nav", "header", "footer", "address", "details", "summary", "fieldset", "form", "center", "dir", "menu", "hgroup", "noscript", "output", "canvas", "video", "audio", "iframe", "object", "map", "embed", "progress", "button", "applet", "frameset", "noframes", "isindex", "colgroup", "col", "textarea", "caption", "tbody", "thead", "tfoot", "tr", "td", "th", "li", "dt", "dd":
		if name == "li" || name == "dt" || name == "dd" || name == "tr" || name == "td" || name == "th" || name == "tbody" || name == "thead" || name == "tfoot" || name == "caption" || name == "col" || name == "colgroup" {
			// stray; parse contents as blocks
			r.pos++
			bs := r.parseBlocksIn(name)
			return bs
		}
		return r.div()
	case "script", "style":
		r.pos++
		// skip raw text and close
		if n := r.peek(); n != nil && n.isText {
			r.pos++
		}
		r.consumeClose(name)
		if r.exts.Has("raw_html") {
			return []Block{&RawBlock{Format: "html", Text: t.tag.Raw}}
		}
		return nil
	case "title", "meta", "link", "base":
		r.pos++
		if name == "title" {
			if n := r.peek(); n != nil && n.isText {
				r.pos++
			}
			r.consumeClose("title")
		}
		return nil
	}
	if blockHtmlTags[name] {
		return r.div()
	}
	// inline content at block level -> Plain
	return r.plain()
}

func (r *htmlReader) parseHead() {
	for !r.eof() {
		t := r.peek()
		if !t.isText && t.kind == tagClose && t.tag.Name == "head" {
			r.pos++
			return
		}
		if !t.isText && t.kind == tagOpen && t.tag.Name == "body" {
			return
		}
		if !t.isText && t.kind == tagOpen {
			switch t.tag.Name {
			case "title":
				r.pos++
				title := ""
				if n := r.peek(); n != nil && n.isText {
					title = html.UnescapeString(n.text)
					r.pos++
				}
				r.consumeClose("title")
				title = strings.Join(strings.Fields(title), " ")
				if title != "" {
					if _, ok := r.meta.Get("title"); !ok {
						r.meta.Set("title", &MetaInlines{Inlines: textToInlines(title)})
					}
				}
				continue
			case "meta":
				r.pos++
				name, _ := t.tag.Attr("name")
				content, _ := t.tag.Attr("content")
				if name != "" && content != "" {
					switch name {
					case "author":
						val := &MetaInlines{Inlines: textToInlines(content)}
						if old, ok := r.meta.Get("author"); ok {
							if l, ok := old.(*MetaList); ok {
								l.Items = append(l.Items, val)
							} else {
								r.meta.Set("author", &MetaList{Items: []MetaValue{old, val}})
							}
						} else {
							r.meta.Set("author", val)
						}
					case "generator", "viewport":
					default:
						if _, ok := r.meta.Get(name); !ok {
							r.meta.Set(name, &MetaString{Text: content})
						}
					}
				}
				continue
			}
		}
		r.pos++
	}
}

func textToInlines(s string) []Inline {
	var out []Inline
	words := strings.Fields(s)
	for i, w := range words {
		if i > 0 {
			out = append(out, &Space{})
		}
		out = append(out, &Str{Text: w})
	}
	return out
}

func (r *htmlReader) plain() []Block {
	ils := r.parseInlinesUntilBlock()
	ils = trimInlines(ils)
	if len(ils) == 0 {
		return nil
	}
	return []Block{&Plain{Inlines: ils}}
}

func (r *htmlReader) parseInlinesUntilBlock() []Inline {
	var out []Inline
	for !r.eof() {
		t := r.peek()
		if !t.isText && (t.kind == tagOpen || t.kind == tagClose) && isBlockLevelName(t.tag.Name) {
			break
		}
		if !t.isText && t.kind == tagClose {
			// stray close of inline tag: skip
			if isBlockLevelName(t.tag.Name) {
				break
			}
		}
		ils := r.inline()
		out = meldInlines(out, ils)
	}
	return out
}

func (r *htmlReader) parseInlinesIn(tagtype string) []Inline {
	var out []Inline
	for !r.eof() {
		if r.atCloseOf(tagtype) {
			break
		}
		ils := r.inline()
		out = meldInlines(out, ils)
	}
	r.consumeClose(tagtype)
	return out
}

func (r *htmlReader) div() []Block {
	t := r.next()
	name := t.tag.Name
	attr := attrFromTag(t.tag)
	if t.tag.SelfClosing {
		return nil
	}
	bs := r.parseBlocksIn(name)
	switch name {
	case "section", "article", "aside", "nav", "header", "footer", "main", "details", "summary", "address", "fieldset", "form", "center", "dir", "menu", "hgroup", "figure":
		if name != "div" {
			attr.Classes = append([]string{name}, attr.Classes...)
		}
	}
	if name == "div" || r.exts.Has("native_divs") || true {
		return []Block{&Div{Attr: attr, Blocks: bs}}
	}
	return bs
}

func (r *htmlReader) codeBlock() []Block {
	t := r.next()
	attr := attrFromTag(t.tag)
	// contents: raw text until </pre>
	var sb strings.Builder
	var codeAttr Attr
	for !r.eof() {
		n := r.peek()
		if !n.isText && n.kind == tagClose && n.tag.Name == "pre" {
			r.pos++
			break
		}
		if !n.isText && n.kind == tagOpen && n.tag.Name == "code" {
			codeAttr = attrFromTag(n.tag)
			r.pos++
			continue
		}
		if !n.isText && n.kind == tagClose && n.tag.Name == "code" {
			r.pos++
			continue
		}
		if !n.isText && n.kind == tagOpen && n.tag.Name == "br" {
			sb.WriteString("\n")
			r.pos++
			continue
		}
		if n.isText {
			sb.WriteString(n.text)
		}
		r.pos++
	}
	// merge attrs
	for _, c := range codeAttr.Classes {
		c = strings.TrimPrefix(c, "language-")
		if c == "sourceCode" {
			continue
		}
		if !attr.HasClass(c) {
			attr.Classes = append(attr.Classes, c)
		}
	}
	if attr.ID == "" {
		attr.ID = codeAttr.ID
	}
	var classes []string
	for _, c := range attr.Classes {
		c = strings.TrimPrefix(c, "language-")
		if c == "sourceCode" {
			continue
		}
		classes = append(classes, c)
	}
	attr.Classes = classes
	text := sb.String()
	// remove leading newline and trailing whitespace lines
	text = strings.TrimPrefix(text, "\n")
	text = strings.TrimRight(text, "\n ")
	return []Block{&CodeBlock{Attr: attr, Text: text}}
}

func (r *htmlReader) listItems(listTag string) [][]Block {
	var items [][]Block
	for !r.eof() {
		t := r.peek()
		if t.isText {
			if strings.TrimSpace(t.text) == "" {
				r.pos++
				continue
			}
			// text directly in list: treat as item content
			items = append(items, r.plain())
			continue
		}
		if t.kind == tagClose && t.tag.Name == listTag {
			r.pos++
			break
		}
		if t.kind == tagClose {
			r.pos++
			continue
		}
		if t.kind == tagComment || t.kind == tagDecl {
			r.pos++
			continue
		}
		if t.tag.Name == "li" {
			r.pos++
			bs := r.parseBlocksIn("li")
			items = append(items, bs)
			continue
		}
		// other content inside list
		bs := r.block()
		if len(bs) > 0 {
			items = append(items, bs)
		}
	}
	return items
}

func (r *htmlReader) bulletList() []Block {
	r.next()
	items := r.listItems("ul")
	return []Block{&BulletList{Items: items}}
}

func (r *htmlReader) orderedList() []Block {
	t := r.next()
	attrs := ListAttributes{Start: 1, Style: DefaultStyle, Delim: DefaultDelim}
	if s, ok := t.tag.Attr("start"); ok {
		if n, err := strconv.Atoi(strings.TrimSpace(s)); err == nil {
			attrs.Start = n
		}
	}
	sty := ""
	if v, ok := t.tag.Attr("type"); ok {
		sty = v
	}
	if cls, ok := t.tag.Attr("class"); ok {
		for _, c := range strings.Fields(cls) {
			switch c {
			case "decimal":
				sty = "1"
			case "lower-alpha", "lower-latin":
				sty = "a"
			case "upper-alpha", "upper-latin":
				sty = "A"
			case "lower-roman":
				sty = "i"
			case "upper-roman":
				sty = "I"
			case "example":
				attrs.Style = Example
			}
		}
	}
	if v, ok := t.tag.Attr("style"); ok {
		v = strings.ReplaceAll(v, " ", "")
		switch {
		case strings.Contains(v, "list-style-type:decimal"):
			sty = "1"
		case strings.Contains(v, "list-style-type:lower-alpha"), strings.Contains(v, "list-style-type:lower-latin"):
			sty = "a"
		case strings.Contains(v, "list-style-type:upper-alpha"), strings.Contains(v, "list-style-type:upper-latin"):
			sty = "A"
		case strings.Contains(v, "list-style-type:lower-roman"):
			sty = "i"
		case strings.Contains(v, "list-style-type:upper-roman"):
			sty = "I"
		}
	}
	switch sty {
	case "1":
		attrs.Style = Decimal
	case "a":
		attrs.Style = LowerAlpha
	case "A":
		attrs.Style = UpperAlpha
	case "i":
		attrs.Style = LowerRoman
	case "I":
		attrs.Style = UpperRoman
	}
	items := r.listItems("ol")
	return []Block{&OrderedList{Attrs: attrs, Items: items}}
}

func (r *htmlReader) definitionList() []Block {
	r.next()
	var items []DefItem
	var cur *DefItem
	for !r.eof() {
		t := r.peek()
		if t.isText {
			r.pos++
			continue
		}
		if t.kind == tagClose && t.tag.Name == "dl" {
			r.pos++
			break
		}
		if t.kind != tagOpen {
			r.pos++
			continue
		}
		switch t.tag.Name {
		case "dt":
			r.pos++
			term := trimInlines(r.parseInlinesIn("dt"))
			if cur != nil && len(cur.Defs) == 0 && len(cur.Term) > 0 {
				// multiple terms: pandoc joins with LineBreak? It creates separate items? Keep simple: join with LineBreak.
				cur.Term = append(append(cur.Term, &LineBreak{}), term...)
				continue
			}
			if cur != nil {
				items = append(items, *cur)
			}
			cur = &DefItem{Term: term}
		case "dd":
			r.pos++
			bs := r.parseBlocksIn("dd")
			if cur == nil {
				cur = &DefItem{}
			}
			cur.Defs = append(cur.Defs, bs)
		default:
			r.block()
		}
	}
	if cur != nil {
		items = append(items, *cur)
	}
	return []Block{&DefinitionList{Items: items}}
}

func (r *htmlReader) figure() []Block {
	t := r.next()
	attr := attrFromTag(t.tag)
	var capt []Block
	var content []Block
	for !r.eof() {
		n := r.peek()
		if n.isText {
			if strings.TrimSpace(n.text) == "" {
				r.pos++
				continue
			}
		}
		if !n.isText && n.kind == tagClose && n.tag.Name == "figure" {
			r.pos++
			break
		}
		if !n.isText && n.kind == tagOpen && n.tag.Name == "figcaption" {
			r.pos++
			bs := r.parseBlocksIn("figcaption")
			capt = bs
			continue
		}
		content = append(content, r.block()...)
	}
	// convert Plain to Plain (pandoc keeps Plain for images)
	return []Block{&Figure{Attr: attr, Caption: Caption{Blocks: capt}, Blocks: content}}
}

// ---- tables ----

func (r *htmlReader) table() []Block {
	t := r.next()
	attr := attrFromTag(t.tag)
	tbl := &Table{Attr: attr}
	var headRows []Row
	var bodyRows []Row
	var footRows []Row
	var widths []ColWidth
	inSection := ""
	for !r.eof() {
		n := r.peek()
		if n.isText {
			r.pos++
			continue
		}
		if n.kind == tagClose && n.tag.Name == "table" {
			r.pos++
			break
		}
		if n.kind != tagOpen {
			r.pos++
			continue
		}
		switch n.tag.Name {
		case "caption":
			r.pos++
			bs := r.parseBlocksIn("caption")
			tbl.Caption = Caption{Blocks: bs}
		case "colgroup":
			r.pos++
		case "col":
			r.pos++
			w := ColWidth{Default: true}
			if st, ok := n.tag.Attr("style"); ok {
				st = strings.ReplaceAll(st, " ", "")
				if i := strings.Index(st, "width:"); i >= 0 {
					v := st[i+6:]
					if j := strings.IndexAny(v, ";"); j >= 0 {
						v = v[:j]
					}
					if strings.HasSuffix(v, "%") {
						if f, err := strconv.ParseFloat(strings.TrimSuffix(v, "%"), 64); err == nil {
							w = ColWidth{Width: f / 100}
						}
					}
				}
			} else if wv, ok := n.tag.Attr("width"); ok {
				if strings.HasSuffix(wv, "%") {
					if f, err := strconv.ParseFloat(strings.TrimSuffix(wv, "%"), 64); err == nil {
						w = ColWidth{Width: f / 100}
					}
				}
			}
			widths = append(widths, w)
			r.consumeClose("col")
		case "thead":
			r.pos++
			inSection = "thead"
		case "tbody":
			r.pos++
			inSection = "tbody"
		case "tfoot":
			r.pos++
			inSection = "tfoot"
		case "tr":
			row, allTh := r.tableRow()
			switch inSection {
			case "thead":
				headRows = append(headRows, row)
			case "tfoot":
				footRows = append(footRows, row)
			default:
				if allTh && len(bodyRows) == 0 && len(headRows) == 0 && inSection == "" {
					headRows = append(headRows, row)
				} else {
					bodyRows = append(bodyRows, row)
				}
			}
		default:
			r.pos++
		}
	}
	ncols := 0
	for _, rows := range [][]Row{headRows, bodyRows, footRows} {
		for _, row := range rows {
			n := 0
			for _, c := range row.Cells {
				n += c.ColSpan
			}
			if n > ncols {
				ncols = n
			}
		}
	}
	for i := 0; i < ncols; i++ {
		cs := ColSpec{Align: AlignDefault, Width: ColWidth{Default: true}}
		if i < len(widths) {
			cs.Width = widths[i]
		}
		// alignment from first body row cells
		tbl.ColSpecs = append(tbl.ColSpecs, cs)
	}
	// derive column alignment from header/first row cells
	for i := range tbl.ColSpecs {
		for _, rows := range [][]Row{headRows, bodyRows} {
			if len(rows) > 0 && i < len(rows[0].Cells) {
				if rows[0].Cells[i].Align != AlignDefault {
					tbl.ColSpecs[i].Align = rows[0].Cells[i].Align
					break
				}
			}
		}
	}
	tbl.Head = TableHead{Rows: headRows}
	tbl.Bodies = []TableBody{{Body: bodyRows}}
	tbl.Foot = TableFoot{Rows: footRows}
	return []Block{tbl}
}

func (r *htmlReader) tableRow() (Row, bool) {
	t := r.next()
	row := Row{Attr: attrFromTag(t.tag)}
	allTh := true
	for !r.eof() {
		n := r.peek()
		if n.isText {
			r.pos++
			continue
		}
		if n.kind == tagClose && (n.tag.Name == "tr" || n.tag.Name == "table" || n.tag.Name == "thead" || n.tag.Name == "tbody" || n.tag.Name == "tfoot") {
			if n.tag.Name == "tr" {
				r.pos++
			}
			break
		}
		if n.kind == tagOpen && (n.tag.Name == "tr") {
			break
		}
		if n.kind == tagOpen && (n.tag.Name == "td" || n.tag.Name == "th") {
			if n.tag.Name == "td" {
				allTh = false
			}
			r.pos++
			cell := Cell{Attr: attrFromTag(n.tag), RowSpan: 1, ColSpan: 1, Align: AlignDefault}
			if v, ok := n.tag.Attr("rowspan"); ok {
				if k, err := strconv.Atoi(strings.TrimSpace(v)); err == nil && k > 0 {
					cell.RowSpan = k
				}
			}
			if v, ok := n.tag.Attr("colspan"); ok {
				if k, err := strconv.Atoi(strings.TrimSpace(v)); err == nil && k > 0 {
					cell.ColSpan = k
				}
			}
			if v, ok := n.tag.Attr("align"); ok {
				cell.Align = alignFromString(v)
			}
			if v, ok := n.tag.Attr("style"); ok {
				v2 := strings.ReplaceAll(v, " ", "")
				if i := strings.Index(v2, "text-align:"); i >= 0 {
					a := v2[i+11:]
					if j := strings.Index(a, ";"); j >= 0 {
						a = a[:j]
					}
					cell.Align = alignFromString(a)
				}
			}
			// remove align/style attrs used
			var kvs [][2]string
			for _, kv := range cell.Attr.KVs {
				if kv[0] == "rowspan" || kv[0] == "colspan" || kv[0] == "align" || (kv[0] == "style" && strings.Contains(kv[1], "text-align")) {
					continue
				}
				kvs = append(kvs, kv)
			}
			cell.Attr.KVs = kvs
			bs := r.parseBlocksIn(n.tag.Name)
			cell.Blocks = bs
			row.Cells = append(row.Cells, cell)
			continue
		}
		r.pos++
	}
	return row, allTh
}

func alignFromString(s string) Alignment {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "left":
		return AlignLeft
	case "right":
		return AlignRight
	case "center":
		return AlignCenter
	}
	return AlignDefault
}

// ---- inlines ----

func (r *htmlReader) inline() []Inline {
	t := r.next()
	if t == nil {
		return nil
	}
	if t.isText {
		return r.textToInlines(t.text)
	}
	switch t.kind {
	case tagComment:
		if r.exts.Has("raw_html") {
			return []Inline{&RawInline{Format: "html", Text: t.tag.Raw}}
		}
		return nil
	case tagDecl:
		return nil
	case tagClose:
		return nil
	}
	name := t.tag.Name
	attr := attrFromTag(t.tag)
	switch name {
	case "br":
		r.consumeClose("br")
		return []Inline{&LineBreak{}}
	case "img":
		src, _ := t.tag.Attr("src")
		alt, _ := t.tag.Attr("alt")
		title, _ := t.tag.Attr("title")
		var kvs [][2]string
		for _, kv := range attr.KVs {
			if kv[0] == "src" || kv[0] == "alt" || kv[0] == "title" {
				continue
			}
			kvs = append(kvs, kv)
		}
		attr.KVs = kvs
		r.consumeClose("img")
		return []Inline{&Image{Attr: attr, Inlines: textToInlines(alt), Target: Target{URL: escapeURI(src), Title: title}}}
	case "a":
		href, hasHref := t.tag.Attr("href")
		title, _ := t.tag.Attr("title")
		ils := r.parseInlinesIn("a")
		if !hasHref {
			// anchor without href: span with id
			if attr.ID != "" {
				return []Inline{&Span{Attr: attr, Inlines: ils}}
			}
			return ils
		}
		var kvs [][2]string
		for _, kv := range attr.KVs {
			if kv[0] == "href" || kv[0] == "title" {
				continue
			}
			kvs = append(kvs, kv)
		}
		attr.KVs = kvs
		return []Inline{&Link{Attr: attr, Inlines: ils, Target: Target{URL: escapeURI(href), Title: title}}}
	case "em", "i", "dfn":
		return []Inline{&Emph{Inlines: r.parseInlinesIn(name)}}
	case "strong", "b":
		return []Inline{&Strong{Inlines: r.parseInlinesIn(name)}}
	case "del", "s", "strike":
		return []Inline{&Strikeout{Inlines: r.parseInlinesIn(name)}}
	case "u", "ins":
		return []Inline{&Underline{Inlines: r.parseInlinesIn(name)}}
	case "sup":
		return []Inline{&Superscript{Inlines: r.parseInlinesIn(name)}}
	case "sub":
		return []Inline{&Subscript{Inlines: r.parseInlinesIn(name)}}
	case "small":
		return []Inline{&Span{Attr: Attr{Classes: []string{"small"}}, Inlines: r.parseInlinesIn(name)}}
	case "q":
		return []Inline{&Quoted{Type: DoubleQuote, Inlines: r.parseInlinesIn(name)}}
	case "cite":
		return []Inline{&Span{Attr: Attr{Classes: []string{"cite"}}, Inlines: r.parseInlinesIn(name)}}
	case "mark":
		return []Inline{&Span{Attr: Attr{Classes: []string{"mark"}}, Inlines: r.parseInlinesIn(name)}}
	case "code", "tt", "kbd", "samp", "var":
		var sb strings.Builder
		for !r.eof() {
			n := r.peek()
			if !n.isText && n.kind == tagClose && n.tag.Name == name {
				r.pos++
				break
			}
			if n.isText {
				sb.WriteString(n.text)
			} else if n.kind == tagOpen && n.tag.Name == "br" {
				sb.WriteString("\n")
			} else if n.kind == tagClose && isBlockLevelName(n.tag.Name) {
				break
			}
			r.pos++
		}
		if name != "code" && name != "tt" {
			attr.Classes = append([]string{name}, attr.Classes...)
		}
		return []Inline{&Code{Attr: attr, Text: strings.Join(strings.Fields(sb.String()), " ")}}
	case "span":
		ils := r.parseInlinesIn("span")
		if attr.ID == "" && len(attr.KVs) == 0 && len(attr.Classes) == 1 && attr.Classes[0] == "smallcaps" {
			return []Inline{&SmallCaps{Inlines: ils}}
		}
		if style, ok := attr.Get("style"); ok {
			if strings.Contains(strings.ReplaceAll(style, " ", ""), "font-variant:small-caps") {
				var kvs [][2]string
				for _, kv := range attr.KVs {
					if kv[0] != "style" {
						kvs = append(kvs, kv)
					}
				}
				attr.KVs = kvs
				if attr.IsNull() {
					return []Inline{&SmallCaps{Inlines: ils}}
				}
				return []Inline{&SmallCaps{Inlines: []Inline{&Span{Attr: attr, Inlines: ils}}}}
			}
		}
		if attr.HasClass("math") {
			txt := stringify(ils)
			if attr.HasClass("display") {
				return []Inline{&Math{Type: DisplayMath, Text: txt}}
			}
			return []Inline{&Math{Type: InlineMath, Text: txt}}
		}
		if attr.IsNull() && !r.exts.Has("native_spans") {
			return ils
		}
		return []Inline{&Span{Attr: attr, Inlines: ils}}
	case "script":
		if ty, _ := t.tag.Attr("type"); strings.HasPrefix(ty, "math/tex") {
			txt := ""
			if n := r.peek(); n != nil && n.isText {
				txt = n.text
				r.pos++
			}
			r.consumeClose("script")
			if strings.Contains(ty, "display") {
				return []Inline{&Math{Type: DisplayMath, Text: strings.TrimSpace(txt)}}
			}
			return []Inline{&Math{Type: InlineMath, Text: strings.TrimSpace(txt)}}
		}
		if n := r.peek(); n != nil && n.isText {
			r.pos++
		}
		r.consumeClose("script")
		return nil
	case "abbr", "time", "data", "bdi", "bdo", "wbr", "font", "big", "center", "label", "ruby", "rt", "rp", "acronym", "output", "nobr":
		if t.tag.SelfClosing || name == "wbr" {
			return nil
		}
		ils := r.parseInlinesIn(name)
		return ils
	case "input", "button", "select", "textarea", "iframe", "object", "embed", "video", "audio", "svg", "canvas", "map", "area", "source", "track", "picture", "noscript", "template", "meter", "progress":
		if t.tag.SelfClosing {
			return nil
		}
		// skip contents
		depth := 1
		for !r.eof() && depth > 0 {
			n := r.next()
			if n.isText {
				continue
			}
			if n.kind == tagOpen && n.tag.Name == name && !n.tag.SelfClosing {
				depth++
			} else if n.kind == tagClose && n.tag.Name == name {
				depth--
			}
		}
		return nil
	}
	if isBlockLevelName(name) {
		// block tag in inline context: should have been handled; back up and stop
		r.pos--
		return r.blockInInline(name)
	}
	// unknown inline tag: keep contents
	if t.tag.SelfClosing {
		return nil
	}
	return r.parseInlinesIn(name)
}

// blockInInline handles a block tag encountered where inlines are expected.
func (r *htmlReader) blockInInline(name string) []Inline {
	// consume the block and convert to inlines via stringify-ish approach: pandoc would end the inline context.
	t := r.next()
	_ = t
	bs := r.parseBlocksIn(name)
	var out []Inline
	for _, b := range bs {
		out = append(out, blockInlines(b)...)
	}
	return out
}

func (r *htmlReader) textToInlines(s string) []Inline {
	var out []Inline
	rs := []rune(s)
	i := 0
	for i < len(rs) {
		if unicode.IsSpace(rs[i]) {
			hasNL := false
			for i < len(rs) && unicode.IsSpace(rs[i]) {
				if rs[i] == '\n' {
					hasNL = true
				}
				i++
			}
			if hasNL {
				out = append(out, &SoftBreak{})
			} else {
				out = append(out, &Space{})
			}
			continue
		}
		start := i
		for i < len(rs) && !unicode.IsSpace(rs[i]) {
			i++
		}
		out = append(out, &Str{Text: string(rs[start:i])})
	}
	return out
}
