func toTableOfContents(sects []Block, depth int) *BulletList {
	var items [][]Block
	for _, b := range sects {
		if it := sectionToListItem(b, depth); len(it) > 0 {
			items = append(items, it)
		}
	}
	return &BulletList{Items: items}
}

func sectionToListItem(b Block, depth int) []Block {
	d, ok := b.(*Div)
	if !ok || len(d.Blocks) == 0 {
		return nil
	}
	h, ok := d.Blocks[0].(*Header)
	if !ok || len(d.Attr.Classes) == 0 || d.Attr.Classes[0] != "section" {
		return nil
	}
	if h.Level > depth || h.Attr.HasClass("unlisted") {
		return nil
	}
	num, _ := h.Attr.Get("number")
	title := removeNotesAndLinks(h.Inlines)
	if num != "" {
		title = append([]Inline{&Span{Attr: Attr{Classes: []string{"toc-section-number"}}, Inlines: []Inline{&Str{Text: num}}}, &Space{}}, title...)
	}
	var headerLink []Inline
	if d.Attr.ID == "" {
		headerLink = title
	} else {
		headerLink = []Inline{&Link{Attr: Attr{ID: "toc-" + d.Attr.ID}, Inlines: title, Target: Target{URL: "#" + d.Attr.ID}}}
	}
	var sub [][]Block
	for _, sb := range d.Blocks[1:] {
		if it := sectionToListItem(sb, depth); len(it) > 0 {
			sub = append(sub, it)
		}
	}
	out := []Block{&Plain{Inlines: headerLink}}
	if len(sub) > 0 {
		out = append(out, &BulletList{Items: sub})
	}
	return out
}

func removeNotesAndLinks(ils []Inline) []Inline {
	return walkInlines(ils, func(xs []Inline) []Inline {
		var out []Inline
		for _, il := range xs {
			switch x := il.(type) {
			case *Note:
				continue
			case *Link:
				out = append(out, x.Inlines...)
			default:
				out = append(out, il)
			}
		}
		return out
	})
}

