	for _, sb := range d.Blocks[1:] {
		if it := sectionToListItem(sb, depth); len(it) > 0 {
			sub = append(sub, it)
		}
	}
	out := []Block{&Plain{Inlines: headerLink}}
	if len(sub) > 0 {
		out = append(out, &BulletList{Items: sub})
	}
	return out
}

func removeNotesAndLinks(ils []Inline) []Inline {
	return walkInlines(ils, func(xs []Inline) []Inline {
		var out []Inline
		for _, il := range xs {
			switch x := il.(type) {
			case *Note:
				continue
			case *Link:
				out = append(out, x.Inlines...)
			default:
				out = append(out, il)
			}
		}
		return out
	})
}

