func (r *ltxReader) parseInlines(stop func() bool) []Inline {
	var out []Inline
	for !r.eof() {
		if stop() {
			break
		}
		ils, ok := r.inline()
		if !ok {
			break
		}
		out = meldInlines(out, ils)
	}
	return out
}

func (r *ltxReader) inline() ([]Inline, bool) {
	c := r.peek()
	switch {
	case c == '%':
		r.skipComment()
		return nil, true
	case c == '\n':
		r.pos++
		// blank line? handled by caller stop; here treat as softbreak
		for !r.eof() && (r.peek() == ' ' || r.peek() == '\t') {
			r.pos++
		}
		return []Inline{&SoftBreak{}}, true
	case c == ' ' || c == '\t' || c == '\r':
		for !r.eof() && (r.peek() == ' ' || r.peek() == '\t' || r.peek() == '\r') {
			r.pos++
		}
		return []Inline{&Space{}}, true
	case c == '{':
		arg, ok := r.braced()
		if !ok {
			r.pos++
			return nil, true
		}
		return r.parseInlinesStrKeepSpace(arg), true
	case c == '}':
		r.pos++
		return nil, true
	case c == '~':
		r.pos++
		return []Inline{&Str{Text: "\u00a0"}}, true
	case c == '$':
		return r.dollarMath(), true
	case c == '`':
		if r.peekAt(1) == '`' {
			r.pos += 2
			return r.quoted(DoubleQuote, "''"), true
		}
		r.pos++
		return r.quoted(SingleQuote, "'"), true
	case c == '\'':
		if r.peekAt(1) == '\'' {
			r.pos += 2
			return []Inline{&Str{Text: "\u201d"}}, true
		}
		r.pos++
		return []Inline{&Str{Text: "\u2019"}}, true
	case c == '-':
		if r.lookingAt("---") {
			r.pos += 3
			return []Inline{&Str{Text: "\u2014"}}, true
		}
		if r.lookingAt("--") {
			r.pos += 2
			return []Inline{&Str{Text: "\u2013"}}, true
		}
		r.pos++
		return []Inline{&Str{Text: "-"}}, true
	case c == '\\':
		return r.inlineCommand()
	case c == '&':
		r.pos++
		return nil, true
	case c == '#':
		r.pos++
		return []Inline{&Str{Text: "#"}}, true
	}
	// regular text run
	start := r.pos
	for !r.eof() {
		ch := r.peek()
		if ch == '\\' || ch == '{' || ch == '}' || ch == '$' || ch == '%' || ch == '~' || ch == '`' || ch == '\'' || ch == '-' || ch == '&' || unicode.IsSpace(ch) || ch == '#' {
			break
		}
		r.pos++
	}
	if r.pos == start {
		r.pos++
		return []Inline{&Str{Text: string(c)}}, true
	}
	return []Inline{&Str{Text: string(r.s[start:r.pos])}}, true
}

func (r *ltxReader) parseInlinesStrKeepSpace(s string) []Inline {
	q := r.sub(s)
	ils := q.parseInlines(func() bool { return false })
	r.warnings = append(r.warnings, q.warnings...)
	return ils
}

func (r *ltxReader) quoted(qt QuoteType, closer string) []Inline {
	var contents []Inline
	for !r.eof() {
		if r.lookingAt(closer) {
			r.pos += len(closer)
			return []Inline{&Quoted{Type: qt, Inlines: trimInlines(contents)}}
		}
		if r.peek() == '\n' && r.isBlankLineAheadFrom(r.pos+1) {
			break
		}
		ils, ok := r.inline()
		if !ok {
			break
		}
		contents = meldInlines(contents, ils)
	}
	open := "\u2018"
	if qt == DoubleQuote {
		open = "\u201c"
	}
	return meldInlines([]Inline{&Str{Text: open}}, contents)
}

func (r *ltxReader) isBlankLineAheadFrom(pos int) bool {
	for pos < len(r.s) && (r.s[pos] == ' ' || r.s[pos] == '\t') {
		pos++
	}
	return pos < len(r.s) && r.s[pos] == '\n'
}

func (r *ltxReader) dollarMath() []Inline {
	if r.lookingAt("$$") {
		r.pos += 2
		start := r.pos
		for !r.eof() && !r.lookingAt("$$") {
			r.pos++
		}
		body := string(r.s[start:r.pos])
		r.pos += 2
		return []Inline{&Math{Type: DisplayMath, Text: strings.TrimSpace(body)}}
	}
	r.pos++
	start := r.pos
	for !r.eof() && r.peek() != '$' {
		if r.peek() == '\\' {
			r.pos++
		}
		r.pos++
	}
	body := string(r.s[start:r.pos])
	r.pos++
	return []Inline{&Math{Type: InlineMath, Text: strings.TrimSpace(body)}}
}

func (r *ltxReader) inlineCommand() ([]Inline, bool) {
	save := r.pos
	name := r.controlSeq()
	if name == "" {
		return nil, true
	}
	// macros
	if m, ok := r.macros[name]; ok {
		var args []string
		for i := 0; i < m.nargs; i++ {
			a, ok := r.braced()
			if !ok {
				break
			}
			args = append(args, a)
		}
		body := m.body
		for i := len(args); i >= 1; i-- {
			body = strings.ReplaceAll(body, "#"+strconv.Itoa(i), args[i-1])
		}
		return r.parseInlinesStrKeepSpace(body), true
	}
	if acc, ok := ltxAccents[name]; ok && len(name) == 1 {
		// accent: next char or group
		var target rune
		if r.peek() == '{' {
			arg, _ := r.braced()
			rs := []rune(strings.TrimSpace(arg))
			if len(rs) == 0 {
				return []Inline{&Str{Text: accentStandalone(name)}}, true
			}
			target = rs[0]
			if len(rs) > 1 {
				if m, ok := acc[target]; ok {
					return []Inline{&Str{Text: string(m) + string(rs[1:])}}, true
				}
				return []Inline{&Str{Text: string(rs)}}, true
			}
		} else if r.peek() == '\\' {
			n := r.controlSeq()
			if n == "i" {
				target = 'i'
			} else if n == "j" {
				target = 'j'
			}
		} else if r.eof() {
			return nil, true
		} else {
			target = r.peek()
			r.pos++
		}
		if m, ok := acc[target]; ok {
			return []Inline{&Str{Text: string(m)}}, true
		}
		return []Inline{&Str{Text: string(target) + accentCombining(name)}}, true
	}
	switch name {
	case "\\":
		r.bracketed()
		// skip whitespace/newline after
		for !r.eof() && (r.peek() == ' ' || r.peek() == '\t') {
			r.pos++
		}
		if r.peek() == '\n' {
			r.pos++
		}
		return []Inline{&LineBreak{}}, true
	case "newline", "linebreak":
		return []Inline{&LineBreak{}}, true
	case "emph", "textit", "textsl", "it", "itshape", "slshape":
		if name == "it" || name == "itshape" || name == "slshape" {
			rest := r.restOfGroup()
			return []Inline{&Emph{Inlines: r.parseInlinesStr(rest)}}, true
		}
		arg, _ := r.braced()
		return []Inline{&Emph{Inlines: r.parseInlinesStr(arg)}}, true
	case "textbf", "bf", "bfseries":
		if name != "textbf" {
			rest := r.restOfGroup()
			return []Inline{&Strong{Inlines: r.parseInlinesStr(rest)}}, true
		}
		arg, _ := r.braced()
		return []Inline{&Strong{Inlines: r.parseInlinesStr(arg)}}, true
	case "texttt", "tt", "ttfamily":
		if name != "texttt" {
			rest := r.restOfGroup()
			return []Inline{&Code{Text: stringify(r.parseInlinesStr(rest))}}, true
		}
		arg, _ := r.braced()
		return []Inline{&Code{Text: stringify(r.parseInlinesStr(arg))}}, true
	case "textsc", "sc", "scshape":
		if name != "textsc" {
			rest := r.restOfGroup()
			return []Inline{&SmallCaps{Inlines: r.parseInlinesStr(rest)}}, true
		}
		arg, _ := r.braced()
		return []Inline{&SmallCaps{Inlines: r.parseInlinesStr(arg)}}, true
	case "textrm", "textsf", "textup", "textnormal", "textmd", "mbox", "hbox", "text", "rm", "sf", "upshape", "mdseries", "normalfont", "textsmaller", "textlarger", "lowercase", "uppercase", "MakeUppercase", "MakeLowercase":
		if name == "rm" || name == "sf" || name == "upshape" || name == "mdseries" || name == "normalfont" {
			return nil, true
		}
		arg, _ := r.braced()
		ils := r.parseInlinesStr(arg)
		if name == "uppercase" || name == "MakeUppercase" {
			ils = capitalizeInlines(ils)
		}
		return ils, true
	case "underline", "uline", "ul":
		arg, _ := r.braced()
		return []Inline{&Underline{Inlines: r.parseInlinesStr(arg)}}, true
	case "sout", "st", "strikeout", "strikethrough":
		arg, _ := r.braced()
		return []Inline{&Strikeout{Inlines: r.parseInlinesStr(arg)}}, true
	case "textsuperscript":
		arg, _ := r.braced()
		return []Inline{&Superscript{Inlines: r.parseInlinesStr(arg)}}, true
	case "textsubscript":
		arg, _ := r.braced()
		return []Inline{&Subscript{Inlines: r.parseInlinesStr(arg)}}, true
	case "footnote", "footnotetext", "thanks", "marginpar", "sidenote":
		r.bracketed()
		arg, _ := r.braced()
		bs := r.parseBlocksStr(arg)
		return []Inline{&Note{Blocks: bs}}, true
	case "href":
		url, _ := r.braced()
		r.bracketed()
		txt, _ := r.braced()
		return []Inline{&Link{Inlines: r.parseInlinesStr(txt), Target: Target{URL: strings.TrimSpace(url)}}}, true
	case "url", "nolinkurl", "path":
		var url string
		if r.peek() == '{' {
			url, _ = r.braced()
		} else {
			d := r.peek()
			r.pos++
			start := r.pos
			for !r.eof() && r.peek() != d {
				r.pos++
			}
			url = string(r.s[start:r.pos])
			r.pos++
		}
		url = strings.TrimSpace(url)
		if name == "nolinkurl" || name == "path" {
			return []Inline{&Code{Text: url}}, true
		}
		return []Inline{&Link{Attr: Attr{Classes: []string{"uri"}}, Inlines: []Inline{&Str{Text: url}}, Target: Target{URL: url}}}, true
	case "verb", "lstinline", "mintinline":
		if name == "mintinline" {
			r.braced()
		}
		if name == "lstinline" {
			r.bracketed()
		}
		var txt string
		if r.peek() == '{' && name != "verb" {
			txt, _ = r.braced()
		} else {
			d := r.peek()
			r.pos++
			start := r.pos
			for !r.eof() && r.peek() != d {
				r.pos++
			}
			txt = string(r.s[start:r.pos])
			r.pos++
		}
		return []Inline{&Code{Text: txt}}, true
	case "cite", "citep", "citet", "citealp", "citealt", "citeauthor", "citeyear", "citeyearpar", "textcite", "parencite", "autocite", "footcite", "nocite", "Citep", "Citet", "Textcite", "Parencite", "Autocite", "cite*", "citep*", "citet*", "fullcite", "citetitle", "smartcite", "supercite":
		var prefix, suffix string
		if o1, ok := r.bracketed(); ok {
			if o2, ok2 := r.bracketed(); ok2 {
				prefix, suffix = o1, o2
			} else {
				suffix = o1
			}
		}
		keysRaw, _ := r.braced()
		var cits []Citation
		keys := strings.Split(keysRaw, ",")
		mode := NormalCitation
		if name == "citet" || name == "textcite" || name == "Textcite" || name == "citealt" || name == "Citet" || name == "citet*" || name == "citeauthor" || name == "smartcite" {
			mode = AuthorInText
		}
		if name == "citeyear" || name == "citeyearpar" {
			mode = SuppressAuthor
		}
		var rawParts []string
		for i, k := range keys {
			k = strings.TrimSpace(k)
			if k == "" {
				continue
			}
			c := Citation{ID: k, Mode: mode}
			if i == 0 && prefix != "" {
				c.Prefix = r.parseInlinesStr(prefix)
			}
			if i == len(keys)-1 && suffix != "" {
				c.Suffix = r.parseInlinesStr(suffix)
			}
			cits = append(cits, c)
			rawParts = append(rawParts, "@"+k)
		}
		if name == "nocite" {
			return nil, true
		}
		var txt []Inline
		if mode == AuthorInText && len(cits) == 1 {
			txt = []Inline{&Str{Text: "@" + cits[0].ID}}
		} else {
			inner := strings.Join(rawParts, "; ")
			if prefix != "" {
				inner = prefix + " " + inner
			}
			if suffix != "" {
				inner = inner + ", " + suffix
			}
			txt = []Inline{&Str{Text: "[" + inner + "]"}}
		}
		return []Inline{&Cite{Citations: cits, Inlines: txt}}, true
	case "ref", "eqref", "pageref", "autoref", "cref", "Cref", "nameref", "vref":
		lab, _ := r.braced()
		lab = strings.TrimSpace(lab)
		txt := lab
		return []Inline{&Link{Attr: Attr{KVs: [][2]string{{"reference-type", "ref"}, {"reference", lab}}}, Inlines: []Inline{&Str{Text: txt}}, Target: Target{URL: "#" + lab}}}, true
	case "label":
		lab, _ := r.braced()
		return []Inline{&Span{Attr: Attr{ID: strings.TrimSpace(lab), Classes: nil, KVs: [][2]string{{"label", strings.TrimSpace(lab)}}}}}, true
	case "includegraphics":
		opt, _ := r.bracketed()
		src, _ := r.braced()
		attr := Attr{}
		for _, kv := range strings.Split(opt, ",") {
			kv = strings.TrimSpace(kv)
			if i := strings.Index(kv, "="); i > 0 {
				k := strings.TrimSpace(kv[:i])
				v := strings.TrimSpace(kv[i+1:])
				if k == "width" || k == "height" {
					v = latexDimToCSS(v)
					if v != "" {
						attr.KVs = append(attr.KVs, [2]string{k, v})
					}
				}
			}
		}
		src = strings.TrimSpace(src)
		return []Inline{&Image{Attr: attr, Inlines: []Inline{&Str{Text: "image"}}, Target: Target{URL: src}}}, true
	case "(":
		start := r.pos
		for !r.eof() && !r.lookingAt("\\)") {
			r.pos++
		}
		body := string(r.s[start:r.pos])
		r.pos += 2
		return []Inline{&Math{Type: InlineMath, Text: strings.TrimSpace(body)}}, true
	case "[":
		start := r.pos
		for !r.eof() && !r.lookingAt("\\]") {
			r.pos++
		}
		body := string(r.s[start:r.pos])
		r.pos += 2
		return []Inline{&Math{Type: DisplayMath, Text: strings.TrimSpace(body)}}, true
	case "begin":
		env := r.peekEnvName()
		_ = env
		r.pos = save
		// inline environment within paragraph: parse as block and flatten
		bs := r.environment()
		var out []Inline
		for _, b := range bs {
			out = append(out, blockInlines(b)...)
		}
		return out, true
	case "textcolor", "color", "colorbox", "fcolorbox":
		r.bracketed()
		r.braced()
		if name == "fcolorbox" {
			r.braced()
		}
		if name == "color" {
			return nil, true
		}
		arg, _ := r.braced()
		return r.parseInlinesStr(arg), true
	case "hspace", "hspace*", "vspace", "vspace*", "rule", "hskip", "vskip", "kern", "phantom", "hphantom", "vphantom", "setlength", "addtolength", "index", "glossary", "pagestyle", "thispagestyle", "setcounter", "addtocounter", "stepcounter", "refstepcounter", "vfill", "framebox", "makebox", "raisebox", "parbox", "scalebox", "resizebox", "rotatebox", "fbox", "hyphenation", "nocite", "bibliographystyle", "addcontentsline", "markboth", "markright", "enlargethispage", "linespread", "fontsize", "selectfont", "DeclareMathOperator", "input", "include", "usepackage", "documentclass", "newcounter", "newlength", "providecommand", "let", "global", "long", "noindent", "indent", "par", "newpage", "clearpage", "pagebreak", "nopagebreak", "samepage", "sloppy", "centering", "raggedright", "raggedleft", "small", "large", "Large", "LARGE", "huge", "Huge", "normalsize", "footnotesize", "scriptsize", "tiny", "maketitle", "tableofcontents", "listoffigures", "listoftables", "appendix", "frontmatter", "mainmatter", "backmatter", "bigskip", "medskip", "smallskip", "hrule", "vphantom*":
		switch name {
		case "hspace", "hspace*", "vspace", "vspace*", "hskip", "vskip", "kern", "phantom", "hphantom", "vphantom", "index", "glossary", "pagestyle", "thispagestyle", "stepcounter", "refstepcounter", "linespread", "input", "include", "newcounter", "newlength", "enlargethispage", "markright", "bibliographystyle", "nocite":
			r.braced()
		case "rule", "setlength", "addtolength", "setcounter", "addtocounter", "markboth", "fontsize", "DeclareMathOperator":
			r.bracketed()
			r.braced()
			r.braced()
		case "framebox", "makebox", "raisebox", "parbox", "scalebox", "resizebox", "rotatebox", "fbox":
			r.bracketed()
			r.bracketed()
			if name == "raisebox" || name == "scalebox" || name == "rotatebox" {
				r.braced()
			}
			if name == "resizebox" || name == "parbox" {
				r.braced()
				r.braced()
			}
			arg, _ := r.braced()
			return r.parseInlinesStr(arg), true
		case "usepackage", "documentclass", "addcontentsline":
			r.bracketed()
			r.braced()
			if name == "addcontentsline" {
				r.braced()
				r.braced()
			}
		case "providecommand":
			r.defineMacro(name)
		}
		return nil, true
	case "item":
		return []Inline{}, true
	case "and":
		return []Inline{&Str{Text: ";"}, &Space{}}, true
	case "textbackslash":
		return []Inline{&Str{Text: "\\"}}, true
	case "ensuremath":
		arg, _ := r.braced()
		return []Inline{&Math{Type: InlineMath, Text: arg}}, true
	case "symbol", "char":
		return nil, true
	case "frac", "sqrt", "sum", "int", "alpha", "beta", "gamma", "pi", "infty", "times", "cdot", "leq", "geq", "neq", "approx", "rightarrow", "leftarrow", "to", "mathbf", "mathrm", "mathcal", "mathbb":
		// math command outside math: treat as inline math raw
		r.pos = save
		cmd := r.readRawCommand()
		return []Inline{&Math{Type: InlineMath, Text: cmd}}, true
	}
	if sym, ok := ltxSymbolCmds[name]; ok {
		if sym == "" {
			return nil, true
		}
		return []Inline{&Str{Text: sym}}, true
	}
	// unknown command
	if r.exts.Has("raw_tex") {
		r.pos = save
		cmd := r.readRawCommand()
		return []Inline{&RawInline{Format: "latex", Text: cmd}}, true
	}
	line, col := r.lineCol(save)
	r.warnings = append(r.warnings, "[WARNING] Skipped '\\"+strings.TrimSuffix(name, " ")+"' at line "+strconv.Itoa(line)+" column "+strconv.Itoa(col))
	return nil, true
}

func (r *ltxReader) lineCol(pos int) (int, int) {
	line := 1
	col := 1
	for i := 0; i < pos && i < len(r.s); i++ {
		if r.s[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return line, col
}

func (r *ltxReader) readRawCommand() string {
	start := r.pos
	r.controlSeq()
	for {
		s := r.pos
		if _, ok := r.bracketed(); ok {
			continue
		}
		if _, ok := r.braced(); ok {
			continue
		}
		r.pos = s
		break
	}
	return strings.TrimRight(string(r.s[start:r.pos]), " ")
}

// restOfGroup: for declarations like \bf, consume the rest of the enclosing group text.
func (r *ltxReader) restOfGroup() string {
	start := r.pos
	depth := 0
	for !r.eof() {
		c := r.peek()
		if c == '\\' {
			r.pos += 2
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			if depth == 0 {
				break
			}
			depth--
		} else if c == '\n' && r.isBlankLineAheadFrom(r.pos+1) {
			break
		}
		r.pos++
	}
	return string(r.s[start:r.pos])
}

func accentStandalone(name string) string {
	switch name {
	case "'":
		return "´"
	case "`":
		return "`"
	case "^":
		return "^"
	case "\"":
		return "¨"
	case "~":
		return "~"
	}
	return ""
}

func accentCombining(name string) string {
	switch name {
	case "'":
		return "\u0301"
	case "`":
		return "\u0300"
	case "^":
		return "\u0302"
	case "\"":
		return "\u0308"
	case "~":
		return "\u0303"
	case "c":
		return "\u0327"
	case "v":
		return "\u030c"
	case "u":
		return "\u0306"
	case "=":
		return "\u0304"
	case ".":
		return "\u0307"
	case "k":
		return "\u0328"
	case "H":
		return "\u030b"
	case "r":
		return "\u030a"
	}
	return ""
}

func latexDimToCSS(v string) string {
	v = strings.TrimSpace(v)
	if strings.Contains(v, "\\textwidth") || strings.Contains(v, "\\linewidth") || strings.Contains(v, "\\columnwidth") {
		num := strings.TrimSpace(strings.NewReplacer("\\textwidth", "", "\\linewidth", "", "\\columnwidth", "").Replace(v))
		if num == "" {
			return "100%"
		}
		f, err := strconv.ParseFloat(num, 64)
		if err != nil {
			return ""
		}
		return strconv.FormatFloat(f*100, 'f', -1, 64) + "%"
	}
	if strings.Contains(v, "\\textheight") {
		num := strings.TrimSpace(strings.ReplaceAll(v, "\\textheight", ""))
		if num == "" {
			return "100%"
		}
		f, err := strconv.ParseFloat(num, 64)
		if err != nil {
			return ""
		}
		return strconv.FormatFloat(f*100, 'f', -1, 64) + "%"
	}
	for _, u := range []string{"cm", "mm", "in", "pt", "em", "ex", "px", "pc", "bp"} {
		if strings.HasSuffix(v, u) {
			if u == "bp" {
				return strings.TrimSuffix(v, "bp") + "pt"
			}
			return v
		}
	}
	return ""
}

func (r *ltxReader) resolveLabels(bs []Block) []Block {
	return bs
}
