package main

import (
	"strconv"
	"strings"
	"unicode"
)

// ---- A basic LaTeX reader ----

type ltxReader struct {
	s           []rune
	pos         int
	meta        *MetaMap
	identifiers map[string]bool
	warnings    []string
	exts        *ExtSet
	macros      map[string]ltxMacro
	inList      bool
	labels      map[string]string
}

type ltxMacro struct {
	nargs int
	body  string
}

func readLaTeX(input string, exts *ExtSet, opts *ReaderOptions) (*Pandoc, []string) {
	input = strings.ReplaceAll(input, "\r\n", "\n")
	r := &ltxReader{s: []rune(input), meta: newMetaMap(), identifiers: map[string]bool{}, exts: exts, macros: map[string]ltxMacro{}, labels: map[string]string{}}
	blocks := r.parseBlocks(func() bool { return false })
	blocks = r.resolveLabels(blocks)
	return &Pandoc{Meta: r.meta, Blocks: blocks}, r.warnings
}

func (r *ltxReader) eof() bool { return r.pos >= len(r.s) }
func (r *ltxReader) peek() rune {
	if r.pos < len(r.s) {
		return r.s[r.pos]
	}
	return 0
}
func (r *ltxReader) peekAt(n int) rune {
	if r.pos+n < len(r.s) {
		return r.s[r.pos+n]
	}
	return 0
}
func (r *ltxReader) lookingAt(s string) bool { return hasPrefixRunes(r.s, r.pos, s) }

// skipComment skips a % comment including the newline.
func (r *ltxReader) skipComment() bool {
	if r.peek() != '%' {
		return false
	}
	for !r.eof() && r.peek() != '\n' {
		r.pos++
	}
	if !r.eof() {
		r.pos++
	}
	// skip leading whitespace on next line
	for !r.eof() && (r.peek() == ' ' || r.peek() == '\t') {
		r.pos++
	}
	return true
}

// skipBlank skips whitespace and comments; returns number of newlines seen.
func (r *ltxReader) skipBlank() int {
	nl := 0
	for !r.eof() {
		c := r.peek()
		if c == '%' {
			r.skipComment()
			continue
		}
		if c == '\n' {
			nl++
			r.pos++
			continue
		}
		if c == ' ' || c == '\t' || c == '\r' {
			r.pos++
			continue
		}
		break
	}
	return nl
}

func (r *ltxReader) isBlankLineAhead() bool {
	save := r.pos
	defer func() { r.pos = save }()
	// current position is after a newline? check: skip spaces, expect newline
	for !r.eof() && (r.peek() == ' ' || r.peek() == '\t') {
		r.pos++
	}
	return r.peek() == '\n'
}

// controlSeq reads a control sequence at '\'. Returns name (without backslash).
func (r *ltxReader) controlSeq() string {
	if r.peek() != '\\' {
		return ""
	}
	r.pos++
	if r.eof() {
		return ""
	}
	if unicode.IsLetter(r.peek()) {
		start := r.pos
		for !r.eof() && unicode.IsLetter(r.peek()) {
			r.pos++
		}
		name := string(r.s[start:r.pos])
		// optional star
		if r.peek() == '*' {
			r.pos++
			name += "*"
		}
		// skip following whitespace (but not blank lines)
		for !r.eof() && (r.peek() == ' ' || r.peek() == '\t') {
			r.pos++
		}
		return name
	}
	c := r.peek()
	r.pos++
	return string(c)
}

func (r *ltxReader) peekControlSeq() string {
	save := r.pos
	n := r.controlSeq()
	r.pos = save
	return n
}

// braced reads {...} returning inner text (raw).
func (r *ltxReader) braced() (string, bool) {
	save := r.pos
	for !r.eof() && (r.peek() == ' ' || r.peek() == '\t') {
		r.pos++
	}
	if r.peek() != '{' {
		r.pos = save
		return "", false
	}
	r.pos++
	depth := 1
	start := r.pos
	for !r.eof() {
		c := r.peek()
		if c == '\\' {
			r.pos += 2
			continue
		}
		if c == '%' {
			r.skipComment()
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
			if depth == 0 {
				s := string(r.s[start:r.pos])
				r.pos++
				return s, true
			}
		}
		r.pos++
	}
	r.pos = save
	return "", false
}

// bracketed reads [...] returning inner text.
func (r *ltxReader) bracketed() (string, bool) {
	save := r.pos
	for !r.eof() && (r.peek() == ' ' || r.peek() == '\t') {
		r.pos++
	}
	if r.peek() != '[' {
		r.pos = save
		return "", false
	}
	r.pos++
	depth := 0
	start := r.pos
	for !r.eof() {
		c := r.peek()
		if c == '\\' {
			r.pos += 2
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
		} else if c == ']' && depth <= 0 {
			s := string(r.s[start:r.pos])
			r.pos++
			return s, true
		}
		r.pos++
	}
	r.pos = save
	return "", false
}

func (r *ltxReader) sub(s string) *ltxReader {
	q := &ltxReader{s: []rune(s), meta: r.meta, identifiers: r.identifiers, exts: r.exts, macros: r.macros, labels: r.labels, inList: r.inList}
	return q
}

func (r *ltxReader) parseInlinesStr(s string) []Inline {
	q := r.sub(s)
	ils := q.parseInlines(func() bool { return false })
	r.warnings = append(r.warnings, q.warnings...)
	return trimInlines(ils)
}

func (r *ltxReader) parseBlocksStr(s string) []Block {
	q := r.sub(s)
	bs := q.parseBlocks(func() bool { return false })
	r.warnings = append(r.warnings, q.warnings...)
	return bs
}

// ---- blocks ----

var ltxSectionLevels = map[string]int{"part": -1, "chapter": 0, "section": 1, "subsection": 2, "subsubsection": 3, "paragraph": 4, "subparagraph": 5}

func (r *ltxReader) parseBlocks(stop func() bool) []Block {
	var out []Block
	for {
		r.skipBlank()
		if r.eof() || stop() {
			break
		}
		bs := r.block()
		out = append(out, bs...)
	}
	return out
}

func (r *ltxReader) block() []Block {
	c := r.peek()
	if c == '\\' {
		name := r.peekControlSeq()
		switch {
		case name == "begin":
			return r.environment()
		case name == "end":
			// stray \end: skip it
			r.controlSeq()
			r.braced()
			return nil
		case ltxIsSectionCmd(name):
			r.controlSeq()
			return r.sectionCmd(name)
		case name == "item":
			// stray item outside list
			r.controlSeq()
			return r.paragraph()
		case name == "par":
			r.controlSeq()
			return nil
		case name == "documentclass" || name == "usepackage" || name == "maketitle" || name == "tableofcontents" || name == "newpage" || name == "clearpage" || name == "pagebreak" || name == "noindent" || name == "bibliographystyle" || name == "bibliography" || name == "setlength" || name == "setcounter" || name == "pagestyle" || name == "thispagestyle" || name == "hypersetup" || name == "geometry" || name == "frontmatter" || name == "mainmatter" || name == "backmatter" || name == "appendix" || name == "listoffigures" || name == "listoftables" || name == "linespread" || name == "vspace" || name == "vspace*" || name == "bigskip" || name == "medskip" || name == "smallskip" || name == "centering" || name == "raggedright" || name == "raggedleft" || name == "small" || name == "large" || name == "Large" || name == "LARGE" || name == "huge" || name == "Huge" || name == "normalsize" || name == "footnotesize" || name == "scriptsize" || name == "tiny" || name == "selectfont" || name == "makeatletter" || name == "makeatother" || name == "input" || name == "include" || name == "addcontentsline" || name == "printbibliography" || name == "nocite" || name == "label" || name == "index" || name == "newlength" || name == "providecommand" || name == "DeclareMathOperator" || name == "theoremstyle" || name == "newtheorem" || name == "numberwithin" || name == "graphicspath" || name == "PassOptionsToPackage" || name == "IfFileExists" || name == "urlstyle" || name == "hyphenation":
			r.controlSeq()
			r.bracketed()
			r.braced()
			if name == "IfFileExists" {
				r.braced()
				r.braced()
			}
			if name == "newtheorem" {
				r.bracketed()
				r.braced()
				r.bracketed()
			}
			if name == "label" {
				// handled inline normally; ignore stray
			}
			return nil
		case name == "title" || name == "author" || name == "date" || name == "subtitle" || name == "institute":
			r.controlSeq()
			r.bracketed()
			arg, _ := r.braced()
			ils := r.parseInlinesStr(arg)
			if name == "author" {
				// split on \and
				var auths []MetaValue
				for _, part := range splitLatexAnd(arg) {
					auths = append(auths, &MetaInlines{Inlines: r.parseInlinesStr(part)})
				}
				if len(auths) == 1 {
					r.meta.Set("author", auths[0])
				} else {
					r.meta.Set("author", &MetaList{Items: auths})
				}
			} else {
				r.meta.Set(name, &MetaInlines{Inlines: ils})
			}
			return nil
		case name == "newcommand" || name == "renewcommand" || name == "newcommand*" || name == "renewcommand*" || name == "def":
			r.controlSeq()
			r.defineMacro(name)
			return nil
		case name == "hrule" || name == "hrulefill":
			r.controlSeq()
			return []Block{&HorizontalRule{}}
		case name == "[":
			return r.paragraph()
		}
	}
	return r.paragraph()
}

func splitLatexAnd(s string) []string {
	var parts []string
	depth := 0
	start := 0
	rs := []rune(s)
	for i := 0; i < len(rs); i++ {
		switch rs[i] {
		case '{':
			depth++
		case '}':
			depth--
		case '\\':
			if depth == 0 && hasPrefixRunes(rs, i, "\\and") && (i+4 >= len(rs) || !unicode.IsLetter(rs[i+4])) {
				parts = append(parts, string(rs[start:i]))
				i += 4
				start = i
				i--
			}
		}
	}
	parts = append(parts, string(rs[start:]))
	var out []string
	for _, p := range parts {
		if strings.TrimSpace(p) != "" {
			out = append(out, strings.TrimSpace(p))
		}
	}
	return out
}

func ltxIsSectionCmd(name string) bool {
	_, ok := ltxSectionLevels[strings.TrimSuffix(name, "*")]
	return ok
}

func (r *ltxReader) sectionCmd(name string) []Block {
	unnumbered := strings.HasSuffix(name, "*")
	base := strings.TrimSuffix(name, "*")
	level := ltxSectionLevels[base]
	if level < 1 {
		// part/chapter: treat chapter as level 1? pandoc shifts so that chapter=1 when present? It uses level 0 -> Header 0? pandoc: chapter -> 1, section -> 2 when chapters present (via book class). Keep: chapter=1, section=2 handled by hasChapters.
	}
	r.bracketed() // short title
	arg, _ := r.braced()
	ils := r.parseInlinesStr(arg)
	attr := Attr{}
	if unnumbered {
		attr.Classes = append(attr.Classes, "unnumbered")
	}
	// label following
	r.skipBlank()
	if r.peekControlSeq() == "label" {
		r.controlSeq()
		lab, _ := r.braced()
		attr.ID = lab
	}
	if attr.ID == "" && r.exts.Has("auto_identifiers") {
		attr.ID = uniqueIdent(ils, r.identifiers, false, false)
	}
	r.identifiers[attr.ID] = true
	lvl := level
	if r.hasChapters() {
		lvl = level + 1
	}
	if lvl < 1 {
		lvl = 1
	}
	return []Block{&Header{Level: lvl, Attr: attr, Inlines: ils}}
}

func (r *ltxReader) hasChapters() bool {
	// if \chapter appears in the document
	s := string(r.s)
	return strings.Contains(s, "\\chapter") || strings.Contains(s, "\\part")
}

func (r *ltxReader) paragraph() []Block {
	ils := r.parseInlines(func() bool {
		// stop at blank line or block-level command/environment
		if r.peek() == '\n' {
			save := r.pos
			r.pos++
			blank := r.isBlankLineAhead()
			r.pos = save
			if blank {
				return true
			}
		}
		if r.peek() == '\\' {
			name := r.peekControlSeq()
			if name == "begin" {
				env := r.peekEnvName()
				if !ltxInlineEnvs[env] {
					return true
				}
			}
			if name == "end" || ltxIsSectionCmd(name) || name == "item" || name == "par" || name == "maketitle" || name == "tableofcontents" || name == "newpage" || name == "clearpage" || name == "hrule" {
				return true
			}
		}
		return false
	})
	ils = trimInlines(ils)
	if len(ils) == 0 {
		return nil
	}
	if len(ils) == 1 {
		if img, ok := ils[0].(*Image); ok {
			_ = img
		}
	}
	return []Block{&Para{Inlines: ils}}
}

var ltxInlineEnvs = map[string]bool{"math": true, "displaymath": true, "equation": true, "equation*": true, "align": true, "align*": true, "gather": true, "gather*": true, "multline": true, "multline*": true, "eqnarray": true, "eqnarray*": true, "alignat": true, "alignat*": true, "flalign": true, "flalign*": true}

func (r *ltxReader) peekEnvName() string {
	save := r.pos
	defer func() { r.pos = save }()
	if r.controlSeq() != "begin" {
		return ""
	}
	name, _ := r.braced()
	return name
}

// readEnvBody reads raw text until the matching \end{name}.
func (r *ltxReader) readEnvBody(name string) string {
	depth := 1
	start := r.pos
	beginS := "\\begin{" + name + "}"
	endS := "\\end{" + name + "}"
	for !r.eof() {
		if r.lookingAt(beginS) {
			depth++
			r.pos += len([]rune(beginS))
			continue
		}
		if r.lookingAt(endS) {
			depth--
			if depth == 0 {
				body := string(r.s[start:r.pos])
				r.pos += len([]rune(endS))
				return body
			}
			r.pos += len([]rune(endS))
			continue
		}
		r.pos++
	}
	return string(r.s[start:])
}

func (r *ltxReader) environment() []Block {
	r.controlSeq() // begin
	name, ok := r.braced()
	if !ok {
		return nil
	}
	switch name {
	case "document":
		return nil
	case "itemize", "enumerate", "description":
		return r.listEnv(name)
	case "quote", "quotation", "verse":
		body := r.readEnvBody(name)
		return []Block{&BlockQuote{Blocks: r.parseBlocksStr(body)}}
	case "verbatim", "lstlisting", "minted", "Verbatim", "alltt", "spverbatim", "BVerbatim", "LVerbatim", "code":
		attr := Attr{}
		if name == "lstlisting" || name == "Verbatim" {
			if opt, ok := r.bracketed(); ok {
				for _, kv := range strings.Split(opt, ",") {
					kv = strings.TrimSpace(kv)
					if strings.HasPrefix(kv, "language=") {
						attr.Classes = append(attr.Classes, strings.ToLower(strings.TrimPrefix(kv, "language=")))
					}
				}
			}
		}
		if name == "minted" {
			r.bracketed()
			if lang, ok := r.braced(); ok {
				attr.Classes = append(attr.Classes, lang)
			}
		}
		body := r.readEnvBody(name)
		body = strings.TrimPrefix(body, "\n")
		body = strings.TrimRight(body, "\n ")
		return []Block{&CodeBlock{Attr: attr, Text: body}}
	case "center", "flushleft", "flushright":
		body := r.readEnvBody(name)
		bs := r.parseBlocksStr(body)
		if name == "center" {
			return []Block{&Div{Attr: Attr{Classes: []string{"center"}}, Blocks: bs}}
		}
		return bs
	case "abstract":
		body := r.readEnvBody(name)
		bs := r.parseBlocksStr(body)
		r.meta.Set("abstract", &MetaBlocks{Blocks: bs})
		return nil
	case "figure", "figure*":
		r.bracketed()
		return r.figureEnv(name)
	case "table", "table*":
		r.bracketed()
		return r.tableEnv(name)
	case "tabular", "tabular*", "longtable", "tabularx":
		return r.tabular(name, nil, Attr{})
	case "titlepage", "frame", "minipage", "multicols", "small", "footnotesize", "sloppypar", "samepage", "adjustwidth", "landscape", "group", "singlespace", "spacing", "tcolorbox", "mdframed", "framed", "shaded", "snugshade":
		r.bracketed()
		if name == "minipage" || name == "multicols" || name == "spacing" {
			r.braced()
		}
		body := r.readEnvBody(name)
		return r.parseBlocksStr(body)
	case "thebibliography":
		r.braced()
		body := r.readEnvBody(name)
		return r.parseBlocksStr(body)
	}
	if ltxInlineEnvs[name] {
		body := r.readEnvBody(name)
		if name == "math" {
			return []Block{&Para{Inlines: []Inline{&Math{Type: InlineMath, Text: body}}}}
		}
		if name == "displaymath" {
			return []Block{&Para{Inlines: []Inline{&Math{Type: DisplayMath, Text: strings.TrimSpace(body)}}}}
		}
		full := "\\begin{" + name + "}" + body + "\\end{" + name + "}"
		return []Block{&Para{Inlines: []Inline{&Math{Type: DisplayMath, Text: full}}}}
	}
	// unknown environment: parse contents as blocks (pandoc wraps in Div? it just parses contents)
	r.bracketed()
	body := r.readEnvBody(name)
	bs := r.parseBlocksStr(body)
	if r.exts.Has("raw_tex") {
		return []Block{&RawBlock{Format: "latex", Text: "\\begin{" + name + "}" + body + "\\end{" + name + "}"}}
	}
	return []Block{&Div{Attr: Attr{Classes: []string{name}}, Blocks: bs}}
}

func (r *ltxReader) listEnv(name string) []Block {
	r.bracketed()
	body := r.readEnvBody(name)
	// split body by \item at depth 0
	rs := []rune(body)
	var items []string
	var labels []string
	depth := 0
	start := -1
	for i := 0; i < len(rs); i++ {
		c := rs[i]
		switch {
		case c == '\\' && hasPrefixRunes(rs, i, "\\begin{"):
			depth++
			i += 6
		case c == '\\' && hasPrefixRunes(rs, i, "\\end{"):
			depth--
			i += 4
		case c == '\\' && depth == 0 && hasPrefixRunes(rs, i, "\\item") && (i+5 >= len(rs) || !unicode.IsLetter(rs[i+5])):
			if start >= 0 {
				items = append(items, string(rs[start:i]))
			}
			i += 5
			// optional label
			j := i
			for j < len(rs) && (rs[j] == ' ' || rs[j] == '\t') {
				j++
			}
			lab := ""
			if j < len(rs) && rs[j] == '[' {
				d := 0
				k := j + 1
				for k < len(rs) {
					if rs[k] == '{' {
						d++
					} else if rs[k] == '}' {
						d--
					} else if rs[k] == ']' && d <= 0 {
						break
					}
					k++
				}
				lab = string(rs[j+1 : k])
				i = k + 1
			} else {
				i = j
			}
			labels = append(labels, lab)
			start = i
			i--
		case c == '\\':
			i++
		case c == '%':
			for i < len(rs) && rs[i] != '\n' {
				i++
			}
		}
	}
	if start >= 0 {
		items = append(items, string(rs[start:]))
	}
	old := r.inList
	r.inList = true
	defer func() { r.inList = old }()
	switch name {
	case "itemize":
		var out [][]Block
		for _, it := range items {
			out = append(out, r.listItemBlocks(it))
		}
		return []Block{&BulletList{Items: out}}
	case "enumerate":
		var out [][]Block
		for _, it := range items {
			out = append(out, r.listItemBlocks(it))
		}
		return []Block{&OrderedList{Attrs: ListAttributes{Start: 1, Style: Decimal, Delim: Period}, Items: out}}
	case "description":
		var out []DefItem
		for i, it := range items {
			term := r.parseInlinesStr(labels[i])
			out = append(out, DefItem{Term: term, Defs: [][]Block{r.listItemBlocks(it)}})
		}
		return []Block{&DefinitionList{Items: out}}
	}
	return nil
}

func (r *ltxReader) listItemBlocks(s string) []Block {
	bs := r.parseBlocksStr(s)
	// convert single Para to Plain (pandoc: list items with one para become Plain)
	if len(bs) >= 1 {
		if p, ok := bs[0].(*Para); ok {
			allPlain := true
			for _, b := range bs[1:] {
				if _, ok := b.(*Para); ok {
					allPlain = false
				}
			}
			if allPlain {
				bs[0] = &Plain{Inlines: p.Inlines}
			}
		}
	}
	return bs
}

func (r *ltxReader) figureEnv(name string) []Block {
	body := r.readEnvBody(name)
	q := r.sub(body)
	var capt []Inline
	hasCapt := false
	label := ""
	var content []Inline
	for {
		q.skipBlank()
		if q.eof() {
			break
		}
		if q.peek() == '\\' {
			n := q.peekControlSeq()
			switch n {
			case "caption":
				q.controlSeq()
				q.bracketed()
				arg, _ := q.braced()
				capt = r.parseInlinesStr(arg)
				hasCapt = true
				continue
			case "label":
				q.controlSeq()
				lab, _ := q.braced()
				label = lab
				continue
			case "centering", "small", "footnotesize", "vspace", "hspace", "noindent", "par":
				q.controlSeq()
				if n == "vspace" || n == "hspace" {
					q.braced()
				}
				continue
			}
		}
		ils := q.parseInlines(func() bool {
			n := q.peekControlSeq()
			return q.peek() == '\\' && (n == "caption" || n == "label")
		})
		content = meldInlines(content, ils)
	}
	r.warnings = append(r.warnings, q.warnings...)
	content = trimInlines(content)
	attr := Attr{ID: label}
	if label != "" {
		r.identifiers[label] = true
	}
	if len(content) == 1 {
		if img, ok := content[0].(*Image); ok {
			if hasCapt {
				return []Block{&Figure{Attr: attr, Caption: Caption{Blocks: []Block{&Plain{Inlines: capt}}}, Blocks: []Block{&Plain{Inlines: []Inline{img}}}}}
			}
			return []Block{&Para{Inlines: []Inline{img}}}
		}
	}
	if len(content) == 0 {
		return nil
	}
	if hasCapt {
		return []Block{&Figure{Attr: attr, Caption: Caption{Blocks: []Block{&Plain{Inlines: capt}}}, Blocks: []Block{&Plain{Inlines: content}}}}
	}
	return []Block{&Para{Inlines: content}}
}

func (r *ltxReader) tableEnv(name string) []Block {
	body := r.readEnvBody(name)
	q := r.sub(body)
	var capt []Inline
	label := ""
	var out []Block
	for {
		q.skipBlank()
		if q.eof() {
			break
		}
		if q.peek() == '\\' {
			n := q.peekControlSeq()
			switch n {
			case "caption":
				q.controlSeq()
				q.bracketed()
				arg, _ := q.braced()
				capt = r.parseInlinesStr(arg)
				continue
			case "label":
				q.controlSeq()
				lab, _ := q.braced()
				label = lab
				continue
			case "centering", "small", "footnotesize", "vspace", "noindent", "par":
				q.controlSeq()
				if n == "vspace" {
					q.braced()
				}
				continue
			case "begin":
				env := q.peekEnvName()
				if env == "tabular" || env == "tabular*" || env == "longtable" || env == "tabularx" {
					q.controlSeq()
					q.braced()
					out = append(out, q.tabular(env, nil, Attr{})...)
					continue
				}
			}
		}
		out = append(out, q.block()...)
	}
	r.warnings = append(r.warnings, q.warnings...)
	for _, b := range out {
		if t, ok := b.(*Table); ok {
			if len(capt) > 0 {
				t.Caption = Caption{Blocks: []Block{&Plain{Inlines: capt}}}
			}
			t.Attr.ID = label
		}
	}
	return out
}

func (r *ltxReader) tabular(name string, _ []Alignment, attr Attr) []Block {
	if name == "tabular*" || name == "tabularx" {
		r.braced() // width
	}
	r.bracketed()
	spec, _ := r.braced()
	var aligns []Alignment
	for _, c := range spec {
		switch c {
		case 'l':
			aligns = append(aligns, AlignLeft)
		case 'r':
			aligns = append(aligns, AlignRight)
		case 'c':
			aligns = append(aligns, AlignCenter)
		case 'p', 'm', 'b', 'X':
			aligns = append(aligns, AlignLeft)
		}
	}
	body := r.readEnvBody(name)
	// split rows by \\ at depth 0
	rs := []rune(body)
	var rowsRaw []string
	depth := 0
	start := 0
	for i := 0; i < len(rs); i++ {
		c := rs[i]
		switch {
		case c == '{':
			depth++
		case c == '}':
			depth--
		case c == '\\' && i+1 < len(rs) && rs[i+1] == '\\' && depth == 0:
			rowsRaw = append(rowsRaw, string(rs[start:i]))
			i++
			// skip optional [len]
			start = i + 1
		case c == '\\' && hasPrefixRunes(rs, i, "\\tabularnewline") && depth == 0:
			rowsRaw = append(rowsRaw, string(rs[start:i]))
			i += len("\\tabularnewline") - 1
			start = i + 1
		case c == '\\':
			i++
		}
	}
	if strings.TrimSpace(string(rs[start:])) != "" {
		rowsRaw = append(rowsRaw, string(rs[start:]))
	}
	var rows []Row
	headEnd := -1
	for _, raw := range rowsRaw {
		t := strings.TrimSpace(raw)
		// strip rules
		hasMidrule := false
		for _, rule := range []string{"\\hline", "\\toprule", "\\midrule", "\\bottomrule", "\\endhead", "\\endfirsthead", "\\endlastfoot", "\\endfoot"} {
			for strings.Contains(t, rule) {
				if rule == "\\midrule" || rule == "\\hline" && len(rows) > 0 && headEnd < 0 {
					hasMidrule = true
				}
				t = strings.Replace(t, rule, "", 1)
			}
		}
		t = strings.TrimSpace(t)
		if hasMidrule && headEnd < 0 && len(rows) > 0 {
			headEnd = len(rows)
		}
		if t == "" {
			continue
		}
		cellsRaw := splitLatexCells(t)
		row := Row{}
		for _, c := range cellsRaw {
			ils := r.parseInlinesStr(c)
			var bs []Block
			if len(ils) > 0 {
				bs = []Block{&Plain{Inlines: ils}}
			}
			row.Cells = append(row.Cells, Cell{Align: AlignDefault, RowSpan: 1, ColSpan: 1, Blocks: bs})
		}
		rows = append(rows, row)
	}
	ncols := len(aligns)
	for _, row := range rows {
		if len(row.Cells) > ncols {
			ncols = len(row.Cells)
		}
	}
	for len(aligns) < ncols {
		aligns = append(aligns, AlignDefault)
	}
	tbl := &Table{Attr: attr}
	for _, a := range aligns {
		tbl.ColSpecs = append(tbl.ColSpecs, ColSpec{Align: a, Width: ColWidth{Default: true}})
	}
	for i := range rows {
		for len(rows[i].Cells) < ncols {
			rows[i].Cells = append(rows[i].Cells, Cell{Align: AlignDefault, RowSpan: 1, ColSpan: 1})
		}
	}
	if headEnd > 0 {
		tbl.Head = TableHead{Rows: rows[:headEnd]}
		tbl.Bodies = []TableBody{{Body: rows[headEnd:]}}
	} else {
		tbl.Bodies = []TableBody{{Body: rows}}
	}
	return []Block{tbl}
}

func splitLatexCells(s string) []string {
	rs := []rune(s)
	var cells []string
	depth := 0
	start := 0
	for i := 0; i < len(rs); i++ {
		switch rs[i] {
		case '{':
			depth++
		case '}':
			depth--
		case '\\':
			i++
		case '&':
			if depth == 0 {
				cells = append(cells, string(rs[start:i]))
				start = i + 1
			}
		}
	}
	cells = append(cells, string(rs[start:]))
	return cells
}

func (r *ltxReader) defineMacro(cmd string) {
	// \newcommand{\name}[n]{body} or \def\name{body}
	var name string
	if cmd == "def" {
		name = r.controlSeq()
		// skip parameter text
		for !r.eof() && r.peek() != '{' {
			r.pos++
		}
	} else {
		if r.peek() == '{' {
			arg, _ := r.braced()
			name = strings.TrimPrefix(strings.TrimSpace(arg), "\\")
		} else {
			name = r.controlSeq()
		}
	}
	nargs := 0
	if n, ok := r.bracketed(); ok {
		nargs, _ = strconv.Atoi(strings.TrimSpace(n))
	}
	r.bracketed() // default
	body, _ := r.braced()
	if name != "" {
		r.macros[name] = ltxMacro{nargs: nargs, body: body}
	}
}

