func (w *orgWriter) tableToOrg(t *Table) *Doc {
	lt := toLegacyTable(t)
	ncols := len(lt.aligns)
	render := func(bs []Block) string {
		return Render(0, w.blockListToOrg(bs))
	}
	var headers []string
	for _, h := range lt.headers {
		headers = append(headers, render(h))
	}
	var rows [][]string
	for _, r := range lt.rows {
		var rr []string
		for _, c := range r {
			rr = append(rr, render(c))
		}
		rows = append(rows, rr)
	}
	widths := make([]int, ncols)
	all := append([][]string{headers}, rows...)
	for _, r := range all {
		for i := 0; i < ncols && i < len(r); i++ {
			if n := realLength(r[i]); n > widths[i] {
				widths[i] = n
			}
		}
	}
	mkRow := func(cells []string) *Doc {
		var sb strings.Builder
		sb.WriteString("|")
		for i := 0; i < ncols; i++ {
			c := ""
			if i < len(cells) {
				c = cells[i]
			}
			sb.WriteString(" " + c + strings.Repeat(" ", widths[i]-realLength(c)) + " |")
		}
		return TextD(sb.String())
	}
	var parts []*Doc
	headless := true
	for _, h := range lt.headers {
		if len(h) > 0 {
			headless = false
		}
	}
	if !headless {
		parts = append(parts, mkRow(headers))
		var sb strings.Builder
		sb.WriteString("|")
		for i := 0; i < ncols; i++ {
			if i > 0 {
				sb.WriteString("+")
			}
			sb.WriteString(strings.Repeat("-", widths[i]+2))
		}
		sb.WriteString("|")
		parts = append(parts, TextD(sb.String()))
	}
	for _, r := range rows {
		parts = append(parts, mkRow(r))
	}
	var capt *Doc = Empty
	if len(lt.caption) > 0 {
		capt = Cat(TextD("#+caption: "), w.inlineListToOrg(lt.caption), CR)
	}
	return Cat(capt, Vcat(parts), Blankline)
}

func (w *orgWriter) inlineListToOrg(ils []Inline) *Doc {
	var docs []*Doc
	for _, il := range ils {
		docs = append(docs, w.inlineToOrg(il))
	}
	return Cat(docs...)
}

func (w *orgWriter) inlineToOrg(il Inline) *Doc {
	switch x := il.(type) {
	case *Str:
		return Literal(x.Text)
	case *Space:
		return BreakingSpace
	case *SoftBreak:
		if w.opts.WrapText == WrapPreserve {
			return CR
		}
		return BreakingSpace
	case *LineBreak:
		return Cat(TextD("\\\\"), CR)
	case *Emph:
		return Cat(TextD("/"), w.inlineListToOrg(x.Inlines), TextD("/"))
	case *Underline:
		return Cat(TextD("_"), w.inlineListToOrg(x.Inlines), TextD("_"))
	case *Strong:
		return Cat(TextD("*"), w.inlineListToOrg(x.Inlines), TextD("*"))
	case *Strikeout:
		return Cat(TextD("+"), w.inlineListToOrg(x.Inlines), TextD("+"))
	case *Superscript:
		return Cat(TextD("^{"), w.inlineListToOrg(x.Inlines), TextD("}"))
	case *Subscript:
		return Cat(TextD("_{"), w.inlineListToOrg(x.Inlines), TextD("}"))
	case *SmallCaps:
		return w.inlineListToOrg(x.Inlines)
	case *Quoted:
		contents := w.inlineListToOrg(x.Inlines)
		if x.Type == SingleQuote {
			return Cat(TextD("'"), contents, TextD("'"))
		}
		return Cat(TextD("\""), contents, TextD("\""))
	case *Code:
		return TextD("=" + x.Text + "=")
	case *Math:
		if x.Type == InlineMath {
			return TextD("$" + x.Text + "$")
		}
		return TextD("$$" + x.Text + "$$")
	case *RawInline:
		if x.Format == "org" {
			return Literal(x.Text)
		}
		if x.Format == "html" || x.Format == "latex" || x.Format == "tex" {
			f := x.Format
			if f == "tex" {
				f = "latex"
			}
			return TextD("@@" + f + ":" + x.Text + "@@")
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *Link:
		src := x.Target.URL
		if len(x.Inlines) == 1 {
			if s, ok := x.Inlines[0].(*Str); ok && (s.Text == src || "mailto:"+s.Text == src) {
				return TextD("[[" + src + "]]")
			}
		}
		return Cat(TextD("[["+orgPath(src)+"]["), w.inlineListToOrg(x.Inlines), TextD("]]"))
	case *Image:
		return TextD("[[" + orgPath(x.Target.URL) + "]]")
	case *Note:
		w.notes = append(w.notes, x.Blocks)
		return TextD("[fn:" + strconv.Itoa(len(w.notes)) + "]")
	case *Span:
		return w.inlineListToOrg(x.Inlines)
	case *Cite:
		return w.inlineListToOrg(x.Inlines)
	}
	return Empty
}

func orgPath(src string) string {
	if strings.HasPrefix(src, "#") {
		return src
	}
	if strings.Contains(src, "://") || strings.HasPrefix(src, "mailto:") {
		return src
	}
	return "file:" + src
}
