cat > src/manwriter.go <<'EOF'
package main

import (
	"strconv"
	"strings"
)

type manWriter struct {
	opts     *WriterOptions
	notes    [][]Block
	warnings []string
	hasTables bool
}

func writeMan(doc *Pandoc, opts *WriterOptions) (string, []string) {
	w := &manWriter{opts: opts}
	colwidth := 0
	if opts.WrapText == WrapAuto {
		colwidth = opts.Columns
	}
	body := w.blockListToMan(doc.Blocks)
	notes := w.notesToMan()
	main := Render(colwidth, Cat(body, notes))
	if !opts.Standalone {
		return main, w.warnings
	}
	meta := doc.Meta
	title := ""
	section := ""
	header := ""
	footer := ""
	if t, ok := meta.Get("title"); ok {
		ts := stringify(metaInlinesOf(t))
		// parse "NAME(1) footer | header"
		if i := strings.Index(ts, "("); i > 0 {
			if j := strings.Index(ts[i:], ")"); j > 0 {
				title = ts[:i]
				section = ts[i+1 : i+j]
				rest := strings.TrimSpace(ts[i+j+1:])
				if k := strings.Index(rest, "|"); k >= 0 {
					footer = strings.TrimSpace(rest[:k])
					header = strings.TrimSpace(rest[k+1:])
				} else {
					footer = rest
				}
			}
		} else {
			title = ts
		}
	}
	if s := lookupMetaString(meta, "section"); s != "" {
		section = s
	}
	if s := lookupMetaString(meta, "header"); s != "" {
		header = s
	}
	if s := lookupMetaString(meta, "footer"); s != "" {
		footer = s
	}
	date := lookupMetaString(meta, "date")
	var sb strings.Builder
	sb.WriteString(".\\\" Automatically generated by Pandoc 3.9.0.2\n.\\\"\n")
	sb.WriteString(".TH \"" + manEscape(strings.ToUpper(title)) + "\" \"" + section + "\" \"" + manEscape(date) + "\" \"" + manEscape(footer) + "\" \"" + manEscape(header) + "\"\n")
	if w.hasTables {
	}
	sb.WriteString(main)
	if !strings.HasSuffix(main, "\n") {
		sb.WriteString("\n")
	}
	return sb.String(), w.warnings
}

func manEscape(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '\\':
			sb.WriteString("\\\\")
		case '-':
			sb.WriteString("\\-")
		case '\u2018':
			sb.WriteString("\\[oq]")
		case '\u2019':
			sb.WriteString("\\[cq]")
		case '\u201c':
			sb.WriteString("\\[lq]")
		case '\u201d':
			sb.WriteString("\\[rq]")
		case '\u2013':
			sb.WriteString("\\[en]")
		case '\u2014':
			sb.WriteString("\\[em]")
		case '\u2026':
			sb.WriteString("\\&...")
		case '\u00a0':
			sb.WriteString("\\ ")
		case '\'':
			sb.WriteString("\\[aq]")
		case '"':
			sb.WriteString("\\[dq]")
		case '`':
			sb.WriteString("\\[ga]")
		case '^':
			sb.WriteString("\\[ha]")
		case '~':
			sb.WriteString("\\[ti]")
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func (w *manWriter) escString(s string) string {
	return manEscape(s)
}

func (w *manWriter) notesToMan() *Doc {
	if len(w.notes) == 0 {
		return Empty
	}
	var docs []*Doc
	for i, n := range w.notes {
		contents := w.blockListToMan(n)
		docs = append(docs, Cat(TextD(".SS ["+strconv.Itoa(i+1)+"]"), CR, contents))
	}
	return Cat(TextD(".SH NOTES"), CR, Vcat(docs))
}

func (w *manWriter) blockListToMan(bs []Block) *Doc {
	var docs []*Doc
	for _, b := range bs {
		docs = append(docs, w.blockToMan(b))
	}
	return Vcat(docs)
}

func (w *manWriter) blockToMan(b Block) *Doc {
	switch x := b.(type) {
	case *Plain:
		return w.inlineListToMan(x.Inlines)
	case *Para:
		return Cat(TextD(".PP"), CR, w.inlineListToMan(x.Inlines))
	case *LineBlock:
		var ils []Inline
		for i, l := range x.Lines {
			if i > 0 {
				ils = append(ils, &LineBreak{})
			}
			ils = append(ils, l...)
		}
		return w.blockToMan(&Para{Inlines: ils})
	case *RawBlock:
		if x.Format == "man" {
			return Literal(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *HorizontalRule:
		return TextD(".PP\n   *   *   *   *   *")
	case *Header:
		contents := w.inlineListToMan(x.Inlines)
		if x.Level == 1 {
			return Nowrap(Cat(TextD(".SH "), contents))
		}
		return Nowrap(Cat(TextD(".SS "), contents))
	case *CodeBlock:
		return Cat(TextD(".IP"), CR, TextD(".EX"), CR, Literal(manEscapeCode(x.Text)), CR, TextD(".EE"))
	case *BlockQuote:
		contents := w.blockListToMan(x.Blocks)
		return Cat(TextD(".RS"), CR, contents, CR, TextD(".RE"))
	case *BulletList:
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, w.bulletListItemToMan(it))
		}
		return Vcat(items)
	case *OrderedList:
		markers := orderedListMarkers(x.Attrs.Start, x.Attrs.Style, x.Attrs.Delim, len(x.Items))
		maxLen := 0
		for _, m := range markers {
			if len(m) > maxLen {
				maxLen = len(m)
			}
		}
		indent := strconv.Itoa(maxLen + 1)
		var items []*Doc
		for i, it := range x.Items {
			items = append(items, w.orderedListItemToMan(markers[i], indent, it))
		}
		return Vcat(items)
	case *DefinitionList:
		var items []*Doc
		for _, it := range x.Items {
			label := w.inlineListToMan(it.Term)
			var defs []*Doc
			for _, d := range it.Defs {
				var bd []*Doc
				for i, blk := range d {
					dd := w.blockToMan(blk)
					if i == 0 {
						if p, ok := blk.(*Para); ok {
							dd = w.inlineListToMan(p.Inlines)
						}
					}
					bd = append(bd, dd)
				}
				defs = append(defs, Vcat(bd))
			}
			items = append(items, Cat(TextD(".TP"), CR, Nowrap(label), CR, Vcat(defs)))
		}
		return Vcat(items)
	case *Div:
		return w.blockListToMan(x.Blocks)
	case *Figure:
		return w.blockListToMan(x.Blocks)
	case *Table:
		return w.tableToMan(x)
	}
	return Empty
}

func manEscapeCode(s string) string {
	var lines []string
	for _, l := range strings.Split(s, "\n") {
		e := manEscape(l)
		if strings.HasPrefix(e, ".") || strings.HasPrefix(e, "'") {
			e = "\\&" + e
		}
		lines = append(lines, e)
	}
	return strings.Join(lines, "\n")
}

func (w *manWriter) bulletListItemToMan(bs []Block) *Doc {
	if len(bs) == 0 {
		return TextD(".IP \\[bu] 2")
	}
	first := bs[0]
	var firstDoc *Doc
	switch f := first.(type) {
	case *Para:
		firstDoc = w.inlineListToMan(f.Inlines)
	case *Plain:
		firstDoc = w.inlineListToMan(f.Inlines)
	default:
		firstDoc = w.blockToMan(first)
	}
	rest := bs[1:]
	var restDoc *Doc = Empty
	if len(rest) > 0 {
		restDoc = Cat(CR, TextD(".RS 2"), CR, w.blockListToMan(rest), CR, TextD(".RE"))
	}
	return Cat(TextD(".IP \\[bu] 2"), CR, firstDoc, restDoc)
}

func (w *manWriter) orderedListItemToMan(marker, indent string, bs []Block) *Doc {
	if len(bs) == 0 {
		return TextD(".IP \"" + marker + "\" " + indent)
	}
	first := bs[0]
	var firstDoc *Doc
	switch f := first.(type) {
	case *Para:
		firstDoc = w.inlineListToMan(f.Inlines)
	case *Plain:
		firstDoc = w.inlineListToMan(f.Inlines)
	default:
		firstDoc = w.blockToMan(first)
	}
	rest := bs[1:]
	var restDoc *Doc = Empty
	if len(rest) > 0 {
		restDoc = Cat(CR, TextD(".RS "+indent), CR, w.blockListToMan(rest), CR, TextD(".RE"))
	}
	return Cat(TextD(".IP \""+marker+"\" "+indent), CR, firstDoc, restDoc)
}

func (w *manWriter) tableToMan(t *Table) *Doc {
	w.hasTables = true
	lt := toLegacyTable(t)
	ncols := len(lt.aligns)
	var parts []*Doc
	parts = append(parts, TextD(".PP"))
	if len(lt.caption) > 0 {
		parts = append(parts, w.inlineListToMan(lt.caption))
	}
	parts = append(parts, TextD(".TS"), TextD("tab(@);"))
	var alignStrs []string
	for _, a := range lt.aligns {
		switch a {
		case AlignRight:
			alignStrs = append(alignStrs, "r")
		case AlignCenter:
			alignStrs = append(alignStrs, "c")
		default:
			alignStrs = append(alignStrs, "l")
		}
	}
	parts = append(parts, TextD(strings.Join(alignStrs, " ")+"."))
	renderRow := func(cells [][]Block) *Doc {
		var cs []*Doc
		for i := 0; i < ncols; i++ {
			var c []Block
			if i < len(cells) {
				c = cells[i]
			}
			var inner *Doc
			if len(c) == 1 {
				switch bb := c[0].(type) {
				case *Plain:
					inner = w.inlineListToMan(bb.Inlines)
				case *Para:
					inner = w.inlineListToMan(bb.Inlines)
				}
			}
			if inner == nil {
				inner = Cat(TextD("T{"), CR, w.blockListToMan(c), CR, TextD("T}"))
			}
			cs = append(cs, inner)
		}
		var row []*Doc
		for i, c := range cs {
			if i > 0 {
				row = append(row, TextD("@"))
			}
			row = append(row, c)
		}
		return Cat(row...)
	}
	headless := true
	for _, h := range lt.headers {
		if len(h) > 0 {
			headless = false
		}
	}
	if !headless {
		parts = append(parts, renderRow(lt.headers), TextD("_"))
	}
	for _, r := range lt.rows {
		parts = append(parts, renderRow(r))
	}
	parts = append(parts, TextD(".TE"))
	return Vcat(parts)
}

func (w *manWriter) inlineListToMan(ils []Inline) *Doc {
	var docs []*Doc
	for _, il := range ils {
		docs = append(docs, w.inlineToMan(il))
	}
	return Cat(docs...)
}

func (w *manWriter) inlineToMan(il Inline) *Doc {
	switch x := il.(type) {
	case *Str:
		return Literal(w.escString(x.Text))
	case *Space:
		return BreakingSpace
	case *SoftBreak:
		if w.opts.WrapText == WrapPreserve {
			return CR
		}
		return BreakingSpace
	case *LineBreak:
		return Cat(CR, TextD(".PD 0"), CR, TextD(".P"), CR, TextD(".PD"), CR)
	case *Emph:
		return Cat(TextD("\\f[I]"), w.inlineListToMan(x.Inlines), TextD("\\f[R]"))
	case *Underline:
		return Cat(TextD("\\f[I]"), w.inlineListToMan(x.Inlines), TextD("\\f[R]"))
	case *Strong:
		return Cat(TextD("\\f[B]"), w.inlineListToMan(x.Inlines), TextD("\\f[R]"))
	case *Strikeout:
		return Cat(TextD("[STRIKEOUT:"), w.inlineListToMan(x.Inlines), TextD("]"))
	case *Superscript:
		return Cat(TextD("^("), w.inlineListToMan(x.Inlines), TextD(")"))
	case *Subscript:
		return Cat(TextD("_("), w.inlineListToMan(x.Inlines), TextD(")"))
	case *SmallCaps:
		return w.inlineListToMan(capitalizeInlines(x.Inlines))
	case *Quoted:
		contents := w.inlineListToMan(x.Inlines)
		if x.Type == SingleQuote {
			return Cat(TextD("\\[oq]"), contents, TextD("\\[cq]"))
		}
		return Cat(TextD("\\[lq]"), contents, TextD("\\[rq]"))
	case *Code:
		return Cat(TextD("\\f[CR]"), Literal(w.escString(x.Text)), TextD("\\f[R]"))
	case *Math:
		ils, ok := texMathToInlines(x.Type, x.Text)
		if !ok {
			return Literal(w.escString(x.Text))
		}
		if x.Type == DisplayMath {
			return Cat(CR, TextD(".RS"), CR, w.inlineListToMan(ils), CR, TextD(".RE"))
		}
		return w.inlineListToMan(ils)
	case *RawInline:
		if x.Format == "man" {
			return Literal(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *Link:
		src := x.Target.URL
		srcSuffix := strings.TrimPrefix(src, "mailto:")
		if len(x.Inlines) == 1 {
			if s, ok := x.Inlines[0].(*Str); ok && escapeURI(s.Text) == srcSuffix {
				return TextD("<" + w.escString(srcSuffix) + ">")
			}
		}
		linktext := w.inlineListToMan(x.Inlines)
		return Cat(linktext, TextD(" ("+w.escString(src)+")"))
	case *Image:
		alt := w.inlineListToMan(x.Inlines)
		return Cat(TextD("["), TextD("IMAGE: "), alt, TextD("]"))
	case *Note:
		w.notes = append(w.notes, x.Blocks)
		return TextD("[" + strconv.Itoa(len(w.notes)) + "]")
	case *Span:
		return w.inlineListToMan(x.Inlines)
	case *Cite:
		return w.inlineListToMan(x.Inlines)
	}
	return Empty
}
