func parseCSVRecords(s string, sep rune) [][]string {
	var records [][]string
	var cur []string
	var field strings.Builder
	rs := []rune(s)
	i := 0
	inQuotes := false
	hasField := false
	for i < len(rs) {
		c := rs[i]
		if inQuotes {
			if c == '"' {
				if i+1 < len(rs) && rs[i+1] == '"' {
					field.WriteRune('"')
					i += 2
					continue
				}
				inQuotes = false
				i++
				continue
			}
			field.WriteRune(c)
			i++
			continue
		}
		switch {
		case c == '"' && sep == ',':
			inQuotes = true
			hasField = true
			i++
		case c == sep:
			cur = append(cur, field.String())
			field.Reset()
			hasField = true
			i++
		case c == '\n' || c == '\r':
			if c == '\r' && i+1 < len(rs) && rs[i+1] == '\n' {
				i++
			}
			if hasField || field.Len() > 0 {
				cur = append(cur, field.String())
				records = append(records, cur)
			}
			cur = nil
			field.Reset()
			hasField = false
			i++
		default:
			field.WriteRune(c)
			hasField = true
			i++
		}
	}
	if hasField || field.Len() > 0 {
		cur = append(cur, field.String())
		records = append(records, cur)
	}
	return records
}

func bText(s string) []Inline {
	// like Builder.text: split into Str/Space/SoftBreak
	var out []Inline
	rs := []rune(s)
	i := 0
	for i < len(rs) {
		if unicode.IsSpace(rs[i]) {
			hasNL := false
			for i < len(rs) && unicode.IsSpace(rs[i]) {
				if rs[i] == '\n' {
					hasNL = true
				}
				i++
			}
			if hasNL {
				out = append(out, &SoftBreak{})
			} else {
				out = append(out, &Space{})
			}
			continue
		}
		start := i
		for i < len(rs) && !unicode.IsSpace(rs[i]) {
			i++
		}
		out = append(out, &Str{Text: string(rs[start:i])})
	}
	return out
}

func readCSV(input string, sep rune) *Pandoc {
	recs := parseCSVRecords(input, sep)
	doc := &Pandoc{Meta: newMetaMap()}
	if len(recs) == 0 {
		return doc
	}
	numcols := len(recs[0])
	mkRow := func(fields []string) Row {
		r := Row{}
		for i := 0; i < numcols; i++ {
			f := ""
			if i < len(fields) {
				f = fields[i]
			}
			var bs []Block
			ils := bText(f)
			if len(ils) > 0 {
				bs = []Block{&Plain{Inlines: ils}}
			}
			r.Cells = append(r.Cells, Cell{Align: AlignDefault, RowSpan: 1, ColSpan: 1, Blocks: bs})
		}
		return r
	}
	t := &Table{}
	for i := 0; i < numcols; i++ {
		t.ColSpecs = append(t.ColSpecs, ColSpec{Align: AlignDefault, Width: ColWidth{Default: true}})
	}
	t.Head = TableHead{Rows: []Row{mkRow(recs[0])}}
	body := TableBody{}
	for _, r := range recs[1:] {
		body.Body = append(body.Body, mkRow(r))
	}
	t.Bodies = []TableBody{body}
	doc.Blocks = []Block{t}
	return doc
}
