package main

import (
	"strings"
)

type mwWriter struct {
	opts     *WriterOptions
	notes    bool
	listLevel string
	useTags  bool
	warnings []string
}

func writeMediaWiki(doc *Pandoc, opts *WriterOptions) (string, []string) {
	w := &mwWriter{opts: opts}
	body := w.blockListToMW(doc.Blocks)
	notesText := ""
	if w.notes {
		notesText = "\n<references />"
	}
	main := body + notesText
	main = strings.TrimRight(main, "\n")
	if !opts.Standalone {
		return main, w.warnings
	}
	// no real template: just body
	return main, w.warnings
}

func (w *mwWriter) blockListToMW(bs []Block) string {
	var parts []string
	for _, b := range bs {
		parts = append(parts, w.blockToMW(b))
	}
	return strings.Join(parts, "\n")
}

func (w *mwWriter) blockToMW(b Block) string {
	switch x := b.(type) {
	case *Plain:
		return w.inlineListToMW(x.Inlines)
	case *Para:
		contents := w.inlineListToMW(x.Inlines)
		if w.useTags {
			return "<p>" + contents + "</p>"
		}
		if w.listLevel == "" {
			return contents + "\n"
		}
		return contents
	case *LineBlock:
		return w.blockToMW(linesToPara(x.Lines))
	case *RawBlock:
		if x.Format == "mediawiki" || x.Format == "html" {
			return x.Text
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return ""
	case *HorizontalRule:
		return "\n-----\n"
	case *Header:
		contents := w.inlineListToMW(x.Inlines)
		eqs := strings.Repeat("=", x.Level)
		return eqs + " " + contents + " " + eqs + "\n"
	case *CodeBlock:
		langs := map[string]bool{}
		for _, l := range strings.Fields("actionscript ada apache applescript asm asp autoit bash blitzbasic bnf boo c c_mac caddcl cadlisp cfdg cfm cpp cpp-qt csharp css d delphi diff div dos dot eiffel fortran freebasic gml groovy html4strict idl ini inno io java java5 javascript latex lisp lua matlab mirc mpasm mysql nsis objc ocaml ocaml-brief oobas oracle8 pascal perl php php-brief plsql python qbasic rails reg robots ruby sas scheme sdlbasic smalltalk smarty sql tcl text thinbasic tsql vb vbnet vhdl visualfoxpro winbatch xml xpp z80") {
			langs[l] = true
		}
		var lang string
		for _, c := range x.Attr.Classes {
			if langs[strings.ToLower(c)] {
				lang = c
				break
			}
		}
		if len(x.Attr.Classes) > 0 && lang == "" {
			// pandoc uses first class if any
		}
		if lang == "" {
			return "<pre>" + escapeMWText(x.Text) + "</pre>"
		}
		attrs := " lang=\"" + lang + "\""
		if x.Attr.HasClass("numberLines") || x.Attr.HasClass("number-lines") {
			attrs += " line"
		}
		if sf, ok := x.Attr.Get("startFrom"); ok {
			attrs += " start=\"" + sf + "\""
		}
		return "<syntaxhighlight" + attrs + ">" + x.Text + "</syntaxhighlight>"
	case *BlockQuote:
		return "<blockquote>" + w.blockListToMW(x.Blocks) + "</blockquote>"
	case *BulletList:
		return w.listToMW("*", x.Items)
	case *OrderedList:
		if x.Attrs.Start != 1 || x.Attrs.Style != DefaultStyle && x.Attrs.Style != Decimal {
			// use tags
			old := w.useTags
			w.useTags = true
			var items []string
			for _, it := range x.Items {
				items = append(items, "<li>"+w.blockListToMW(it)+"</li>")
			}
			w.useTags = old
			attrs := ""
			if x.Attrs.Start != 1 {
				attrs += " start=\"" + itoaS(x.Attrs.Start) + "\""
			}
			switch x.Attrs.Style {
			case LowerAlpha:
				attrs += " style=\"list-style-type: lower-alpha;\""
			case UpperAlpha:
				attrs += " style=\"list-style-type: upper-alpha;\""
			case LowerRoman:
				attrs += " style=\"list-style-type: lower-roman;\""
			case UpperRoman:
				attrs += " style=\"list-style-type: upper-roman;\""
			}
			return "<ol" + attrs + ">\n" + strings.Join(items, "\n") + "\n</ol>"
		}
		return w.listToMW("#", x.Items)
	case *DefinitionList:
		if w.useTags {
			var items []string
			for _, it := range x.Items {
				items = append(items, "<dt>"+w.inlineListToMW(it.Term)+"</dt>")
				for _, d := range it.Defs {
					items = append(items, "<dd>"+w.blockListToMW(d)+"</dd>")
				}
			}
			return "<dl>\n" + strings.Join(items, "\n") + "\n</dl>"
		}
		old := w.listLevel
		w.listLevel += ";"
		var items []string
		for _, it := range x.Items {
			term := w.inlineListToMW(it.Term)
			s := w.listLevel + " " + term
			for _, d := range it.Defs {
				marker := strings.TrimSuffix(w.listLevel, ";") + ":"
				s += "\n" + marker + " " + w.blockListToMW(d)
			}
			items = append(items, s)
		}
		w.listLevel = old
		out := strings.Join(items, "\n")
		if w.listLevel == "" {
			out += "\n"
		}
		return out
	case *Div:
		contents := w.blockListToMW(x.Blocks)
		var attrs []string
		if x.Attr.ID != "" {
			attrs = append(attrs, "id=\""+x.Attr.ID+"\"")
		}
		if len(x.Attr.Classes) > 0 {
			attrs = append(attrs, "class=\""+strings.Join(x.Attr.Classes, " ")+"\"")
		}
		for _, kv := range x.Attr.KVs {
			attrs = append(attrs, kv[0]+"=\""+kv[1]+"\"")
		}
		a := ""
		if len(attrs) > 0 {
			a = " " + strings.Join(attrs, " ")
		}
		return "<div" + a + ">\n\n" + contents + "\n\n</div>"
	case *Figure:
		if len(x.Blocks) == 1 {
			if pl, ok := x.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
				if img, ok := pl.Inlines[0].(*Image); ok {
					capt := w.inlineListToMW(blocksInlines(x.Caption.Blocks))
					return "[[File:" + img.Target.URL + "|thumb|none" + w.imageDims(img.Attr) + "|" + capt + "]]\n"
				}
			}
		}
		return w.blockListToMW(x.Blocks)
	case *Table:
		return w.tableToMW(x)
	}
	return ""
}

func itoaS(n int) string {
	return strings.TrimSpace(strings.Repeat(" ", 0) + intToStrS(n))
}

func intToStrS(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b []byte
	for n > 0 {
		b = append([]byte{byte('0' + n%10)}, b...)
		n /= 10
	}
	if neg {
		b = append([]byte{'-'}, b...)
	}
	return string(b)
}

func (w *mwWriter) listToMW(marker string, items [][]Block) string {
	old := w.listLevel
	w.listLevel += marker
	var out []string
	for _, it := range items {
		out = append(out, w.listLevel+" "+w.listItemToMW(it))
	}
	w.listLevel = old
	s := strings.Join(out, "\n")
	if w.listLevel == "" {
		s += "\n"
	}
	return s
}

func (w *mwWriter) listItemToMW(bs []Block) string {
	// in mediawiki, nested lists on their own lines
	var parts []string
	for i, b := range bs {
		switch x := b.(type) {
		case *BulletList, *OrderedList, *DefinitionList:
			parts = append(parts, "\n"+w.blockToMW(x))
		default:
			s := w.blockToMW(b)
			if i > 0 {
				s = " " + s
			}
			parts = append(parts, s)
		}
	}
	return strings.TrimRight(strings.Join(parts, ""), "\n")
}

func (w *mwWriter) imageDims(attr Attr) string {
	s := ""
	if wd, ok := attr.Get("width"); ok {
		s += "|" + strings.TrimSuffix(wd, "px")
		if ht, ok := attr.Get("height"); ok {
			s += "x" + strings.TrimSuffix(ht, "px")
		}
		s += "px"
	} else if ht, ok := attr.Get("height"); ok {
		s += "|x" + strings.TrimSuffix(ht, "px") + "px"
	}
	return s
}

func (w *mwWriter) tableToMW(t *Table) string {
	lt := toLegacyTable(t)
	var sb strings.Builder
	sb.WriteString("{|\n")
	if len(lt.caption) > 0 {
		sb.WriteString("|+ " + w.inlineListToMW(lt.caption) + "\n")
	}
	headless := true
	for _, h := range lt.headers {
		if len(h) > 0 {
			headless = false
		}
	}
	alignStr := func(a Alignment) string {
		switch a {
		case AlignLeft:
			return "align=\"left\"| "
		case AlignRight:
			return "align=\"right\"| "
		case AlignCenter:
			return "align=\"center\"| "
		}
		return ""
	}
	if !headless {
		sb.WriteString("|-\n")
		for i, h := range lt.headers {
			sb.WriteString("! " + alignStr(lt.aligns[i]) + w.blockListToMW(h) + "\n")
		}
	}
	for _, r := range lt.rows {
		sb.WriteString("|-\n")
		for i, c := range r {
			a := AlignDefault
			if i < len(lt.aligns) {
				a = lt.aligns[i]
			}
			sb.WriteString("| " + alignStr(a) + w.blockListToMW(c) + "\n")
		}
	}
	sb.WriteString("|}\n")
	return sb.String()
}

func escapeMWText(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;").Replace(s)
}

func (w *mwWriter) inlineListToMW(ils []Inline) string {
	var sb strings.Builder
	for _, il := range ils {
		sb.WriteString(w.inlineToMW(il))
	}
	return sb.String()
}

func (w *mwWriter) inlineToMW(il Inline) string {
	switch x := il.(type) {
	case *Str:
		return escapeMWText(x.Text)
	case *Space:
		return " "
	case *SoftBreak:
		switch w.opts.WrapText {
		case WrapPreserve:
			return "\n"
		}
		return " "
	case *LineBreak:
		return "<br />\n"
	case *Emph:
		return "''" + w.inlineListToMW(x.Inlines) + "''"
	case *Underline:
		return "<u>" + w.inlineListToMW(x.Inlines) + "</u>"
	case *Strong:
		return "'''" + w.inlineListToMW(x.Inlines) + "'''"
	case *Strikeout:
		return "<s>" + w.inlineListToMW(x.Inlines) + "</s>"
	case *Superscript:
		return "<sup>" + w.inlineListToMW(x.Inlines) + "</sup>"
	case *Subscript:
		return "<sub>" + w.inlineListToMW(x.Inlines) + "</sub>"
	case *SmallCaps:
		return "<span style=\"font-variant:small-caps;\">" + w.inlineListToMW(x.Inlines) + "</span>"
	case *Quoted:
		if x.Type == SingleQuote {
			return "\u2018" + w.inlineListToMW(x.Inlines) + "\u2019"
		}
		return "\u201c" + w.inlineListToMW(x.Inlines) + "\u201d"
	case *Code:
		return "<code>" + escapeMWText(x.Text) + "</code>"
	case *Math:
		return "<math>" + x.Text + "</math>"
	case *RawInline:
		if x.Format == "mediawiki" || x.Format == "html" {
			return x.Text
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return ""
	case *Link:
		label := w.inlineListToMW(x.Inlines)
		src := x.Target.URL
		if len(x.Inlines) == 1 {
			if s, ok := x.Inlines[0].(*Str); ok && isURI(src) && escapeURI(s.Text) == src {
				return src
			}
		}
		if isURI(src) {
			return "[" + src + " " + label + "]"
		}
		src2 := strings.TrimPrefix(src, "/")
		return "[[" + src2 + "|" + label + "]]"
	case *Image:
		alt := w.inlineListToMW(x.Inlines)
		txt := ""
		if x.Target.Title != "" {
			txt = "|" + x.Target.Title
		} else if len(x.Inlines) > 0 {
			txt = "|" + alt
		}
		return "[[File:" + x.Target.URL + w.imageDims(x.Attr) + txt + "]]"
	case *Note:
		w.notes = true
		contents := w.blockListToMW(x.Blocks)
		return "<ref>" + contents + "</ref>"
	case *Span:
		return w.inlineListToMW(x.Inlines)
	case *Cite:
		return w.inlineListToMW(x.Inlines)
	}
	return ""
}
