cd /workspace && cat > src/asciidocwriter.go <<'EOF'
package main

import (
	"strconv"
	"strings"
)

type adocWriter struct {
	opts      *WriterOptions
	legacy    bool
	ids       map[string]bool
	inList    bool
	bulletLvl int
	orderLvl  int
	intraword bool
	warnings  []string
	hasMath   bool
}

func writeAsciiDoc(doc *Pandoc, opts *WriterOptions, legacy bool) (string, []string) {
	w := &adocWriter{opts: opts, legacy: legacy, ids: map[string]bool{}}
	colwidth := 0
	if opts.WrapText == WrapAuto {
		colwidth = opts.Columns
	}
	body := w.blockListToAD(doc.Blocks)
	main := Render(colwidth, body)
	if !opts.Standalone {
		return main, w.warnings
	}
	meta := doc.Meta
	var sb strings.Builder
	if t, ok := meta.Get("title"); ok {
		sb.WriteString("= " + Render(0, w.inlineListToAD(metaInlinesOf(t))) + "\n")
		var auths []string
		if a, ok := meta.Get("author"); ok {
			if l, ok := a.(*MetaList); ok {
				for _, it := range l.Items {
					auths = append(auths, Render(0, w.inlineListToAD(metaInlinesOf(it))))
				}
			} else {
				auths = append(auths, Render(0, w.inlineListToAD(metaInlinesOf(a))))
			}
		}
		if len(auths) > 0 {
			sb.WriteString(strings.Join(auths, "; ") + "\n")
		}
		if d, ok := meta.Get("date"); ok {
			sb.WriteString(Render(0, w.inlineListToAD(metaInlinesOf(d))) + "\n")
		}
		sb.WriteString("\n")
	}
	if w.hasMath {
		sb.WriteString(":stem: latexmath\n\n")
	}
	return sb.String() + main, w.warnings
}

func (w *adocWriter) blockListToAD(bs []Block) *Doc {
	var docs []*Doc
	for _, b := range bs {
		docs = append(docs, w.blockToAD(b))
	}
	return Cat(docs...)
}

func (w *adocWriter) blockToAD(b Block) *Doc {
	switch x := b.(type) {
	case *Plain:
		return Cat(w.inlineListToAD(x.Inlines), CR)
	case *Para:
		contents := w.inlineListToAD(x.Inlines)
		// escape if para starts with a list-like marker
		if len(x.Inlines) == 1 {
			if img, ok := x.Inlines[0].(*Image); ok && len(img.Inlines) > 0 {
				capt := w.inlineListToAD(img.Inlines)
				return Cat(TextD("."), capt, CR, TextD("image::"+img.Target.URL+"[image]"), Blankline)
			}
		}
		return Cat(contents, Blankline)
	case *LineBlock:
		var lines []*Doc
		for _, l := range x.Lines {
			lines = append(lines, w.inlineListToAD(l))
		}
		return Cat(TextD("[verse]"), CR, TextD("--"), CR, Vcat(lines), CR, TextD("--"), Blankline)
	case *RawBlock:
		if x.Format == "asciidoc" {
			return Cat(Literal(x.Text), Blankline)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *HorizontalRule:
		return Cat(Blankline, TextD("'''''"), Blankline)
	case *Header:
		contents := w.inlineListToAD(x.Inlines)
		autoId := uniqueIdent(x.Inlines, w.ids, false, false)
		w.ids[autoId] = true
		ident := Empty
		if x.Attr.ID != "" && x.Attr.ID != autoId {
			ident = Cat(TextD("[["+x.Attr.ID+"]]"), CR)
		}
		return Cat(ident, TextD(strings.Repeat("=", x.Level+1)+" "), contents, Blankline)
	case *CodeBlock:
		var classes []string
		for _, c := range x.Attr.Classes {
			if c != "numberLines" && c != "number-lines" {
				classes = append(classes, c)
			}
		}
		attrs := Empty
		if len(classes) > 0 {
			attrs = Cat(TextD("[source,"+classes[0]+"]"), CR)
		}
		dashes := "----"
		for strings.Contains(x.Text, dashes) {
			dashes += "-"
		}
		return Cat(attrs, TextD(dashes), CR, Literal(x.Text), CR, TextD(dashes), Blankline)
	case *BlockQuote:
		contents := w.blockListToAD(x.Blocks)
		return Cat(TextD("____"), CR, Chomp(contents), CR, TextD("____"), Blankline)
	case *BulletList:
		old := w.bulletLvl
		w.bulletLvl++
		marker := strings.Repeat("*", w.bulletLvl)
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, w.listItemToAD(marker, it))
		}
		w.bulletLvl = old
		return Cat(Vcat(items), Blankline)
	case *OrderedList:
		old := w.orderLvl
		w.orderLvl++
		marker := strings.Repeat(".", w.orderLvl)
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, w.listItemToAD(marker, it))
		}
		w.orderLvl = old
		attrs := Empty
		if x.Attrs.Start != 1 {
			attrs = Cat(TextD("[start="+strconv.Itoa(x.Attrs.Start)+"]"), CR)
		}
		return Cat(attrs, Vcat(items), Blankline)
	case *DefinitionList:
		var items []*Doc
		for _, it := range x.Items {
			label := w.inlineListToAD(it.Term)
			var defs []*Doc
			for _, d := range it.Defs {
				defs = append(defs, Chomp(w.blockListToAD(d)))
			}
			items = append(items, Cat(label, TextD("::"), CR, Nest(2, Vsep(defs))))
		}
		return Cat(Vcat(items), Blankline)
	case *Div:
		contents := w.blockListToAD(x.Blocks)
		if x.Attr.ID != "" {
			return Cat(TextD("[["+x.Attr.ID+"]]"), CR, contents)
		}
		return contents
	case *Figure:
		if len(x.Blocks) == 1 {
			if pl, ok := x.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
				if img, ok := pl.Inlines[0].(*Image); ok {
					capt := w.inlineListToAD(blocksInlines(x.Caption.Blocks))
					return Cat(TextD("."), capt, CR, TextD("image::"+img.Target.URL+"[image]"), Blankline)
				}
			}
		}
		return w.blockListToAD(x.Blocks)
	case *Table:
		return w.tableToAD(x)
	}
	return Empty
}

func (w *adocWriter) listItemToAD(marker string, bs []Block) *Doc {
	var parts []*Doc
	for i, b := range bs {
		d := w.blockToAD(b)
		if i == 0 {
			switch b.(type) {
			case *Para, *Plain:
				parts = append(parts, Cat(TextD(marker+" "), Chomp(d)))
			default:
				parts = append(parts, Cat(TextD(marker+" "), Chomp(d)))
			}
		} else {
			switch b.(type) {
			case *BulletList, *OrderedList:
				parts = append(parts, Chomp(d))
			default:
				parts = append(parts, Cat(TextD("+"), CR, Chomp(d)))
			}
		}
	}
	return Vcat(parts)
}

func (w *adocWriter) tableToAD(t *Table) *Doc {
	lt := toLegacyTable(t)
	ncols := len(lt.aligns)
	var capt *Doc = Empty
	if len(lt.caption) > 0 {
		capt = Cat(TextD("."), w.inlineListToAD(lt.caption), CR)
	}
	headless := true
	for _, h := range lt.headers {
		if len(h) > 0 {
			headless = false
		}
	}
	var colspecs []string
	for i := 0; i < ncols; i++ {
		s := ""
		switch lt.aligns[i] {
		case AlignLeft:
			s = "<"
		case AlignRight:
			s = ">"
		case AlignCenter:
			s = "^"
		}
		if lt.widths[i] > 0 {
			s += strconv.Itoa(int(lt.widths[i] * 100))
		}
		colspecs = append(colspecs, s)
	}
	allEmpty := true
	for _, c := range colspecs {
		if c != "" {
			allEmpty = false
		}
	}
	var attrParts []string
	if !allEmpty || true {
		attrParts = append(attrParts, "cols=\""+strings.Join(colspecs, ",")+"\"")
	}
	if !headless {
		attrParts = append(attrParts, "options=\"header\"")
	}
	attrs := TextD("[" + strings.Join(attrParts, ",") + ",]")
	renderRow := func(cells [][]Block) *Doc {
		var parts []*Doc
		for i := 0; i < ncols; i++ {
			var c []Block
			if i < len(cells) {
				c = cells[i]
			}
			var inner *Doc
			if len(c) == 1 {
				switch bb := c[0].(type) {
				case *Plain:
					inner = w.inlineListToAD(bb.Inlines)
				case *Para:
					inner = w.inlineListToAD(bb.Inlines)
				}
			}
			if inner == nil {
				inner = Chomp(w.blockListToAD(c))
			}
			if i > 0 {
				parts = append(parts, TextD(" "))
			}
			parts = append(parts, TextD("|"), inner)
		}
		return Cat(parts...)
	}
	var rows []*Doc
	if !headless {
		rows = append(rows, renderRow(lt.headers))
	}
	for _, r := range lt.rows {
		rows = append(rows, renderRow(r))
	}
	return Cat(capt, attrs, CR, TextD("|==="), CR, Vcat(rows), CR, TextD("|==="), Blankline)
}

func (w *adocWriter) inlineListToAD(ils []Inline) *Doc {
	var docs []*Doc
	for i, il := range ils {
		// intraword emphasis detection
		w.intraword = false
		if i > 0 {
			if s, ok := ils[i-1].(*Str); ok && s.Text != "" {
				last := []rune(s.Text)[len([]rune(s.Text))-1]
				if isAlphaNum(last) {
					w.intraword = true
				}
			}
		}
		if i+1 < len(ils) && !w.intraword {
			if s, ok := ils[i+1].(*Str); ok && s.Text != "" {
				first := []rune(s.Text)[0]
				if isAlphaNum(first) {
					w.intraword = true
				}
			}
		}
		docs = append(docs, w.inlineToAD(il))
	}
	return Cat(docs...)
}

func (w *adocWriter) inlineToAD(il Inline) *Doc {
	switch x := il.(type) {
	case *Str:
		return Literal(escapeAD(x.Text))
	case *Space:
		return BreakingSpace
	case *SoftBreak:
		if w.opts.WrapText == WrapPreserve {
			return CR
		}
		return BreakingSpace
	case *LineBreak:
		return Cat(TextD(" +"), CR)
	case *Emph:
		m := "_"
		if w.intraword {
			m = "__"
		}
		return Cat(TextD(m), w.inlineListToAD(x.Inlines), TextD(m))
	case *Underline:
		return Cat(TextD("[.underline]#"), w.inlineListToAD(x.Inlines), TextD("#"))
	case *Strong:
		m := "*"
		if w.intraword {
			m = "**"
		}
		return Cat(TextD(m), w.inlineListToAD(x.Inlines), TextD(m))
	case *Strikeout:
		return Cat(TextD("[line-through]*"), w.inlineListToAD(x.Inlines), TextD("*"))
	case *Superscript:
		return Cat(TextD("^"), w.inlineListToAD(x.Inlines), TextD("^"))
	case *Subscript:
		return Cat(TextD("~"), w.inlineListToAD(x.Inlines), TextD("~"))
	case *SmallCaps:
		return Cat(TextD("[smallcaps]#"), w.inlineListToAD(x.Inlines), TextD("#"))
	case *Quoted:
		contents := w.inlineListToAD(x.Inlines)
		if x.Type == SingleQuote {
			if w.legacy {
				return Cat(TextD("`"), contents, TextD("'"))
			}
			return Cat(TextD("'`"), contents, TextD("`'"))
		}
		if w.legacy {
			return Cat(TextD("``"), contents, TextD("''"))
		}
		return Cat(TextD("\"`"), contents, TextD("`\""))
	case *Code:
		if w.intraword {
			return TextD("``" + x.Text + "``")
		}
		return TextD("`" + x.Text + "`")
	case *Math:
		w.hasMath = true
		if x.Type == InlineMath {
			return TextD("latexmath:[" + x.Text + "]")
		}
		return Cat(TextD("[latexmath]"), CR, TextD("++++"), CR, Literal("\\["+x.Text+"\\]"), CR, TextD("++++"))
	case *RawInline:
		if x.Format == "asciidoc" {
			return Literal(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *Link:
		src := x.Target.URL
		linktext := w.inlineListToAD(x.Inlines)
		if len(x.Inlines) == 1 {
			if s, ok := x.Inlines[0].(*Str); ok && (escapeURI(s.Text) == src || "mailto:"+s.Text == src) {
				return TextD(strings.TrimPrefix(src, "mailto:"))
			}
		}
		if strings.HasPrefix(src, "#") {
			return Cat(TextD("<<"+src[1:]+","), linktext, TextD(">>"))
		}
		prefix := ""
		if !isURI(src) {
			prefix = "link:"
		}
		return Cat(TextD(prefix+src+"["), linktext, TextD("]"))
	case *Image:
		alt := w.inlineListToAD(x.Inlines)
		var dims []string
		if wd, ok := x.Attr.Get("width"); ok {
			dims = append(dims, "width="+strings.TrimSuffix(wd, "px"))
		}
		if ht, ok := x.Attr.Get("height"); ok {
			dims = append(dims, "height="+strings.TrimSuffix(ht, "px"))
		}
		d := ""
		if len(dims) > 0 {
			d = "," + strings.Join(dims, ",")
		}
		return Cat(TextD("image:"+x.Target.URL+"["), alt, TextD(d+"]"))
	case *Note:
		contents := w.blockListToAD(x.Blocks)
		return Cat(TextD("footnote:["), Chomp(contents), TextD("]"))
	case *Span:
		contents := w.inlineListToAD(x.Inlines)
		if x.Attr.IsNull() {
			return contents
		}
		var parts []string
		if x.Attr.ID != "" {
			parts = append(parts, "#"+x.Attr.ID)
		}
		for _, c := range x.Attr.Classes {
			parts = append(parts, "."+c)
		}
		return Cat(TextD("["+strings.Join(parts, "")+"]#"), contents, TextD("#"))
	case *Cite:
		return w.inlineListToAD(x.Inlines)
	}
	return Empty
}

func escapeAD(s string) string {
	// escape asciidoc special chars minimally
	s = strings.ReplaceAll(s, "{", "\\{")
	s = strings.ReplaceAll(s, "}", "\\}")
	return s
}
