cat > src/typstwriter.go <<'EOF'
package main

import (
	"strconv"
	"strings"
)

type typstWriter struct {
	opts     *WriterOptions
	warnings []string
}

func writeTypst(doc *Pandoc, opts *WriterOptions) (string, []string) {
	w := &typstWriter{opts: opts}
	colwidth := 0
	if opts.WrapText == WrapAuto {
		colwidth = opts.Columns
	}
	body := w.blockListToTypst(doc.Blocks)
	main := Render(colwidth, body)
	if !opts.Standalone {
		return main, w.warnings
	}
	meta := doc.Meta
	var sb strings.Builder
	sb.WriteString("#import \"@preview/pandoc-template:0.1.0\": conf\n")
	_ = sb
	// simplified standalone: title block via #set document
	var out strings.Builder
	if t, ok := meta.Get("title"); ok {
		out.WriteString("#set document(title: [" + Render(0, w.inlineListToTypst(metaInlinesOf(t))) + "])\n")
		out.WriteString("#align(center)[#block(inset: 2em)[\n#text(weight: \"bold\", size: 1.5em)[" + Render(0, w.inlineListToTypst(metaInlinesOf(t))) + "]\n]]\n\n")
	}
	out.WriteString(main)
	return out.String(), w.warnings
}

func (w *typstWriter) blockListToTypst(bs []Block) *Doc {
	var docs []*Doc
	for _, b := range bs {
		docs = append(docs, w.blockToTypst(b))
	}
	return Cat(docs...)
}

func (w *typstWriter) blockToTypst(b Block) *Doc {
	switch x := b.(type) {
	case *Plain:
		return Cat(w.inlineListToTypst(x.Inlines), CR)
	case *Para:
		return Cat(w.inlineListToTypst(x.Inlines), Blankline)
	case *LineBlock:
		var lines []*Doc
		for _, l := range x.Lines {
			lines = append(lines, Cat(w.inlineListToTypst(l), TextD("\\")))
		}
		return Cat(Vcat(lines), Blankline)
	case *RawBlock:
		if x.Format == "typst" {
			return Cat(Literal(x.Text), Blankline)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawBlock (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *HorizontalRule:
		return Cat(Blankline, TextD("#horizontalrule"), Blankline)
	case *Header:
		contents := w.inlineListToTypst(x.Inlines)
		lab := Empty
		if x.Attr.ID != "" {
			lab = Cat(CR, TextD("<"+x.Attr.ID+">"))
		}
		return Cat(TextD(strings.Repeat("=", x.Level)+" "), contents, lab, Blankline)
	case *CodeBlock:
		lang := ""
		if len(x.Attr.Classes) > 0 {
			lang = x.Attr.Classes[0]
		}
		fence := "```"
		for strings.Contains(x.Text, fence) {
			fence += "`"
		}
		return Cat(TextD(fence+lang), CR, Literal(x.Text), CR, TextD(fence), Blankline)
	case *BlockQuote:
		contents := w.blockListToTypst(x.Blocks)
		return Cat(TextD("#quote(block: true)["), CR, Chomp(contents), CR, TextD("]"), Blankline)
	case *BulletList:
		var items []*Doc
		for _, it := range x.Items {
			items = append(items, Hang(2, TextD("- "), Chomp(w.blockListToTypst(it))))
		}
		return Cat(Vcat(items), Blankline)
	case *OrderedList:
		var items []*Doc
		for i, it := range x.Items {
			marker := "+ "
			if x.Attrs.Start != 1 && i == 0 {
				marker = strconv.Itoa(x.Attrs.Start) + ". "
			}
			items = append(items, Hang(2, TextD(marker), Chomp(w.blockListToTypst(it))))
		}
		return Cat(Vcat(items), Blankline)
	case *DefinitionList:
		var items []*Doc
		for _, it := range x.Items {
			term := w.inlineListToTypst(it.Term)
			var defs []*Doc
			for _, d := range it.Defs {
				defs = append(defs, Chomp(w.blockListToTypst(d)))
			}
			items = append(items, Cat(TextD("/ "), term, TextD(": "), Vsep(defs)))
		}
		return Cat(Vcat(items), Blankline)
	case *Div:
		contents := w.blockListToTypst(x.Blocks)
		if x.Attr.ID != "" {
			return Cat(TextD("#block["), CR, Chomp(contents), CR, TextD("]<"+x.Attr.ID+">"), Blankline)
		}
		return contents
	case *Figure:
		if len(x.Blocks) == 1 {
			if pl, ok := x.Blocks[0].(*Plain); ok && len(pl.Inlines) == 1 {
				if img, ok := pl.Inlines[0].(*Image); ok {
					capt := w.inlineListToTypst(blocksInlines(x.Caption.Blocks))
					lab := Empty
					if x.Attr.ID != "" {
						lab = TextD(" <" + x.Attr.ID + ">")
					}
					return Cat(TextD("#figure(image(\""+img.Target.URL+"\"),"), CR, TextD("  caption: ["), CR, Nest(4, capt), CR, TextD("  ]"), CR, TextD(")"), lab, Blankline)
				}
			}
		}
		return w.blockListToTypst(x.Blocks)
	case *Table:
		return w.tableToTypst(x)
	}
	return Empty
}

func (w *typstWriter) tableToTypst(t *Table) *Doc {
	lt := toLegacyTable(t)
	ncols := len(lt.aligns)
	var aligns []string
	for _, a := range lt.aligns {
		switch a {
		case AlignLeft:
			aligns = append(aligns, "left")
		case AlignRight:
			aligns = append(aligns, "right")
		case AlignCenter:
			aligns = append(aligns, "center")
		default:
			aligns = append(aligns, "auto")
		}
	}
	renderRow := func(cells [][]Block) *Doc {
		var parts []*Doc
		for i := 0; i < ncols; i++ {
			var c []Block
			if i < len(cells) {
				c = cells[i]
			}
			parts = append(parts, TextD("["), Chomp(w.blockListToTypst(c)), TextD("],"))
			if i < ncols-1 {
				parts = append(parts, TextD(" "))
			}
		}
		return Cat(parts...)
	}
	var rows []*Doc
	rows = append(rows, TextD("columns: "+strconv.Itoa(ncols)+","))
	rows = append(rows, TextD("align: ("+strings.Join(aligns, ",")+",),"))
	headless := true
	for _, h := range lt.headers {
		if len(h) > 0 {
			headless = false
		}
	}
	if !headless {
		rows = append(rows, Cat(TextD("table.header("), renderRow(lt.headers), TextD("),")), TextD("table.hline(),"))
	}
	for _, r := range lt.rows {
		rows = append(rows, renderRow(r))
	}
	tbl := Cat(TextD("#table("), CR, Nest(2, Vcat(rows)), CR, TextD(")"))
	if len(lt.caption) > 0 {
		capt := w.inlineListToTypst(lt.caption)
		return Cat(TextD("#figure("), CR, Nest(2, Cat(TextD("align(center)["), Nest(0, tbl), TextD("]"), CR, TextD(", caption: ["), CR, Nest(2, capt), CR, TextD("]"), CR, TextD(", kind: table"), CR, TextD(")"))), Blankline)
	}
	return Cat(TextD("#figure("), CR, Nest(2, Cat(TextD("align(center)["), tbl, TextD("]"), CR, TextD(", kind: table"), CR, TextD(")"))), Blankline)
}

func escapeTypst(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '\\', '*', '_', '`', '#', '$', '<', '>', '@', '[', ']', '"', '\'', '~', '/', '+', '-', '=':
			if r == '-' || r == '+' || r == '/' || r == '=' || r == '\'' || r == '"' {
				sb.WriteRune(r)
			} else {
				sb.WriteRune('\\')
				sb.WriteRune(r)
			}
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func (w *typstWriter) inlineListToTypst(ils []Inline) *Doc {
	var docs []*Doc
	for i, il := range ils {
		d := w.inlineToTypst(il)
		// typst needs ';' after function calls followed by alphanumerics
		switch il.(type) {
		case *Superscript, *Subscript, *Strikeout, *SmallCaps, *Underline, *Note, *Link:
			if i+1 < len(ils) {
				if s, ok := ils[i+1].(*Str); ok && s.Text != "" && isAlphaNum([]rune(s.Text)[0]) {
					d = Cat(d, TextD(";"))
				}
			}
		}
		docs = append(docs, d)
	}
	return Cat(docs...)
}

func (w *typstWriter) inlineToTypst(il Inline) *Doc {
	switch x := il.(type) {
	case *Str:
		return Literal(escapeTypst(x.Text))
	case *Space:
		return BreakingSpace
	case *SoftBreak:
		if w.opts.WrapText == WrapPreserve {
			return CR
		}
		return BreakingSpace
	case *LineBreak:
		return Cat(TextD("\\"), CR)
	case *Emph:
		return Cat(TextD("_"), w.inlineListToTypst(x.Inlines), TextD("_"))
	case *Underline:
		return Cat(TextD("#underline["), w.inlineListToTypst(x.Inlines), TextD("]"))
	case *Strong:
		return Cat(TextD("*"), w.inlineListToTypst(x.Inlines), TextD("*"))
	case *Strikeout:
		return Cat(TextD("#strike["), w.inlineListToTypst(x.Inlines), TextD("]"))
	case *Superscript:
		return Cat(TextD("#super["), w.inlineListToTypst(x.Inlines), TextD("]"))
	case *Subscript:
		return Cat(TextD("#sub["), w.inlineListToTypst(x.Inlines), TextD("]"))
	case *SmallCaps:
		return Cat(TextD("#smallcaps["), w.inlineListToTypst(x.Inlines), TextD("]"))
	case *Quoted:
		contents := w.inlineListToTypst(x.Inlines)
		if x.Type == SingleQuote {
			return Cat(TextD("'"), contents, TextD("'"))
		}
		return Cat(TextD("\""), contents, TextD("\""))
	case *Code:
		ticks := "`"
		for strings.Contains(x.Text, ticks) {
			ticks += "`"
		}
		return TextD(ticks + x.Text + ticks)
	case *Math:
		if x.Type == InlineMath {
			return TextD("$" + x.Text + "$")
		}
		return TextD("$ " + x.Text + " $")
	case *RawInline:
		if x.Format == "typst" {
			return Literal(x.Text)
		}
		w.warnings = append(w.warnings, "[WARNING] Not rendering RawInline (Format \""+x.Format+"\") "+haskellShowString(x.Text))
		return Empty
	case *Link:
		src := x.Target.URL
		if strings.HasPrefix(src, "#") {
			return Cat(TextD("#link(<"+src[1:]+">)["), w.inlineListToTypst(x.Inlines), TextD("]"))
		}
		if len(x.Inlines) == 1 {
			if s, ok := x.Inlines[0].(*Str); ok && (s.Text == src || "mailto:"+s.Text == src) {
				return TextD("#link(\"" + src + "\")")
			}
		}
		return Cat(TextD("#link(\""+src+"\")["), w.inlineListToTypst(x.Inlines), TextD("]"))
	case *Image:
		var opts []string
		if wd, ok := x.Attr.Get("width"); ok {
			opts = append(opts, "width: "+wd)
		}
		if ht, ok := x.Attr.Get("height"); ok {
			opts = append(opts, "height: "+ht)
		}
		o := ""
		if len(opts) > 0 {
			o = ", " + strings.Join(opts, ", ")
		}
		return TextD("#image(\"" + x.Target.URL + "\"" + o + ")")
	case *Note:
		contents := w.blockListToTypst(x.Blocks)
		return Cat(TextD("#footnote["), Chomp(contents), TextD("]"))
	case *Span:
		return w.inlineListToTypst(x.Inlines)
	case *Cite:
		return w.inlineListToTypst(x.Inlines)
	}
	return Empty
}
